  `requesting_dept` varchar(80) DEFAULT NULL COMMENT 'الإدارة الطالبة',
  `raise_reason` varchar(255) DEFAULT NULL COMMENT 'سبب الرفع للأعلى',
  `amount` decimal(18,2) DEFAULT NULL COMMENT 'القيمة',
  `currency` varchar(8) DEFAULT NULL,
  `dept_cap` decimal(18,2) DEFAULT NULL COMMENT 'سقف الإدارة لحظة الرفع',
  `overage` decimal(18,2) DEFAULT NULL COMMENT 'التجاوز',
  `prior_approvers` varchar(255) DEFAULT NULL COMMENT 'المعتمِدون قبلي',
  `deadline` varchar(60) DEFAULT NULL COMMENT 'المهلة المعلنة',
  `decision` varchar(30) DEFAULT NULL COMMENT 'قراري: اعتماد/اعتماد بشرط/رد/تأجيل',
  `decision_reason` varchar(300) DEFAULT NULL COMMENT 'سبب القرار أو الشرط',
  `decision_date` date DEFAULT NULL,
  `approver_name` varchar(120) DEFAULT NULL COMMENT 'المعتمِد — الاسم والصفة',
  `authority_ref` varchar(120) DEFAULT NULL COMMENT 'مرجع التفويض أو سلطة أصلية',
  `status` varchar(40) NOT NULL DEFAULT 'قيد المراجعة',
  `source_request_id` bigint(20) unsigned DEFAULT NULL COMMENT 'ربط الطلب الحقيقي requests.id',
  `source_kind` varchar(30) DEFAULT NULL COMMENT 'منشأ الصف: يدوي/رفع آلي/طلب',
  `is_seed` tinyint(1) NOT NULL DEFAULT 0,
  `created_by` int(11) DEFAULT NULL,
  `created_by_name` varchar(120) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `approved_at` datetime DEFAULT NULL COMMENT 'لحظةُ الاعتماد — وبها يُقاس زمنُ الدورة',
  `approver_user_id` int(11) DEFAULT NULL COMMENT 'هويةُ المعتمِدِ من سلسلةِ الاعتماد — والاسمُ يُقرأ منها لا يُكتب',
  `item_code` varchar(255) DEFAULT NULL COMMENT 'معرّف البند',
  `item_category` varchar(80) DEFAULT NULL COMMENT 'الفئة ▼',
  `item_kind` varchar(80) DEFAULT NULL COMMENT 'النوع ▼',
  `source_dept` varchar(255) DEFAULT NULL COMMENT 'الإدارة المصدر ◄',
  `txn_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع المعاملة ◄',
  `project_ref` varchar(120) DEFAULT NULL COMMENT 'Project ◄',
  `budget_status` varchar(255) DEFAULT NULL COMMENT 'Budget_Status ◄',
  `matrix_rule_ref` varchar(255) DEFAULT NULL COMMENT 'قاعدة المصفوفة المفعِّلة ◄',
  `prior_levels` varchar(255) DEFAULT NULL COMMENT 'المستويات السابقة ◄',
  `deputy_recommendation` varchar(255) DEFAULT NULL COMMENT 'Relevant_Deputy_Recommendation ◄',
  `finance_review_status` varchar(255) DEFAULT NULL COMMENT 'Finance_Review_Status ◄',
  `risk_level` varchar(255) DEFAULT NULL COMMENT 'Risk_Level ◄',
  `ceo_decision` varchar(80) DEFAULT NULL COMMENT 'CEO_Decision ▼',
  `decision_conditions` varchar(255) DEFAULT NULL COMMENT 'Decision_Conditions',
  `data_state` varchar(255) DEFAULT NULL COMMENT 'حالة البيانات ▼',
  `src_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع المصدر',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_exec_appr_no` (`company_id`,`request_no`),
  KEY `ix_exap_live` (`company_id`,`status`,`received_date`),
  KEY `ix_exap_src` (`source_request_id`),
  KEY `fk_exec_approvals_approver` (`approver_user_id`),
  CONSTRAINT `fk_exec_approvals_approver` FOREIGN KEY (`approver_user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `chk_exec_approvals_approver_identity` CHECK (`created_at` < '2026-08-19 00:00:00' or `approver_name` is null or trim(`approver_name`) = '' or `approver_user_id` is not null)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='M-00 §8-2: الاعتماد الأعلى — الجدول الأصلي لشاشة ceo_approvals';

