  `g380` varchar(190) DEFAULT NULL COMMENT 'النطاق',
  `g381` varchar(190) DEFAULT NULL COMMENT 'FOP_ID',
  `g382` varchar(190) DEFAULT NULL COMMENT 'FCON_ID',
