  `g384` varchar(190) DEFAULT NULL COMMENT 'كود العين/الآلية',
  `g385` varchar(190) DEFAULT NULL COMMENT 'ترتيب الانتقال',
  `g386` varchar(190) DEFAULT NULL COMMENT 'من (المالك السابق)',
  `g387` varchar(190) DEFAULT NULL COMMENT 'إلى (المالك الجديد)',
  `g388` varchar(190) DEFAULT NULL COMMENT 'الحصة %',
  `g389` varchar(190) DEFAULT NULL COMMENT 'التاريخ',
  `g390` varchar(190) DEFAULT NULL COMMENT 'قيمة البيع',
  `g391` varchar(190) DEFAULT NULL COMMENT 'العملة',
  `g392` varchar(190) DEFAULT NULL COMMENT 'نوع الخروج',
  `g393` varchar(190) DEFAULT NULL COMMENT 'المستند',
  `g394` varchar(190) DEFAULT NULL COMMENT 'الاعتماد',
  `g395` varchar(190) DEFAULT NULL COMMENT 'الحجية',
  `g396` varchar(190) DEFAULT NULL COMMENT 'حالة البيانات',
  `g397` varchar(190) DEFAULT NULL COMMENT 'Source_Row_Ref',
