) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='FIN-01 - ممول واحد';

-- ── Table: fin_financier_contact ──
CREATE TABLE `fin_financier_contact` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `entity_id` int(10) unsigned NOT NULL COMMENT 'legal_entities.entity_id — الممول',
  `person_name` varchar(160) NOT NULL DEFAULT '',
  `role_ar` varchar(120) NOT NULL DEFAULT '',
  `is_authorized` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'مفوض بالتوقيع',
  `mandate_ref` varchar(160) NOT NULL DEFAULT '' COMMENT 'مستند التفويض',
  `phone` varchar(40) NOT NULL DEFAULT '',
  `email` varchar(120) NOT NULL DEFAULT '',
  `valid_from` date NOT NULL,
  `valid_to` date DEFAULT NULL COMMENT 'فارغ = ساري — والنسخة مؤرخة لا تدهس',
  `state` varchar(16) NOT NULL DEFAULT 'active',
  `created_by` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `g31` varchar(190) DEFAULT NULL COMMENT 'كود الجهة',
  `g32` varchar(190) DEFAULT NULL COMMENT 'كود الممول',
  `g33` varchar(190) DEFAULT NULL COMMENT 'اسم الممول (بحث)',
  `g34` varchar(190) DEFAULT NULL COMMENT 'الاسم',
  `g35` varchar(190) DEFAULT NULL COMMENT 'الدور',
  `g36` varchar(190) DEFAULT NULL COMMENT 'مفوض توقيع؟',
  `g37` varchar(190) DEFAULT NULL COMMENT 'الهاتف',
  `g38` varchar(190) DEFAULT NULL COMMENT 'البريد',
  `g39` varchar(190) DEFAULT NULL COMMENT 'سريان من',
  `g40` varchar(190) DEFAULT NULL COMMENT 'إلى',
  `g41` varchar(190) DEFAULT NULL COMMENT 'الحالة',
  `g42` varchar(190) DEFAULT NULL COMMENT 'حالة البيانات',
  PRIMARY KEY (`id`),
  KEY `ix_ffc_entity` (`company_id`,`entity_id`,`valid_from`),
  CONSTRAINT `chk_ffc_name` CHECK (`person_name` <> ''),
  CONSTRAINT `chk_ffc_mandate` CHECK (`is_authorized` = 0 or `mandate_ref` <> ''),
  CONSTRAINT `chk_ffc_span` CHECK (`valid_to` is null or `valid_to` >= `valid_from`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='REPAIR01 W12 - جهات اتصال الممول والمفوض عبر الزمن';

-- ── Table: fin_financier_document ──
CREATE TABLE `fin_financier_document` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `entity_id` int(10) unsigned NOT NULL,
  `doc_kind` varchar(32) NOT NULL DEFAULT '' COMMENT 'license او registry او tax او kyc او rating',
  `doc_ref` varchar(160) NOT NULL DEFAULT '',
  `issued_on` date DEFAULT NULL,
  `expires_on` date DEFAULT NULL,
  `verified_by` int(10) unsigned NOT NULL DEFAULT 0,
  `verified_at` datetime DEFAULT NULL,
  `state` varchar(16) NOT NULL DEFAULT 'pending' COMMENT 'pending او verified او expired او rejected',
  `note` varchar(400) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_ffd_entity` (`company_id`,`entity_id`,`doc_kind`),
  CONSTRAINT `chk_ffd_ref` CHECK (`doc_kind` <> '' and `doc_ref` <> ''),
  CONSTRAINT `chk_ffd_ver` CHECK (`state` <> 'verified' or `verified_by` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='REPAIR01 W12 - وثائق التاهيل والعناية الواجبة للممول';

-- ── Table: fin_financier_due ──
CREATE TABLE `fin_financier_due` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL DEFAULT 0 COMMENT 'بوابة المستأجر',
  `g253` varchar(190) DEFAULT NULL COMMENT 'كود الاستحقاق',
  `g254` varchar(190) DEFAULT NULL COMMENT 'كود العملية',
  `g255` varchar(190) DEFAULT NULL COMMENT 'كود الممول',
  `g256` varchar(190) DEFAULT NULL COMMENT 'اسم الممول (بحث)',
  `g257` varchar(190) DEFAULT NULL COMMENT 'العملة',
  `g258` varchar(190) DEFAULT NULL COMMENT 'المستحق حتى الأفق',
  `g259` varchar(190) DEFAULT NULL COMMENT 'المدفوع (الدفتر)',
  `g260` varchar(190) DEFAULT NULL COMMENT 'صافي المستحق غير المسدد',
  `g261` varchar(190) DEFAULT NULL COMMENT 'أساس الاحتساب',
  `g262` varchar(190) DEFAULT NULL COMMENT 'Record_Basis',
  `g263` varchar(190) DEFAULT NULL COMMENT 'Derivation_Rule',
  `g264` varchar(190) DEFAULT NULL COMMENT 'Confidence',
  `g265` varchar(190) DEFAULT NULL COMMENT 'Needs_Review',
  `g266` varchar(190) DEFAULT NULL COMMENT 'حالة البيانات',
  `g267` varchar(190) DEFAULT NULL COMMENT 'Source_Row_Ref',
  `g268` varchar(190) DEFAULT NULL COMMENT 'ملاحظات',
  `created_at` datetime DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_54e6141f_co` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='FIN-14 - استحقاق ممول لفترة';

-- ── Table: fin_funding_facilities ──
CREATE TABLE `fin_funding_facilities` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `facility_no` varchar(30) NOT NULL,
  `facility_type` enum('loan','murabaha','lease','bank_guarantee','letter_of_credit','operating_finance') NOT NULL,
  `purpose` enum('equipment','supplier','operational','general') NOT NULL,
  `lender_entity_id` int(11) DEFAULT NULL COMMENT 'suppliers/entities.id (مرجع مرن)',
  `lender_name` varchar(160) DEFAULT NULL COMMENT 'لقطة نصية للممول',
  `principal` decimal(16,2) NOT NULL,
  `profit_rate` decimal(9,4) DEFAULT NULL COMMENT '% أو هامش',
  `currency` varchar(8) NOT NULL DEFAULT 'SDG',
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `state` enum('draft','approved','active','settled','closed') NOT NULL DEFAULT 'draft',
  `note` varchar(200) DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fin_fac_no` (`company_id`,`facility_no`),
  KEY `ix_fin_fac_type` (`company_id`,`facility_type`),
  KEY `ix_fin_fac_state` (`company_id`,`state`),
  KEY `ix_fin_fac_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: fin_funding_need ──
CREATE TABLE `fin_funding_need` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `need_code` varchar(40) NOT NULL,
  `title` varchar(255) NOT NULL DEFAULT '',
  `requester_dept` varchar(120) NOT NULL DEFAULT '',
  `purpose` varchar(32) NOT NULL DEFAULT '' COMMENT 'equipment او operational او supplier او general',
  `amount_needed` decimal(18,2) NOT NULL DEFAULT 0.00,
  `currency` varchar(8) NOT NULL DEFAULT '',
  `needed_by` date DEFAULT NULL,
  `justification` varchar(600) NOT NULL DEFAULT '',
  `state` varchar(16) NOT NULL DEFAULT 'draft' COMMENT 'draft او submitted او approved او rejected او sourced',
  `raised_by` int(10) unsigned NOT NULL DEFAULT 0,
  `approved_by` int(10) unsigned NOT NULL DEFAULT 0,
  `approved_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `g43` varchar(190) DEFAULT NULL COMMENT 'كود الحاجة',
  `g44` varchar(190) DEFAULT NULL COMMENT 'كود العملية الناتجة',
  `g45` varchar(190) DEFAULT NULL COMMENT 'Selected_Financier_ID نتيجة لاحقة بعد العروض والاختيار',
  `g46` varchar(190) DEFAULT NULL COMMENT 'Requesting_Department الإدارة الطالبة',
  `g47` varchar(190) DEFAULT NULL COMMENT 'Requested_By الطالب',
  `g48` varchar(190) DEFAULT NULL COMMENT 'Required_By_Date',
  `g49` varchar(190) DEFAULT NULL COMMENT 'Priority',
  `g50` varchar(190) DEFAULT NULL COMMENT 'Need_Approval اعتماد الحاجة',
  `g51` varchar(190) DEFAULT NULL COMMENT 'Approved_Amount',
  `g52` varchar(190) DEFAULT NULL COMMENT 'اسم الممول (بحث)',
  `g53` varchar(190) DEFAULT NULL COMMENT 'الأصل المطلوب',
  `g54` varchar(190) DEFAULT NULL COMMENT 'كود العين',
  `g55` varchar(190) DEFAULT NULL COMMENT 'القيمة (من العملية)',
  `g56` varchar(190) DEFAULT NULL COMMENT 'العملة',
  `g57` varchar(190) DEFAULT NULL COMMENT 'نموذج التمويل',
  `g58` varchar(190) DEFAULT NULL COMMENT 'Need_Date',
  `g59` varchar(190) DEFAULT NULL COMMENT 'Need_Must_Precede',
  `g60` varchar(190) DEFAULT NULL COMMENT 'المشروع/عقد العميل',
  `g61` varchar(190) DEFAULT NULL COMMENT 'سبب الحاجة',
  `g62` varchar(190) DEFAULT NULL COMMENT 'Record_Basis',
  `g63` varchar(190) DEFAULT NULL COMMENT 'Derivation_Rule',
  `g64` varchar(190) DEFAULT NULL COMMENT 'Confidence',
  `g65` varchar(190) DEFAULT NULL COMMENT 'Needs_Review',
  `g66` varchar(190) DEFAULT NULL COMMENT 'حالة البيانات',
  `g67` varchar(190) DEFAULT NULL COMMENT 'Source_Row_Ref',
  `g68` varchar(190) DEFAULT NULL COMMENT 'ملاحظات',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ffn_code` (`company_id`,`need_code`),
  CONSTRAINT `chk_ffn_amt` CHECK (`amount_needed` > 0 and `currency` <> ''),
  CONSTRAINT `chk_ffn_why` CHECK (`state` = 'draft' or `justification` <> ''),
  CONSTRAINT `chk_ffn_sod` CHECK (`state` <> 'approved' or `approved_by` > 0 and `approved_by` <> `raised_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='REPAIR01 W12 - حاجة تمويلية واحدة';

-- ── Table: fin_funding_offer ──
CREATE TABLE `fin_funding_offer` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `offer_code` varchar(40) NOT NULL,
  `need_id` int(10) unsigned NOT NULL DEFAULT 0,
  `entity_id` int(10) unsigned NOT NULL COMMENT 'الممول مقدم العرض',
  `version_no` smallint(5) unsigned NOT NULL DEFAULT 1 COMMENT 'طبقة اصدارات — التفاوض نسخ لا دهس',
  `model_code` varchar(32) NOT NULL DEFAULT '',
  `principal` decimal(18,2) NOT NULL DEFAULT 0.00,
  `currency` varchar(8) NOT NULL DEFAULT '',
  `profit_rate` decimal(9,4) NOT NULL DEFAULT 0.0000,
  `tenor_months` smallint(5) unsigned NOT NULL DEFAULT 0,
  `grace_months` smallint(5) unsigned NOT NULL DEFAULT 0,
  `fees_total` decimal(18,2) NOT NULL DEFAULT 0.00,
  `collateral` varchar(400) NOT NULL DEFAULT '',
  `offer_doc_ref` varchar(160) NOT NULL DEFAULT '',
  `received_on` date DEFAULT NULL,
  `valid_until` date DEFAULT NULL,
  `state` varchar(16) NOT NULL DEFAULT 'received' COMMENT 'received او negotiating او shortlisted او accepted او declined او expired',
  `superseded_by` int(10) unsigned NOT NULL DEFAULT 0,
  `created_by` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `g69` varchar(190) DEFAULT NULL COMMENT 'كود العرض',
  `g70` varchar(190) DEFAULT NULL COMMENT 'كود الحاجة',
  `g71` varchar(190) DEFAULT NULL COMMENT 'كود العملية الناتجة',
  `g72` varchar(190) DEFAULT NULL COMMENT 'كود الممول',
  `g73` varchar(190) DEFAULT NULL COMMENT 'اسم الممول (بحث)',
  `g74` varchar(190) DEFAULT NULL COMMENT 'صفة العرض',
  `g75` varchar(190) DEFAULT NULL COMMENT 'رقم النسخة',
  `g76` varchar(190) DEFAULT NULL COMMENT 'النسخة الأساس',
  `g77` varchar(190) DEFAULT NULL COMMENT 'ما الذي تغير عن سابقتها',
  `g78` varchar(190) DEFAULT NULL COMMENT 'من اقترح التغيير',
  `g79` varchar(190) DEFAULT NULL COMMENT 'تاريخ التغيير',
  `g80` varchar(190) DEFAULT NULL COMMENT 'حالة التفاوض',
  `g81` varchar(190) DEFAULT NULL COMMENT 'نموذج التمويل',
  `g82` varchar(190) DEFAULT NULL COMMENT 'رأس المال',
  `g83` varchar(190) DEFAULT NULL COMMENT 'العملة',
  `g84` varchar(190) DEFAULT NULL COMMENT 'نسبة الأرباح %',
  `g85` varchar(190) DEFAULT NULL COMMENT 'قيمة الأرباح',
  `g86` varchar(190) DEFAULT NULL COMMENT 'المقدم',
  `g87` varchar(190) DEFAULT NULL COMMENT 'المدة (شهر)',
  `g88` varchar(190) DEFAULT NULL COMMENT 'عدد الأقساط',
  `g89` varchar(190) DEFAULT NULL COMMENT 'قيمة القسط',
  `g90` varchar(190) DEFAULT NULL COMMENT 'الضمانات',
  `g91` varchar(190) DEFAULT NULL COMMENT 'تاريخ العرض',
  `g92` varchar(190) DEFAULT NULL COMMENT 'Offer_Must_Precede',
  `g93` varchar(190) DEFAULT NULL COMMENT 'عروض المنافسين',
  `g94` varchar(190) DEFAULT NULL COMMENT 'Record_Basis',
  `g95` varchar(190) DEFAULT NULL COMMENT 'Derivation_Rule',
  `g96` varchar(190) DEFAULT NULL COMMENT 'Confidence',
  `g97` varchar(190) DEFAULT NULL COMMENT 'Needs_Review',
  `g98` varchar(190) DEFAULT NULL COMMENT 'حالة البيانات',
  `g99` varchar(190) DEFAULT NULL COMMENT 'Source_Row_Ref',
  `g100` varchar(190) DEFAULT NULL COMMENT 'ملاحظات',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ffo_ver` (`company_id`,`offer_code`,`version_no`),
  KEY `ix_ffo_need` (`company_id`,`need_id`,`state`),
  CONSTRAINT `chk_ffo_amt` CHECK (`principal` > 0 and `currency` <> ''),
  CONSTRAINT `chk_ffo_doc` CHECK (`state` not in ('shortlisted','accepted') or `offer_doc_ref` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='REPAIR01 W12 - عرض تمويل واحد بطبقة اصدارات';

-- ── Table: fin_funding_schedules ──
CREATE TABLE `fin_funding_schedules` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `facility_id` int(11) NOT NULL,
  `installment_no` int(11) NOT NULL,
  `due_date` date NOT NULL,
  `principal_due` decimal(16,2) NOT NULL DEFAULT 0.00,
  `profit_due` decimal(16,2) NOT NULL DEFAULT 0.00,
  `total_due` decimal(16,2) GENERATED ALWAYS AS (`principal_due` + `profit_due`) STORED,
  `paid_amount` decimal(16,2) NOT NULL DEFAULT 0.00,
  `state` enum('due','partial','paid','overdue') NOT NULL DEFAULT 'due',
  `event_id` int(11) DEFAULT NULL COMMENT 'حدثُ استحقاق القسط — «أقساطٌ آليةٌ بمرجع الجدول لحظةَ استحقاقها»',
  `accrued_at` datetime DEFAULT NULL COMMENT 'لحظةُ الاعتراف بالاستحقاق — لا تُكتب إلا مع الحدث',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_funding_installment` (`company_id`,`facility_id`,`installment_no`),
  KEY `ix_fin_fs_fac` (`company_id`,`facility_id`),
  KEY `ix_fin_fs_due` (`company_id`,`due_date`),
  KEY `fk_fin_fs_fac` (`facility_id`),
  KEY `ix_funding_due` (`company_id`,`due_date`,`state`),
  CONSTRAINT `fk_fin_fs_fac` FOREIGN KEY (`facility_id`) REFERENCES `fin_funding_facilities` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: fin_fx_differences ──
CREATE TABLE `fin_fx_differences` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `kind` enum('realized','unrealized') NOT NULL,
  `source_kind` enum('allocation','revaluation') NOT NULL,
  `source_ref` int(11) NOT NULL COMMENT 'سطرُ التخصيص أو الذمّةُ المُعاد تقييمُها',
  `party_ref` int(11) DEFAULT NULL COMMENT 'العميلُ إن عُرف',
  `from_currency` varchar(8) NOT NULL COMMENT 'العملةُ التي نشأ منها الفرق',
  `functional_currency` varchar(8) NOT NULL COMMENT '**العملةُ الوظيفية** — وفيها وحدَها يُقاس الفرق',
  `amount` decimal(18,2) NOT NULL COMMENT 'موجبٌ ربحُ صرفٍ · سالبٌ خسارتُه',
  `rate_from` decimal(20,8) DEFAULT NULL,
  `rate_to` decimal(20,8) DEFAULT NULL,
  `occurred_on` date NOT NULL,
  `note` varchar(255) DEFAULT NULL,
  `event_id` int(11) DEFAULT NULL COMMENT 'وصلُ الدفتر — **مؤجَّلٌ إلى H-09**',
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fxd_source` (`kind`,`source_kind`,`source_ref`),
  KEY `ix_fxd_lookup` (`company_id`,`kind`,`occurred_on`),
  CONSTRAINT `ck_fxd_amount` CHECK (`amount` <> 0),
  CONSTRAINT `ck_fxd_currency` CHECK (`functional_currency` <> _utf8mb4'' and `from_currency` <> _utf8mb4'')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: fin_fx_rates ──
CREATE TABLE `fin_fx_rates` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL COMMENT 'عزل المستأجر',
  `currency_code` varchar(8) NOT NULL COMMENT 'العملة المُسعَّرة',
  `rate_to_base` decimal(20,8) NOT NULL COMMENT 'كم وحدةَ أساسٍ يساوي واحدٌ منها — base = ROUND(amount × rate, 2)',
  `effective_from` date NOT NULL COMMENT 'أولُ يومٍ يسري فيه — والسعرُ النافذ آخرُ سعرٍ سابقٍ للتاريخ أو مساوٍ',
  `source` varchar(32) DEFAULT NULL COMMENT 'مصدرُ السعر: system · بنك مركزي · قرارٌ إداري',
  `note` varchar(255) DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fx_currency_date` (`company_id`,`currency_code`,`effective_from`) COMMENT 'سعرٌ واحدٌ لكل (عملة × تاريخ سريان) — التصحيحُ تعديلُ الصفّ لا صفٌّ ثانٍ',
  KEY `ix_fx_lookup` (`company_id`,`currency_code`,`effective_from`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='أسعارُ الصرف بتواريخها — السعرُ لحظةَ الحدث (FES-01 §3.1)';

-- ── Table: fin_internal_allocations ──
CREATE TABLE `fin_internal_allocations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `alloc_type` enum('internal_allocation','intercompany_settlement') NOT NULL,
  `from_center_id` int(11) DEFAULT NULL COMMENT 'fin_cost_centers',
  `to_center_id` int(11) DEFAULT NULL COMMENT 'fin_cost_centers',
  `from_entity_id` int(11) DEFAULT NULL COMMENT 'entities (مرجع مرن)',
  `to_entity_id` int(11) DEFAULT NULL COMMENT 'entities (مرجع مرن)',
  `basis` varchar(120) DEFAULT NULL COMMENT 'ساعات/استخدام/عدد',
  `amount` decimal(16,2) NOT NULL,
  `period_id` int(11) DEFAULT NULL COMMENT 'fin_financial_periods (soft)',
  `event_id` int(11) DEFAULT NULL,
  `state` enum('draft','approved','posted') NOT NULL DEFAULT 'draft',
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_fin_ia_type` (`company_id`,`alloc_type`),
  KEY `ix_fin_ia_deleted` (`is_deleted`),
  KEY `fk_fin_ia_from` (`from_center_id`),
  KEY `fk_fin_ia_to` (`to_center_id`),
  CONSTRAINT `fk_fin_ia_from` FOREIGN KEY (`from_center_id`) REFERENCES `fin_cost_centers` (`id`),
  CONSTRAINT `fk_fin_ia_to` FOREIGN KEY (`to_center_id`) REFERENCES `fin_cost_centers` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: fin_journal_entries ──
CREATE TABLE `fin_journal_entries` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `entry_no` varchar(30) NOT NULL COMMENT 'يُسنِده الخادم',
  `event_id` int(11) DEFAULT NULL COMMENT 'fin_financial_events.id (مرجع مرن)',
  `posting_date` date NOT NULL,
  `txn_date` date NOT NULL DEFAULT curdate() COMMENT 'M-38: تاريخُ الحركة الفعلي (بجانب posting_date تاريخِ الترحيل)',
  `request_no` varchar(64) DEFAULT NULL COMMENT 'M-38: خيطُ الطلب — رقمُ الطلب المالي المولِّد إن وُجد',
  `request_owner` varchar(64) DEFAULT NULL COMMENT 'M-38: صاحبُ الطلب (اسمُ الرافع لحظةَ التوليد — لقطة)',
  `request_group` varchar(64) DEFAULT NULL COMMENT 'M-38: مجموعةُ الطلب (request_type)',
  `currency` varchar(8) NOT NULL DEFAULT 'SDG' COMMENT 'M-38: عملةُ القيد (افتراضُ SDG يطابق نمطَ fin_financial_events)',
  `fx_rate` decimal(18,6) DEFAULT NULL COMMENT 'M-38: سعرُ الصرف إلى عملة الأساس يومَ الحركة — NULL = سعرٌ غيرُ مُدخَل (فجوةٌ معلَنة)',
  `base_amount` decimal(18,2) DEFAULT NULL COMMENT 'M-38: المعادلُ الموحّد بعملة الأساس = ROUND(total_debit × fx_rate, 2)',
  `total_debit` decimal(16,2) NOT NULL DEFAULT 0.00,
  `total_credit` decimal(16,2) NOT NULL DEFAULT 0.00,
  `memo` varchar(200) DEFAULT NULL,
  `state` enum('draft','posted','reversed') NOT NULL DEFAULT 'draft',
  `posted_by` int(11) DEFAULT NULL,
  `posted_at` datetime DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `manual_kind` varchar(40) NOT NULL DEFAULT '' COMMENT 'النوع — تسويةٌ/تصحيحٌ/إقفالٌ/عكس',
  `source_doc_ref` varchar(120) NOT NULL DEFAULT '' COMMENT 'المستندُ المصدر',
  `approval_ref` varchar(120) NOT NULL DEFAULT '' COMMENT 'مرجعُ الاعتماد',
  `reversal_link` bigint(20) DEFAULT NULL COMMENT 'رابطُ العكس — القيدُ المعكوس',
  `period_code` varchar(16) NOT NULL DEFAULT '' COMMENT 'الفترةُ YYYY-MM',
  `manual_gov_state` varchar(20) NOT NULL DEFAULT 'GOVERNED' COMMENT 'GOVERNED · PRE_GOVERNANCE',
  `recognition_request_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'طلب الاعتراف الذي انتج القيد',
  `entity_scope` varchar(24) NOT NULL DEFAULT 'SINGLE_ENTITY' COMMENT 'SINGLE_ENTITY او GROUP_PROJECTION',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fin_entry_no` (`company_id`,`entry_no`),
  KEY `ix_fin_entry_state` (`company_id`,`state`),
  KEY `ix_fin_entry_event` (`event_id`),
  KEY `ix_fin_entry_deleted` (`is_deleted`),
  KEY `ix_je_txn_date` (`company_id`,`txn_date`),
  KEY `ix_je_request_no` (`company_id`,`request_no`),
  CONSTRAINT `ck_je_balanced` CHECK (round(`total_debit`,2) = round(`total_credit`,2)),
  CONSTRAINT `ck_je_fx_pair` CHECK (`fx_rate` is null and `base_amount` is null or `fx_rate` is not null and `base_amount` = round(`total_debit` * `fx_rate`,2)),
  CONSTRAINT `chk_manual_journal_governed` CHECK (`event_id` is not null and `event_id` > 0 or `manual_gov_state` = 'PRE_GOVERNANCE' or trim(`manual_kind`) <> '' and trim(`source_doc_ref`) <> '' and trim(coalesce(`memo`,'')) <> '' and trim(`period_code`) <> '' and `created_by` > 0 and (`state` <> 'posted' or trim(`approval_ref`) <> '' and coalesce(`posted_by`,0) > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: fin_journal_lines ──
CREATE TABLE `fin_journal_lines` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `entry_id` int(11) NOT NULL,
  `account_id` int(11) NOT NULL COMMENT 'fin_chart_of_accounts.id',
  `legacy_account_id` int(11) DEFAULT NULL COMMENT '◆ التصنيفُ الأصليُّ قبل ترحيلِ الشجرة — فالترحيلُ يُعكس ولا يُمحى',
  `posting_rule_code` varchar(16) NOT NULL DEFAULT '' COMMENT 'صفُّ مصفوفةِ الترحيلِ الذي اشتقَّ الحسابَ — ولا يُختار يدويًّا',
  `debit` decimal(16,2) NOT NULL DEFAULT 0.00,
  `credit` decimal(16,2) NOT NULL DEFAULT 0.00,
  `project_id` int(11) DEFAULT NULL COMMENT 'project.id (بُعد، مرجع مرن)',
  `equipment_id` int(11) DEFAULT NULL COMMENT 'equipments.id (بُعد، مرجع مرن)',
  `site_id` int(11) DEFAULT NULL COMMENT 'D3 الموقعُ — إلزاميٌّ في القيودِ الميدانية',
  `cost_center_id` int(11) DEFAULT NULL COMMENT 'M-38: مركزُ التكلفة من الدليل — بديلُ النص الحر cost_center',
  `cost_center` varchar(60) DEFAULT NULL,
  `counterparty_type` varchar(24) NOT NULL DEFAULT '' COMMENT 'D6 نوعُ الطرفِ: client · supplier · employee · financier · partner',
  `counterparty_id` int(11) DEFAULT NULL COMMENT '◆ D6 يحلُّ محلَّ أسماءِ الأشخاصِ في الشجرة (R2)',
  `business_model` varchar(16) NOT NULL DEFAULT '' COMMENT 'D7 نموذجُ العمل: hour · ton · meter — يُنتج ربحيةَ كل نموذج',
  `contract_id` int(11) DEFAULT NULL COMMENT 'D8 العقدُ — إلزاميٌّ في الإيرادِ والجزاءات',
  `contract_type_code` varchar(12) NOT NULL DEFAULT '' COMMENT 'D9 نوعُ العقد: EC-01..08 للموظفينَ · FC-01..10 للممولين',
  `memo` varchar(200) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_fin_jl_entry` (`company_id`,`entry_id`),
  KEY `ix_fin_jl_account` (`company_id`,`account_id`),
  KEY `fk_fin_jl_entry` (`entry_id`),
  KEY `fk_fin_jl_acc` (`account_id`),
  KEY `ix_jl_cost_center` (`company_id`,`cost_center_id`),
  KEY `fk_fin_jl_cc` (`cost_center_id`),
  KEY `ix_jl_dims` (`company_id`,`contract_id`,`business_model`),
  KEY `ix_jl_party` (`company_id`,`counterparty_type`,`counterparty_id`),
  KEY `ix_jl_legacy` (`legacy_account_id`),
  CONSTRAINT `fk_fin_jl_acc` FOREIGN KEY (`account_id`) REFERENCES `fin_chart_of_accounts` (`id`),
  CONSTRAINT `fk_fin_jl_cc` FOREIGN KEY (`cost_center_id`) REFERENCES `fin_cost_centers` (`id`),
  CONSTRAINT `fk_fin_jl_entry` FOREIGN KEY (`entry_id`) REFERENCES `fin_journal_entries` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: fin_legacy_payment_aggregate ──
CREATE TABLE `fin_legacy_payment_aggregate` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `layer` varchar(8) NOT NULL DEFAULT 'LEGACY',
  `op_id` int(10) unsigned NOT NULL,
  `entity_id` int(10) unsigned NOT NULL DEFAULT 0,
  `period_label` varchar(40) NOT NULL DEFAULT '' COMMENT 'الفترة كما وردت في المصدر التاريخي',
  `paid_aggregate` decimal(18,2) NOT NULL DEFAULT 0.00 COMMENT 'المبلغ المدفوع مجمعا لا مفصلا',
  `ledger_rows` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'عدد صفوف الدفتر التي جمعها هذا السطر',
  `currency` varchar(8) NOT NULL DEFAULT '',
  `evidence_grade` varchar(16) NOT NULL DEFAULT '' COMMENT 'الحجية — documented او aggregate او asserted',
  `source_row_ref` varchar(160) NOT NULL DEFAULT '' COMMENT 'مرجع الصف في المصدر',
  `data_state` varchar(16) NOT NULL DEFAULT 'legacy',
  `allocatable` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'صفر دائما — المجمع لا يخصص كامر',
  `note` varchar(400) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_flpa_op` (`company_id`,`op_id`,`period_label`),
  CONSTRAINT `chk_flpa_layer` CHECK (`layer` = 'LEGACY'),
  CONSTRAINT `chk_flpa_evid` CHECK (`evidence_grade` <> '' and `source_row_ref` <> ''),
  CONSTRAINT `chk_flpa_alloc` CHECK (`allocatable` = 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='REPAIR01 W12 - الطبقة التاريخية المجمعة بحجيتها ومرجع صفها';

-- ── Table: fin_maint_provision_rules ──
CREATE TABLE `fin_maint_provision_rules` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `equipment_id` int(10) unsigned DEFAULT NULL COMMENT 'معدةٌ بعينها — NULL = القاعدةُ لنوعها أو الأعمّ',
  `equipment_type` int(10) unsigned DEFAULT NULL COMMENT 'نوعُ المعدة — NULL مع NULL أعلاه = الأعمّ',
  `basis` enum('hour','unit') NOT NULL COMMENT '«أساسُ المخصص (ساعة/وحدة)» — نصُّ #23',
  `rate` decimal(14,4) NOT NULL COMMENT 'معدلُ المخصص لوحدة الأساس',
  `currency` varchar(8) NOT NULL DEFAULT 'SDG' COMMENT 'لا جمعَ عملتين في رقم',
  `effective_from` date NOT NULL,
  `effective_to` date DEFAULT NULL,
  `state` enum('active','ended') NOT NULL DEFAULT 'active',
  `note` varchar(200) DEFAULT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_mprov_rule` (`company_id`,`equipment_id`,`equipment_type`,`basis`,`effective_from`),
  KEY `ix_mprov_rule_lookup` (`company_id`,`state`,`effective_from`,`effective_to`),
  CONSTRAINT `ck_mprov_rate` CHECK (`rate` > 0),
  CONSTRAINT `ck_mprov_span` CHECK (`effective_to` is null or `effective_to` >= `effective_from`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: fin_maint_provisions ──
CREATE TABLE `fin_maint_provisions` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `equipment_id` int(10) unsigned NOT NULL,
  `period_ref` varchar(10) NOT NULL COMMENT 'YYYY-MM',
  `rule_id` int(10) unsigned DEFAULT NULL COMMENT 'القاعدةُ التي احتُسب بها — «لا كتابةَ يدويةً»',
  `basis` enum('hour','unit') NOT NULL,
  `qty` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'من **وحدات المعدة المعتمدة** في الفترة',
  `rate` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `amount` decimal(18,2) NOT NULL DEFAULT 0.00 COMMENT '**محسوبٌ لا مُدخَل**: الكميةُ × المعدل',
  `currency` varchar(8) NOT NULL DEFAULT 'SDG',
  `event_id` int(11) DEFAULT NULL,
  `basis_json` text DEFAULT NULL,
  `source` enum('screen','cron') NOT NULL DEFAULT 'screen',
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_maint_provision` (`company_id`,`equipment_id`,`period_ref`) COMMENT '«بمفتاح (المعدة × الفترة)» بنيويًّا',
  KEY `ix_mprov_period` (`company_id`,`period_ref`),
  KEY `ix_mprov_event` (`event_id`),
  CONSTRAINT `ck_mprov_amount` CHECK (`amount` >= 0),
  CONSTRAINT `ck_mprov_rule_src` CHECK (`amount` = 0 or `rule_id` is not null)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: fin_margin_analysis ──
CREATE TABLE `fin_margin_analysis` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `run_code` varchar(16) NOT NULL COMMENT 'MRG-000001',
  `period` varchar(7) NOT NULL,
  `contract_id` int(11) DEFAULT NULL,
  `project_id` int(11) DEFAULT NULL,
  `unit_ref` varchar(32) NOT NULL DEFAULT '' COMMENT 'الوحدةُ إن كان الحسابُ بواقعة',
  `revenue_recognized` decimal(18,2) NOT NULL DEFAULT 0.00 COMMENT 'الإيرادُ المعترَف به',
  `cost_operators` decimal(18,2) NOT NULL DEFAULT 0.00 COMMENT '(حساس)',
  `cost_fuel` decimal(18,2) NOT NULL DEFAULT 0.00,
  `cost_maintenance` decimal(18,2) NOT NULL DEFAULT 0.00,
  `cost_inventory` decimal(18,2) NOT NULL DEFAULT 0.00,
  `cost_transfer` decimal(18,2) NOT NULL DEFAULT 0.00,
  `cost_financing` decimal(18,2) NOT NULL DEFAULT 0.00,
  `depreciation` decimal(18,2) NOT NULL DEFAULT 0.00,
  `total_cost` decimal(18,2) NOT NULL DEFAULT 0.00,
  `margin` decimal(18,2) NOT NULL DEFAULT 0.00 COMMENT '(حساس)',
  `margin_pct` decimal(9,4) DEFAULT NULL,
  `currency` varchar(8) NOT NULL DEFAULT 'SDG',
  `state` enum('computed','superseded') NOT NULL DEFAULT 'computed',
  `supersedes_id` int(10) unsigned DEFAULT NULL COMMENT 'إعادةُ احتسابٍ بعد تصحيح — نسخةٌ تشير لسابقتها',
  `computed_by` int(11) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `approved_by` int(11) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `authority_ref` varchar(120) NOT NULL DEFAULT '',
  `parent_ref` varchar(32) NOT NULL DEFAULT '',
  `idempotency_key` varchar(96) NOT NULL COMMENT '(الفترة×العقد×الوحدة×النسخة)',
  `cost_center_id` int(11) DEFAULT NULL,
  `fx_note` varchar(64) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_mrg_code` (`company_id`,`run_code`),
  UNIQUE KEY `uq_mrg_idem` (`company_id`,`idempotency_key`),
  KEY `ix_mrg_scope` (`company_id`,`period`,`contract_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='M-10 الشاشة ١٤: الهامشُ محسوبٌ من الاعترافات الثلاثة — وتظهر العقودُ الخاسرة';

-- ── Table: fin_migration_map ──
CREATE TABLE `fin_migration_map` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL DEFAULT 0 COMMENT 'بوابة المستأجر',
  `g443` varchar(190) DEFAULT NULL COMMENT 'النطاق',
  `g444` varchar(190) DEFAULT NULL COMMENT 'المصدر/الشيت السابق',
  `g445` varchar(190) DEFAULT NULL COMMENT 'العمود/الوصف',
  `g446` varchar(190) DEFAULT NULL COMMENT 'الوجهة/القرار',
  `g447` varchar(190) DEFAULT NULL COMMENT 'التصنيف',
  `g448` varchar(190) DEFAULT NULL COMMENT 'ملاحظة',
  `created_at` datetime DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_d768b0f4_co` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='FIN-27 - سطر خريطة ترحيل';

-- ── Table: fin_monthly_close ──
CREATE TABLE `fin_monthly_close` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `close_kind` varchar(16) NOT NULL DEFAULT 'MONTHLY',
  `close_code` varchar(40) NOT NULL COMMENT 'FMC',
  `op_id` int(10) unsigned NOT NULL,
  `entity_id` int(10) unsigned NOT NULL,
  `accounting_month` char(7) NOT NULL COMMENT 'YYYY-MM — الشهر التقويمي',
  `month_start` date NOT NULL,
  `month_end` date NOT NULL,
  `currency` varchar(8) NOT NULL,
  `contract_closes_n` smallint(5) unsigned NOT NULL DEFAULT 0 COMMENT 'عدد الاقفالات التعاقدية في الشهر',
  `open_balance` decimal(18,2) NOT NULL DEFAULT 0.00,
  `due_in_month` decimal(18,2) NOT NULL DEFAULT 0.00,
  `paid_in_month` decimal(18,2) NOT NULL DEFAULT 0.00,
  `allocated_in_month` decimal(18,2) NOT NULL DEFAULT 0.00,
  `unallocated_in_month` decimal(18,2) NOT NULL DEFAULT 0.00,
  `arrears_in_month` decimal(18,2) NOT NULL DEFAULT 0.00,
  `close_balance` decimal(18,2) NOT NULL DEFAULT 0.00,
  `rollforward_ok` tinyint(1) NOT NULL DEFAULT 0,
  `financier_stmt_match` varchar(16) NOT NULL DEFAULT 'unmatched' COMMENT 'unmatched او matched او disputed',
  `data_state` varchar(16) NOT NULL DEFAULT 'derived',
  `state` varchar(16) NOT NULL DEFAULT 'draft',
  `prepared_by` int(10) unsigned NOT NULL DEFAULT 0,
  `reviewed_by` int(10) unsigned NOT NULL DEFAULT 0,
  `approved_by` int(10) unsigned NOT NULL DEFAULT 0,
  `approved_at` datetime DEFAULT NULL,
  `note` varchar(400) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fmc_grain` (`company_id`,`op_id`,`accounting_month`,`currency`),
  UNIQUE KEY `uq_fmc_code` (`company_id`,`close_code`),
  KEY `ix_fmc_state` (`company_id`,`state`,`accounting_month`),
  CONSTRAINT `chk_fmc_kind` CHECK (`close_kind` = 'MONTHLY'),
  CONSTRAINT `chk_fmc_month` CHECK (dayofmonth(`month_start`) = 1 and `month_end` = last_day(`month_start`) and `accounting_month` = concat(year(`month_start`),'-',lpad(month(`month_start`),2,'0'))),
  CONSTRAINT `chk_fmc_cur` CHECK (`currency` <> ''),
  CONSTRAINT `chk_fmc_appr` CHECK (`state` <> 'approved' or `approved_by` > 0 and `approved_at` is not null and `approved_by` <> `prepared_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='REPAIR01 W12 - الاقفال الشهري - ممول × عملية × شهر تقويمي × عملة';

-- ── Table: fin_monthly_close_stmt ──
CREATE TABLE `fin_monthly_close_stmt` (
