  `start_date` date DEFAULT NULL COMMENT 'تاريخ بدء التفتيش',
  `start_time` time DEFAULT NULL COMMENT 'وقت البدء',
  `end_date` date DEFAULT NULL COMMENT 'تاريخ الانتهاء',
  `end_time` time DEFAULT NULL COMMENT 'وقت الانتهاء',
  `location` varchar(255) DEFAULT NULL COMMENT 'الموقع',
  `project_ref` varchar(255) DEFAULT NULL COMMENT 'المشروع ◄',
  `meter_reading` decimal(12,2) DEFAULT NULL COMMENT 'قراءة العداد',
  `last_meter` decimal(12,2) DEFAULT NULL COMMENT 'العداد بآخر تفتيش ◄',
  `hours_since_last` decimal(12,2) DEFAULT NULL COMMENT 'الساعات منذ آخر تفتيش ◄',
  `engine_state` varchar(80) DEFAULT NULL COMMENT 'حالة المحرك ▼',
  `hydraulic_state` varchar(80) DEFAULT NULL COMMENT 'النظام الهيدروليكي ▼',
  `transmission_state` varchar(80) DEFAULT NULL COMMENT 'ناقل الحركة ▼',
  `electrical_state` varchar(80) DEFAULT NULL COMMENT 'النظام الكهربائي ▼',
  `brakes_state` varchar(80) DEFAULT NULL COMMENT 'الفرامل ▼',
  `tires_tracks_state` varchar(80) DEFAULT NULL COMMENT 'الإطارات أو الجنازير ▼',
  `body_state` varchar(80) DEFAULT NULL COMMENT 'الجسم والهيكل ▼',
  `cabin_state` varchar(80) DEFAULT NULL COMMENT 'الكبينة ▼',
