-- ── Table: founding_mode ──
CREATE TABLE `founding_mode` (
  `mode_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `mode` enum('discovery','permission_test') NOT NULL,
  `enabled` tinyint(1) NOT NULL DEFAULT 0,
  `started_at` datetime DEFAULT NULL,
  `ends_at` datetime DEFAULT NULL COMMENT 'إلزامي عند التفعيل — لا وضع تأسيس مفتوح المدة',
  `banner_text` varchar(255) DEFAULT NULL,
  `closed_by` int(11) DEFAULT NULL,
  `closed_at` datetime DEFAULT NULL,
  `closure_ref` varchar(120) DEFAULT NULL,
  PRIMARY KEY (`mode_id`),
  UNIQUE KEY `uq_fm_mode` (`mode`),
  CONSTRAINT `chk_fm_ends` CHECK (`enabled` = 0 or `ends_at` is not null)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: gov_a11y_measurements ──
CREATE TABLE `gov_a11y_measurements` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `screen_file` varchar(190) NOT NULL,
  `component_version` varchar(32) NOT NULL COMMENT 'قياسٌ بإصدارٍ سابقٍ لا يُقرأ — المكتبةُ تغيّرت فالقياسُ لاغٍ',
  `checks_total` tinyint(3) unsigned NOT NULL DEFAULT 12,
  `violations_total` smallint(5) unsigned NOT NULL,
  `keyboard_modality` tinyint(1) NOT NULL COMMENT 'أضُغطت Tab حقيقيةٌ قبل القياس؟ بلا ذلك فحصُ التركيزِ لاغٍ',
  `detail_json` text NOT NULL COMMENT 'مخرَجُ المسبارِ كما هو — لا ملخَّصٌ مُعاد صوغُه',
  `measured_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_screen_ver` (`screen_file`,`component_version`),
  KEY `ix_ver` (`component_version`),
  CONSTRAINT `chk_a11y_modality` CHECK (`keyboard_modality` = 1 or `violations_total` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='الاثنا عشرَ فحصًا مقيسةً حيًّا — بإصدارِ المكوّنِ وشرطِ القياس';

-- ── Table: gov_alternate_authority ──
CREATE TABLE `gov_alternate_authority` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0,
  `when_requester_role_id` smallint(5) unsigned NOT NULL COMMENT 'الدورُ الذي يتعذّر اعتمادُه لنفسِه',
  `alternate_kind` enum('role','committee','board') NOT NULL DEFAULT 'committee',
  `alternate_role_id` smallint(5) unsigned DEFAULT NULL,
  `alternate_label` varchar(120) NOT NULL,
  `quorum` tinyint(3) unsigned NOT NULL DEFAULT 2 COMMENT 'يدان لا يد',
  `doc_ref` varchar(40) NOT NULL DEFAULT 'LAD-01',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_alt` (`company_id`,`when_requester_role_id`),
  CONSTRAINT `chk_alt_independent` CHECK (`alternate_role_id` is null or `alternate_role_id` <> `when_requester_role_id`),
  CONSTRAINT `chk_alt_quorum` CHECK (`quorum` >= 2)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='② جهةُ اعتمادٍ بديلةٌ مستقلة — فلا يكون الرئيسُ معتمِدًا وحيدًا وممنوعًا معًا';

-- ── Table: gov_appearance_gaps ──
CREATE TABLE `gov_appearance_gaps` (
  `route` varchar(190) NOT NULL,
  `owner_dept` varchar(120) NOT NULL COMMENT 'المالكُ المؤكَّدُ بالشاهد',
  `seen_in` varchar(190) NOT NULL DEFAULT '' COMMENT 'المساحةُ الوحيدةُ التي تظهر فيها اليوم',
  `basis` varchar(400) NOT NULL DEFAULT '',
  `state` enum('OPEN','OWNER_DECIDED','CLOSED') NOT NULL DEFAULT 'OPEN',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`route`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='مِلكيةٌ صحيحةٌ وظهورٌ ناقصٌ في مساحةِ المالك — دَينٌ لا يُغلَق تلقائيًّا';

-- ── Table: gov_approval_decisions ──
CREATE TABLE `gov_approval_decisions` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `decision_code` varchar(16) NOT NULL COMMENT 'APD-000001',
  `source_kind` enum('fin_request','supplier_settlement','journal_entry','period_close','other') NOT NULL COMMENT 'الصندوقُ الموحَّد يجمع من مصادرَ أربعة — والقرارُ بخدمة مصدره',
  `source_ref` varchar(64) NOT NULL COMMENT 'مرجعُ المستند في مصدره',
  `decision` enum('rejected','returned','withdrawn_decision') NOT NULL COMMENT 'rejected: رفضٌ بسبب · returned: إعادةٌ للتصحيح',
  `reason_code` varchar(32) NOT NULL DEFAULT '' COMMENT 'السببُ المحكوم: RSN-BUDGET · RSN-DOCS · RSN-AUTH · RSN-DUP · RSN-DATA · RSN-OTHER',
  `reason_note` varchar(255) NOT NULL DEFAULT '' COMMENT 'بيانُ السبب — إلزاميٌّ مع RSN-OTHER',
  `ring_no` tinyint(3) unsigned NOT NULL DEFAULT 1 COMMENT 'الحلقةُ في السلسلة عند القرار',
  `decided_by` int(11) NOT NULL COMMENT 'المعتمِدُ صاحبُ القرار',
  `decided_capacity` varchar(120) NOT NULL DEFAULT '' COMMENT 'صفتُه من المسمى الحي — لا الاسم',
  `authority_ref` varchar(120) NOT NULL DEFAULT '' COMMENT '§9-1 مرجعُ التفويض',
  `parent_ref` varchar(64) NOT NULL DEFAULT '' COMMENT 'المرجعُ الأب — المستندُ المقرَّرُ فيه',
  `event_id` int(11) DEFAULT NULL COMMENT 'ApprovalRejected/ApprovalReturned في الممر المحايد',
  `state` enum('effective','superseded') NOT NULL DEFAULT 'effective',
  `superseded_by_ref` varchar(16) NOT NULL DEFAULT '' COMMENT 'إعادةُ رفعٍ بعد التصحيح — دورةٌ جديدة',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `idempotency_key` varchar(96) NOT NULL COMMENT '(المصدرُ×المرجعُ×القرارُ×الحلقة)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_apd_code` (`company_id`,`decision_code`),
  UNIQUE KEY `uq_apd_idem` (`company_id`,`idempotency_key`),
  KEY `ix_apd_source` (`company_id`,`source_kind`,`source_ref`),
  KEY `ix_apd_reason` (`company_id`,`reason_code`) COMMENT 'السببُ يُقاس في تحليل الاختناقات'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='M-14 approval.reject/return: القرارُ بسببٍ محكومٍ يُقاس — وسجلُّه لا يُعدَّل';

-- ── Table: gov_audit_followup ──
CREATE TABLE `gov_audit_followup` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `followup_no` varchar(40) NOT NULL,
  `finding_no` varchar(40) NOT NULL DEFAULT '' COMMENT 'مرجع لا نسخة - والنتيجة تبقى عند المراجعة',
  `finding_source` varchar(16) NOT NULL DEFAULT '' COMMENT 'داخلية ام خارجية',
  `mgmt_plan_ar` varchar(600) NOT NULL DEFAULT '',
  `plan_owner_dept` varchar(12) NOT NULL DEFAULT '',
  `plan_due` date DEFAULT NULL,
  `recurrence_no` smallint(6) NOT NULL DEFAULT 1,
  `action_no` varchar(40) NOT NULL DEFAULT '',
  `follow_state` varchar(24) NOT NULL DEFAULT 'tracking',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `finding_ar` varchar(600) DEFAULT NULL COMMENT 'النتيجة',
  `finding_class` varchar(40) DEFAULT NULL COMMENT 'التصنيف',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gaf` (`company_id`,`followup_no`),
  KEY `ix_gaf_find` (`finding_no`),
  CONSTRAINT `chk_gaf_ref` CHECK (`finding_no` <> ''),
  CONSTRAINT `chk_gaf_src` CHECK (`finding_source` in ('internal','external')),
  CONSTRAINT `chk_gaf_state` CHECK (`follow_state` in ('tracking','overdue','escalated','plan_done')),
  CONSTRAINT `chk_gaf_plan` CHECK (`mgmt_plan_ar` = '' or `plan_owner_dept` <> '' and `plan_due` is not null)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 GOV-26 - الحوكمة تتابع خطة الادارة ولا تملك نتيجة المراجعة';

-- ── Table: gov_authority_grants ──
CREATE TABLE `gov_authority_grants` (
  `grant_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0,
  `user_id` int(11) NOT NULL,
  `profile_id` int(10) unsigned NOT NULL,
  `source` enum('profile','escalation','delegation','elevation') NOT NULL,
  `elevation_id` int(10) unsigned DEFAULT NULL COMMENT 'إلزاميٌّ حين المصدرُ رفعٌ — chk_grant_source',
  `delegation_id` int(10) unsigned DEFAULT NULL,
  `valid_from` datetime NOT NULL DEFAULT current_timestamp(),
  `valid_to` datetime DEFAULT NULL COMMENT 'NULL لقالبِ الأصلِ وحدَه — chk_temp_has_end',
  `issued_by` int(11) NOT NULL COMMENT 'الجهةُ المانحة — حصرًا أدوارُ الحوكمة (قادحُ trg_grant_issuer)',
  `reason` varchar(255) NOT NULL DEFAULT '',
  `revoked_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`grant_id`),
  KEY `ix_user` (`user_id`,`valid_to`),
  KEY `ix_profile` (`profile_id`),
  CONSTRAINT `fk_ag_profile` FOREIGN KEY (`profile_id`) REFERENCES `gov_role_profiles` (`profile_id`),
  CONSTRAINT `chk_temp_has_end` CHECK (`source` = 'profile' or `valid_to` is not null),
  CONSTRAINT `chk_grant_source` CHECK (`source` <> 'elevation' or `elevation_id` is not null),
  CONSTRAINT `chk_no_single_hand` CHECK (`source` = 'profile' or `issued_by` <> `user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GOV-AUTH-01 — المنحُ الفعليُّ بمصادرِه الأربعةِ لا خامسَ لها';

-- ── Table: gov_authority_limits ──
CREATE TABLE `gov_authority_limits` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '0 = مرجعٌ عامٌّ لكلِّ الكيانات',
  `doc_code` varchar(24) NOT NULL COMMENT 'الوثيقةُ التي تُعلن الحد',
  `code` varchar(24) NOT NULL COMMENT 'LIMIT-01 ..',
  `seq` smallint(5) unsigned NOT NULL DEFAULT 0,
  `subject_role` varchar(120) NOT NULL DEFAULT '' COMMENT 'من لا يملك — كما تسميه الوثيقة',
  `role_ids` varchar(60) NOT NULL DEFAULT '' COMMENT 'أدوارُه مفصولةً بفاصلة',
  `forbidden` varchar(300) NOT NULL COMMENT 'الفعلُ الممنوع',
  `action_codes` varchar(400) NOT NULL DEFAULT '' COMMENT 'رموزُ الأفعالِ التي يمنعها هذا الحدُّ — والفارغُ لا يمنع فعلًا بعينِه',
  `enforced_by` varchar(200) NOT NULL DEFAULT '' COMMENT '◆ المُنفِذُ الحي — والفارغُ دعوى لا قيد',
  `enforce_kind` enum('service','guard','schema','permission','manual','none') NOT NULL DEFAULT 'none',
  `limit_kind` enum('absolute','conditional') NOT NULL DEFAULT 'conditional' COMMENT 'FN-09 · مطلقٌ يُوصَل برمزِ فعلٍ · مشروطٌ لا يُوصَل ويُفحص شرطُه في الخدمة',
  `condition_note` varchar(300) NOT NULL DEFAULT '' COMMENT 'الشرطُ الذي يجعل الفعلَ ممنوعًا — يُفحص في الخدمةِ لا في الحارس',
  `accept_test` varchar(300) NOT NULL DEFAULT '',
  `doc_ref` varchar(24) NOT NULL DEFAULT '',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_lim` (`company_id`,`doc_code`,`code`),
  KEY `ix_enf` (`enforce_kind`,`active`),
  CONSTRAINT `chk_gal_conditional_unwired` CHECK (`limit_kind` <> 'conditional' or `action_codes` is null or `action_codes` = '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='الوثائقُ الخمس — الحدودُ الصريحةُ «ما لا يملكه» بمُنفِذِ كلٍّ';

-- ── Table: gov_breach ──
CREATE TABLE `gov_breach` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `case_no` varchar(40) NOT NULL COMMENT 'Governance_Case_ID',
  `opened_basis` varchar(32) NOT NULL DEFAULT '',
  `control_ref` varchar(64) NOT NULL DEFAULT '' COMMENT 'الضابط المكسور - لا يفتح بلا ضابط',
  `policy_no` varchar(40) NOT NULL DEFAULT '',
  `obligation_no` varchar(40) NOT NULL DEFAULT '',
  `deviation_no` varchar(40) NOT NULL DEFAULT '' COMMENT 'مرجع الانحراف لا نسخته',
  `severity` varchar(16) NOT NULL DEFAULT '',
  `title_ar` varchar(255) NOT NULL DEFAULT '',
  `opened_by` int(11) NOT NULL DEFAULT 0,
  `opened_at` datetime DEFAULT NULL,
  `investigation_no` varchar(40) NOT NULL DEFAULT '',
  `action_no` varchar(40) NOT NULL DEFAULT '',
  `closed_by` int(11) NOT NULL DEFAULT 0,
  `closed_at` datetime DEFAULT NULL,
  `close_evidence` varchar(200) NOT NULL DEFAULT '',
  `state` varchar(24) NOT NULL DEFAULT 'opened',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `impact_ar` varchar(400) DEFAULT NULL COMMENT 'الأثر المقدر',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gvb` (`company_id`,`case_no`),
  KEY `ix_gvb_dev` (`deviation_no`),
  CONSTRAINT `chk_gvb_basis` CHECK (`opened_basis` in ('MANDATORY_STEP_IGNORED','NO_ESCALATION','AUTHORITY_EXCEEDED','MANIPULATION','CONCEALMENT','FORGERY','POLICY_BREACH','CONTROL_BROKEN')),
  CONSTRAINT `chk_gvb_control` CHECK (`control_ref` <> '' or `policy_no` <> '' or `obligation_no` <> ''),
  CONSTRAINT `chk_gvb_severity` CHECK (`severity` in ('low','medium','high','critical')),
  CONSTRAINT `chk_gvb_state` CHECK (`state` in ('opened','investigated','action_assigned','remediated','closed','reopened')),
  CONSTRAINT `chk_gvb_close` CHECK (`state` <> 'closed' or `action_no` <> '' and `close_evidence` <> '' and `closed_by` <> 0),
  CONSTRAINT `chk_gvb_hands` CHECK (`closed_by` = 0 or `closed_by` <> `opened_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 GOV-24 - حالة الحوكمة باساس من الثمانية ولا تفتح لانحراف صرف';

-- ── Table: gov_cap_history ──
CREATE TABLE `gov_cap_history` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0,
  `ladder_code` varchar(10) NOT NULL COMMENT 'LD-01..LD-20',
  `cap_amount` decimal(16,2) DEFAULT NULL COMMENT 'NULL = غيرُ محسومٍ (يوقف)',
  `cap_currency` varchar(8) NOT NULL DEFAULT 'USD',
  `effective_from` datetime NOT NULL COMMENT 'يسري على ما يُنشأ بعدَه فقط',
  `changed_by` int(11) NOT NULL COMMENT 'باعتمادِ المالكِ وحدَه — يفرضه القادح',
  `reason` varchar(300) NOT NULL COMMENT 'لماذا — يُقرأ بعدَ سنة',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_ladder` (`ladder_code`,`effective_from`),
  CONSTRAINT `chk_cap_reason` CHECK (`reason` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='قرارُ المالكِ ⑥ — سقوفٌ مرنةٌ بسجلٍّ لا يُحذف: من غيَّر ومتى ولماذا';

-- ── Table: gov_cap_proposals ──
CREATE TABLE `gov_cap_proposals` (
  `ladder_code` varchar(12) NOT NULL,
  `proposed_amount` decimal(16,2) DEFAULT NULL COMMENT 'NULL = لا سكّانَ للاشتقاق — لا يُخترع رقم',
  `currency` varchar(8) NOT NULL DEFAULT 'USD',
  `pop_n` int(11) NOT NULL,
  `p50` decimal(16,2) DEFAULT NULL,
  `p90` decimal(16,2) DEFAULT NULL,
  `p95` decimal(16,2) DEFAULT NULL,
  `p99` decimal(16,2) DEFAULT NULL,
  `pmax` decimal(16,2) DEFAULT NULL,
  `basis` varchar(600) NOT NULL COMMENT 'أساسُ الاشتقاقِ كاملًا — لا رقمَ بلا مصدر',
  `measured_at` datetime NOT NULL,
  `applied_at` datetime DEFAULT NULL COMMENT 'يُملأ حين يعتمده المالكُ من الشاشة',
  PRIMARY KEY (`ladder_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='مقترحاتُ السقوفِ المشتقةُ آليًّا — تُعرض في شاشةِ حدودِ المبالغِ ويعتمدها المالك';

-- ── Table: gov_chain_nodes ──
CREATE TABLE `gov_chain_nodes` (
  `node_no` tinyint(3) unsigned NOT NULL,
  `declared_file` varchar(64) NOT NULL,
  `title_ar` varchar(120) NOT NULL,
  `technical_runtime` varchar(80) NOT NULL COMMENT 'أين تعيش الخدمة — وصفٌ هندسيٌّ لا ملكية',
  `process_owner` varchar(80) NOT NULL COMMENT 'مالكُ الحدثِ أو المستند',
  `embedded_accountant` varchar(80) DEFAULT NULL COMMENT 'المحاسبُ المنتدبُ — يراجع ويهيّئ ولا يعتمد',
  `ladder_id` varchar(48) NOT NULL COMMENT 'LD-nn | NO_LADDER_REQUIRED | RESOLVE_FROM_POLICY:key',
  `accounting_control` varchar(80) DEFAULT NULL COMMENT 'إجازةٌ مستقلةٌ تسبق الترحيل',
  `cash_execution` varchar(80) DEFAULT NULL COMMENT 'الخزينةُ — ولا تملك قيدًا',
  `gl_posting_approval` varchar(80) DEFAULT NULL COMMENT 'السلطةُ البشريةُ التي تُجيز الترحيل',
  `gl_posting_executor` varchar(80) DEFAULT NULL COMMENT 'محرّكُ الترحيلِ وحدَه — لا كاتبَ بشريّ',
  `instance_scope` varchar(24) DEFAULT NULL COMMENT 'عقدٌ يشترك في نسخةِ سلّمٍ واحدةٍ مع غيرِه',
  `build_state` enum('BUILT','UNDER_OTHER_ROUTE','MISSING') NOT NULL,
  `carrier_route` varchar(160) DEFAULT NULL COMMENT 'السطحُ الحاملُ إن كان باسمٍ آخر',
  `build_wave` tinyint(3) unsigned DEFAULT NULL,
  `governing_doc` varchar(32) NOT NULL DEFAULT 'INJ-CHAIN-CLOSE-01',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`node_no`),
  KEY `ix_state` (`build_state`),
  KEY `ix_ladder` (`ladder_id`),
  CONSTRAINT `chk_chain_ladder_code` CHECK (`ladder_id` = 'NO_LADDER_REQUIRED' or `ladder_id` regexp '^LD-[0-9]{2}$' or `ladder_id` regexp '^RESOLVE_FROM_POLICY:[a-z_]+$')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='INJ-CHAIN-CLOSE-01 — 29 عقدةً بثماني خاناتِ ملكية';

-- ── Table: gov_chain_state_corrections ──
CREATE TABLE `gov_chain_state_corrections` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `entry_id` int(10) unsigned NOT NULL,
  `entry_no` varchar(30) DEFAULT NULL,
  `state_before` varchar(24) NOT NULL,
  `state_after` varchar(24) NOT NULL,
  `reason` varchar(400) NOT NULL,
  `evidence` varchar(300) NOT NULL COMMENT 'ما قِيس في المصبِّ قبلَ التصحيح',
  `corrected_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_csc_entry` (`entry_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='INJ-CHAIN-CLOSE-01 — تصحيحُ حالةٍ بلغت بلا سلّمِها · بالحالةِ السابقةِ ودليلِها';

-- ── Table: gov_committee ──
CREATE TABLE `gov_committee` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `committee_code` varchar(40) NOT NULL,
  `name_ar` varchar(200) NOT NULL DEFAULT '',
  `mandate_ar` varchar(600) NOT NULL DEFAULT '',
  `charter_ref` varchar(120) NOT NULL DEFAULT '',
  `chair_person` int(11) NOT NULL DEFAULT 0,
  `member_count` smallint(6) NOT NULL DEFAULT 0,
  `quorum_key` varchar(64) NOT NULL DEFAULT '' COMMENT 'مفتاح النصاب في السجل - ولا رقم هنا',
  `meeting_cycle` varchar(24) NOT NULL DEFAULT '',
  `authority_rule_id` varchar(48) NOT NULL DEFAULT '',
  `state` varchar(24) NOT NULL DEFAULT 'formed',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gcm` (`company_id`,`committee_code`),
  CONSTRAINT `chk_gcm_state` CHECK (`state` in ('formed','active','suspended','dissolved')),
  CONSTRAINT `chk_gcm_cycle` CHECK (`meeting_cycle` in ('weekly','monthly','quarterly','semiannual','annual','on_call')),
  CONSTRAINT `chk_gcm_active` CHECK (`state` <> 'active' or `charter_ref` <> '' and `chair_person` <> 0 and `member_count` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 GOV-30 - اللجان النافذة بتشكيلها وصلاحياتها ودوريتها';

-- ── Table: gov_compliance_due ──
CREATE TABLE `gov_compliance_due` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `obligation_no` varchar(40) NOT NULL,
  `due_date` date NOT NULL,
  `owner_dept` varchar(12) NOT NULL DEFAULT '',
  `owner_person` int(11) NOT NULL DEFAULT 0,
  `derived_from` varchar(48) NOT NULL DEFAULT '' COMMENT 'مشتق من الالتزام او الترخيص او الاقرار',
  `settled_ref` varchar(64) NOT NULL DEFAULT '',
  `state` varchar(24) NOT NULL DEFAULT 'due',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `due_no` varchar(40) DEFAULT NULL COMMENT 'معرف الاستحقاق',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gcd` (`company_id`,`obligation_no`,`due_date`),
  CONSTRAINT `chk_gcd_state` CHECK (`state` in ('due','met','late','waived')),
  CONSTRAINT `chk_gcd_derived` CHECK (`derived_from` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 GOV-05 - تقويم الامتثال مشتق بمرجع اشتقاقه';

-- ── Table: gov_component_versions ──
CREATE TABLE `gov_component_versions` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `version_tag` varchar(24) NOT NULL COMMENT 'مثال: ux-1.0.0',
  `fingerprint` char(64) NOT NULL COMMENT 'sha256 لملفاتِ المكتبةِ مجتمعة',
  `files_json` text NOT NULL COMMENT 'الملفاتُ الداخلةُ في البصمةِ وبصمةُ كلٍّ',
  `state` enum('DRAFT','PROMOTED','SUPERSEDED') NOT NULL DEFAULT 'DRAFT' COMMENT 'PROMOTED غيرُ قابلٍ للتعديل — التغييرُ ينشئ إصدارًا جديدًا',
  `promoted_at` datetime DEFAULT NULL,
  `note` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_tag` (`version_tag`),
  UNIQUE KEY `uq_fp` (`fingerprint`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='إصداراتُ مكتبةِ المكوّنات — المرقَّى ثابتٌ ولا يُعدَّل في صمت';

-- ── Table: gov_conduct_ack ──
CREATE TABLE `gov_conduct_ack` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `employee_id` int(11) NOT NULL DEFAULT 0,
  `code_version` varchar(24) NOT NULL DEFAULT '',
  `policy_no` varchar(40) NOT NULL DEFAULT '',
  `due_date` date DEFAULT NULL,
  `acked_at` datetime DEFAULT NULL,
  `evidence_ref` varchar(120) NOT NULL DEFAULT '',
  `state` varchar(24) NOT NULL DEFAULT 'due',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `ack_no` varchar(40) DEFAULT NULL COMMENT 'معرف الإقرار',
  `ack_channel` varchar(24) DEFAULT NULL COMMENT 'قناة الإقرار',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gca` (`company_id`,`employee_id`,`code_version`),
  CONSTRAINT `chk_gca_state` CHECK (`state` in ('due','acknowledged','overdue','exempt')),
  CONSTRAINT `chk_gca_ack` CHECK (`state` <> 'acknowledged' or `acked_at` is not null and `evidence_ref` <> ''),
  CONSTRAINT `chk_gca_emp` CHECK (`employee_id` <> 0 and `code_version` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 GOV-13 - اقرار مدونة السلوك عند التعيين وعند كل اصدار';

-- ── Table: gov_conflict_disclosure ──
CREATE TABLE `gov_conflict_disclosure` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `disclosure_no` varchar(40) NOT NULL,
  `person_id` int(11) NOT NULL DEFAULT 0,
  `nature_ar` varchar(400) NOT NULL DEFAULT '',
  `counterparty_ar` varchar(200) NOT NULL DEFAULT '',
  `related_party_no` varchar(40) NOT NULL DEFAULT '',
  `disclosed_at` datetime DEFAULT NULL,
  `assessed_by` int(11) NOT NULL DEFAULT 0,
  `decision` varchar(24) NOT NULL DEFAULT '',
  `decision_ref` varchar(120) NOT NULL DEFAULT '',
  `recused_from` varchar(255) NOT NULL DEFAULT '' COMMENT 'القرار الذي تنحى عنه صاحب الافصاح',
  `state` varchar(24) NOT NULL DEFAULT 'disclosed',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `relation_ar` varchar(200) DEFAULT NULL COMMENT 'العلاقة',
  `controls_ar` varchar(400) DEFAULT NULL COMMENT 'الضوابط المفروضة',
  `approved_at` datetime DEFAULT NULL COMMENT 'تاريخ الاعتماد',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gcf` (`company_id`,`disclosure_no`),
  CONSTRAINT `chk_gcf_person` CHECK (`person_id` <> 0),
  CONSTRAINT `chk_gcf_state` CHECK (`state` in ('disclosed','assessed','mitigated','recused','rejected','closed')),
  CONSTRAINT `chk_gcf_decision` CHECK (`decision` in ('','mitigate','recuse','reject')),
  CONSTRAINT `chk_gcf_self` CHECK (`assessed_by` = 0 or `assessed_by` <> `person_id`),
  CONSTRAINT `chk_gcf_recusal` CHECK (`decision` <> 'recuse' or `recused_from` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 GOV-10 - الافصاح واجب والقرار للحوكمة ولا يقرر صاحبه';

-- ── Table: gov_corrective_action ──
CREATE TABLE `gov_corrective_action` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `action_no` varchar(40) NOT NULL,
  `source_kind` varchar(24) NOT NULL DEFAULT '',
  `source_ref` varchar(64) NOT NULL DEFAULT '',
  `title_ar` varchar(255) NOT NULL DEFAULT '',
  `owner_dept` varchar(12) NOT NULL DEFAULT '',
  `owner_person` int(11) NOT NULL DEFAULT 0,
  `due_date` date DEFAULT NULL,
  `assigned_by` int(11) NOT NULL DEFAULT 0,
  `evidence_ref` varchar(200) NOT NULL DEFAULT '',
  `verified_by` int(11) NOT NULL DEFAULT 0,
  `verified_at` datetime DEFAULT NULL,
  `escalation_level` tinyint(4) NOT NULL DEFAULT 0,
  `state` varchar(24) NOT NULL DEFAULT 'assigned',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gca2` (`company_id`,`action_no`),
  CONSTRAINT `chk_gac_source` CHECK (`source_kind` in ('BREACH','INVESTIGATION','AUDIT_FINDING','RISK_TREATMENT','EXCEPTION')),
  CONSTRAINT `chk_gac_ref` CHECK (`source_ref` <> ''),
  CONSTRAINT `chk_gac_owner` CHECK (`owner_dept` <> '' and `owner_person` <> 0 and `due_date` is not null),
  CONSTRAINT `chk_gac_state` CHECK (`state` in ('assigned','in_progress','evidence_submitted','verified','closed','overdue')),
  CONSTRAINT `chk_gac_close` CHECK (`state` not in ('verified','closed') or `evidence_ref` <> '' and `verified_by` <> 0),
  CONSTRAINT `chk_gac_hands` CHECK (`verified_by` = 0 or `verified_by` <> `owner_person`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 GOV-25 - كل اجراء بمالك ومهلة ودليل اغلاق';

-- ── Table: gov_cycle_consumers_backup ──
CREATE TABLE `gov_cycle_consumers_backup` (
  `cycle_id` int(10) unsigned NOT NULL,
  `consumers_before` varchar(255) NOT NULL,
  `swept_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`cycle_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: gov_cycle_name_log ──
CREATE TABLE `gov_cycle_name_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `row_id` int(11) NOT NULL,
  `field` varchar(32) NOT NULL,
  `old_value` varchar(255) NOT NULL,
  `new_value` varchar(255) NOT NULL,
  `requirement_id` varchar(32) NOT NULL,
  `changed_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `k_row` (`row_id`),
  KEY `k_req` (`requirement_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: gov_dashboard_kpi ──
CREATE TABLE `gov_dashboard_kpi` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL DEFAULT 0,
  `kpi_id` varchar(60) DEFAULT NULL COMMENT 'معرف المؤشر',
  `kpi_ref` varchar(255) DEFAULT NULL COMMENT 'المؤشر - KPI Catalog',
  `value` decimal(18,2) DEFAULT NULL COMMENT 'القيمة',
  `uom` varchar(80) DEFAULT NULL COMMENT 'الوحدة',
  `state` varchar(255) DEFAULT NULL COMMENT 'الحالة',
  `updated_on` datetime DEFAULT NULL COMMENT 'اخر تحديث',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_govkpi_co` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='DEP-08 GOV-01 - لوحة الحوكمة والالتزام - الحبة: مؤشر واحد لفترة واحدة';

-- ── Table: gov_data_classes ──
CREATE TABLE `gov_data_classes` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '0 = مرجعٌ عامٌّ لكلِّ الكيانات',
  `code` varchar(6) NOT NULL COMMENT 'DC-1..DC-4',
  `title` varchar(120) NOT NULL,
  `name_en` varchar(120) NOT NULL DEFAULT '',
  `meaning` varchar(400) NOT NULL DEFAULT '',
  `examples` varchar(700) NOT NULL DEFAULT '',
  `owner_label` varchar(200) NOT NULL DEFAULT '',
  `create_roles` varchar(120) NOT NULL DEFAULT '' COMMENT 'فارغٌ = الإدارةُ المالكةُ للمستند',
  `edit_roles` varchar(120) NOT NULL DEFAULT '' COMMENT 'فارغٌ = لا أحدَ يعدّل مباشرةً',
  `read_roles` varchar(120) NOT NULL DEFAULT '' COMMENT 'فارغٌ = بحسبِ صلاحيةِ الشاشة',
  `edit_mode` enum('direct','proposal','amendment_only','decision_only') NOT NULL DEFAULT 'direct' COMMENT 'كيف يتغير: مباشرةً · اقتراحًا · بملحقٍ موقَّع · بقرارٍ معتمد',
  `doc_ref` varchar(24) NOT NULL DEFAULT '',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_dc` (`company_id`,`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='FIN-OBL-01 §4-17 — التصنيفُ الرباعيُّ للبيانات';

-- ── Table: gov_dead_letter_rulings ──
CREATE TABLE `gov_dead_letter_rulings` (
  `job_id` bigint(20) NOT NULL,
  `job_type` varchar(64) NOT NULL,
  `ruling` varchar(32) NOT NULL COMMENT 'TEST_POLLUTION · RETRY · DROP · NEEDS_GOVERNING_SOURCE',
  `owner_role` varchar(64) NOT NULL,
  `reason` varchar(400) NOT NULL,
  `evidence` varchar(300) NOT NULL,
  `ruled_at` datetime NOT NULL,
  PRIMARY KEY (`job_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='FR-EVT-007 — لا رسالةَ ميتةً بلا قرارٍ ومالكٍ وسبب';

-- ── Table: gov_decision_propagation ──
CREATE TABLE `gov_decision_propagation` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `decision_id` varchar(32) NOT NULL,
  `verdict` enum('RUNTIME_VERIFIED','RUNTIME_PRESENT','TARGET_PROPAGATED_BUILD_PENDING','BLOCKED_OWNER_VALUES','BLOCKED_ENVIRONMENT','UNPROPAGATED') NOT NULL,
  `probe_kind` varchar(40) NOT NULL COMMENT 'TABLE_PROBE/ENGINE_FILE/REQ_LEDGER/MANUAL/…',
  `probe_ref` varchar(400) NOT NULL COMMENT 'اسمُ الجدولِ/الملفِّ/الشاهدِ الذي سُبر',
  `basis` varchar(500) NOT NULL,
  `measured_at` datetime NOT NULL DEFAULT current_timestamp(),
  `snapshot_id` varchar(48) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_dec` (`decision_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GOV_EXEC §8: حكمُ نفاذِ كلِّ قرارٍ معتمدٍ بمجسِّه — APPROVED_DECISION_WITH_UNPROPAGATED_IMPACT يقاس منه';

-- ── Table: gov_delegation_state ──
CREATE TABLE `gov_delegation_state` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `pathway` varchar(48) NOT NULL COMMENT 'DELEGATION | ESCALATION',
  `store` varchar(64) NOT NULL,
  `rows_live` int(10) unsigned NOT NULL,
  `readers` varchar(300) NOT NULL COMMENT 'قرّاءُ الإنتاجِ المقيسون',
  `verdict` varchar(32) NOT NULL COMMENT 'LIVE_READABLE | DORMANT',
  `note` varchar(400) NOT NULL,
  `measured_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_store` (`store`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GAP-03 — حالةُ مساراتِ التفويضِ والتصعيدِ مقيسةً بالبياناتِ والقرّاء';

-- ── Table: gov_delegations ──
CREATE TABLE `gov_delegations` (
  `delegation_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0,
  `from_user` int(11) NOT NULL,
  `to_user` int(11) NOT NULL,
  `scope_json` text NOT NULL COMMENT 'نطاقُ التفويض — أفعالٌ وشاشاتٌ وسقوف',
  `valid_from` datetime NOT NULL DEFAULT current_timestamp(),
  `valid_to` datetime NOT NULL COMMENT 'إلزاميٌّ — المؤقَّتُ ينتهي بنفسِه (A6)',
  `reason` varchar(255) NOT NULL,
  `revoked_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`delegation_id`),
  KEY `ix_to` (`to_user`,`valid_to`),
  KEY `ix_from` (`from_user`),
  CONSTRAINT `chk_deleg_reason` CHECK (`reason` <> '' and `valid_to` > `valid_from`),
  CONSTRAINT `chk_deleg_not_self` CHECK (`from_user` <> `to_user`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GOV-AUTH-01 §6 — التفويضُ المؤقَّتُ بمدّةٍ وسببٍ إلزاميَّين';

-- ── Table: gov_denial_reviews ──
CREATE TABLE `gov_denial_reviews` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `review_code` varchar(16) NOT NULL COMMENT 'DNR-000001',
  `denial_id` int(11) NOT NULL COMMENT 'guard_denials.deny_id — المحاولةُ المرصودة',
  `guard_code` varchar(64) NOT NULL DEFAULT '' COMMENT 'رمزُ الحارس الذي منع',
  `classification` enum('يحتاج استثناءً','خطأ تصنيف حماية','محاولة تجاوز','عابر — لا إجراء') NOT NULL COMMENT 'التصنيفُ الثلاثي + العابر — §7-2 denial.review',
  `decision_note` varchar(255) NOT NULL DEFAULT '' COMMENT 'قرارُ المراجعة وتسبيبه',
  `follow_up_ref` varchar(64) NOT NULL DEFAULT '' COMMENT 'الأثرُ التالي: رقمُ طلب استثناءٍ أو تصحيحِ تصنيفٍ أو بلاغ',
  `state` enum('open','closed') NOT NULL DEFAULT 'open',
  `reviewed_by` int(11) NOT NULL COMMENT '§9-1 المُنشئ — المراجِع',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `closed_by` int(11) DEFAULT NULL,
  `closed_at` datetime DEFAULT NULL,
  `authority_ref` varchar(120) NOT NULL DEFAULT '',
  `parent_ref` varchar(32) NOT NULL DEFAULT '' COMMENT 'المرجعُ الأب — رقمُ المحاولة',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_dnr_code` (`company_id`,`review_code`),
  UNIQUE KEY `uq_dnr_denial` (`company_id`,`denial_id`) COMMENT 'مراجعةٌ واحدةٌ للمحاولة — والتحديثُ عليها',
  KEY `ix_dnr_state` (`company_id`,`state`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='M-14 denial.review: المنعُ المتكرر يُراجَع ويُصنَّف — لا يُترك صامتًا';

-- ── Table: gov_dept_propagation ──
CREATE TABLE `gov_dept_propagation` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0,
  `dept_name` varchar(120) NOT NULL,
  `propagated` smallint(5) unsigned NOT NULL DEFAULT 0 COMMENT 'أحكامٌ منتشرةٌ عليها',
  `dept_total` smallint(5) unsigned NOT NULL DEFAULT 0 COMMENT 'إجماليُّ أحكامِها',
  `doors_note` varchar(300) NOT NULL DEFAULT '' COMMENT 'الأبوابُ الثمانيةُ التي تمسُّها',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_dept` (`company_id`,`dept_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PROP-01 §6-1 — الأحكامُ المنتشرةُ في الإداراتِ الستَّ عشرة';

-- ── Table: gov_doc_registry ──
CREATE TABLE `gov_doc_registry` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '0 = يخصُّ الوثيقةَ لا الكيان',
  `doc_code` varchar(24) NOT NULL COMMENT 'الوثيقةُ المعلِنة',
  `family` varchar(16) NOT NULL COMMENT 'DUTY · LIMIT · COMP · SCEN · CYCLE …',
  `item_code` varchar(24) NOT NULL COMMENT 'رمزُ البندِ داخلَ عائلته',
  `seq` smallint(5) unsigned NOT NULL DEFAULT 0,
  `title` varchar(300) NOT NULL,
  `detail` varchar(500) NOT NULL DEFAULT '',
  `accept_test` varchar(300) NOT NULL DEFAULT '' COMMENT 'شاهدُ القبولِ كما تكتبه الوثيقة',
  `doc_ref` varchar(24) NOT NULL DEFAULT '' COMMENT 'المتطلبُ الذريُّ المصدر',
  `covered_by` varchar(200) NOT NULL DEFAULT '' COMMENT 'الأثرُ الحيُّ المنفِّذ — والفارغُ ثغرة',
  `coverage_kind` enum('table','service','screen','guard','harness','catalogue','uat','seed','none') NOT NULL DEFAULT 'none' COMMENT 'harness = يُنفَّذ آليًّا · catalogue = مرجعٌ بطبعِه · uat = بيدِ المستخدم · seed = مكتوبٌ لم يُنفَّذ بعد',
  `coverage_note` varchar(300) NOT NULL DEFAULT '',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_item` (`company_id`,`doc_code`,`family`,`item_code`),
  KEY `ix_fam` (`doc_code`,`family`),
  KEY `ix_cov` (`coverage_kind`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='update0013 — البنودُ المعلَنةُ في الوثائقِ وتغطيتُها الحية';

-- ── Table: gov_doc_variance ──
CREATE TABLE `gov_doc_variance` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '0 = يخصُّ الوثيقةَ لا الكيان',
  `variance_code` varchar(12) NOT NULL COMMENT 'V-01 ..',
  `doc_code` varchar(24) NOT NULL COMMENT 'الوثيقةُ صاحبةُ التعارض',
  `subject` varchar(200) NOT NULL COMMENT 'موضعُ التعارض',
  `declared_where` varchar(120) NOT NULL DEFAULT '' COMMENT 'أين أُعلن الرقمُ الأول',
  `declared_value` varchar(120) NOT NULL DEFAULT '',
  `registered_where` varchar(120) NOT NULL DEFAULT '' COMMENT 'أين سُجِّل الثاني',
  `registered_value` varchar(120) NOT NULL DEFAULT '',
  `resolution` enum('follow_register','follow_declared','derive','defer') NOT NULL COMMENT 'follow_register = يُتبع السجلُّ الذريُّ لأنه القابلُ للاختبار',
  `resolved_value` varchar(120) NOT NULL DEFAULT '' COMMENT 'الرقمُ الذي بُني عليه فعلًا',
  `basis` varchar(600) NOT NULL COMMENT 'أساسُ الحسمِ — ولا حسمَ بلا أساس',
  `impact` varchar(400) NOT NULL DEFAULT '' COMMENT 'ما بُني نتيجةَ الحسم',
  `decided_by` varchar(120) NOT NULL DEFAULT '' COMMENT 'من حسمَه وبأي صفة',
  `decided_at` datetime NOT NULL,
  `owner_action` varchar(300) NOT NULL DEFAULT '' COMMENT 'ما يلزم مالكَ الوثيقةِ فعلُه',
  `state` enum('open','resolved','accepted_by_owner','superseded') NOT NULL DEFAULT 'resolved',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_var` (`company_id`,`variance_code`),
  KEY `ix_doc` (`doc_code`,`state`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='update0013 — مخالفاتُ الوثائقِ وحسمُها بأساسٍ مكتوبٍ يُفحص كلَّ بوابة';

-- ── Table: gov_dup_semantics ──
CREATE TABLE `gov_dup_semantics` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `similarity` decimal(5,3) NOT NULL COMMENT 'درجةُ التشابهِ المحسوبة — مؤشِّرٌ لا حكم',
  `route_a` varchar(190) NOT NULL,
  `label_a` varchar(190) NOT NULL,
  `route_b` varchar(190) NOT NULL,
  `label_b` varchar(190) NOT NULL,
  `owner_dept` varchar(120) DEFAULT NULL,
  `nature` varchar(60) DEFAULT NULL,
  `shared_concepts` varchar(190) DEFAULT NULL,
  `machine_hint` varchar(190) DEFAULT NULL COMMENT 'الترجيحُ الآليّ — **اقتراحٌ لا حكم** (ف١٥-١ بند ٤)',
  `human_verdict` enum('SAME_FUNCTION','DIFFERENT_ANGLE','INDEPENDENT') DEFAULT NULL COMMENT 'الحكمُ البشريُّ الثلاثيُّ — ولا يُملأ آليًّا بحال',
  `human_by` varchar(120) DEFAULT NULL,
  `decision` varchar(190) DEFAULT NULL COMMENT 'دمجٌ · منظرٌ محفوظ · إبقاءٌ منفصلًا',
  `decided_at` datetime DEFAULT NULL,
  `human_note` text DEFAULT NULL COMMENT 'نصُّ الحكمِ الفنيِّ كما كُتب — لا يُلخَّص ولا يُعاد صوغُه',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pair` (`route_a`,`route_b`),
  KEY `ix_verdict` (`human_verdict`),
  CONSTRAINT `chk_dupsem_human` CHECK (`decision` is null or `human_verdict` is not null and `human_by` is not null)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='أزواجُ ازدواجِ المعنى — الترجيحُ الآليُّ والحكمُ البشريُّ عمودانِ لا عمود';

-- ── Table: gov_effect_map ──
CREATE TABLE `gov_effect_map` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `event_key` varchar(80) NOT NULL,
  `producer_mod` varchar(40) NOT NULL COMMENT 'وحدةُ الإنتاجِ التقنية',
  `producer_space` varchar(80) NOT NULL COMMENT 'المساحةُ المالكةُ للواقعة',
  `fact_rows` int(11) NOT NULL DEFAULT 0 COMMENT 'وقائعُ حيةٌ بهذا المفتاح',
  `consumer_key` varchar(80) NOT NULL COMMENT 'المستهلِك',
  `consumer_space` varchar(80) NOT NULL DEFAULT '—',
  `consumer_doc` varchar(120) NOT NULL DEFAULT '' COMMENT 'المستندُ الذي يُنتجه المستهلِك',
  `evidence` enum('MEASURED','DECLARED_ACTIVE','DECLARED_INACTIVE') NOT NULL,
  `evidence_n` int(11) NOT NULL DEFAULT 0 COMMENT 'صفوفُ الأثرِ الواصلةِ فعلًا',
  `note` varchar(255) NOT NULL DEFAULT '',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gem` (`event_key`,`consumer_key`),
  KEY `ix_gem_prod` (`producer_space`),
  KEY `ix_gem_ev` (`evidence`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ثامنًا-٢ خريطةُ الأثر — من يُنتج · من يستهلك · وأيُّ مستندٍ يُنتجه';

-- ── Table: gov_elevations ──
CREATE TABLE `gov_elevations` (
  `elevation_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0,
  `user_id` int(11) NOT NULL,
  `target_grade` enum('G1','G2','G3','G4','G5','G6','G7','G8','G9') NOT NULL,
  `target_dept` varchar(120) NOT NULL DEFAULT '',
  `reason` varchar(255) NOT NULL,
  `scope_note` varchar(255) NOT NULL DEFAULT '' COMMENT 'النطاقُ المحصور',
  `hr_witness` int(11) DEFAULT NULL COMMENT 'شهادةُ الأهلية — الموارد البشرية (LD-21 ②)',
  `fin_witness` int(11) DEFAULT NULL COMMENT 'شهادةُ الأثرِ الماليّ (LD-21 ③)',
  `ceo_approver` int(11) DEFAULT NULL COMMENT 'اعتمادُ الرئيسِ حصرًا — لا يُفوَّض (LD-21 ④)',
  `valid_to` datetime NOT NULL COMMENT 'مدّةٌ محصورةٌ إلزامية',
  `state` enum('requested','hr_ok','fin_ok','approved','active','expired','rejected') NOT NULL DEFAULT 'requested',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`elevation_id`),
  KEY `ix_user` (`user_id`,`state`),
  CONSTRAINT `chk_elev_reason` CHECK (`reason` <> ''),
  CONSTRAINT `chk_elev_four_parties` CHECK (`state` not in ('approved','active') or `hr_witness` is not null and `fin_witness` is not null and `ceo_approver` is not null),
  CONSTRAINT `chk_elev_ceo_not_self` CHECK (`ceo_approver` is null or `ceo_approver` <> `user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GOV-AUTH-01 §7 — الرفعُ الاستثنائيُّ LD-21: أربعةُ أطرافٍ في أربعةِ أعمدةٍ لا واحدٍ نصيّ';

-- ── Table: gov_event_rulings ──
CREATE TABLE `gov_event_rulings` (
  `event_key` varchar(120) NOT NULL,
  `ruling` enum('business','audit') DEFAULT NULL,
  `reason` varchar(400) DEFAULT NULL,
  `produced_count` int(10) unsigned NOT NULL DEFAULT 0,
  `has_subscription` tinyint(1) NOT NULL DEFAULT 0,
  `subscription_active` tinyint(1) NOT NULL DEFAULT 0,
  `handler_class` varchar(190) DEFAULT NULL,
  `handler_on_disk` tinyint(1) NOT NULL DEFAULT 0,
  `in_projection` tinyint(1) NOT NULL DEFAULT 0,
  `measured_at` datetime NOT NULL DEFAULT current_timestamp(),
  `decided_at` datetime DEFAULT NULL,
  `decided_by` varchar(120) DEFAULT NULL,
  PRIMARY KEY (`event_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: gov_export_log ──
CREATE TABLE `gov_export_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL DEFAULT 0,
  `exported_by` int(11) NOT NULL DEFAULT 0,
  `actor_capacity` varchar(120) NOT NULL DEFAULT '',
  `entity_key` varchar(64) NOT NULL DEFAULT '',
  `screen_code` varchar(190) NOT NULL DEFAULT '',
  `columns_text` text DEFAULT NULL,
  `blocked_text` text DEFAULT NULL,
  `filters_text` text DEFAULT NULL,
  `row_count` int(10) unsigned NOT NULL DEFAULT 0,
  `fmt` varchar(12) NOT NULL DEFAULT 'xlsx',
  `exported_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_gel_company_time` (`company_id`,`exported_at`),
  KEY `idx_gel_actor` (`exported_by`,`exported_at`),
  KEY `idx_gel_entity` (`entity_key`,`exported_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RF-03 · سجلُّ التصديرِ الحوكميِّ بتسعةِ بنودٍ ومنها المستبعَد';

-- ── Table: gov_field_class ──
CREATE TABLE `gov_field_class` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0,
  `screen_code` varchar(80) NOT NULL COMMENT 'رمزُ الشاشةِ الحاكمة',
  `field_key` varchar(80) NOT NULL COMMENT 'مفتاحُ الحقلِ في الشاشة',
  `label_ar` varchar(160) NOT NULL DEFAULT '',
  `dc_code` varchar(6) NOT NULL COMMENT 'DC-1..DC-4 — ولا حقلَ بلا صنف',
  `is_sensitive` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'يحتاج منحًا فرديًّا ويُسجَّل الاطّلاع',
  `doc_ref` varchar(24) NOT NULL DEFAULT '',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_field` (`company_id`,`screen_code`,`field_key`),
  KEY `ix_dc` (`dc_code`,`active`),
  KEY `ix_screen` (`screen_code`,`active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PROP-01 §7-2 ⑤ — صفرُ حقلٍ في شاشةٍ حاكمةٍ بلا صنف';

-- ── Table: gov_field_inheritance ──
CREATE TABLE `gov_field_inheritance` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0,
  `child_entity` varchar(60) NOT NULL COMMENT 'المستندُ التابع: accrual · obligation · invoice · timesheet',
  `child_field` varchar(80) NOT NULL,
  `parent_entity` varchar(60) NOT NULL COMMENT 'المرجعُ الأب',
  `parent_field` varchar(80) NOT NULL,
  `label_ar` varchar(160) NOT NULL DEFAULT '',
  `readonly` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'IN-01 — الموروثُ للقراءةِ فقط',
  `on_parent_change` enum('cascade_if_draft','notify_only') NOT NULL DEFAULT 'cascade_if_draft',
  `doc_ref` varchar(24) NOT NULL DEFAULT '',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_inh` (`company_id`,`child_entity`,`child_field`),
  KEY `ix_parent` (`parent_entity`,`parent_field`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='FIN-OBL-01 §4-21 — التوريثُ ومنعُ إعادةِ الإدخال';

-- ── Table: gov_field_trace ──
CREATE TABLE `gov_field_trace` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `book` varchar(60) NOT NULL,
  `sheet` varchar(120) NOT NULL,
  `sheet_no` smallint(5) unsigned NOT NULL DEFAULT 0,
  `header_cell` varchar(12) NOT NULL,
  `field_no` smallint(5) unsigned NOT NULL DEFAULT 0,
  `field_name` varchar(255) NOT NULL,
  `as_is` varchar(120) NOT NULL DEFAULT '',
  `to_be` varchar(120) NOT NULL DEFAULT '',
  `visibility_rule` varchar(255) NOT NULL DEFAULT '',
  `judged_from` varchar(160) NOT NULL DEFAULT '',
  `surface_state` varchar(120) NOT NULL DEFAULT '',
  `req_id` varchar(16) NOT NULL DEFAULT '',
  `reconciliation` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `u_field` (`book`,`sheet`,`header_cell`),
  KEY `k_req` (`req_id`),
  KEY `k_tobe` (`to_be`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: gov_filing ──
CREATE TABLE `gov_filing` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `filing_no` varchar(40) NOT NULL,
  `obligation_no` varchar(40) NOT NULL DEFAULT '',
  `authority_ar` varchar(160) NOT NULL DEFAULT '',
  `period_label` varchar(40) NOT NULL DEFAULT '',
  `due_date` date DEFAULT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `submitted_by` int(11) NOT NULL DEFAULT 0,
  `receipt_ref` varchar(120) NOT NULL DEFAULT '',
  `state` varchar(24) NOT NULL DEFAULT 'due',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `filing_kind` varchar(40) DEFAULT NULL COMMENT 'نوع التقديم',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gvf` (`company_id`,`filing_no`),
  CONSTRAINT `chk_gvf_state` CHECK (`state` in ('due','prepared','submitted','acknowledged','late')),
  CONSTRAINT `chk_gvf_receipt` CHECK (`state` <> 'acknowledged' or `receipt_ref` <> ''),
  CONSTRAINT `chk_gvf_submitted` CHECK (`state` not in ('submitted','acknowledged') or `submitted_at` is not null)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 GOV-08 - التقديم النظامي بموعده وايصاله';

-- ── Table: gov_finance_gate_policy ──
CREATE TABLE `gov_finance_gate_policy` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `ladder_code` varchar(12) NOT NULL,
  `policy` varchar(24) NOT NULL COMMENT 'MANDATORY_GATE | REQUEST_REGISTER',
  `covered_by` varchar(12) DEFAULT NULL COMMENT 'سلّمُ البوابةِ المُغطّي لسجلِّ الطلبات',
  `reason` varchar(400) NOT NULL,
  `decided_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ladder` (`ladder_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GAP-15 — قرارٌ مُعلَنٌ لكلِّ سلّمٍ بسقفٍ نقديّ: بوابةٌ إلزاميةٌ أم سجلُّ طلبات';

-- ── Table: gov_gift_disclosure ──
CREATE TABLE `gov_gift_disclosure` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `gift_no` varchar(40) NOT NULL,
  `person_id` int(11) NOT NULL DEFAULT 0,
  `gift_kind` varchar(24) NOT NULL DEFAULT '',
  `giver_ar` varchar(200) NOT NULL DEFAULT '',
  `est_value` decimal(18,2) DEFAULT NULL,
  `currency` varchar(8) NOT NULL DEFAULT '',
  `threshold_key` varchar(64) NOT NULL DEFAULT '' COMMENT 'مفتاح الحد في السجل - ولا رقم هنا',
  `disclosed_at` datetime DEFAULT NULL,
  `decided_by` int(11) NOT NULL DEFAULT 0,
  `decision` varchar(24) NOT NULL DEFAULT '',
  `state` varchar(24) NOT NULL DEFAULT 'disclosed',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `direction` varchar(24) DEFAULT NULL COMMENT 'الاتجاه',
  `description_ar` varchar(400) DEFAULT NULL COMMENT 'الوصف',
  `context_ar` varchar(400) DEFAULT NULL COMMENT 'السياق',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ggf` (`company_id`,`gift_no`),
  CONSTRAINT `chk_ggf_kind` CHECK (`gift_kind` in ('gift','hospitality','travel','other')),
  CONSTRAINT `chk_ggf_state` CHECK (`state` in ('disclosed','assessed','accepted','returned','declined')),
  CONSTRAINT `chk_ggf_decision` CHECK (`decision` in ('','accept','return','decline')),
  CONSTRAINT `chk_ggf_self` CHECK (`decided_by` = 0 or `decided_by` <> `person_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 GOV-12 - الهدايا والضيافة والحد من السجل لا من الشيفرة';

-- ── Table: gov_golden_approvals ──
CREATE TABLE `gov_golden_approvals` (
  `id` tinyint(3) unsigned NOT NULL,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'عمودُ العزل — 0: قرارٌ معياريٌّ لكلِّ الكيانات',
  `screen_file` varchar(160) NOT NULL,
  `title_ar` varchar(160) NOT NULL,
  `test_account` varchar(60) NOT NULL COMMENT 'حسابُ الدورِ المخوَّلِ لفتحِها — مقيسٌ من صلاحيتِها الحية',
  `role_id` smallint(5) unsigned NOT NULL,
  `url_params` varchar(60) NOT NULL DEFAULT '' COMMENT 'معاملُ مسارٍ تشترطه الشاشةُ للدخول',
  `state` enum('pending','approved','noted') NOT NULL DEFAULT 'pending' COMMENT 'pending بانتظارِ المالك · approved تمضي في التعميم · noted ملاحظةٌ تُصلَّح ثم تُعاد',
  `approval_basis` enum('OBJECTIVE_GATE','HUMAN_REVIEW','OWNER_OVERRIDE') DEFAULT NULL COMMENT 'كيفَ اعتُمد: بوابةٌ موضوعيةٌ · مراجعةٌ بشريةٌ مستقلةٌ · تجاوزُ المالك',
  `basis_ref` varchar(190) DEFAULT NULL COMMENT 'مرجعُ الأساس: تقريرُ البوابةِ أو محضرُ المراجعةِ ومنفِّذُها',
  `pattern_state` enum('PENDING','VISUAL_PATTERN_APPROVED','GOLDEN_SCREEN_FINAL','REJECTED') NOT NULL DEFAULT 'PENDING' COMMENT 'اعتمادٌ على مرحلتَين: النمطُ يفتح التعميمَ · والنهائيُّ بعد (ب) و(ج)',
  `category` varchar(60) DEFAULT NULL COMMENT 'فئةُ التعميم: سجلات · كيانات · نماذج · لوحات · طوابير',
  `owner_note` varchar(500) NOT NULL DEFAULT '',
  `decided_at` datetime DEFAULT NULL,
  `fixed_at` datetime DEFAULT NULL COMMENT 'لحظةُ إصلاحِ الملاحظةِ قبلَ إعادتِها للمالك',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_screen` (`company_id`,`screen_file`),
  KEY `ix_state` (`state`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='UXW-01 §8-1 — اعتمادُ العشرِ الذهبيةِ إفراديًّا بقرارِ المالك 2026-08-18';

-- ── Table: gov_governing_screens ──
CREATE TABLE `gov_governing_screens` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0,
  `screen_code` varchar(80) NOT NULL,
  `title_ar` varchar(200) NOT NULL DEFAULT '',
  `file_path` varchar(160) NOT NULL DEFAULT '',
  `why_governing` varchar(300) NOT NULL DEFAULT '' COMMENT 'لماذا عُدَّت حاكمة',
  `owner_doc` varchar(40) NOT NULL DEFAULT '',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_scr` (`company_id`,`screen_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PROP-01 §4-1 ⑤ — سجلُّ الشاشاتِ الحاكمةِ الخاضعةِ لشرطِ التصنيف';

-- ── Table: gov_independent_reviews ──
CREATE TABLE `gov_independent_reviews` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `screen_file` varchar(160) NOT NULL,
  `review_kind` enum('human_test','investor_round') NOT NULL,
  `executed_by_user` int(11) DEFAULT NULL COMMENT 'منفِّذٌ مستقلٌّ عن البانِي — يُقرأ من الجلسةِ لا يُكتب نصًّا',
  `executed_by_dept` varchar(120) DEFAULT NULL COMMENT 'إدارةُ الحوكمةِ أو إدارةٌ غيرُ معنيةٍ بالشاشة',
  `participants` smallint(5) unsigned DEFAULT NULL COMMENT 'عدةُ مستخدمينَ جددٍ لم يشاركوا في البناء',
  `tasks_defined` smallint(5) unsigned DEFAULT NULL COMMENT 'مهامُّ محددةٌ سلفًا',
  `attempts_total` smallint(5) unsigned DEFAULT NULL COMMENT 'مجموعُ محاولاتِ المهامِّ — مقامُ النسبة',
  `attempts_success` smallint(5) unsigned DEFAULT NULL,
  `success_rate` decimal(5,2) DEFAULT NULL COMMENT 'تُحسب على مجموعِ المحاولاتِ لا على رأيِ شخص',
  `yes_answers` tinyint(3) unsigned DEFAULT NULL COMMENT 'جولةُ العرض: أسئلةُ الفجوةِ السبعُ = صفرُ نعم',
  `verdict` enum('PASS','FAIL') DEFAULT NULL,
  `minutes_ref` varchar(190) DEFAULT NULL COMMENT 'مرجعُ المحضرِ — لا حكمَ بلا شاهد',
  `component_version` varchar(24) DEFAULT NULL,
  `commit_hash` varchar(40) NOT NULL DEFAULT '' COMMENT 'التزامُ الشيفرةِ الذي رآه المراجِعُ — لا الذي يُقرأ اليوم',
  `visual_baseline_version` varchar(40) NOT NULL DEFAULT '' COMMENT 'وسمُ خطِّ الأساسِ البصريِّ لحظةَ المراجعة',
  `recorded_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_screen_kind_ver` (`screen_file`,`review_kind`,`component_version`),
  CONSTRAINT `chk_review_version_triple` CHECK (`component_version` <> '' and `visual_baseline_version` <> '' and char_length(`commit_hash`) >= 7)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='المراجعةُ البشريةُ المستقلةُ وجولةُ العرض — ينفّذهما مستقلٌّ عن البانِي';

-- ── Table: gov_inheritance_denials ──
CREATE TABLE `gov_inheritance_denials` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `child_entity` varchar(60) NOT NULL,
  `child_ref` varchar(120) NOT NULL DEFAULT '',
  `child_field` varchar(80) NOT NULL,
  `source_shown` varchar(200) NOT NULL DEFAULT '' COMMENT 'المصدرُ الذي بُيِّن للمستخدم',
  `attempted_by` int(10) unsigned NOT NULL DEFAULT 0,
  `denied_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_field` (`company_id`,`child_entity`,`child_field`,`denied_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='FIN-OBL-01 IN-01 — سجلُّ رفضِ تعديلِ الموروث';

-- ── Table: gov_integrity_report ──
CREATE TABLE `gov_integrity_report` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `report_no` varchar(40) NOT NULL,
  `channel` varchar(24) NOT NULL DEFAULT '',
  `is_anonymous` tinyint(1) NOT NULL DEFAULT 1,
  `reporter_token` varchar(64) NOT NULL DEFAULT '' COMMENT 'رمز لا اسم - والكشف بمستوى مخول',
  `reporter_person` int(11) NOT NULL DEFAULT 0,
  `disclosure_role_key` varchar(64) NOT NULL DEFAULT '' COMMENT 'مفتاح المستوى المخول من السجل',
  `subject_ar` varchar(400) NOT NULL DEFAULT '',
  `received_at` datetime DEFAULT NULL,
  `triage_by` int(11) NOT NULL DEFAULT 0,
  `triage_at` datetime DEFAULT NULL,
  `referred_to` varchar(12) NOT NULL DEFAULT '',
  `investigation_no` varchar(40) NOT NULL DEFAULT '',
  `retaliation_flag` tinyint(1) NOT NULL DEFAULT 0,
  `state` varchar(24) NOT NULL DEFAULT 'received',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `description_ar` varchar(600) DEFAULT NULL COMMENT 'الوصف المقيد',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gir` (`company_id`,`report_no`),
  CONSTRAINT `chk_gir_state` CHECK (`state` in ('received','triaged','referred','closed','dismissed')),
  CONSTRAINT `chk_gir_anon` CHECK (`is_anonymous` = 0 or `reporter_person` = 0),
  CONSTRAINT `chk_gir_named` CHECK (`is_anonymous` = 1 or `reporter_person` <> 0),
  CONSTRAINT `chk_gir_token` CHECK (`reporter_token` <> ''),
  CONSTRAINT `chk_gir_referred` CHECK (`state` <> 'referred' or `referred_to` <> ''),
  CONSTRAINT `chk_gir_triage` CHECK (`state` = 'received' or `triage_at` is not null)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 GOV-22 - قناة محمية بهوية محجوبة ولا انتقام';

-- ── Table: gov_investigation ──
CREATE TABLE `gov_investigation` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `inv_no` varchar(40) NOT NULL COMMENT 'Integrity_Investigation_ID',
  `inv_kind` varchar(24) NOT NULL DEFAULT '',
  `owner_dept` varchar(12) NOT NULL DEFAULT '',
  `origin` varchar(24) NOT NULL DEFAULT '',
  `origin_ref` varchar(64) NOT NULL DEFAULT '',
  `triage_ref` varchar(64) NOT NULL DEFAULT '' COMMENT 'فرز سابق - وبدونه لا يفتح تحقيق من سجل المنع',
  `mandate_doc_ref` varchar(120) NOT NULL DEFAULT '' COMMENT 'التكليف المكتوب - شرط المراجعة الداخلية',
  `subject_person` int(11) NOT NULL DEFAULT 0,
  `scope_ar` varchar(400) NOT NULL DEFAULT '',
  `investigator_id` int(11) NOT NULL DEFAULT 0,
  `opened_by` int(11) NOT NULL DEFAULT 0,
  `conflict_flag` tinyint(1) NOT NULL DEFAULT 0,
  `recusal_of` varchar(120) NOT NULL DEFAULT '',
  `reserved_authority_ref` varchar(120) NOT NULL DEFAULT '',
  `conclusion_ar` varchar(600) NOT NULL DEFAULT '',
  `concluded_by` int(11) NOT NULL DEFAULT 0,
  `concluded_at` datetime DEFAULT NULL,
  `referred_to` varchar(12) NOT NULL DEFAULT '' COMMENT 'الجهة التي تستقبل الاثر لا التي تعيد التحقيق',
  `state` varchar(24) NOT NULL DEFAULT 'mandated',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `confidentiality` varchar(24) DEFAULT NULL COMMENT 'مستوى السرية',
  `due_period` varchar(40) DEFAULT NULL COMMENT 'المدة المقررة',
  `recommendations_ar` varchar(600) DEFAULT NULL COMMENT 'التوصيات',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gin` (`company_id`,`inv_no`),
  CONSTRAINT `chk_gin_kind` CHECK (`inv_kind` in ('DISCIPLINARY','INTEGRITY','OPERATIONAL_FACT','SPECIAL_INDEPENDENT')),
  CONSTRAINT `chk_gin_iaf_mandate` CHECK (`inv_kind` <> 'SPECIAL_INDEPENDENT' or `mandate_doc_ref` <> ''),
  CONSTRAINT `chk_gin_denial_triage` CHECK (`origin` <> 'DENIAL' or `triage_ref` <> ''),
  CONSTRAINT `chk_gin_origin` CHECK (`origin` in ('INTEGRITY_REPORT','DENIAL','BREACH','AUDIT_FINDING','MANAGEMENT_REQUEST','OWNER_ORDER','OPERATIONAL')),
  CONSTRAINT `chk_gin_recusal` CHECK (`conflict_flag` = 0 or `recusal_of` <> '' and `reserved_authority_ref` <> ''),
  CONSTRAINT `chk_gin_self` CHECK (`investigator_id` = 0 or `investigator_id` <> `subject_person`),
  CONSTRAINT `chk_gin_state` CHECK (`state` in ('mandated','evidence','concluded','referred','closed')),
  CONSTRAINT `chk_gin_conclusion` CHECK (`state` not in ('concluded','referred','closed') or `conclusion_ar` <> '' and `concluded_by` <> 0),
  CONSTRAINT `chk_gin_hands` CHECK (`concluded_by` = 0 or `concluded_by` <> `opened_by`),
  CONSTRAINT `chk_gin_kind_owner` CHECK (`inv_kind` = 'DISCIPLINARY' and `owner_dept` = 'DEP-07' or `inv_kind` = 'INTEGRITY' and `owner_dept` = 'DEP-08' or `inv_kind` = 'SPECIAL_INDEPENDENT' and `owner_dept` = 'IAF' or `inv_kind` = 'OPERATIONAL_FACT' and `owner_dept` not in ('DEP-07','DEP-08','IAF') and `owner_dept` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 GOV-23 - ثلاثة انواع بثلاثة ملاك والمراجعة بتكليف مكتوب';

-- ── Table: gov_journey_ladders ──
CREATE TABLE `gov_journey_ladders` (
  `journey_code` varchar(20) NOT NULL COMMENT 'JR-REV إيراد · JR-SUP مورّد · JR-OPR مشغّل',
  `journey_ar` varchar(80) NOT NULL,
  `seq_no` tinyint(4) NOT NULL COMMENT 'ترتيبُ السلّمِ داخلَ الرحلة',
  `ladder_code` varchar(20) NOT NULL,
  `driver_route` varchar(190) NOT NULL DEFAULT '' COMMENT 'الشاشةُ التي تقود هذه الخطوةَ اليوم',
  `driver_state` enum('LIVE_IN_NAV','FILE_ONLY','MISSING') NOT NULL DEFAULT 'MISSING' COMMENT 'مقيسٌ من nav_items النشِط ومن القرص — لا مُعلَنٌ يدويًّا',
  `nav_hits` smallint(6) NOT NULL DEFAULT 0 COMMENT 'مواضعُ الشاشةِ في سايدبارِ الأدوار',
  `ladder_wired` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'أتقرأ الشاشةُ سلّمَها لحظةَ الاعتماد؟ — الفجوةُ المرفوعة',
  `gap_note` varchar(255) NOT NULL DEFAULT '',
  `entity_type` varchar(64) DEFAULT NULL,
  `action` varchar(64) DEFAULT NULL,
  PRIMARY KEY (`journey_code`,`seq_no`),
  KEY `ix_gjl_ladder` (`ladder_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='خامسًا/سابعًا — الـ13 سلّمًا مرتّبةً بحسبِ الرحلاتِ الثلاث';

-- ── Table: gov_key_pollution_archive ──
CREATE TABLE `gov_key_pollution_archive` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `src_table` varchar(64) NOT NULL,
  `src_column` varchar(64) NOT NULL,
  `src_row_id` bigint(20) NOT NULL,
  `original_value` text NOT NULL,
  `replacement` varchar(191) NOT NULL,
  `row_snapshot` longtext DEFAULT NULL,
  `reason` varchar(191) NOT NULL,
  `quarantined_at` datetime NOT NULL DEFAULT current_timestamp(),
  `restored_at` datetime DEFAULT NULL,
  `superseded_to` varchar(64) DEFAULT NULL COMMENT 'الجدولُ الذي انتقل إليه الصفُّ — فلا موضعَ حيًّا يُردُّ إليه',
  `superseded_reason` varchar(300) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_kpa_src` (`src_table`,`src_column`,`src_row_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: gov_label_unified_log ──
CREATE TABLE `gov_label_unified_log` (
  `nav_id` int(11) NOT NULL,
  `role_id` int(11) NOT NULL,
  `route` varchar(160) NOT NULL,
  `label_before` varchar(120) NOT NULL,
  `label_after` varchar(120) NOT NULL,
  `basis` varchar(160) NOT NULL,
  `at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`nav_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='توحيدُ الاسمِ الظاهرِ على الكنسيّ — بالاسمِ السابقِ لكلِّ صفّ';

-- ── Table: gov_ladder_actor_roles ──
CREATE TABLE `gov_ladder_actor_roles` (
  `actor_code` varchar(40) NOT NULL,
  `role_id` int(11) NOT NULL COMMENT 'دورُ النظامِ الذي يحمل هذا الموضع',
  `basis` varchar(255) NOT NULL COMMENT 'سندُ الإسناد — لا إسنادَ بلا مرجع',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`actor_code`),
  KEY `ix_role` (`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='جسرُ موضعِ السلطةِ في السلّمِ بدورِ النظام — والموضعُ لا شخص';

-- ── Table: gov_ladder_decisions ──
CREATE TABLE `gov_ladder_decisions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `ladder_code` varchar(12) NOT NULL,
  `subject_kind` varchar(40) NOT NULL COMMENT 'نوعُ المستند — claim_invoice · payment · settlement …',
  `subject_ref` bigint(20) unsigned NOT NULL,
  `scope_key` varchar(96) NOT NULL COMMENT 'نسخةُ السلّم — عقدتان متصلتان تتشاركانها',
  `step_no` tinyint(3) unsigned NOT NULL,
  `actor_id` int(10) unsigned NOT NULL,
  `note` varchar(190) DEFAULT NULL,
  `decided_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gld` (`company_id`,`scope_key`,`step_no`,`actor_id`),
  KEY `ix_gld_ladder` (`ladder_code`,`subject_kind`),
  KEY `ix_gld_scope` (`scope_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='سجلُّ قراراتِ السلالمِ الواحد — INJ-CHAIN-CLOSE-01 · GAP-01';

-- ── Table: gov_ladder_shadow ──
CREATE TABLE `gov_ladder_shadow` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `ladder_code` varchar(16) NOT NULL,
  `subject_kind` varchar(48) NOT NULL,
  `subject_ref` bigint(20) NOT NULL,
  `step_no` int(11) DEFAULT NULL,
  `actor_id` int(11) NOT NULL,
  `current_decision` enum('allow','deny') NOT NULL,
  `ladder_decision` enum('allow','deny') NOT NULL,
  `diverged` tinyint(1) NOT NULL DEFAULT 0,
  `reason` varchar(500) NOT NULL DEFAULT '',
  `idem_key` varchar(128) NOT NULL,
  `observed_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `u_idem` (`idem_key`),
  KEY `k_div` (`diverged`,`observed_at`),
  KEY `k_kind` (`subject_kind`,`observed_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='FR-APP-001 — ظلُّ بوابةِ السلّم · يرصد ولا يمنع';

-- ── Table: gov_ladder_steps ──
CREATE TABLE `gov_ladder_steps` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'عمودُ العزل TS-02 — 0 = كلُّ كيانٍ نشط (يرثه من سلّمِه)',
  `ladder_code` varchar(12) NOT NULL,
  `step_no` tinyint(3) unsigned NOT NULL,
  `actor_code` varchar(40) NOT NULL COMMENT 'رمزُ الفاعلِ الوظيفيّ',
  `actor_name_ar` varchar(120) NOT NULL,
  `step_kind` enum('entry','review','approve','system') NOT NULL,
  `is_accountant` tinyint(1) NOT NULL DEFAULT 0 COMMENT '① محاسبٌ — ممنوعٌ في المراحلِ التشغيليةِ قبلَ بوابةِ المالية',
  `is_finance_gate` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'هذه الخطوةُ بوابةُ المالية أو بعدَها',
  `may_approve` tinyint(1) NOT NULL DEFAULT 0,
  `forbid_note` varchar(255) DEFAULT NULL COMMENT 'قيدُ منعٍ صريحٌ على هذه الخطوة',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ld_step` (`ladder_code`,`step_no`),
  KEY `ix_ld` (`ladder_code`),
  KEY `ix_company` (`company_id`),
  CONSTRAINT `fk_ld_step` FOREIGN KEY (`ladder_code`) REFERENCES `gov_ladders` (`ladder_code`) ON DELETE CASCADE,
  CONSTRAINT `chk_step_entry_no_approve` CHECK (`step_kind` <> 'entry' or `may_approve` = 0),
  CONSTRAINT `chk_step_accountant` CHECK (`is_accountant` = 0 or `is_finance_gate` = 1 or `actor_code` = 'FIN_FIELD_VERIFY')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='① لا محاسبَ في مرحلةٍ تشغيليةٍ قبلَ بوابةِ المالية — يفرضه chk_step_accountant';

-- ── Table: gov_ladders ──
CREATE TABLE `gov_ladders` (
  `ladder_code` varchar(12) NOT NULL COMMENT 'LD-01 … LD-09',
  `company_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '0 = كلُّ كيانٍ نشط',
  `slug` varchar(48) NOT NULL COMMENT 'unit_daily_approve …',
  `name_ar` varchar(160) NOT NULL,
  `cycle_no` tinyint(3) unsigned DEFAULT NULL COMMENT 'موضعُه في الدورةِ التسعية — NULL لغيرِ التايم شيت',
  `escalate_after_hours` smallint(5) unsigned DEFAULT NULL COMMENT 'تجاوزُها تصعيدٌ لا إغلاق',
  `cap_kind` enum('none','scope','amount') NOT NULL DEFAULT 'none',
  `cap_amount` decimal(16,2) DEFAULT NULL,
  `cap_currency` varchar(8) DEFAULT NULL,
  `cap_state` enum('resolved','unresolved','not_applicable') NOT NULL DEFAULT 'unresolved' COMMENT '③ غيرُ المحسومِ يوقف السلّمَ — fail-closed',
  `payload_note` varchar(255) DEFAULT NULL COMMENT 'ما يكتبه المحرّكُ بعدَ الاكتمال',
  `doc_ref` varchar(40) NOT NULL DEFAULT 'LAD-01',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `entity_type` varchar(64) DEFAULT NULL,
  `action` varchar(64) DEFAULT NULL,
  PRIMARY KEY (`ladder_code`),
  KEY `ix_ld_cycle` (`cycle_no`),
  CONSTRAINT `chk_ld_cap` CHECK (`cap_state` <> 'resolved' or `cap_kind` <> 'amount' or `cap_amount` is not null and `cap_currency` is not null)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='LAD-01: سلاليمُ الاعتماد — والسقفُ غيرُ المحسومِ يوقف السلّم';

-- ── Table: gov_legacy_nav_recon ──
CREATE TABLE `gov_legacy_nav_recon` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `gtn_id` int(11) NOT NULL COMMENT 'صف gov_target_nav المصالَح',
  `role_id` int(11) NOT NULL,
  `route` varchar(190) NOT NULL,
  `group_ar` varchar(150) DEFAULT NULL,
  `doc_code` varchar(40) DEFAULT NULL,
  `verdict` enum('MATCHES_GOVERNING_TARGET','APPROVED_POST_GUIDE_ADDITION','VALID_UTILITY','DUPLICATE','CURRENT_ONLY_UNGOVERNED','SUPERSEDED') NOT NULL,
  `basis` varchar(300) NOT NULL,
  `reconciled_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gtn` (`gtn_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='§٢٠: مصالحةُ إرثِ gov_target_nav — Current يقترح ولا يعتمد نفسَه';

-- ── Table: gov_migration_ledger ──
CREATE TABLE `gov_migration_ledger` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `dept` varchar(120) NOT NULL,
  `layer` varchar(60) DEFAULT NULL,
  `stage` varchar(190) DEFAULT NULL,
  `screen_label` varchar(190) DEFAULT NULL,
  `proposed_label` varchar(190) DEFAULT NULL,
  `file_base` varchar(120) NOT NULL COMMENT 'كما في الدفتر — اسمٌ مجرَّدٌ لا مسار',
  `route` varchar(190) DEFAULT NULL COMMENT 'المسارُ المحلولُ — NULL إن تعذّر أو تعدَّد',
  `resolve_state` enum('RESOLVED','AMBIGUOUS','NOT_FOUND') NOT NULL DEFAULT 'NOT_FOUND' COMMENT 'وما تعدَّد مطابقُه لا يُخمَّن',
  `is_duplicate` varchar(20) DEFAULT NULL,
  `entity` varchar(120) DEFAULT NULL,
  `parent_file` varchar(120) DEFAULT NULL,
  `target_type` varchar(120) DEFAULT NULL,
  `target_template` varchar(120) DEFAULT NULL,
  `required_components` varchar(400) DEFAULT NULL,
  `nature` varchar(120) DEFAULT NULL,
  `official_doc` varchar(190) DEFAULT NULL,
  `problems` text DEFAULT NULL,
  `severity` varchar(30) DEFAULT NULL COMMENT 'عالٍ · متوسط · — · ويُرتَّب الترحيلُ بها',
  `decision` varchar(190) DEFAULT NULL,
  `acceptance_test` varchar(190) DEFAULT NULL,
  `migration_state` enum('NOT_STARTED','IN_PROGRESS','TECHNICALLY_ELIGIBLE','GOLDEN_SCREEN_FINAL','BLOCKED_EXTERNAL_INPUT') NOT NULL DEFAULT 'NOT_STARTED' COMMENT 'مفرداتُ الإغلاقِ المعتمَدةُ — ولا «CLOSED» ولا «100٪»',
  `measured_at` datetime DEFAULT NULL,
  `measure_note` varchar(400) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_dept_file_stage` (`dept`,`file_base`,`stage`),
  KEY `ix_route` (`route`),
  KEY `ix_sev` (`severity`),
  KEY `ix_state` (`migration_state`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='سجلُّ الترحيلِ — 663 موضعًا بأعمدةِ الدفترِ التسعةَ عشرَ وحالةٍ مقيسة';

-- ── Table: gov_migration_settlement ──
CREATE TABLE `gov_migration_settlement` (
  `filename` varchar(255) NOT NULL COMMENT 'اسمُ ملفِّ الهجرةِ أو صفِّ الدفتر',
  `kind` enum('DISK_NOT_LEDGERED','LEDGER_NOT_ON_DISK','UNMANAGED_NAME') NOT NULL COMMENT 'عائلةُ عدمِ المصالحة',
  `ruling` varchar(48) NOT NULL COMMENT 'الحكمُ المعتمد',
  `evidence` varchar(600) NOT NULL DEFAULT '' COMMENT 'الدليلُ المقيسُ — كائناتُ المخطَّطِ التي فُحصت',
  `verified` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'أُثبت أثرُه في المخطَّطِ قياسًا',
  `objects_checked` smallint(5) unsigned NOT NULL DEFAULT 0 COMMENT 'مقامُ الفحص — كم كائنًا سُئل',
  `objects_found` smallint(5) unsigned NOT NULL DEFAULT 0 COMMENT 'كم منها وُجد',
  `owner_ref` varchar(190) NOT NULL COMMENT 'مرجعُ القرارِ المخوِّل — ⛔ ولا حكمَ بلا مرجع',
  `settled_at` datetime NOT NULL DEFAULT current_timestamp(),
  `settled_by` varchar(64) NOT NULL DEFAULT '',
  PRIMARY KEY (`filename`),
  KEY `ix_gms_kind` (`kind`),
  KEY `ix_gms_ruling` (`ruling`),
  CONSTRAINT `chk_gms_verified_needs_evidence` CHECK (`verified` = 0 or char_length(`evidence`) >= 12 and `objects_checked` > 0),
  CONSTRAINT `chk_gms_owner_ref` CHECK (char_length(`owner_ref`) >= 6)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='أحكامُ الهجراتِ غيرِ المصالَحةِ مع الدفتر — RPR-02 §٩ · RPR-03 §٣·١';

-- ── Table: gov_nav_findings ──
CREATE TABLE `gov_nav_findings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `kind` varchar(40) NOT NULL,
  `role_id` int(11) DEFAULT NULL,
  `workspace_id` varchar(24) DEFAULT NULL,
  `detail` varchar(400) NOT NULL,
  `hits` int(10) unsigned NOT NULL DEFAULT 1,
  `first_seen` datetime NOT NULL DEFAULT current_timestamp(),
  `last_seen` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_finding` (`kind`,`role_id`,`workspace_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='NAVR: BUSINESS_WORKSPACE_GLOBAL_FALLBACK وأخواتُها — Fail-visible لا سقوطًا صامتًا';

-- ── Table: gov_nav_hidden_log ──
CREATE TABLE `gov_nav_hidden_log` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `role_id` int(11) NOT NULL,
  `nav_id` int(11) NOT NULL,
  `route` varchar(160) NOT NULL,
  `label_ar` varchar(120) NOT NULL,
  `group_before` int(11) DEFAULT NULL,
  `sort_before` int(11) DEFAULT NULL,
  `doc_code` varchar(24) NOT NULL,
  `reachable` varchar(40) NOT NULL COMMENT 'TAB_IN_PARENT | ACTIVE_FOR_OTHER_ROLE | OWNED_ELSEWHERE',
  `hidden_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_hidden` (`nav_id`),
  KEY `ix_hidden_role` (`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ما أُخفي من التنقّلِ بموضعِه السابق — الرجوعُ يعيده حرفًا';

-- ── Table: gov_nav_reference_standard ──
CREATE TABLE `gov_nav_reference_standard` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `layer_no` tinyint(3) unsigned NOT NULL COMMENT '1 مركز العمل · 2 دورة الإدارة · 3 المرجع والإدارة',
  `layer_name` varchar(60) NOT NULL,
  `stage_order` tinyint(3) unsigned NOT NULL,
  `stage_name` varchar(160) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_stage` (`layer_no`,`stage_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='INJ-FIX-02 NF-04 — المعيارُ المرجعيُّ للترتيب: طبقةٌ ثم مرحلةٌ ثم رتبةٌ مستندية';

-- ── Table: gov_nav_stage_bridge ──
CREATE TABLE `gov_nav_stage_bridge` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `cycle_layer` varchar(60) NOT NULL,
  `cycle_stage` varchar(160) NOT NULL,
  `screens` smallint(5) unsigned NOT NULL,
  `std_layer_no` tinyint(3) unsigned DEFAULT NULL,
  `std_stage_order` tinyint(3) unsigned DEFAULT NULL,
  `std_stage_name` varchar(160) DEFAULT NULL,
  `match_kind` varchar(24) NOT NULL COMMENT 'EXACT | TOKEN | LAYER_ONLY | UNMAPPED',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cycle` (`cycle_layer`,`cycle_stage`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='INJ-FIX-02 NF-04 — جسرُ مراحلِ دفترِ الدورةِ برؤوسِ المعيارِ المرجعيّ';

-- ── Table: gov_obligation ──
CREATE TABLE `gov_obligation` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `obligation_no` varchar(40) NOT NULL COMMENT 'Compliance_Obligation_ID',
  `title_ar` varchar(255) NOT NULL DEFAULT '',
  `authority_ar` varchar(160) NOT NULL DEFAULT '' COMMENT 'الجهة المفروض منها الالتزام',
  `basis_ref` varchar(160) NOT NULL DEFAULT '',
  `periodicity` varchar(24) NOT NULL DEFAULT '',
  `owner_dept` varchar(12) NOT NULL DEFAULT '',
  `owner_person` int(11) NOT NULL DEFAULT 0,
  `policy_ref` varchar(40) NOT NULL DEFAULT '',
  `next_due` date DEFAULT NULL,
  `state` varchar(24) NOT NULL DEFAULT 'registered',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gvo` (`company_id`,`obligation_no`),
  CONSTRAINT `chk_gvo_state` CHECK (`state` in ('registered','monitored','met','breached','retired')),
  CONSTRAINT `chk_gvo_owner` CHECK (`owner_dept` <> '' and `authority_ar` <> ''),
  CONSTRAINT `chk_gvo_period` CHECK (`periodicity` in ('once','monthly','quarterly','semiannual','annual','on_event'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 GOV-04 - الالتزام التنظيمي بجهته ودوريته ومالكه';

-- ── Table: gov_orphan_consumer_rulings ──
CREATE TABLE `gov_orphan_consumer_rulings` (
  `consumer_key` varchar(64) NOT NULL,
  `event_codes` varchar(400) NOT NULL COMMENT 'الأحداثُ المشترَكُ فيها — مقيسة',
  `ruling` varchar(32) NOT NULL COMMENT 'NO_HANDLER_ON_DISK · NEEDS_OWNER_DECISION',
  `owner` varchar(96) NOT NULL,
  `reason` varchar(500) NOT NULL,
  `evidence` varchar(300) NOT NULL,
  `ruled_at` datetime NOT NULL,
  PRIMARY KEY (`consumer_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='FR-EVT-003 — اليتيمُ يُحكَم مرّةً ولا يُنذَر كلَّ ساعة';

-- ── Table: gov_orphan_links ──
CREATE TABLE `gov_orphan_links` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0,
  `sheet_role` varchar(120) NOT NULL COMMENT 'الورقةُ الحية — دورُ القائمةِ في الدفتر',
  `label_ar` varchar(200) NOT NULL,
  `route` varchar(160) NOT NULL,
  `live_class` varchar(120) NOT NULL DEFAULT '' COMMENT 'التصنيفُ الحي',
  `proposed_group` varchar(160) NOT NULL DEFAULT '' COMMENT 'المجموعةُ المقترحةُ في الدفتر',
  `proposal_method` varchar(120) NOT NULL DEFAULT '',
  `owner_decision` enum('pending','approved','relocated','retired') NOT NULL DEFAULT 'pending' COMMENT 'قرارُ المالكِ صفًّا صفًّا — pending حتى يصدر',
  `decided_at` datetime DEFAULT NULL,
  `deactivated_nav_ids` varchar(255) NOT NULL DEFAULT '' COMMENT 'روابطُ nav_items التي عُطِّلت — للعكسِ الدقيق',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_orphan` (`sheet_role`,`route`,`label_ar`),
  KEY `ix_decision` (`owner_decision`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='UXW-01 §8 — الروابطُ اليتيمةُ في مركزِ الحوكمةِ التقنيِّ حتى قرارِ المالك';

-- ── Table: gov_ownership_rulings ──
CREATE TABLE `gov_ownership_rulings` (
  `route` varchar(190) NOT NULL,
  `owner_before` varchar(120) NOT NULL,
  `owner_after` varchar(120) NOT NULL,
  `witness` varchar(255) NOT NULL COMMENT 'الشاهدُ ومصدرُه',
  `witness_kind` enum('DOMAIN_WRITE','DATA_READ','DOC_CYCLE','NONE','VARIANT_OF_BASE') NOT NULL,
  `ruling` enum('OWNER_CONFIRMED','OWNER_CHANGED','APPEARANCE_MISSING','SHARED_PLATFORM','NOT_APPLICABLE','OWNER_ESTABLISHED') NOT NULL,
  `reason` varchar(400) NOT NULL DEFAULT '',
  `decided_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`route`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ثامنًا-٣ حسمُ المِلكيةِ المشكوكة — بالشاهدِ أو بالدورةِ المستندية';

-- ── Table: gov_path_rulings ──
CREATE TABLE `gov_path_rulings` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `gap` varchar(16) NOT NULL,
  `path_key` varchar(96) NOT NULL,
  `ruling` varchar(32) NOT NULL COMMENT 'AUTHORITY | NON_AUTHORITATIVE | SUBORDINATE | ACTIVE_ENGINE | STAGING_ONLY',
  `authority_of` varchar(96) DEFAULT NULL COMMENT 'إن كان تابعًا فمن يحكمه',
  `prod_readers` smallint(5) unsigned NOT NULL,
  `evidence` varchar(300) NOT NULL,
  `reason` varchar(500) NOT NULL,
  `decided_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_path` (`path_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GAP-24 و GAP-31 — حكمٌ مكتوبٌ لكلِّ مسارٍ يحمل معنًى حاكمًا';

-- ── Table: gov_permission_corrections ──
CREATE TABLE `gov_permission_corrections` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `module_code` varchar(160) NOT NULL,
  `role_id` int(11) NOT NULL,
  `field` varchar(24) NOT NULL,
  `old_value` tinyint(4) NOT NULL,
  `new_value` tinyint(4) NOT NULL,
  `policy_source` varchar(255) NOT NULL COMMENT 'نصُّ السياسةِ ومرجعُها — لا منحَ بلا سند',
  `applied_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_mod_role` (`module_code`,`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='تصحيحاتُ صلاحياتٍ تُعبّر عن سياسةٍ منصوصة — بأثرٍ مقروءٍ لا صامت';

-- ── Table: gov_phantom_policy_rulings ──
CREATE TABLE `gov_phantom_policy_rulings` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `source_register` varchar(64) NOT NULL,
  `declared_target` varchar(160) NOT NULL,
  `ruling` varchar(32) NOT NULL COMMENT 'NO_REAL_TARGET · SUPERSEDED · NEEDS_OWNER_DECISION',
  `candidates` varchar(600) NOT NULL COMMENT 'أعمدةٌ حقيقيةٌ مرشَّحةٌ — مقيسة',
  `candidate_count` int(11) NOT NULL,
  `reason` varchar(600) NOT NULL,
  `owner` varchar(96) NOT NULL,
  `ruled_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_target` (`declared_target`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='FR-SEC-005 — لا سياسةَ وهميةً بلا حكم';

-- ── Table: gov_policy ──
CREATE TABLE `gov_policy` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `policy_no` varchar(40) NOT NULL,
  `version_no` smallint(6) NOT NULL DEFAULT 1,
  `title_ar` varchar(255) NOT NULL DEFAULT '',
  `domain_ar` varchar(120) NOT NULL DEFAULT '',
  `owner_dept` varchar(12) NOT NULL DEFAULT '',
  `owner_person` int(11) NOT NULL DEFAULT 0,
  `doc_ref` varchar(120) NOT NULL DEFAULT '',
  `effective_from` date DEFAULT NULL,
  `review_due` date DEFAULT NULL,
  `review_periodicity` varchar(24) DEFAULT NULL COMMENT 'دورية المراجعة - خانة ادخال مفتوحة بنص الورقة',
  `supersedes` varchar(40) NOT NULL DEFAULT '',
  `authored_by` int(11) NOT NULL DEFAULT 0,
  `reviewed_by` int(11) NOT NULL DEFAULT 0,
  `approved_by` int(11) NOT NULL DEFAULT 0,
  `approved_at` datetime DEFAULT NULL,
  `state` varchar(24) NOT NULL DEFAULT 'draft',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gvp` (`company_id`,`policy_no`,`version_no`),
  CONSTRAINT `chk_gvp_state` CHECK (`state` in ('draft','reviewed','approved','effective','superseded','retired')),
  CONSTRAINT `chk_gvp_owner` CHECK (`state` = 'draft' or `owner_dept` <> '' and `owner_person` <> 0),
  CONSTRAINT `chk_gvp_sod` CHECK (`approved_by` = 0 or `approved_by` <> `authored_by`),
  CONSTRAINT `chk_gvp_effective_doc` CHECK (`state` <> 'effective' or `doc_ref` <> '' and `effective_from` is not null)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 GOV-03 - سجل السياسات بالاصدار ولا سياسة بلا مالك';

-- ── Table: gov_policy_changes ──
CREATE TABLE `gov_policy_changes` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `policy_key` varchar(80) NOT NULL,
  `old_rule` text NOT NULL COMMENT 'نصُّ الحكمِ السابقِ كما كان — لا يُمحى',
  `new_rule` text NOT NULL,
  `changed_on` date NOT NULL,
  `reason` text NOT NULL COMMENT 'سببُ التعديلِ بنصِّ صاحبِ القرار',
  `source_ref` varchar(120) NOT NULL COMMENT 'مرجعُ الوثيقةِ والفصل',
  `recorded_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_key_date` (`policy_key`,`changed_on`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='تاريخُ الأحكامِ الحاكمة — القديمُ يبقى بتاريخِه وسببِه';

-- ── Table: gov_pollution_findings ──
CREATE TABLE `gov_pollution_findings` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `table_name` varchar(64) NOT NULL,
  `column_name` varchar(64) NOT NULL,
  `marker` varchar(24) NOT NULL COMMENT 'UAT · TEST · SEED · DEMO · SAMPLE · NOTE_IN_CODE',
  `hits` int(10) unsigned NOT NULL,
  `sample_value` varchar(255) DEFAULT NULL,
  `column_role` varchar(40) DEFAULT NULL COMMENT 'خانةُ رمزٍ/تعدادٍ أم حقلٌ نصيٌّ مشروع',
  `verdict` enum('UNCLASSIFIED','LEGIT_PRODUCTION','TEST_POLLUTION','SUSPECT') NOT NULL DEFAULT 'UNCLASSIFIED' COMMENT 'التصنيفُ الثلاثيُّ — والافتراضُ «غيرُ مصنَّف» لا «تلوث»',
  `action_taken` enum('NONE','QUARANTINED','FIXED') NOT NULL DEFAULT 'NONE',
  `scanned_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_tcm` (`table_name`,`column_name`,`marker`),
  KEY `ix_verdict` (`verdict`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='جردُ التلوثِ — الجولةُ الأولى قراءةٌ فقط ولا كتابةَ في بيانات';

-- ── Table: gov_profile_items ──
CREATE TABLE `gov_profile_items` (
  `item_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0,
  `profile_id` int(10) unsigned NOT NULL,
  `item_kind` enum('screen','action','cap','scope','field') NOT NULL,
  `item_ref` varchar(160) NOT NULL COMMENT 'مرجعُ البند: كودُ الشاشةِ أو الفعلِ أو السقفِ أو النطاقِ أو الحقل',
  `allow` tinyint(1) NOT NULL DEFAULT 1,
  `can_add` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'للشاشة: يُعِدّ',
  `can_edit` tinyint(1) NOT NULL DEFAULT 0,
  `can_delete` tinyint(1) NOT NULL DEFAULT 0,
  `seeded_from` varchar(60) NOT NULL DEFAULT '' COMMENT 'مصدرُ البذرِ المقيس: role_permissions:<role_id>',
  PRIMARY KEY (`item_id`),
  UNIQUE KEY `uq_item` (`profile_id`,`item_kind`,`item_ref`),
  KEY `ix_profile` (`profile_id`),
  CONSTRAINT `fk_pi_profile` FOREIGN KEY (`profile_id`) REFERENCES `gov_role_profiles` (`profile_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GOV-AUTH-01 §5-1 — بنودُ القالبِ الستة';

-- ── Table: gov_redirect_repoint_log ──
CREATE TABLE `gov_redirect_repoint_log` (
  `old_route` varchar(128) NOT NULL,
  `heir_before` varchar(128) NOT NULL,
  `heir_after` varchar(128) NOT NULL,
  `basis` varchar(255) NOT NULL,
  `at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`old_route`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='تحويلٌ أُعيد توجيهُه لأن وارثَه صار تبويبًا — بالأصلِ للرجوع';

-- ── Table: gov_related_party ──
CREATE TABLE `gov_related_party` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `party_no` varchar(40) NOT NULL,
  `party_name` varchar(255) NOT NULL DEFAULT '',
  `relation_ar` varchar(200) NOT NULL DEFAULT '',
  `person_id` int(11) NOT NULL DEFAULT 0,
  `deal_ref` varchar(120) NOT NULL DEFAULT '',
  `deal_amount` decimal(18,2) DEFAULT NULL,
  `deal_currency` varchar(8) NOT NULL DEFAULT '',
  `disclosure_no` varchar(40) NOT NULL DEFAULT '' COMMENT 'AAM-015 الالزامي',
  `from_legal_entity_id` int(10) unsigned NOT NULL DEFAULT 0,
  `to_legal_entity_id` int(10) unsigned NOT NULL DEFAULT 0,
  `intercompany_flag` tinyint(1) NOT NULL DEFAULT 0,
  `counterparty_entity_id` int(10) unsigned NOT NULL DEFAULT 0,
  `transaction_type` varchar(40) NOT NULL DEFAULT '',
  `counterparty_ref` varchar(120) NOT NULL DEFAULT '',
  `state` varchar(24) NOT NULL DEFAULT 'declared',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_grp` (`company_id`,`party_no`),
  CONSTRAINT `chk_grp_state` CHECK (`state` in ('declared','verified','active','ended')),
  CONSTRAINT `chk_grp_disclosure` CHECK (`state` = 'declared' or `disclosure_no` <> ''),
  CONSTRAINT `chk_grp_not_self` CHECK (`intercompany_flag` = 0 or `from_legal_entity_id` <> `to_legal_entity_id`),
  CONSTRAINT `chk_grp_intercompany` CHECK (`intercompany_flag` = 0 or `from_legal_entity_id` > 0 and `to_legal_entity_id` > 0 and `counterparty_entity_id` > 0 and `transaction_type` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 GOV-11 - الطرف ذو العلاقة وتعامله موسوما بين الكيانات منذ انشائه';

-- ── Table: gov_req_id_recon ──
CREATE TABLE `gov_req_id_recon` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `pack_ref` varchar(60) NOT NULL COMMENT 'مرجعُ نسخةِ الحزمةِ المسبِّبة',
  `unit` varchar(160) NOT NULL,
  `old_id` varchar(32) DEFAULT NULL COMMENT 'NULL لهدفٍ جديدٍ لا سلفَ له',
  `new_id` varchar(32) NOT NULL,
  `surface_norm` varchar(255) NOT NULL COMMENT 'الاسمُ المطبَّعُ — مفتاحُ المزاوجةِ لا الرقم',
  `kind` enum('UNCHANGED','SHIFTED','NEW_TARGET') NOT NULL,
  `basis` varchar(400) NOT NULL,
  `reconciled_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pack_new` (`pack_ref`,`new_id`),
  KEY `ix_old` (`old_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='م 121: مصالحةُ معرِّفاتِ المتطلّباتِ بين نسخِ الحزمةِ — بالاسمِ المطبَّعِ والحكمُ يُرحَّل لا يُدهَس';

-- ── Table: gov_request_type ──
CREATE TABLE `gov_request_type` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `type_code` varchar(48) NOT NULL,
  `version_no` smallint(6) NOT NULL DEFAULT 1,
  `name_ar` varchar(200) NOT NULL DEFAULT '',
  `definition_owner_dept` varchar(12) NOT NULL DEFAULT '' COMMENT 'المجال يملك تعريف طلبه',
  `registry_governed_by` varchar(12) NOT NULL DEFAULT 'DEP-08' COMMENT 'الحوكمة تحكم السجل',
  `authority_rule_id` varchar(48) NOT NULL DEFAULT '' COMMENT 'AAM يحدد من يعتمد',
  `routing_rule_ref` varchar(64) NOT NULL DEFAULT '' COMMENT 'النظام ينفذ التوجيه',
  `permission_policy` varchar(60) NOT NULL DEFAULT '',
  `exception_policy` varchar(60) NOT NULL DEFAULT '',
  `retired_at` date DEFAULT NULL,
  `state` varchar(24) NOT NULL DEFAULT 'draft',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `owner_table` varchar(96) NOT NULL DEFAULT '' COMMENT 'جدول المالك الذي ينشا فيه الطلب - النظام ينفذ التوجيه',
  `owner_service` varchar(200) NOT NULL DEFAULT '' COMMENT 'خدمة المالك التي تنشئ السجل - ولا يكتب المطلق مباشرة',
  `projection_user_col` varchar(64) NOT NULL DEFAULT '' COMMENT 'عمود صاحب الطلب في جدول المالك - به تقرا مساحة عملي اسقاطها',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_grt` (`company_id`,`type_code`,`version_no`),
  CONSTRAINT `chk_grt_state` CHECK (`state` in ('draft','approved','active','superseded','retired')),
  CONSTRAINT `chk_grt_gov` CHECK (`registry_governed_by` = 'DEP-08'),
  CONSTRAINT `chk_grt_domain` CHECK (`definition_owner_dept` <> '' and `definition_owner_dept` <> 'DEP-08'),
  CONSTRAINT `chk_grt_active` CHECK (`state` <> 'active' or `authority_rule_id` <> '' and `routing_rule_ref` <> '' and `permission_policy` <> ''),
  CONSTRAINT `chk_grt_retired` CHECK (`state` <> 'retired' or `retired_at` is not null),
  CONSTRAINT `chk_grt_binding` CHECK (`state` <> 'active' or `owner_table` <> '' and `owner_service` <> '' and `projection_user_col` <> ''),
  CONSTRAINT `chk_grt_not_workspace` CHECK (`definition_owner_dept` <> 'WS-MY')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 - سجل انواع الطلبات قدرة مركزية تحكمها الحوكمة ولا توجه يوميا';

-- ── Table: gov_restricted_views ──
CREATE TABLE `gov_restricted_views` (
  `view_key` varchar(60) NOT NULL COMMENT 'مُعرِّفُ المنظر',
  `source_table` varchar(64) NOT NULL COMMENT 'جدولُ المصدر',
  `owner_dept_ar` varchar(120) NOT NULL COMMENT 'مالكُ المصدر',
  `consumer_space` varchar(80) NOT NULL COMMENT 'المساحةُ المستهلِكة',
  `purpose_ar` varchar(255) NOT NULL COMMENT 'غرضُه — ولا منظرَ بلا غرضٍ مكتوب',
  `row_scope_col` varchar(64) NOT NULL COMMENT 'عمودُ نطاقِ الصفِّ — يُحقن في الشرطِ لا يُرشَّح بعدَه',
  `field_allowlist` varchar(500) NOT NULL COMMENT 'الحقولُ المسموحةُ حصرًا',
  `allow_export` tinyint(1) NOT NULL DEFAULT 0,
  `needs_audit` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'أيلزمه أثرٌ في سجلِّ الاطّلاع',
  `replaces_route` varchar(190) NOT NULL DEFAULT '' COMMENT 'الشاشةُ الممنوعةُ التي يحلُّ محلَّها',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`view_key`),
  KEY `ix_grv_space` (`consumer_space`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='سادسًا — المنظرُ المقيَّدُ: row_scope × field_allowlist';

-- ── Table: gov_role_profiles ──
CREATE TABLE `gov_role_profiles` (
  `profile_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'عمودُ العزل — 0: قالبٌ معياريٌّ لكلِّ الكيانات',
  `profile_code` varchar(20) NOT NULL COMMENT 'رمزُ الورقة: DEPT-G#',
  `grade` enum('G1','G2','G3','G4','G5','G6','G7','G8','G9') NOT NULL,
  `dept_code` varchar(120) NOT NULL COMMENT 'الإدارةُ بنصِّ ورقةِ الدفتر',
  `title_ar` varchar(120) NOT NULL,
  `screens_target` smallint(5) unsigned NOT NULL DEFAULT 0 COMMENT 'عددُ الشاشاتِ المستهدَفُ من الورقة',
  `prepares_target` smallint(5) unsigned NOT NULL DEFAULT 0,
  `approves_target` smallint(5) unsigned NOT NULL DEFAULT 0,
  `approval_cap_label` varchar(200) NOT NULL DEFAULT '' COMMENT 'سقفُ الاعتمادِ نصًّا — الأرقامُ مرجعُها 24-أ وهي موقوفةٌ Fail-Closed',
  `data_scope` varchar(120) NOT NULL DEFAULT '',
  `sensitive_fields` varchar(200) NOT NULL DEFAULT '',
  `fixed_rule` varchar(255) NOT NULL DEFAULT '' COMMENT 'القيدُ الثابتُ من الورقة',
  `version` smallint(5) unsigned NOT NULL DEFAULT 1 COMMENT 'لا يُعدَّل نافذٌ في مكانِه — إصدارٌ جديدٌ ويُرحَّل حاملوه',
  `state` enum('draft','active','retired') NOT NULL DEFAULT 'draft' COMMENT 'draft حتى اعتمادِ تقريرِ الفروق',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`profile_id`),
  UNIQUE KEY `uq_profile` (`company_id`,`profile_code`,`version`),
  KEY `ix_grade_dept` (`grade`,`dept_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GOV-AUTH-01 A2 — قالبُ المسمَّى: تسعُ درجاتٍ × الإداراتِ التسعَ عشرة';

-- ── Table: gov_screen_cycle ──
CREATE TABLE `gov_screen_cycle` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'عمودُ العزل — 0: مصفوفةٌ معياريةٌ لكلِّ الكيانات',
  `dept_name` varchar(120) NOT NULL,
  `layer_name` varchar(60) NOT NULL COMMENT 'مركزُ العمل · دورةُ الإدارة · المرجعُ والإدارة',
  `stage_order` varchar(10) NOT NULL DEFAULT '',
  `stage_name` varchar(160) NOT NULL DEFAULT '',
  `group_name` varchar(160) NOT NULL DEFAULT '',
  `screen_title` varchar(255) NOT NULL,
  `screen_file` varchar(160) NOT NULL DEFAULT '' COMMENT 'مفتاحُ عرضِ الترويسة — فارغٌ حيث لا ملفَ في الورقة',
  `inputs_note` varchar(255) NOT NULL DEFAULT '' COMMENT '① ما يدخل',
  `output_doc` varchar(255) NOT NULL DEFAULT '' COMMENT '② المستندُ الرسميُّ الناتج — NM-06',
  `resp_role` varchar(160) NOT NULL DEFAULT '' COMMENT '③④ من يراجع/يعتمد',
  `next_state` varchar(255) NOT NULL DEFAULT '' COMMENT '⑤ الحالةُ التالية',
  `consumers` varchar(255) NOT NULL DEFAULT '' COMMENT '⑥ الإدارةُ المستهلكة',
  `fin_impact` varchar(160) NOT NULL DEFAULT '' COMMENT '⑦ الأثرُ الماليّ',
  `stage_kind` enum('canonical','contextual','not_applicable') NOT NULL DEFAULT 'canonical' COMMENT 'NF-13 — canonical: مرحلة قانونية · contextual: قراءة سياقية · not_applicable: سبب عدم انطباق (5-10)',
  `screen_id` varchar(12) NOT NULL DEFAULT '' COMMENT 'معرف الشاشة — الوصل بالمعرف لا بالاسم (7-13)',
  `bridge_rule` enum('','BASENAME_UNIQUE','AMBIGUOUS_DECLARED','NO_LIVE_SURFACE','PATH_OR_SCOPE_RESOLVED','C5_AUTHORED','C5_NOT_APPLICABLE','C6_MANUAL_AMBIG') NOT NULL DEFAULT '' COMMENT 'قاعدة الجسر — والمقياس يعلن ايتها حكمت',
  `bridge_witness` varchar(400) NOT NULL DEFAULT '' COMMENT 'شاهد الحل او شاهد تعذره',
  `bridge_snapshot` varchar(48) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `ix_file` (`screen_file`),
  KEY `ix_dept` (`dept_name`),
  KEY `ix_cyc_screen` (`screen_id`),
  KEY `ix_cyc_rule` (`bridge_rule`),
  CONSTRAINT `chk_cyc_bridge` CHECK (`bridge_rule` in ('BASENAME_UNIQUE','PATH_OR_SCOPE_RESOLVED','C5_AUTHORED','C5_NOT_APPLICABLE','C6_MANUAL_AMBIG') and `screen_id` <> '' or `bridge_rule` not in ('BASENAME_UNIQUE','PATH_OR_SCOPE_RESOLVED','C5_AUTHORED','C5_NOT_APPLICABLE','C6_MANUAL_AMBIG') and `screen_id` = '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='UXW-01 §7-1 — مصفوفةُ التحققِ الحاكمةُ: عناصرُ الدورةِ السبعةُ لكلِّ شاشة';

-- ── Table: gov_screen_path_map ──
CREATE TABLE `gov_screen_path_map` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `book_file` varchar(128) NOT NULL COMMENT 'الاسمُ كما في دفترِ الدورة',
  `real_route` varchar(192) DEFAULT NULL COMMENT 'المسارُ الحقيقيُّ على القرص',
  `ruling` varchar(24) NOT NULL COMMENT 'RENAMED_TO | VIEW_OF | MERGED_INTO | OWNED_ELSEWHERE | NOT_BUILT',
  `owner_dept` varchar(64) DEFAULT NULL,
  `chain_node` tinyint(3) unsigned DEFAULT NULL COMMENT 'رقمُ العقدةِ في سلسلةِ الأثرِ إن كانت منها',
  `build_wave` tinyint(3) unsigned DEFAULT NULL COMMENT 'موجةُ البناءِ لغيرِ المبنيّ',
  `source_doc` varchar(32) NOT NULL COMMENT 'الوثيقةُ الحاكمةُ لهذا الحكم',
  `reason` varchar(400) NOT NULL,
  `applied_to_cycle` tinyint(1) NOT NULL DEFAULT 0,
  `decided_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_book` (`book_file`),
  KEY `ix_ruling` (`ruling`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='INJ-EXEC-01 ① — الاسمُ الدفتريُّ ومسارُه الحقيقيُّ بحكمٍ مكتوب';

-- ── Table: gov_sensitive_policy_debt ──
CREATE TABLE `gov_sensitive_policy_debt` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `source_register` varchar(48) NOT NULL COMMENT 'أيُّ سجلٍّ أعلن السياسة',
  `declared_target` varchar(160) NOT NULL COMMENT 'الهدفُ كما كُتب',
  `target_state` varchar(32) NOT NULL COMMENT 'NO_TABLE | NO_COLUMN',
  `real_column` varchar(160) DEFAULT NULL COMMENT 'العمودُ الحقيقيُّ إن عُرف يقينًا',
  `real_column_protected` tinyint(1) NOT NULL DEFAULT 0,
  `note` varchar(400) NOT NULL,
  `detected_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_target` (`source_register`,`declared_target`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='INJ-FIX-02 NF-09 — سياساتٌ تُعلن حمايةً لهدفٍ لا وجودَ له';

-- ── Table: gov_sheet_decisions ──
CREATE TABLE `gov_sheet_decisions` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `doc_code` varchar(24) NOT NULL COMMENT 'INJ-SAL-ALIGN-01 | INJ-SUP-ALIGN-01',
  `sheet_code` varchar(12) NOT NULL,
  `sheet_ar` varchar(160) NOT NULL,
  `stage_ar` varchar(80) NOT NULL COMMENT 'مرحلةُ الدورةِ الحاكمة',
  `decision` varchar(40) NOT NULL,
  `target` varchar(220) NOT NULL COMMENT 'السطحُ المستهدَفُ أو سببُ عدمِ وجودِه',
  `is_index` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'ورقةُ فهرسٍ — خارجَ مقامِ أوراقِ العمل',
  `note` varchar(300) DEFAULT NULL,
  `decided_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sheet` (`doc_code`,`sheet_code`),
  KEY `ix_decision` (`decision`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='قرارُ السطحِ لكلِّ ورقةٍ في وثيقتَي المواءمة — منقولٌ حرفًا';

-- ── Table: gov_sod_conflict ──
CREATE TABLE `gov_sod_conflict` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `conflict_code` varchar(40) NOT NULL,
  `title_ar` varchar(200) NOT NULL DEFAULT '',
  `side_a` varchar(120) NOT NULL DEFAULT '' COMMENT 'طرف العملية الاول',
  `side_b` varchar(120) NOT NULL DEFAULT '' COMMENT 'طرف العملية الثاني',
  `process_key` varchar(64) NOT NULL DEFAULT '',
  `detected_role_id` int(11) NOT NULL DEFAULT 0,
  `detected_user_id` int(11) NOT NULL DEFAULT 0,
  `detected_at` datetime DEFAULT NULL,
  `mitigation_ar` varchar(400) NOT NULL DEFAULT '',
  `exception_no` varchar(40) NOT NULL DEFAULT '',
  `state` varchar(24) NOT NULL DEFAULT 'defined',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `severity` varchar(24) DEFAULT NULL COMMENT 'درجة الخطورة',
  `treatment_decision` varchar(24) DEFAULT NULL COMMENT 'قرار المعالجة',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gsc` (`company_id`,`conflict_code`,`detected_role_id`,`detected_user_id`),
  CONSTRAINT `chk_gsc_sides` CHECK (`side_a` <> '' and `side_b` <> '' and `side_a` <> `side_b`),
  CONSTRAINT `chk_gsc_state` CHECK (`state` in ('defined','detected','mitigated','accepted','closed')),
  CONSTRAINT `chk_gsc_accept` CHECK (`state` <> 'accepted' or `exception_no` <> ''),
  CONSTRAINT `chk_gsc_mitigate` CHECK (`state` <> 'mitigated' or `mitigation_ar` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 GOV-16 - التعارض يعرف مرة ويكشف دوما ولا قبول بلا استثناء';

-- ── Table: gov_space_appearances ──
CREATE TABLE `gov_space_appearances` (
  `id` int(11) NOT NULL,
  `space_ar` varchar(80) NOT NULL COMMENT 'مساحةُ العمل',
  `space_kind` enum('DEPARTMENT','ROLE','CONTROL','EXECUTIVE','PERSONAL') NOT NULL,
  `tab_ar` varchar(120) NOT NULL DEFAULT '',
  `screen_ar` varchar(190) NOT NULL DEFAULT '',
  `route` varchar(190) NOT NULL,
  `owner_dept_ar` varchar(120) NOT NULL DEFAULT '',
  `owner_kind` enum('BUSINESS_DEPARTMENT','PLATFORM_SHARED') NOT NULL DEFAULT 'BUSINESS_DEPARTMENT',
  `src_class` varchar(32) NOT NULL DEFAULT '' COMMENT '① صنفُ الظهورِ كما ورد',
  `src_ownership` varchar(32) NOT NULL DEFAULT '' COMMENT '② حالةُ المِلكيةِ كما وردت',
  `src_decision` varchar(32) NOT NULL DEFAULT '' COMMENT '③ حالةُ القرارِ كما وردت',
  `src_note` varchar(255) NOT NULL DEFAULT '',
  `spaces_count` smallint(6) NOT NULL DEFAULT 0 COMMENT 'في كم مساحةٍ يظهر هذا المسار',
  `cls` varchar(32) NOT NULL DEFAULT '' COMMENT 'صنفُ الظهورِ بعدَ إعادةِ التصنيف',
  `ownership` varchar(32) NOT NULL DEFAULT '',
  `decision` varchar(32) NOT NULL DEFAULT '',
  `basis` varchar(255) NOT NULL DEFAULT '' COMMENT 'الشاهدُ الذي أوجبَ الحكمَ — لا رأيٌ',
  `rule_step` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'أيُّ عقدةٍ من شجرةِ القرارِ حسمَته (١..٦)',
  `view_fields` varchar(500) NOT NULL DEFAULT '' COMMENT 'حقولُ المنظرِ المقيَّدِ إن كان',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_gsa_space` (`space_ar`),
  KEY `ix_gsa_route` (`route`),
  KEY `ix_gsa_cls` (`cls`),
  KEY `ix_gsa_own` (`ownership`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ثامنًا-١ لقطةُ الحال — 887 موضعَ ظهورٍ بثلاثةِ محاورَ مستقلة';

-- ── Table: gov_space_roles ──
CREATE TABLE `gov_space_roles` (
  `role_id` int(11) NOT NULL,
  `space_ar` varchar(80) NOT NULL,
  `overlap_pct` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT 'ثقةُ الربطِ — نسبةُ تقاطعِ المسارات',
  `matched` smallint(6) NOT NULL DEFAULT 0,
  `role_routes` smallint(6) NOT NULL DEFAULT 0,
  `basis` varchar(190) NOT NULL DEFAULT '',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`role_id`),
  KEY `ix_gsr_space` (`space_ar`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='رابعًا — الدورُ ⇄ مساحتُه، مقيسًا بتقاطعِ المساراتِ المُصيَّرة';

-- ── Table: gov_space_url_shadow ──
CREATE TABLE `gov_space_url_shadow` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `route` varchar(200) NOT NULL,
  `space_ar` varchar(120) NOT NULL,
  `role_id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `mode` varchar(12) NOT NULL COMMENT 'observe · enforce',
  `seen_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_route_space` (`route`,`space_ar`),
  KEY `ix_seen` (`seen_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='FR-SEC-008 — ما كان سيُمنَع لو أُنفِذ حارسُ العنوانِ المباشر';

-- ── Table: gov_stage_outputs ──
CREATE TABLE `gov_stage_outputs` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'عمودُ العزل — 0 = كلُّ كيان',
  `role_id` smallint(5) unsigned NOT NULL COMMENT 'الإدارةُ المالكة',
  `stage_no` tinyint(3) unsigned NOT NULL,
  `stage_title` varchar(190) NOT NULL,
  `output_doc` varchar(255) DEFAULT NULL COMMENT 'المستندُ الناتج',
  `output_source` enum('GOV-24','LAD-01','action_writes','nav09_map','none') NOT NULL DEFAULT 'none',
  `next_state` varchar(255) DEFAULT NULL COMMENT 'الحالةُ التالية',
  `next_source` enum('GOV-24','LAD-01','cycle_order','nav09_map','none') NOT NULL DEFAULT 'none',
  `approver_note` varchar(190) DEFAULT NULL COMMENT 'المعتمِدُ كما في الوثيقة',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_stage` (`role_id`,`stage_no`),
  KEY `ix_src` (`output_source`,`next_source`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='⑨ المستندُ الناتجُ والحالةُ التالية — ولكلِّ خانةٍ مصدرُها المعلَن';

-- ── Table: gov_target_nav ──
CREATE TABLE `gov_target_nav` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `doc_code` varchar(24) NOT NULL,
  `role_id` int(11) NOT NULL,
  `group_no` tinyint(3) unsigned NOT NULL,
  `group_ar` varchar(120) NOT NULL,
  `item_no` tinyint(3) unsigned NOT NULL,
  `item_ar` varchar(120) NOT NULL,
  `route` varchar(160) NOT NULL,
  `note` varchar(300) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_tn` (`doc_code`,`route`),
  KEY `ix_tn_role` (`role_id`,`group_no`,`item_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='التنقّلُ المستهدَفُ بعدَ الدمج — منقولٌ من وثيقتَي المواءمة';

-- ── Table: gov_test_data_isolation ──
CREATE TABLE `gov_test_data_isolation` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `table_name` varchar(64) NOT NULL,
  `pk_column` varchar(64) NOT NULL,
  `pk_value` varchar(64) NOT NULL,
  `column_name` varchar(64) NOT NULL,
  `original_value` text NOT NULL COMMENT 'النصُّ الأصليُّ محفوظًا — لا يُفقد',
  `source_ref` varchar(190) NOT NULL COMMENT 'مرجعُ النصِّ كما وُجد',
  `reason` varchar(190) NOT NULL,
  `column_nullable` tinyint(1) NOT NULL COMMENT 'أيقبل الحقلُ NULL؟ يحدّد العلاجَ الممكن',
  `policy_domain` enum('NAVIGATION_NAMING_POSITION','PERMISSIONS','APPROVAL_LADDERS','FINANCIAL_CAPS','SEGREGATION_OF_DUTIES','LEGAL_OBLIGATIONS','FINANCIAL_DECISIONS','OPERATIONAL_DATA') NOT NULL DEFAULT 'OPERATIONAL_DATA',
  `resolution` enum('PENDING_SOURCE','PENDING_OWNER','QUARANTINED','RESOLVED') NOT NULL DEFAULT 'PENDING_SOURCE',
  `registered_at` datetime NOT NULL DEFAULT current_timestamp(),
  `resolved_value` varchar(190) DEFAULT NULL COMMENT 'لا تُملأ إلا من مصدرٍ حاكمٍ — والتخمينُ ممنوع',
  `resolved_source` varchar(190) DEFAULT NULL COMMENT 'المصدرُ الحاكمُ الذي أعطى القيمة — بلا مصدرٍ لا حسم',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_row_col` (`table_name`,`pk_value`,`column_name`),
  KEY `ix_res` (`resolution`),
  KEY `ix_dom` (`policy_domain`),
  CONSTRAINT `chk_resolved_needs_source` CHECK (`resolution` <> 'RESOLVED' or `resolved_value` is not null and `resolved_source` is not null)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='عزلٌ بتسجيلٍ — النصُّ محفوظٌ وبياناتُ العملِ لم تُمَسّ';

-- ── Table: gov_test_residue_archive ──
CREATE TABLE `gov_test_residue_archive` (
  `id` bigint(20) unsigned NOT NULL,
  `company_id` bigint(20) unsigned DEFAULT NULL,
  `project_id` bigint(20) unsigned DEFAULT NULL,
  `contract_id` bigint(20) unsigned DEFAULT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `employee_id` bigint(20) unsigned DEFAULT NULL COMMENT 'لقطة الموظف الفاعل وقت الحدث',
  `role_id` bigint(20) unsigned DEFAULT NULL,
  `role_name` varchar(255) DEFAULT NULL,
  `session_id` varchar(255) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `screen_name` varchar(255) DEFAULT NULL,
  `module_name` varchar(255) DEFAULT NULL,
  `action_type` varchar(50) DEFAULT NULL,
  `button_name` varchar(255) DEFAULT NULL,
  `field_name` varchar(255) DEFAULT NULL,
  `record_id` bigint(20) unsigned DEFAULT NULL,
  `old_value` longtext DEFAULT NULL,
  `new_value` longtext DEFAULT NULL,
  `url` text DEFAULT NULL,
  `http_method` varchar(10) DEFAULT NULL,
  `request_payload` longtext DEFAULT NULL,
  `response_status` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `acted_by` bigint(20) unsigned DEFAULT NULL COMMENT 'الفاعلُ الحقيقيُّ في جلسةِ النيابة (A5)',
  `acted_for` bigint(20) unsigned DEFAULT NULL COMMENT 'من نُفِّذ عنه',
  `impersonation_id` int(10) unsigned DEFAULT NULL COMMENT 'مرجعُ جلسةِ impersonation_sessions',
  `src_table` varchar(64) NOT NULL DEFAULT 'activity_logs',
  `quarantined_at` datetime NOT NULL DEFAULT current_timestamp(),
  `reason` varchar(255) NOT NULL DEFAULT '',
  KEY `idx_company_created` (`company_id`,`created_at`),
  KEY `idx_user_created` (`user_id`,`created_at`),
  KEY `idx_role_created` (`role_id`,`created_at`),
  KEY `idx_action_created` (`action_type`,`created_at`),
  KEY `idx_module_screen_created` (`module_name`,`screen_name`,`created_at`),
  KEY `idx_record_module` (`record_id`,`module_name`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_screen_name` (`screen_name`),
  KEY `idx_module_name` (`module_name`),
  KEY `idx_action_type` (`action_type`),
  KEY `idx_record_id` (`record_id`),
  KEY `idx_employee_created` (`employee_id`,`created_at`),
  KEY `ix_impersonation` (`impersonation_id`),
  CONSTRAINT `chk_act_attribution` CHECK (`impersonation_id` is null or `acted_by` is not null and `acted_for` is not null)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: gov_topbar_exemptions ──
CREATE TABLE `gov_topbar_exemptions` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `route` varchar(190) NOT NULL,
  `kind` varchar(32) NOT NULL COMMENT 'SESSION_ACTION | COUNT_ENDPOINT',
  `reason` varchar(400) NOT NULL,
  `declared_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_route` (`route`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GAP-28 — مساراتُ شريطٍ علويٍّ لا يسري عليها عزلُ المساحة، بسببٍ مكتوب';

-- ── Table: gov_visual_measurements ──
CREATE TABLE `gov_visual_measurements` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `screen_file` varchar(160) NOT NULL,
  `viewport_w` smallint(5) unsigned NOT NULL,
  `viewport_h` smallint(5) unsigned NOT NULL,
  `header_px` smallint(5) unsigned DEFAULT NULL COMMENT 'getBoundingClientRect — لا تقديرَ بنيويّ',
  `header_within_limit` tinyint(1) DEFAULT NULL,
  `has_h_scroll` tinyint(1) DEFAULT NULL COMMENT 'تمريرٌ أفقيٌّ للصفحة — والجدولُ مستثنًى',
  `primary_buttons` smallint(5) unsigned DEFAULT NULL,
  `stacked_toolbars` smallint(5) unsigned DEFAULT NULL COMMENT 'أشرطةٌ متراكبةٌ فوقَ جدولٍ واحد',
  `worst_cell_actions` smallint(5) unsigned DEFAULT NULL,
  `row_height_px` smallint(5) unsigned DEFAULT NULL,
  `component_version` varchar(24) DEFAULT NULL COMMENT 'الإصدارُ وقتَ القياس — يبطل بتغيُّرِه',
  `measured_at` datetime NOT NULL DEFAULT current_timestamp(),
  `measured_by` varchar(60) NOT NULL DEFAULT 'browser-probe',
  PRIMARY KEY (`id`),
  KEY `ix_screen_vp` (`screen_file`,`viewport_w`,`measured_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='قياساتُ محرّكِ العرضِ الحقيقيّ — كلُّ رقمٍ بدقتِه ووقتِه وإصدارِ مكوّنِه';

-- ── Table: governance_flags ──
CREATE TABLE `governance_flags` (
  `flag_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `element_code` varchar(80) NOT NULL COMMENT 'external_accounts · signing_caps · joint_signing · guarantees · licenses …',
  `scope_type` enum('entity','contract') NOT NULL,
  `scope_id` int(10) unsigned NOT NULL,
  `enabled` tinyint(1) NOT NULL DEFAULT 0,
  `reason` varchar(255) DEFAULT NULL,
  `set_by` int(11) DEFAULT NULL,
  `set_at` datetime NOT NULL DEFAULT current_timestamp(),
  `activation_pattern` varchar(24) DEFAULT NULL COMMENT 'نمط التفعيل',
  PRIMARY KEY (`flag_id`),
  UNIQUE KEY `uq_gf_element_scope` (`element_code`,`scope_type`,`scope_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='LEG-01 §7: أعلام التفعيل لكل عنصر على الكيان والعقد — الافتراض النمط ① (كله مطفأ)';

-- ── Table: govui_field_closure_log ──
CREATE TABLE `govui_field_closure_log` (
