  PRIMARY KEY (`id`),
  KEY `k_batch` (`batch`),
  KEY `k_company` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ── Table: govui_fields_pre_settle ──
CREATE TABLE `govui_fields_pre_settle` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
