  `wave` varchar(8) NOT NULL DEFAULT '',
  `unit` varchar(160) NOT NULL DEFAULT '',
  `surface` varchar(255) NOT NULL DEFAULT '',
  `seq` varchar(12) NOT NULL DEFAULT '',
  `field_name` varchar(255) NOT NULL DEFAULT '',
  `field_type` varchar(80) NOT NULL DEFAULT '',
  `visibility_rule` varchar(255) NOT NULL DEFAULT '',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `k_req` (`requirement_id`),
  KEY `k_wave` (`wave`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: govui_label_log ──
CREATE TABLE `govui_label_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `target_id` varchar(24) NOT NULL,
  `store` varchar(64) NOT NULL COMMENT 'الجدولُ والعمودُ الذي كُتب',
  `store_key` varchar(200) NOT NULL COMMENT 'مفتاحُ الصفِّ في مخزنِه',
  `old_label` varchar(190) NOT NULL DEFAULT '',
  `new_label` varchar(190) NOT NULL DEFAULT '',
  `source_ref` varchar(190) NOT NULL COMMENT 'الملفُّ والورقةُ والصفُّ الحاكم',
  `reason` varchar(190) NOT NULL DEFAULT '',
  `changed_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_gll_t` (`target_id`),
  KEY `ix_gll_store` (`store`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GOV_UI_EXEC §7 · UI_NAMING_CHANGELOG: كلُّ اسمٍ كُتب بقيمتِه السابقةِ وسندِه';

-- ── Table: govui_space_fix_log ──
CREATE TABLE `govui_space_fix_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `appearance_id` int(11) NOT NULL,
  `space_ar` varchar(80) NOT NULL,
  `route` varchar(190) NOT NULL,
  `old_cls` varchar(32) NOT NULL,
  `old_owner` varchar(120) NOT NULL,
  `new_cls` varchar(32) NOT NULL,
  `new_owner` varchar(120) NOT NULL,
  `basis` varchar(255) NOT NULL,
  `changed_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_gsfl_app` (`appearance_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GOV_UI_EXEC: قيدُ رجوعِ تصحيحِ منعِ السطحِ في مساحتِه المالكة';

-- ── Table: govui_target_registry ──
CREATE TABLE `govui_target_registry` (
  `target_id` varchar(24) NOT NULL COMMENT 'ثابتٌ قبلَ البناءِ وبعدَه (§4)',
  `workspace_id` varchar(24) NOT NULL,
  `workspace_type` varchar(24) NOT NULL COMMENT 'DEPARTMENT · EXECUTIVE · PERSONAL · PLATFORM_UTILITY',
  `department_id` varchar(24) NOT NULL DEFAULT '' COMMENT 'فارغٌ للتنفيذيِّ والشخصيِّ بحكمِ §1',
  `group_id` int(11) DEFAULT NULL,
  `canonical_group_label` varchar(190) NOT NULL DEFAULT '',
  `group_order` smallint(6) DEFAULT NULL,
  `target_screen_id` varchar(12) NOT NULL DEFAULT '' COMMENT 'SCR-#### متى بُني',
  `canonical_screen_label` varchar(190) NOT NULL,
  `screen_order` smallint(6) NOT NULL,
  `surface_type` varchar(16) NOT NULL COMMENT 'أصنافُ §8 السبعة',
  `surface_rule` varchar(190) NOT NULL DEFAULT '' COMMENT 'القاعدةُ التي حسمت الصنف — ولا صنفَ بلا قاعدة',
  `grain` varchar(400) NOT NULL DEFAULT '',
  `owner` varchar(190) NOT NULL DEFAULT '',
  `source_of_truth` varchar(1000) NOT NULL DEFAULT '',
  `required_roles` varchar(255) NOT NULL DEFAULT '',
  `state_model_ref` varchar(255) NOT NULL DEFAULT '',
  `source_file` varchar(120) NOT NULL,
  `source_sheet` varchar(120) NOT NULL,
  `source_row` smallint(6) NOT NULL,
  `built_route` varchar(190) NOT NULL DEFAULT '',
  `built_at_snapshot` varchar(48) NOT NULL DEFAULT '',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`target_id`),
  KEY `ix_gtr_ws` (`workspace_id`,`screen_order`),
  KEY `ix_gtr_surface` (`surface_type`),
  CONSTRAINT `chk_gtr_rule` CHECK (`surface_type` = '' or `surface_rule` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GOV_UI_EXEC §4 — سجلُّ الأهدافِ بتسعةَ عشرَ عمودًا من الملفَّين الحاكمَين';

-- ── Table: govui_universe_log ──
CREATE TABLE `govui_universe_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `target_uid` varchar(12) NOT NULL,
  `requirement_id` varchar(48) NOT NULL,
  `old_screen_id` varchar(12) NOT NULL DEFAULT '',
  `new_screen_id` varchar(12) NOT NULL DEFAULT '',
  `old_verdict` varchar(24) NOT NULL DEFAULT '',
  `new_verdict` varchar(24) NOT NULL DEFAULT '',
  `old_witness` varchar(400) NOT NULL DEFAULT '',
  `witness` varchar(400) NOT NULL,
  `changed_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_gul_t` (`target_uid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GOV_UI_EXEC: قيدُ رجوعِ جسرِ القياسِ بعدَ حكمِ الوصل';

-- ── Table: govui_wiring_log ──
CREATE TABLE `govui_wiring_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `target_id` varchar(24) NOT NULL,
  `old_route` varchar(160) DEFAULT NULL,
  `old_screen_id` varchar(12) DEFAULT NULL,
  `old_type` varchar(16) NOT NULL DEFAULT '',
  `new_route` varchar(160) DEFAULT NULL,
  `new_screen_id` varchar(12) DEFAULT NULL,
  `new_type` varchar(16) NOT NULL DEFAULT '',
  `witness` varchar(400) NOT NULL,
  `changed_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_gwl_t` (`target_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GOV_UI_EXEC §9: قيدُ رجوعِ أحكامِ الوصل';

-- ── Table: guarantees ──
CREATE TABLE `guarantees` (
  `gtee_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `direction` enum('issued','received') NOT NULL COMMENT 'صادرة منا (التزام محتمل) · واردة إلينا (حق محتمل)',
  `entity_id` int(10) unsigned NOT NULL,
  `counterparty_id` int(10) unsigned DEFAULT NULL,
  `gtee_type` varchar(80) NOT NULL,
  `bank` varchar(120) DEFAULT NULL,
  `amount` decimal(18,2) NOT NULL,
  `currency` varchar(8) NOT NULL,
  `issue_date` date DEFAULT NULL,
  `expiry_date` date NOT NULL,
  `alert_days` int(10) unsigned NOT NULL DEFAULT 30,
  `auto_renew` tinyint(1) NOT NULL DEFAULT 0,
  `fees` decimal(18,2) DEFAULT NULL,
  `state` enum('active','released','called','expired') NOT NULL DEFAULT 'active',
  `doc_ref` varchar(120) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`gtee_id`),
  KEY `ix_g_expiry` (`expiry_date`,`state`),
  KEY `fk_g_entity` (`entity_id`),
  CONSTRAINT `fk_g_entity` FOREIGN KEY (`entity_id`) REFERENCES `legal_entities` (`entity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='LEG-01 §5: الكفالات وخطابات الضمان — التزام/حق محتمل خارج الميزانية، مفصول عن المحتجَز النقدي (P-06)';

-- ── Table: guard_denials ──
CREATE TABLE `guard_denials` (
  `deny_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0,
  `guard_code` varchar(64) NOT NULL,
  `person_id` int(11) NOT NULL,
  `attempted_ref` varchar(120) DEFAULT NULL,
  `reason_code` varchar(80) DEFAULT NULL,
  `at` datetime NOT NULL DEFAULT current_timestamp(),
  `verb` varchar(32) NOT NULL DEFAULT '' COMMENT 'الفعلُ الذي رُفض — view/add/edit/delete أو رمزُ الفعل',
  `verb_state` varchar(16) NOT NULL DEFAULT 'REQUIRED' COMMENT 'REQUIRED · PRE_VERB (موروثٌ قبلَ العمود)',
  `actor_role_id` smallint(5) unsigned DEFAULT NULL COMMENT 'صفة الفاعل وقتها',
  `owner_dept` varchar(12) DEFAULT NULL COMMENT 'الادارة المالكة',
  `request_source` varchar(24) DEFAULT NULL COMMENT 'مصدر الطلب',
  PRIMARY KEY (`deny_id`),
  KEY `ix_gd_guard` (`guard_code`,`at`),
  CONSTRAINT `chk_denial_ref_present` CHECK (`attempted_ref` is not null and `attempted_ref` <> ''),
  CONSTRAINT `chk_denial_verb_present` CHECK (`verb_state` = 'PRE_VERB' or trim(`verb`) <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GOV-01 §9: سجل المنع — مقياس ملاءمة الحماية لا سجل مخالفات المستخدمين';

-- ── Table: guard_override_policies ──
CREATE TABLE `guard_override_policies` (
  `guard_code` varchar(64) NOT NULL,
  `name_ar` varchar(190) NOT NULL,
  `overridable` enum('never','break_glass_only','with_compensating_control') NOT NULL,
  `environments_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'بيئات السريان — production·founding·test' CHECK (json_valid(`environments_json`)),
  PRIMARY KEY (`guard_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SEC-01 §7.2: الاسم يصف السياسة لا النتيجة — ويقرؤها كسر الزجاج فلا يتجاوز never';

-- ── Table: guard_policies ──
CREATE TABLE `guard_policies` (
  `guard_code` varchar(64) NOT NULL,
  `name_ar` varchar(160) NOT NULL,
  `owner_doc` varchar(40) DEFAULT NULL COMMENT 'وثيقة البيت',
  `guard_class` enum('absolute','exception_allowed','advisory') NOT NULL,
