  PRIMARY KEY (`id`),
  KEY `ix_3a6233a4_co` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='HR-14 - الإجازات والغياب';

-- ── Table: hr_workforce_report ──
CREATE TABLE `hr_workforce_report` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL DEFAULT 0 COMMENT 'بوابة المستأجر',
  `g45` varchar(190) DEFAULT NULL COMMENT 'معرف السطر',
  `g46` varchar(190) DEFAULT NULL COMMENT 'الفترة',
  `g47` varchar(190) DEFAULT NULL COMMENT 'الإدارة',
  `g48` varchar(190) DEFAULT NULL COMMENT 'عدد الموظفين',
  `g49` varchar(190) DEFAULT NULL COMMENT 'منهم مشروعيون',
  `g50` varchar(190) DEFAULT NULL COMMENT 'مباشرون جدد',
  `g51` varchar(190) DEFAULT NULL COMMENT 'منتهية خدمتهم',
  `g52` varchar(190) DEFAULT NULL COMMENT 'معدل الدوران',
  `g53` varchar(190) DEFAULT NULL COMMENT 'نسبة الغياب',
  `g54` varchar(190) DEFAULT NULL COMMENT 'ساعات إضافية',
  `g55` varchar(190) DEFAULT NULL COMMENT 'كلفة العمالة',
  `created_at` datetime DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_1a32fad1_co` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='HR-24 - تقرير القوى العاملة';

-- ── Table: iaf_access_log ──
CREATE TABLE `iaf_access_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `auditor_id` int(10) unsigned NOT NULL,
  `scope_kind` varchar(60) NOT NULL COMMENT 'ما اطُّلع عليه',
  `scope_ref` varchar(160) NOT NULL DEFAULT '',
  `purpose` varchar(200) NOT NULL DEFAULT '' COMMENT 'مرجعُ المهمةِ التي تُبرِّر الاطّلاع',
  `engagement_id` int(10) unsigned DEFAULT NULL,
  `accessed_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_aud` (`company_id`,`auditor_id`,`accessed_at`),
  KEY `ix_scope` (`scope_kind`,`scope_ref`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='IAF-0036 + OBL-0127 — سجلُّ اطّلاعِ المراجعِ نفسِه';

-- ── Table: iaf_authorities ──
CREATE TABLE `iaf_authorities` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0,
  `code` varchar(12) NOT NULL COMMENT 'IAF-A01 ..',
  `seq` tinyint(3) unsigned NOT NULL,
  `title` varchar(300) NOT NULL,
  `mode` enum('read','write_own','forbidden') NOT NULL DEFAULT 'read' COMMENT 'IAF-0043 — ولا كتابةَ على السجلاتِ الأصلية بحال',
  `accept_test` varchar(400) NOT NULL DEFAULT '',
  `doc_ref` varchar(24) NOT NULL DEFAULT '',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_a` (`company_id`,`code`),
  KEY `ix_seq` (`seq`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='IAF-01 §4-4 — صلاحياتُ المراجعِ داخلَ النظامِ الاثنتا عشرة';

-- ── Table: iaf_charter ──
CREATE TABLE `iaf_charter` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `version` varchar(20) NOT NULL,
  `functional_line` enum('board','audit_committee','ceo') NOT NULL DEFAULT 'ceo' COMMENT 'IAF-0002 — مجلسٌ أو لجنةٌ · وعند عدمهما الرئيسُ بميثاقٍ مؤقت',
  `admin_line` varchar(120) NOT NULL DEFAULT 'الرئيس التنفيذي — إداريًّا فقط',
  `purpose` varchar(600) NOT NULL DEFAULT '',
  `authority` varchar(600) NOT NULL DEFAULT '',
  `independence` varchar(600) NOT NULL DEFAULT '',
  `not_following` varchar(300) NOT NULL DEFAULT 'لا المالية ولا رئيس الحسابات ولا الحوكمة',
  `approved_by` int(10) unsigned DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `state` enum('draft','approved','superseded') NOT NULL DEFAULT 'draft',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `charter_code` varchar(40) DEFAULT NULL,
  `effective_date` date DEFAULT NULL,
  `scope_of_work` text DEFAULT NULL,
  `info_access_rights` text DEFAULT NULL,
  `review_cycle` varchar(60) DEFAULT NULL,
  `last_review_ref` varchar(80) DEFAULT NULL,
  `attached_doc` varchar(255) DEFAULT NULL,
  `reviewer` varchar(120) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ch` (`company_id`,`version`),
  KEY `ix_state` (`state`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='IAF-01 §4-1 — ميثاقُ المراجعةِ والاستقلال';

-- ── Table: iaf_competencies ──
CREATE TABLE `iaf_competencies` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '0 = مرجعٌ عامٌّ لكلِّ الكيانات',
  `code` varchar(12) NOT NULL COMMENT 'IAF-C01 ..',
  `seq` tinyint(3) unsigned NOT NULL,
  `title` varchar(300) NOT NULL COMMENT 'الاختصاصُ كما تسميه الوثيقة',
  `accept_test` varchar(400) NOT NULL DEFAULT '' COMMENT 'شاهدُ قبولِه',
  `doc_ref` varchar(24) NOT NULL DEFAULT '',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_c` (`company_id`,`code`),
  KEY `ix_seq` (`seq`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='IAF-01 §4-3 — اختصاصاتُ المراجعةِ العشرون';

-- ── Table: iaf_engagements ──
CREATE TABLE `iaf_engagements` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `engagement_no` varchar(40) NOT NULL,
  `plan_id` int(10) unsigned NOT NULL COMMENT 'IAF-0044 — لا مهمةَ بلا خطة',
  `area_code` varchar(40) NOT NULL,
  `title` varchar(200) NOT NULL,
  `lead_auditor` int(10) unsigned NOT NULL,
  `audit_kind` enum('financial','operational','it','compliance','fraud') NOT NULL DEFAULT 'operational',
  `started_at` date DEFAULT NULL,
  `ended_at` date DEFAULT NULL,
  `state` enum('planned','fieldwork','reporting','closed') NOT NULL DEFAULT 'planned',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `engagement_source` varchar(40) DEFAULT NULL,
  `objectives` text DEFAULT NULL,
  `scope` text DEFAULT NULL,
  `period_from` date DEFAULT NULL,
  `period_to` date DEFAULT NULL,
  `team_members` varchar(255) DEFAULT NULL,
  `kickoff_notice_ref` varchar(80) DEFAULT NULL,
  `opening_meeting` varchar(120) DEFAULT NULL,
  `closing_meeting` varchar(120) DEFAULT NULL,
  `reviewer` varchar(120) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_eng` (`company_id`,`engagement_no`),
  KEY `ix_plan` (`plan_id`),
  KEY `ix_area` (`area_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='IAF-01 §4-5 — مهامُّ المراجعة';

-- ── Table: iaf_evidence_request ──
CREATE TABLE `iaf_evidence_request` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `request_no` varchar(40) NOT NULL,
  `engagement_no` varchar(40) NOT NULL DEFAULT '',
  `program_no` varchar(40) NOT NULL DEFAULT '',
  `auditee_dept` varchar(12) NOT NULL DEFAULT '',
  `auditee_person` int(11) NOT NULL DEFAULT 0,
  `item_ar` varchar(400) NOT NULL DEFAULT '',
  `requested_at` datetime DEFAULT NULL,
  `due_date` date DEFAULT NULL,
  `provided_at` datetime DEFAULT NULL,
  `evidence_ref` varchar(200) NOT NULL DEFAULT '',
  `delay_days` int(11) NOT NULL DEFAULT 0,
  `escalation_level` tinyint(4) NOT NULL DEFAULT 0,
  `state` varchar(24) NOT NULL DEFAULT 'requested',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ifr` (`company_id`,`request_no`),
  CONSTRAINT `chk_ifr_due` CHECK (`due_date` is not null),
  CONSTRAINT `chk_ifr_auditee` CHECK (`auditee_dept` <> '' and `auditee_dept` <> 'IAF'),
  CONSTRAINT `chk_ifr_state` CHECK (`state` in ('requested','provided','overdue','escalated','closed')),
  CONSTRAINT `chk_ifr_provided` CHECK (`state` not in ('provided','closed') or `provided_at` is not null and `evidence_ref` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 IAF-08 - الدليل يطلب رسميا بمهلة والتاخر واقعة تصعد';

-- ── Table: iaf_findings ──
CREATE TABLE `iaf_findings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `finding_no` varchar(40) NOT NULL,
  `engagement_id` int(10) unsigned NOT NULL,
  `area_code` varchar(40) NOT NULL DEFAULT '',
  `auditee_dept` varchar(120) NOT NULL DEFAULT '' COMMENT 'الإدارةُ المُراجَعة',
  `auditee_user_id` int(10) unsigned DEFAULT NULL,
  `title` varchar(300) NOT NULL,
  `detail` mediumtext DEFAULT NULL,
  `severity` enum('critical','high','medium','low') NOT NULL DEFAULT 'medium',
  `raised_by` int(10) unsigned NOT NULL COMMENT 'المراجعُ الداخليُّ حصرًا',
  `raised_at` datetime NOT NULL,
  `response_due` date DEFAULT NULL,
  `response_text` mediumtext DEFAULT NULL,
  `responded_by` int(10) unsigned DEFAULT NULL,
  `responded_at` datetime DEFAULT NULL,
  `action_plan` mediumtext DEFAULT NULL,
  `action_owner` int(10) unsigned DEFAULT NULL,
  `action_due` date DEFAULT NULL,
  `evidence_ref` varchar(300) NOT NULL DEFAULT '',
  `evidence_accepted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '◆ لا إغلاقَ بلا قبولِ المراجعِ للدليل — ولو من الرئيس',
  `accepted_by` int(10) unsigned DEFAULT NULL COMMENT 'المراجعُ الذي قَبِل الدليل',
  `closed_by` int(10) unsigned DEFAULT NULL COMMENT '◆ المراجعُ حصرًا — لا الإدارةُ المُراجَعة',
  `closed_at` datetime DEFAULT NULL,
  `state` enum('open','responded','in_remediation','evidence_submitted','closed','escalated') NOT NULL DEFAULT 'open',
  `escalated_at` datetime DEFAULT NULL,
  `escalated_to` enum('ceo','board','audit_committee') DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `result_set_by_dept` varchar(12) NOT NULL DEFAULT '' COMMENT 'من وضع النتيجة - المراجعة وحدها',
  `result_closed_by_dept` varchar(12) NOT NULL DEFAULT '' COMMENT 'من اغلق النتيجة - المراجعة وحدها',
  `classification` varchar(60) DEFAULT NULL,
  `criteria` text DEFAULT NULL,
  `condition_text` text DEFAULT NULL,
  `estimated_effect` varchar(255) DEFAULT NULL,
  `root_cause` text DEFAULT NULL,
  `recommendation` text DEFAULT NULL,
  `auditee_response` varchar(60) DEFAULT NULL,
  `governance_capa_ref` varchar(120) DEFAULT NULL,
  `repeat_from_prior` varchar(20) DEFAULT NULL,
  `reviewer` varchar(120) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_find` (`company_id`,`finding_no`),
  KEY `ix_state` (`company_id`,`state`,`severity`),
  KEY `ix_eng` (`engagement_id`),
  KEY `ix_due` (`company_id`,`action_due`,`state`),
  CONSTRAINT `chk_iaf_close_dept` CHECK (`result_closed_by_dept` in ('','IAF')),
  CONSTRAINT `chk_iaf_result_dept` CHECK (`result_set_by_dept` in ('','IAF'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='IAF-01 §4-5 — ملاحظاتُ المراجعةِ ودورتُها';

-- ── Table: iaf_function_risk ──
CREATE TABLE `iaf_function_risk` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `risk_no` varchar(40) NOT NULL,
  `risk_kind` varchar(32) NOT NULL DEFAULT '',
  `title_ar` varchar(255) NOT NULL DEFAULT '',
  `level_ar` varchar(16) NOT NULL DEFAULT '',
  `treatment_ar` varchar(400) NOT NULL DEFAULT '',
  `owner_person` int(11) NOT NULL DEFAULT 0,
  `reported_to` varchar(32) NOT NULL DEFAULT '' COMMENT 'خط الرفع بالميثاق لا الادارة التنفيذية',
  `review_due` date DEFAULT NULL,
  `state` varchar(24) NOT NULL DEFAULT 'identified',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ifk` (`company_id`,`risk_no`),
  CONSTRAINT `chk_ifk_kind` CHECK (`risk_kind` in ('INDEPENDENCE_LOSS','COMPETENCY_GAP','COVERAGE_GAP','PLAN_DELAY','QUALITY_GAP','ACCESS_DENIED')),
  CONSTRAINT `chk_ifk_state` CHECK (`state` in ('identified','assessed','treated','closed')),
  CONSTRAINT `chk_ifk_reported` CHECK (`reported_to` in ('','owner','audit_committee')),
  CONSTRAINT `chk_ifk_treated` CHECK (`state` not in ('treated','closed') or `treatment_ar` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 IAF-17 - مخاطر الوظيفة نفسها ترفع لخط الرفع بالميثاق';

-- ── Table: iaf_independence ──
CREATE TABLE `iaf_independence` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `auditor_id` int(10) unsigned NOT NULL,
  `scope_ref` varchar(120) NOT NULL DEFAULT '' COMMENT 'فارغٌ = الإقرارُ السنويّ',
  `declared_at` datetime NOT NULL,
  `has_conflict` tinyint(1) NOT NULL DEFAULT 0,
  `conflict_note` varchar(400) NOT NULL DEFAULT '',
  `valid_until` date DEFAULT NULL,
  `declaration_no` varchar(40) DEFAULT NULL,
  `engagement_id` int(11) DEFAULT NULL,
  `prior_work_in_scope` varchar(20) DEFAULT NULL,
  `relation_to_auditee` varchar(60) DEFAULT NULL,
  `independence_decision` varchar(40) DEFAULT NULL,
  `substitute_auditor` varchar(120) DEFAULT NULL,
  `declaration_state` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ind` (`company_id`,`auditor_id`,`scope_ref`),
  KEY `ix_valid` (`company_id`,`valid_until`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='IAF-0009 — إقرارُ الاستقلالِ سنويًّا وقبلَ كل تكليف';

-- ── Table: iaf_plan ──
CREATE TABLE `iaf_plan` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `plan_year` smallint(5) unsigned NOT NULL,
  `charter_id` int(10) unsigned NOT NULL COMMENT 'IAF-0044 — لا خطةَ بلا ميثاق',
  `title` varchar(200) NOT NULL DEFAULT '',
  `basis` varchar(300) NOT NULL DEFAULT 'مبنيةٌ على المخاطر',
  `approved_by` int(10) unsigned DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `state` enum('draft','approved','closed') NOT NULL DEFAULT 'draft',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `plan_item_no` varchar(40) DEFAULT NULL,
  `area_code` varchar(40) DEFAULT NULL,
  `engagement_kind` varchar(40) DEFAULT NULL,
  `planned_quarter` varchar(20) DEFAULT NULL,
  `estimated_days` decimal(6,1) DEFAULT NULL,
  `assigned_auditor` varchar(120) DEFAULT NULL,
  `plan_approval_ref` varchar(80) DEFAULT NULL,
  `amended_by_decision` varchar(80) DEFAULT NULL,
  `reviewer` varchar(120) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_plan` (`company_id`,`plan_year`),
  KEY `ix_charter` (`charter_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='IAF-0015 — خطةُ المراجعةِ السنويةُ المبنيةُ على المخاطر';

-- ── Table: iaf_program ──
CREATE TABLE `iaf_program` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `program_no` varchar(40) NOT NULL,
  `engagement_no` varchar(40) NOT NULL DEFAULT '',
  `step_no` smallint(6) NOT NULL DEFAULT 1,
  `objective_ar` varchar(400) NOT NULL DEFAULT '',
  `test_method` varchar(24) NOT NULL DEFAULT '',
  `population_ar` varchar(200) NOT NULL DEFAULT '',
  `sample_size` int(11) NOT NULL DEFAULT 0,
  `sampling_basis` varchar(200) NOT NULL DEFAULT '',
  `performer_id` int(11) NOT NULL DEFAULT 0,
  `scope_set_by_dept` varchar(12) NOT NULL DEFAULT 'IAF' COMMENT 'النطاق من المراجعة لا من الحوكمة',
  `reviewed_by` int(11) NOT NULL DEFAULT 0,
  `state` varchar(24) NOT NULL DEFAULT 'drafted',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ifp` (`company_id`,`program_no`,`step_no`),
  CONSTRAINT `chk_ifp_scope_not_gov` CHECK (`scope_set_by_dept` = 'IAF'),
  CONSTRAINT `chk_ifp_method` CHECK (`test_method` in ('inquiry','observation','inspection','reperformance','analytics')),
  CONSTRAINT `chk_ifp_state` CHECK (`state` in ('drafted','approved','executing','completed')),
  CONSTRAINT `chk_ifp_objective` CHECK (`objective_ar` <> ''),
  CONSTRAINT `chk_ifp_sampling` CHECK (`state` = 'drafted' or `sample_size` > 0 and `sampling_basis` <> ''),
  CONSTRAINT `chk_ifp_hands` CHECK (`reviewed_by` = 0 or `reviewed_by` <> `performer_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 IAF-07 - البرنامج يربط الهدف بالاختبار والنطاق من المراجعة';

-- ── Table: iaf_quality_reviews ──
CREATE TABLE `iaf_quality_reviews` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `review_no` varchar(40) NOT NULL,
  `kind` enum('internal','external') NOT NULL DEFAULT 'internal',
  `period_label` varchar(60) NOT NULL DEFAULT '',
  `scope_label` varchar(300) NOT NULL DEFAULT '',
  `conformance` enum('conforms','partially_conforms','does_not_conform') DEFAULT NULL,
  `findings_count` int(10) unsigned NOT NULL DEFAULT 0,
  `summary` varchar(800) NOT NULL DEFAULT '',
  `reviewed_by` varchar(160) NOT NULL DEFAULT '' COMMENT 'الجهةُ المقيِّمة — داخليةٌ أو خارجية',
  `reviewed_at` datetime NOT NULL,
  `next_due` date DEFAULT NULL,
  `created_by` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `function_notes` text DEFAULT NULL,
  `improvement_plan` text DEFAULT NULL,
  `escalation_ref` varchar(120) DEFAULT NULL,
  `review_state` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_q` (`company_id`,`review_no`),
  KEY `ix_when` (`company_id`,`reviewed_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='IAF-0008 · IAF-0031 — تقييمُ جودةِ المراجعةِ الدوري';

-- ── Table: iaf_sample ──
CREATE TABLE `iaf_sample` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `sample_no` varchar(40) NOT NULL,
  `program_no` varchar(40) NOT NULL DEFAULT '',
  `step_no` smallint(6) NOT NULL DEFAULT 1,
  `item_ref` varchar(120) NOT NULL DEFAULT '',
  `source_table` varchar(64) NOT NULL DEFAULT '',
  `source_row_id` int(10) unsigned NOT NULL DEFAULT 0,
  `test_result` varchar(16) NOT NULL DEFAULT '',
  `exception_ar` varchar(400) NOT NULL DEFAULT '',
  `tested_by` int(11) NOT NULL DEFAULT 0,
  `tested_at` datetime DEFAULT NULL,
  `finding_no` varchar(40) NOT NULL DEFAULT '',
  `state` varchar(24) NOT NULL DEFAULT 'drawn',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ifs` (`company_id`,`sample_no`),
  KEY `ix_ifs_prog` (`program_no`,`step_no`),
  CONSTRAINT `chk_ifs_result` CHECK (`test_result` in ('','pass','exception','not_applicable')),
  CONSTRAINT `chk_ifs_state` CHECK (`state` in ('drawn','tested','concluded')),
  CONSTRAINT `chk_ifs_tested` CHECK (`state` = 'drawn' or `test_result` <> '' and `tested_by` <> 0),
  CONSTRAINT `chk_ifs_exception` CHECK (`test_result` <> 'exception' or `exception_ar` <> ''),
  CONSTRAINT `chk_ifs_source` CHECK (`source_table` <> '' and `source_row_id` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W14 IAF-09 - العينة تسحب بمنهجية معلنة وكل مفردة بنتيجتها';

-- ── Table: iaf_universe ──
CREATE TABLE `iaf_universe` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `area_code` varchar(40) NOT NULL,
  `area_name` varchar(200) NOT NULL,
  `owner_dept` varchar(120) NOT NULL DEFAULT '',
  `risk_score` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT 'IAF-0014 — التقييمُ السنويُّ للمخاطر',
  `last_audited` date DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `unit_kind` varchar(40) DEFAULT NULL,
  `erm_risk_ref` varchar(80) DEFAULT NULL,
  `risk_rating` varchar(40) DEFAULT NULL,
  `proposed_cycle` varchar(60) DEFAULT NULL,
  `cycle_gap` varchar(60) DEFAULT NULL,
  `inclusion_priority` varchar(40) DEFAULT NULL,
  `unit_state` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_area` (`company_id`,`area_code`),
  KEY `ix_risk` (`company_id`,`risk_score`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='IAF-0013 — سجلُّ الكونِ الرقابي';

-- ── Table: iaf_workpapers ──
CREATE TABLE `iaf_workpapers` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `engagement_id` int(10) unsigned NOT NULL,
  `wp_ref` varchar(60) NOT NULL,
  `title` varchar(200) NOT NULL DEFAULT '',
  `evidence_hash` char(64) NOT NULL DEFAULT '' COMMENT 'بصمةُ النسخةِ — تُثبت عدمَ التعديل',
  `captured_at` datetime NOT NULL,
  `captured_by` int(10) unsigned NOT NULL,
  `frozen` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'غيرُ قابلةٍ للتعديلِ بعد الالتقاط',
  `step_id` varchar(40) DEFAULT NULL,
  `document_ref` varchar(120) DEFAULT NULL,
  `conclusion` text DEFAULT NULL,
  `reviewer_ref` varchar(120) DEFAULT NULL,
  `review_date` date DEFAULT NULL,
  `review_notes` text DEFAULT NULL,
  `wp_state` varchar(40) DEFAULT NULL,
  `reviewer` varchar(120) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_wp` (`company_id`,`engagement_id`,`wp_ref`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='IAF-0037 — أوراقُ العملِ ونسخُ الأدلةِ المجمَّدة';

-- ── Table: impact_matrix ──
CREATE TABLE `impact_matrix` (
  `mx_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `policy_id` int(10) unsigned NOT NULL,
  `state_code` varchar(40) NOT NULL COMMENT 'حالة الإدارة',
  `party_type` enum('client','supplier','operator','company','financier') NOT NULL,
  `effect` enum('billable','countable','payable','penalized','none') NOT NULL,
  `derived_from` varchar(80) DEFAULT NULL COMMENT 'مرجع المصفوفة الأم (CON-02 §5) إن اشتُقت',
  PRIMARY KEY (`mx_id`),
  UNIQUE KEY `uq_mx` (`policy_id`,`state_code`,`party_type`),
  CONSTRAINT `fk_mx_policy` FOREIGN KEY (`policy_id`) REFERENCES `dept_policies` (`policy_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='POL-01 §8: مصفوفة الأثر — لا حالة بلا أثر معلن لكل طرف، ولا أثر يُستنتج';

-- ── Table: impersonation_sessions ──
CREATE TABLE `impersonation_sessions` (
  `imp_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0,
  `actor_user` int(11) NOT NULL COMMENT 'الفاعلُ الحقيقيُّ — الجلسةُ باسمِه هو',
  `target_user` int(11) NOT NULL COMMENT 'المُنابُ عنه',
  `reason` varchar(255) NOT NULL,
  `opened_at` datetime NOT NULL DEFAULT current_timestamp(),
  `closed_at` datetime DEFAULT NULL,
  `valid_to` datetime NOT NULL,
  `notified_at` datetime DEFAULT NULL COMMENT 'إخطارُ صاحبِ الموضعِ — AC-A5: لا جلسةَ مغلقةً بلا إخطار',
  PRIMARY KEY (`imp_id`),
  KEY `ix_actor` (`actor_user`,`closed_at`),
  KEY `ix_target` (`target_user`),
  CONSTRAINT `chk_imp_reason` CHECK (`reason` <> ''),
  CONSTRAINT `chk_imp_not_self` CHECK (`actor_user` <> `target_user`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GOV-AUTH-01 §6-2 — جلسةُ النيابةِ الموسومة: لا دخولَ بحسابِ الغير';

-- ── Table: incentive_allocations ──
CREATE TABLE `incentive_allocations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `rule_id` int(11) NOT NULL,
  `beneficiary_type` enum('employee','job_title') NOT NULL COMMENT 'شخصٌ بعينه أو صفةٌ تُحل وقتَ الاحتساب («مشغّلٌ ومساعدٌ ومشرف»)',
  `beneficiary_id` int(11) NOT NULL,
  `percent` decimal(5,2) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ia_beneficiary` (`rule_id`,`beneficiary_type`,`beneficiary_id`),
  KEY `ix_ia_rule` (`rule_id`),
  KEY `ix_ia_company` (`company_id`),
  CONSTRAINT `fk_ia_rule` FOREIGN KEY (`rule_id`) REFERENCES `incentive_rules` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: incentive_rules ──
CREATE TABLE `incentive_rules` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `contract_id` int(11) NOT NULL,
  `incentive_type` varchar(50) NOT NULL COMMENT 'اسمُ الحافز من الاتفاق — لا قائمةَ مثبَّتةً في الكود',
  `basis` enum('unit','threshold','quality','readiness','safety','fuel','tier') NOT NULL COMMENT 'أسسُ §3.3 السبعة: وحدةٌ منفَّذة · تجاوزُ عتبة · جودة · جاهزية · التزامُ سلامة · توفيرُ وقود · شرائح',
  `rate` decimal(14,4) DEFAULT NULL,
  `threshold` decimal(18,2) DEFAULT NULL,
  `cap` decimal(18,2) DEFAULT NULL COMMENT 'السقف — بنص الشريحة §5.2-③',
  `floor` decimal(18,2) DEFAULT NULL COMMENT 'الحدُّ الأدنى',
  `periodicity` enum('monthly','periodic','once') NOT NULL DEFAULT 'monthly',
  `condition_text` varchar(255) DEFAULT NULL COMMENT 'شرطُ الاستحقاق نصًّا',
  `scope_type` enum('project','equipment_type','site') DEFAULT NULL COMMENT 'نطاقُ §3.3',
  `scope_id` int(11) DEFAULT NULL,
  `valid_from` date DEFAULT NULL,
  `valid_to` date DEFAULT NULL,
  `state` enum('active','replaced','ended') NOT NULL DEFAULT 'active',
  `created_by` int(11) DEFAULT NULL,
  `is_deleted` tinyint(4) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_ir_contract` (`contract_id`),
  KEY `ix_ir_company` (`company_id`),
  CONSTRAINT `fk_ir_contract` FOREIGN KEY (`contract_id`) REFERENCES `employee_contracts` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: injfrd66_sal19_backup ──
CREATE TABLE `injfrd66_sal19_backup` (
  `amendment_id` int(11) NOT NULL,
  `set_to` date NOT NULL,
  `at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`amendment_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: injfrd66_sup01_backup ──
CREATE TABLE `injfrd66_sup01_backup` (
  `supplier_id` int(11) NOT NULL,
  `assigned_code` varchar(60) NOT NULL,
  `at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`supplier_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: injfrd66_sup28_backup ──
CREATE TABLE `injfrd66_sup28_backup` (
  `route` varchar(160) NOT NULL,
  `placement_basis` text DEFAULT NULL,
  `retirement_status` varchar(40) DEFAULT NULL,
  `view_of` varchar(160) DEFAULT NULL,
  `at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`route`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: injfrd66_w2_backup ──
CREATE TABLE `injfrd66_w2_backup` (
  `route` varchar(160) NOT NULL,
  `group_code` varchar(40) NOT NULL,
  `basis` varchar(120) DEFAULT NULL,
  `at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`route`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: injfrd66_xc01_backup ──
CREATE TABLE `injfrd66_xc01_backup` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `route` varchar(160) NOT NULL,
  `canonical_ar` varchar(255) DEFAULT NULL,
  `old_names` text DEFAULT NULL,
  `status` varchar(40) DEFAULT NULL,
  `decision_state` varchar(40) DEFAULT NULL,
  `application_state` varchar(40) DEFAULT NULL,
  `decision_source` text DEFAULT NULL,
  `items_json` text DEFAULT NULL,
  `current_json` text DEFAULT NULL,
  `at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: injfrd66_xc02_backup ──
CREATE TABLE `injfrd66_xc02_backup` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `tbl` varchar(64) NOT NULL,
  `row_key` varchar(255) NOT NULL,
  `col` varchar(64) NOT NULL,
  `old_value` text DEFAULT NULL,
  `swept_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `k_tbl` (`tbl`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: injfrd66_xc12_backup ──
CREATE TABLE `injfrd66_xc12_backup` (
  `route` varchar(160) NOT NULL,
  `nature` varchar(120) DEFAULT NULL,
  `owner_dept` varchar(120) DEFAULT NULL,
  `at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`route`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: intercompany_dues ──
CREATE TABLE `intercompany_dues` (
  `due_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `loan_id` int(10) unsigned NOT NULL,
  `period` char(7) NOT NULL,
  `creditor_entity_id` int(10) unsigned NOT NULL,
  `debtor_entity_id` int(10) unsigned NOT NULL,
  `amount` decimal(18,2) NOT NULL,
  `currency` varchar(8) NOT NULL,
  `state` enum('accrued','settled') NOT NULL DEFAULT 'accrued',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`due_id`),
  UNIQUE KEY `uq_icd` (`loan_id`,`period`,`creditor_entity_id`),
  CONSTRAINT `fk_icd_loan` FOREIGN KEY (`loan_id`) REFERENCES `intercompany_loans` (`loan_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='N-09: المستحق المتبادل المسجَّل بين الكيانين — بنسب التحمل';

-- ── Table: intercompany_loans ──
CREATE TABLE `intercompany_loans` (
  `loan_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `equipment_id` int(11) NOT NULL,
  `lender_entity_id` int(10) unsigned NOT NULL COMMENT 'الكيان المعير — داخلي (is_tenant/داخل المجموعة)',
  `borrower_entity_id` int(10) unsigned NOT NULL COMMENT 'الكيان المستعير — داخلي',
  `date_from` date NOT NULL,
  `date_to` date DEFAULT NULL,
  `monthly_value` decimal(18,2) NOT NULL COMMENT 'القيمة المحاسبية الشهرية للإعارة',
  `currency` varchar(8) NOT NULL DEFAULT 'SDG',
  `bearing_split_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'نسب التحمل بين الكيانين — Σ = 100 (تحرسه الخدمة)' CHECK (json_valid(`bearing_split_json`)),
  `internal_transaction` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'علامة معاملة بين كيانين داخليين — قيد ⑥',
  `state` enum('active','ended') NOT NULL DEFAULT 'active',
  `doc_ref` varchar(120) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`loan_id`),
  KEY `ix_icl_equipment` (`company_id`,`equipment_id`,`state`),
  KEY `fk_icl_lender` (`lender_entity_id`),
  KEY `fk_icl_borrower` (`borrower_entity_id`),
  CONSTRAINT `fk_icl_borrower` FOREIGN KEY (`borrower_entity_id`) REFERENCES `legal_entities` (`entity_id`),
  CONSTRAINT `fk_icl_lender` FOREIGN KEY (`lender_entity_id`) REFERENCES `legal_entities` (`entity_id`),
  CONSTRAINT `ck_icl_not_self` CHECK (`lender_entity_id` <> `borrower_entity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: job_titles ──
CREATE TABLE `job_titles` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title_code` varchar(40) DEFAULT NULL COMMENT 'SEC-01 §12: الكود المعتمد',
  `company_id` int(10) unsigned NOT NULL,
  `name` varchar(100) NOT NULL,
  `family_code` varchar(40) DEFAULT NULL COMMENT 'العائلة — hr_dictionaries',
  `level_code` varchar(40) DEFAULT NULL,
  `org_unit_id` int(10) unsigned DEFAULT NULL,
  `description` varchar(255) DEFAULT NULL,
  `duties_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`duties_json`)),
  `default_manager_position_id` int(10) unsigned DEFAULT NULL,
  `functional_line_unit_id` int(10) unsigned DEFAULT NULL,
  `operational_line_unit_id` int(10) unsigned DEFAULT NULL,
  `template_id` int(10) unsigned DEFAULT NULL,
  `allowed_scopes_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`allowed_scopes_json`)),
  `amount_cap` decimal(18,2) DEFAULT NULL,
  `currency` varchar(8) DEFAULT NULL,
  `prohibitions_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`prohibitions_json`)),
  `qualifications_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`qualifications_json`)),
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `is_operator` tinyint(1) NOT NULL DEFAULT 0,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_jobtitle_company_name` (`company_id`,`name`),
  UNIQUE KEY `uq_jt_code` (`title_code`),
  KEY `idx_jobtitle_company` (`company_id`),
  KEY `idx_jobtitle_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: legal_entities ──
CREATE TABLE `legal_entities` (
  `entity_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `legal_name` varchar(255) NOT NULL,
  `legal_form` varchar(80) DEFAULT NULL,
  `country` varchar(60) NOT NULL DEFAULT 'SD',
  `registry_authority` varchar(120) NOT NULL DEFAULT 'السجل التجاري',
  `commercial_reg` varchar(80) NOT NULL,
  `tax_no` varchar(80) DEFAULT NULL,
  `base_currency` varchar(8) NOT NULL DEFAULT 'SDG' COMMENT 'عملة الدفاتر (functional_currency)',
  `is_tenant` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'كيانات المجموعة المستأجرة — حد العزل من tenants حصرًا',
  `ownership_completeness` enum('full','partial','unknown') NOT NULL DEFAULT 'unknown' COMMENT 'قيد المئة يُفرض عند full وحده',
  `state` enum('active','suspended','liquidation','closed') NOT NULL DEFAULT 'active',
  `registered_address` varchar(255) DEFAULT NULL,
  `founded_date` date DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `legal_rep` varchar(190) DEFAULT NULL COMMENT 'الممثل القانوني',
  `registered_capital` decimal(18,2) DEFAULT NULL COMMENT 'راس المال المسجل',
  `reviewed_by` int(11) DEFAULT NULL COMMENT 'المراجع',
  PRIMARY KEY (`entity_id`),
  UNIQUE KEY `uq_le_registry` (`country`,`registry_authority`,`commercial_reg`) COMMENT 'الفرادة بالثلاثة معًا — الرقم قد يتكرر في دولتين',
  KEY `ix_le_tenant` (`is_tenant`,`state`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='LEG-01 §2: الكيانات القانونية — سجل واحد لا يتكرر، ولا عمود صفات نصي ولا JSON';

-- ── Table: link_groups ──
CREATE TABLE `link_groups` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL COMMENT 'اسم المجموعة كما يظهر في السايدبار',
  `group_code` varchar(40) DEFAULT NULL,
  `owner_role_id` int(11) DEFAULT NULL COMMENT 'الدور المالك — نفس دلالة modules.owner_role_id',
  `icon` varchar(50) NOT NULL DEFAULT 'fa fa-folder',
  `display_order` int(11) NOT NULL DEFAULT 0 COMMENT 'الأصغر يظهر أولاً',
  `stage_no` tinyint(4) DEFAULT NULL,
  `stage_title` varchar(190) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `stage_desc` varchar(200) DEFAULT NULL COMMENT 'NM-05: سطرُ شرحِ المرحلةِ من الوثيقةِ 70 §4-5 — لا يُخترع',
  PRIMARY KEY (`id`),
  KEY `ix_owner_role` (`owner_role_id`),
  KEY `ix_display_order` (`display_order`),
  KEY `idx_lg_code` (`owner_role_id`,`group_code`),
  CONSTRAINT `link_groups_role_fk` FOREIGN KEY (`owner_role_id`) REFERENCES `roles` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='مجموعات روابط السايدبار — لكل دورٍ مجموعاته';

-- ── Table: messages ──
CREATE TABLE `messages` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'المعرف الفريد',
  `company_id` int(11) NOT NULL COMMENT 'رقم الشركة - لعزل الرسائل بين الشركات',
  `sender_id` int(11) NOT NULL COMMENT 'رقم المرسل (users.id)',
  `receiver_id` int(11) NOT NULL COMMENT 'رقم المستلم (users.id)',
  `message` text NOT NULL COMMENT 'نص الرسالة',
  `is_read` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0=غير مقروءة، 1=مقروءة',
  `read_at` datetime DEFAULT NULL COMMENT 'وقت القراءة',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT 'وقت الإرسال',
  `is_deleted_sender` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'حُذفت من قِبل المرسل',
  `is_deleted_receiver` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'حُذفت من قِبل المستلم',
  PRIMARY KEY (`id`),
  KEY `idx_msg_sender` (`sender_id`),
  KEY `idx_msg_receiver` (`receiver_id`),
  KEY `idx_msg_company` (`company_id`),
  KEY `idx_msg_read` (`is_read`),
  KEY `idx_msg_created` (`created_at`),
  KEY `idx_msg_conversation` (`sender_id`,`receiver_id`,`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='الرسائل الداخلية بين مستخدمي الشركة';

-- ── Table: meter_readings ──
CREATE TABLE `meter_readings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `equipment_id` int(11) NOT NULL,
  `meter_type` enum('hour','km') NOT NULL DEFAULT 'hour' COMMENT 'UX-10 §8 نصًّا — لا ثالثَ لهما',
  `chain_no` int(11) NOT NULL DEFAULT 1 COMMENT 'سلسلةُ العدّاد — التصفيرُ الموثَّق يزيدها',
  `reading_date` date NOT NULL,
  `value` decimal(18,2) NOT NULL,
  `delta` decimal(18,2) DEFAULT NULL COMMENT 'الفارقُ عن سابقتها في السلسلة — NULL لأولها',
  `source` enum('manual','inspection','timesheet','reset','transfer') NOT NULL DEFAULT 'manual',
  `source_ref` varchar(80) DEFAULT NULL COMMENT 'مرجعُ الواقعة: TS-‹id› · INS-‹id›',
  `is_reset` tinyint(4) NOT NULL DEFAULT 0,
  `reset_reason` varchar(255) DEFAULT NULL,
  `reset_doc_ref` varchar(120) DEFAULT NULL COMMENT 'مستندُ قرار التصفير — إلزاميٌّ متى صُفّر',
  `note` varchar(255) DEFAULT NULL,
  `recorded_by` int(11) DEFAULT NULL,
  `recorded_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_meter_reading_day` (`equipment_id`,`meter_type`,`reading_date`),
  KEY `ix_meter_latest` (`equipment_id`,`meter_type`,`chain_no`,`reading_date`),
  KEY `ix_meter_co` (`company_id`,`reading_date`),
  CONSTRAINT `fk_meter_reading_equipment` FOREIGN KEY (`equipment_id`) REFERENCES `equipments` (`id`),
  CONSTRAINT `ck_meter_reset_doc` CHECK (`is_reset` = 0 or `reset_doc_ref` is not null and char_length(trim(`reset_doc_ref`)) > 0),
  CONSTRAINT `ck_meter_value` CHECK (`value` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: mnt_breakdown ──
CREATE TABLE `mnt_breakdown` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL COMMENT 'عزل الشركة (إجباري)',
  `code` varchar(50) DEFAULT NULL COMMENT 'مرجع البلاغ، مثل BR-2026-0001',
  `equipment_id` int(11) DEFAULT NULL COMMENT 'FK→equipments.id (ربط رقمي)',
  `project_id` int(11) DEFAULT NULL COMMENT 'FK→project.id',
  `reported_by` int(11) DEFAULT NULL COMMENT 'FK→users.id (المُبلِّغ)',
  `reporter_dept` varchar(100) DEFAULT NULL COMMENT 'القسم المُبلِّغ',
  `target_role` int(11) DEFAULT NULL,
  `report_datetime` datetime DEFAULT NULL,
  `failure_code_id` int(11) DEFAULT NULL COMMENT 'FK→failure_codes.id (إعادة استخدام دون تعديل)',
  `severity` varchar(30) DEFAULT NULL COMMENT 'منخفضة/متوسطة/عالية/حرجة',
  `is_stopped` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'هل المعدة متوقفة',
  `description` text DEFAULT NULL,
  `attachment` varchar(255) DEFAULT NULL,
  `order_id` int(11) DEFAULT NULL COMMENT 'FK→mnt_order.id بعد التحويل لأمر',
  `state` varchar(30) NOT NULL DEFAULT 'جديد' COMMENT 'جديد/قيد التقييم/محوّل/مغلق',
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `failure_start_date` date DEFAULT NULL COMMENT 'تاريخ بداية العطل',
  `failure_start_time` time DEFAULT NULL COMMENT 'وقت البداية',
  `discovery_source` varchar(80) DEFAULT NULL COMMENT 'مصدر الاكتشاف ▼',
  `report_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع البلاغ',
  `operator_at_failure` time DEFAULT NULL COMMENT 'المشغل وقت العطل',
  `site_location` varchar(255) DEFAULT NULL COMMENT 'الموقع',
  `unit_key` varchar(80) DEFAULT NULL COMMENT 'مفتاح الوحدة ◄',
  `meter_reading` decimal(12,2) DEFAULT NULL COMMENT 'قراءة العداد',
  `downtime_start` datetime DEFAULT NULL COMMENT 'بداية التوقف',
  `referred_to_maintenance` varchar(80) DEFAULT NULL COMMENT 'أُحيل للصيانة ▼',
  `referral_date` date DEFAULT NULL COMMENT 'تاريخ الإحالة',
  `diagnosis` varchar(255) DEFAULT NULL COMMENT 'التشخيص ◄',
  `root_cause` varchar(255) DEFAULT NULL COMMENT 'السبب الجذري ◄',
  `return_service_date` date DEFAULT NULL COMMENT 'تاريخ العودة للخدمة',
  `return_service_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع إعادة الخدمة',
  `downtime_end` datetime DEFAULT NULL COMMENT 'نهاية التوقف',
  `downtime_hours` decimal(12,2) DEFAULT NULL COMMENT 'مدة التوقف (ساعة) ◄',
  `operator_liability` varchar(80) DEFAULT NULL COMMENT 'حالة مسؤولية المشغل ▼',
  `investigation_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع التحقيق',
  `bearer_party` varchar(80) DEFAULT NULL COMMENT 'الطرف المتحمِّل ▼',
  `reviewer` varchar(255) DEFAULT NULL COMMENT 'المراجع',
  `review_date` date DEFAULT NULL COMMENT 'تاريخ المراجعة',
  `approved_by` int(11) DEFAULT NULL COMMENT 'المعتمِد',
  `approved_at` datetime DEFAULT NULL COMMENT 'تاريخ الاعتماد',
  `record_basis` varchar(255) DEFAULT NULL COMMENT 'أساس السجل ▼',
  `src_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع المصدر',
  `data_state` varchar(255) DEFAULT NULL COMMENT 'حالة البيانات ▼',
  PRIMARY KEY (`id`),
  KEY `idx_breakdown_eq_company_state` (`equipment_id`,`company_id`,`state`),
  KEY `idx_breakdown_company_state` (`company_id`,`state`),
  KEY `idx_breakdown_order` (`order_id`),
  KEY `idx_breakdown_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: mnt_daily_care ──
CREATE TABLE `mnt_daily_care` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `care_date` date NOT NULL,
  `equipment_id` int(11) NOT NULL,
  `checklist_ref` varchar(120) NOT NULL DEFAULT '' COMMENT 'قائمة العناية للنوع',
  `task_key` varchar(60) NOT NULL,
  `task_ar` varchar(190) NOT NULL DEFAULT '',
  `performed_by` int(11) DEFAULT NULL,
  `result` enum('ok','abnormal','not_done') NOT NULL DEFAULT 'ok',
  `abnormal_note` varchar(400) NOT NULL DEFAULT '',
  `breakdown_id` int(11) DEFAULT NULL COMMENT 'بلاغ متفرع - مشتق لا يدخل',
  `state` enum('open','closed') NOT NULL DEFAULT 'open',
  `state_rule` varchar(60) NOT NULL DEFAULT '',
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `src_ref` varchar(190) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_mdc` (`company_id`,`equipment_id`,`care_date`,`task_key`),
  KEY `ix_mdc_eq` (`equipment_id`,`care_date`),
  CONSTRAINT `chk_mdc_rule` CHECK (`state_rule` <> ''),
  CONSTRAINT `chk_mdc_abn` CHECK (`result` <> 'abnormal' or `abnormal_note` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-W07 MNT-13 - العناية اليومية والتشحيم';

-- ── Table: mnt_diagnosis_request ──
CREATE TABLE `mnt_diagnosis_request` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL DEFAULT 0,
  `diagnosis_no` varchar(80) DEFAULT NULL COMMENT 'رقم الفحص',
  `intake_ref` varchar(255) DEFAULT NULL COMMENT 'معرّف الاستقبال ◄',
  `equipment_ref` varchar(80) DEFAULT NULL COMMENT 'كود المعدة ◄',
  `inspector_ref` varchar(255) DEFAULT NULL COMMENT 'الفاحص ◄',
  `inspect_date` date DEFAULT NULL COMMENT 'تاريخ الفحص',
  `meter_at_inspect` varchar(255) DEFAULT NULL COMMENT 'قراءة العدّاد عند الفحص',
  `final_tree_node` varchar(80) DEFAULT NULL COMMENT 'عقدة الشجرة النهائية ▼',
  `diagnosis_desc` varchar(500) DEFAULT NULL COMMENT 'وصف التشخيص',
  `expected_parts` varchar(255) DEFAULT NULL COMMENT 'القطع المتوقعة',
  `estimated_repair_time` decimal(10,2) DEFAULT NULL COMMENT 'الزمن التقديري للإصلاح',
  `repair_place` varchar(80) DEFAULT NULL COMMENT 'مكان الإصلاح ▼',
  `needs_warranty_supplier` varchar(80) DEFAULT NULL COMMENT 'يتطلب مورد الضمان؟ ▼',
  `inspect_result` varchar(80) DEFAULT NULL COMMENT 'نتيجة الفحص ▼',
  `data_state` varchar(255) DEFAULT NULL COMMENT 'حالة البيانات ▼',
  `src_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع المصدر',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_d93aaa7b_co` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='DEP-14 — طلب الفحص والتشخيص · الحبة: فحصٌ وتشخيصٌ واحدٌ يسبق أمرَ عمل';

-- ── Table: mnt_downtime_segment ──
CREATE TABLE `mnt_downtime_segment` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL DEFAULT 0,
  `segment_code` varchar(255) DEFAULT NULL COMMENT 'معرّف القطاع',
  `stop_event_ref` decimal(12,2) DEFAULT NULL COMMENT 'مرجع واقعة التوقف ◄',
  `equipment_ref` varchar(80) DEFAULT NULL COMMENT 'كود المعدة ◄',
  `segment_seq` int(11) DEFAULT NULL COMMENT 'تسلسل القطاع',
  `segment_kind` varchar(80) DEFAULT NULL COMMENT 'نوع القطاع ▼',
  `segment_owner` varchar(255) DEFAULT NULL COMMENT 'مالك القطاع ◄',
  `segment_start` datetime DEFAULT NULL COMMENT 'بداية القطاع ◄',
  `segment_end` datetime DEFAULT NULL COMMENT 'نهاية القطاع ◄',
  `segment_duration` decimal(12,2) DEFAULT NULL COMMENT 'مدة القطاع ◄',
  `segment_share_pct` decimal(8,2) DEFAULT NULL COMMENT 'نسبته من إجمالي التوقف ◄',
  `segment_reason` varchar(255) DEFAULT NULL COMMENT 'سبب القطاع',
  `owner_ack` varchar(80) DEFAULT NULL COMMENT 'إقرار صاحب القطاع ▼',
  `is_disputed` varchar(255) DEFAULT NULL COMMENT 'متنازَع عليه؟ ◄',
  `ops_manager_ruling` varchar(255) DEFAULT NULL COMMENT 'حكم مدير التشغيل ◄',
  `recurrence_case_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع قضية التكرار ◄',
  `segment_state` varchar(80) DEFAULT NULL COMMENT 'حالة القطاع ▼',
  `data_state` varchar(255) DEFAULT NULL COMMENT 'حالة البيانات ▼',
  `src_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع المصدر',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_981cb2f2_co` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='DEP-14 — تقطيع مسؤولية التوقف · الحبة: قطاعُ مسؤوليةٍ واحدٌ داخلَ واقعةِ توقّف';

-- ── Table: mnt_external_repair ──
CREATE TABLE `mnt_external_repair` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `order_id` int(11) NOT NULL,
  `line_kind` enum('external_referral','warranty_claim') NOT NULL,
  `vendor_id` int(11) DEFAULT NULL COMMENT 'الجهة الخارجية او مورد المعدة',
  `contract_ref` varchar(120) NOT NULL DEFAULT '' COMMENT 'مرجع العقد او الضمان',
  `scope_ar` varchar(400) NOT NULL DEFAULT '',
  `estimated_cost` decimal(14,2) NOT NULL DEFAULT 0.00,
  `actual_cost` decimal(14,2) NOT NULL DEFAULT 0.00,
  `claim_result` enum('pending','accepted','partial','rejected') NOT NULL DEFAULT 'pending',
  `receipt_ref` varchar(120) NOT NULL DEFAULT '' COMMENT 'محضر الاستلام',
  `state` enum('draft','sent','in_progress','received','closed','cancelled') NOT NULL DEFAULT 'draft',
  `state_rule` varchar(60) NOT NULL DEFAULT '',
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `src_ref` varchar(190) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `ix_mer_order` (`order_id`),
  CONSTRAINT `chk_mer_rule` CHECK (`state_rule` <> ''),
  CONSTRAINT `chk_mer_ref` CHECK (`line_kind` <> 'warranty_claim' or `contract_ref` <> ''),
  CONSTRAINT `chk_mer_recv` CHECK (`state` not in ('received','closed') or `receipt_ref` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-W07 MNT-11 - الاصلاح الخارجي ومطالبات الضمان';

-- ── Table: mnt_inspection ──
CREATE TABLE `mnt_inspection` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL COMMENT 'عزل الشركة (إجباري)',
  `code` varchar(50) DEFAULT NULL COMMENT 'مرجع التفتيش، مثل INS-2026-0001',
  `inspection_type` varchar(50) NOT NULL DEFAULT 'دوري' COMMENT 'دوري/زيارة ميدانية/استلام/بعد حادث',
  `template_id` int(11) DEFAULT NULL COMMENT 'FK→mnt_inspection_template.id',
  `equipment_id` int(11) DEFAULT NULL COMMENT 'FK→equipments.id',
  `supplier_id` int(11) DEFAULT NULL COMMENT 'FK→suppliers.id',
  `external_equipment` varchar(255) DEFAULT NULL COMMENT 'وصف معدة خارجية',
  `project_id` int(11) DEFAULT NULL COMMENT 'FK→project.id',
  `inspector_id` int(11) DEFAULT NULL COMMENT 'FK→users.id (الفاحص)',
  `scheduled_date` date DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `score` int(11) DEFAULT NULL,
  `overall_result` varchar(50) DEFAULT NULL,
  `tech_readiness_state` varchar(50) DEFAULT NULL COMMENT 'الجاهزية الفنية',
  `equipment_condition` varchar(50) DEFAULT NULL COMMENT 'تُكتب لكرت المعدة عند الإكمال + تُخزّن',
  `engine_condition` varchar(50) DEFAULT NULL COMMENT 'تُكتب لكرت المعدة عند الإكمال + تُخزّن',
  `notes` text DEFAULT NULL,
  `state` varchar(30) NOT NULL DEFAULT 'جديد' COMMENT 'جديد/مجدول/قيد التنفيذ/مكتمل/مغلق',
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `row_code` varchar(255) DEFAULT NULL COMMENT 'معرّف السطر',
  `fleet_order_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع أمر التفتيش بالأسطول ◄',
  `returned_card_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع بطاقة التفتيش المعادة ◄',
  `row_state` varchar(80) DEFAULT NULL COMMENT 'حالة السطر ▼',
  `data_state` varchar(255) DEFAULT NULL COMMENT 'حالة البيانات ▼',
  `src_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع المصدر',
  PRIMARY KEY (`id`),
  KEY `idx_inspection_equipment` (`equipment_id`),
  KEY `idx_inspection_company_state` (`company_id`,`state`),
  KEY `idx_inspection_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: mnt_inspection_line ──
CREATE TABLE `mnt_inspection_line` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `inspection_id` int(11) NOT NULL COMMENT 'FK→mnt_inspection.id',
  `template_line_id` int(11) DEFAULT NULL COMMENT 'مصدر البند من القالب',
  `component` varchar(150) NOT NULL,
  `section` varchar(150) DEFAULT NULL COMMENT 'المنظومة',
  `applies_to` varchar(80) DEFAULT NULL COMMENT 'ينطبق على',
  `check_method` varchar(120) DEFAULT NULL COMMENT 'طريقة الفحص',
  `measured_value` varchar(255) DEFAULT NULL COMMENT 'القيمة المقاسة/الحد',
  `note` text DEFAULT NULL COMMENT 'الملاحظة',
  `seq` int(11) NOT NULL DEFAULT 0,
  `is_template` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1=بند قالب (لا يُحذف)',
  `condition_state` varchar(30) DEFAULT NULL COMMENT 'سليم/ملاحظة/حرج',
  `recommendation` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `photo_ref` varchar(190) DEFAULT NULL COMMENT 'M-34: مرجعُ صورة البند',
  `converted_ticket_id` int(11) DEFAULT NULL COMMENT 'M-34: بلاغُ NoteConverted — ولا يتكرر',
  PRIMARY KEY (`id`),
  KEY `idx_inspline_inspection` (`inspection_id`),
  CONSTRAINT `fk_inspline_inspection` FOREIGN KEY (`inspection_id`) REFERENCES `mnt_inspection` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: mnt_inspection_template ──
CREATE TABLE `mnt_inspection_template` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) DEFAULT NULL COMMENT 'NULL = قالب عام مشترك لكل الشركات',
  `type_code` varchar(30) NOT NULL COMMENT 'EQUIP-MNT-DLY ...',
  `name` varchar(150) NOT NULL COMMENT 'اسم الاستمارة',
  `inspection_type` varchar(80) NOT NULL COMMENT 'قيمة mnt_inspection.inspection_type',
  `header_type` varchar(20) NOT NULL DEFAULT 'equipment' COMMENT 'equipment/supplier/external',
  `condition_scale` varchar(20) NOT NULL DEFAULT 'default' COMMENT 'default/accident/overhaul',
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_tpl_company_code` (`company_id`,`type_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: mnt_inspection_template_line ──
CREATE TABLE `mnt_inspection_template_line` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `template_id` int(11) NOT NULL,
  `section` varchar(150) DEFAULT NULL COMMENT 'المنظومة/المجموعة',
  `seq` int(11) NOT NULL DEFAULT 0,
  `item` varchar(255) NOT NULL COMMENT 'البند',
  `applies_to` varchar(80) DEFAULT NULL COMMENT 'ينطبق على: عام/حفّار/قلّاب/دريل/لودر',
  `check_method` varchar(120) DEFAULT NULL COMMENT 'طريقة الفحص',
  `reference_limit` varchar(255) DEFAULT NULL COMMENT 'القيمة المقاسة / الحد المرجعي',
  PRIMARY KEY (`id`),
  KEY `idx_tplline_template` (`template_id`),
  CONSTRAINT `fk_tplline_template` FOREIGN KEY (`template_id`) REFERENCES `mnt_inspection_template` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: mnt_kpi_period ──
CREATE TABLE `mnt_kpi_period` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `period` char(7) NOT NULL COMMENT 'YYYY-MM',
  `scope_kind` enum('equipment','category') NOT NULL DEFAULT 'equipment',
  `scope_ref` int(11) NOT NULL DEFAULT 0,
  `breakdowns` int(11) NOT NULL DEFAULT 0,
  `mtbf_hours` decimal(14,2) NOT NULL DEFAULT 0.00,
  `mttr_hours` decimal(14,2) NOT NULL DEFAULT 0.00,
  `readiness_pct` decimal(6,2) NOT NULL DEFAULT 0.00 COMMENT 'مستورد من asset_readiness لا يحسب هنا',
  `pm_done` int(11) NOT NULL DEFAULT 0,
  `pm_due` int(11) NOT NULL DEFAULT 0,
  `pm_compliance_pct` decimal(6,2) NOT NULL DEFAULT 0.00,
  `cost_per_hour` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `derivation_rule` varchar(60) NOT NULL DEFAULT '',
  `derived_from` varchar(300) NOT NULL DEFAULT '',
  `derived_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_mkp` (`company_id`,`period`,`scope_kind`,`scope_ref`),
  CONSTRAINT `chk_mkp_rule` CHECK (`derivation_rule` <> '' and `derived_from` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-W07 MNT-16 - مؤشرات الصيانة الدورية مشتقة بلا ادخال';

-- ── Table: mnt_lookup ──
CREATE TABLE `mnt_lookup` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL COMMENT 'عزل الشركة (إجباري)',
  `type` varchar(40) NOT NULL COMMENT 'سبب عطل/سبب توقّف/نوع مهمة/ورشة',
  `name` varchar(150) NOT NULL,
  `extra` varchar(255) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_lookup_company_type` (`company_id`,`type`),
  KEY `idx_lookup_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: mnt_order ──
CREATE TABLE `mnt_order` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL COMMENT 'عزل الشركة (إجباري)',
  `code` varchar(50) DEFAULT NULL COMMENT 'مرجع الأمر، مثل MNT-2026-0001',
  `breakdown_id` int(11) DEFAULT NULL COMMENT 'FK→mnt_breakdown.id (مصدر بلاغ)',
  `plan_id` int(11) DEFAULT NULL COMMENT 'FK→mnt_plan.id (مصدر وقائي)',
  `inspection_id` int(11) DEFAULT NULL COMMENT 'FK→mnt_inspection.id (مصدر تفتيش)',
  `equipment_id` int(11) DEFAULT NULL COMMENT 'FK→equipments.id',
  `project_id` int(11) DEFAULT NULL COMMENT 'FK→project.id',
  `source` varchar(20) NOT NULL DEFAULT 'بلاغ' COMMENT 'بلاغ/وقائي/تفتيش',
  `is_auto` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Ïú┘àÏ▒ ÏÁ┘èÏº┘åÏ® Ïú┘Å┘åÏ┤Ïª Ï¬┘ä┘éÏºÏª┘è┘ïÏº ┘à┘å ÏÁ┘üÏ¡Ï® Ïº┘äÏ¡Ï▒┘âÏ®',
  `maint_type` varchar(50) DEFAULT NULL COMMENT 'نوع الصيانة',
  `priority` varchar(20) DEFAULT NULL,
  `cost_party` varchar(20) DEFAULT NULL COMMENT 'جهة التكلفة: داخلي/خارجي',
  `charge_supplier_id` int(11) DEFAULT NULL COMMENT 'مورّدُ الآليات الذي تُحمَّل عليه تكلفةُ الأمر — يُفعّل حين cost_party=خارجي',
  `vendor_id` int(11) DEFAULT NULL COMMENT 'FK→suppliers.id (ورشة خارجية)',
  `workshop` varchar(150) DEFAULT NULL,
  `technician_id` int(11) DEFAULT NULL COMMENT 'FK→users.id (الفني)',
  `supervisor_id` int(11) DEFAULT NULL COMMENT 'FK→users.id (المشرف)',
  `failure_code_id` int(11) DEFAULT NULL COMMENT 'FK→failure_codes.id',
  `diagnosis` text DEFAULT NULL,
  `root_cause_id` int(11) DEFAULT NULL COMMENT 'FK→mnt_lookup.id (سبب جذري)',
  `actions_taken` text DEFAULT NULL,
  `work_start` datetime DEFAULT NULL,
  `work_end` datetime DEFAULT NULL,
  `downtime_hours` decimal(10,2) NOT NULL DEFAULT 0.00,
  `labor_cost` decimal(12,2) NOT NULL DEFAULT 0.00,
  `parts_cost` decimal(12,2) NOT NULL DEFAULT 0.00,
  `external_cost` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total_cost` decimal(12,2) NOT NULL DEFAULT 0.00,
  `inspection_result` varchar(20) DEFAULT NULL COMMENT 'ناجح/راسب',
  `state` varchar(20) NOT NULL DEFAULT 'بلاغ' COMMENT 'بلاغ/تنفيذ/فحص/إغلاق/ملغى',
  `closed_at` datetime DEFAULT NULL,
  `closed_by` int(11) DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `waiting_part_since` date DEFAULT NULL COMMENT 'M-32: تاريخُ دخول WaitingPart — العدّادُ يُحسب منه',
  `pm_cycle_key` varchar(80) DEFAULT NULL COMMENT 'M-36: plan:{id}:eq:{id}:due:{date} — يمنع توليدَ الدورة مرتين',
  `readiness_cert_ref` varchar(190) DEFAULT NULL COMMENT 'INJ-0074: مرجعُ شهادةِ الجاهزيةِ الفنية — وتاريخُها ومُصدرُها في closed_at/closed_by',
  `failure_kind` varchar(40) NOT NULL DEFAULT '' COMMENT 'المحور ١ نوع العطل - كهربائي ميكانيكي هيدروليكي اطارات',
  `safety_severity` enum('minor','major','safety_critical') DEFAULT NULL COMMENT 'المحور ٢ خطورة السلامة - DEC-OPEN-12',
  `safety_rule_ref` varchar(60) NOT NULL DEFAULT '' COMMENT 'قاعدة التصنيف من mnt_safety_rule - لا حكم بلا قاعدة',
  `safety_system_key` varchar(60) NOT NULL DEFAULT '' COMMENT 'النظام المصاب الذي رفع التصنيف',
  `severity_override_by` int(11) DEFAULT NULL COMMENT 'DEC-OPEN-12 تصعيد الفني او مهندس الصيانة او مسؤول السلامة',
  `severity_override_reason` varchar(400) NOT NULL DEFAULT '',
  `ops_impact` enum('low','medium','high','critical') DEFAULT NULL COMMENT 'المحور ٣ الاثر التشغيلي - محور ثان مستقل لا يغير السلامة',
  `ops_impact_rule` varchar(60) NOT NULL DEFAULT '',
  `lockout_state` enum('none','locked_out','released') NOT NULL DEFAULT 'none' COMMENT 'ايقاف ومنع تشغيل - شرط الحرج للسلامة',
  `lockout_at` datetime DEFAULT NULL,
  `lockout_by` int(11) DEFAULT NULL,
  `w7_state_rule` varchar(60) NOT NULL DEFAULT '' COMMENT 'قاعدة الانتقال الاخير - لا حالة بلا قاعدة',
  `w7_cert_id` int(10) unsigned DEFAULT NULL COMMENT 'شهادة اعادة الخدمة التي اقفلت الامر',
  `open_date` date DEFAULT NULL COMMENT 'تاريخ الفتح',
  `diagnosis_ref` varchar(80) DEFAULT NULL COMMENT 'رقم الفحص ◄',
  `equipment_type_ref` varchar(255) DEFAULT NULL COMMENT 'نوع المعدة ◄',
  `site_ref` varchar(255) DEFAULT NULL COMMENT 'الموقع ◄',
  `tree_node_ref` varchar(255) DEFAULT NULL COMMENT 'عقدة الشجرة ◄',
  `order_labor_summary` varchar(255) DEFAULT NULL COMMENT 'عمالة الأمر ◄ — تفصيلها ص05-2',
  `meter_at_open` decimal(12,2) DEFAULT NULL COMMENT 'قراءة العدّاد عند الفتح ◄',
  `planned_time` decimal(10,2) DEFAULT NULL COMMENT 'الزمن المخطط',
  `target_finish_date` date DEFAULT NULL COMMENT 'تاريخ الإنجاز المستهدف',
  `accumulated_downtime_hours` decimal(12,2) DEFAULT NULL COMMENT 'ساعات التوقف المتراكمة ◄',
  `estimated_parts_cost` decimal(18,2) DEFAULT NULL COMMENT 'التكلفة التقديرية للقطع ◄',
  `reviewer` varchar(255) DEFAULT NULL COMMENT 'المراجع',
  `approved_by` int(11) DEFAULT NULL COMMENT 'المعتمِد',
  `approved_at` datetime DEFAULT NULL COMMENT 'تاريخ الاعتماد',
  `data_state` varchar(255) DEFAULT NULL COMMENT 'حالة البيانات ▼',
  `src_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع المصدر',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_mnt_pm_cycle` (`pm_cycle_key`),
  KEY `idx_order_eq_company_state` (`equipment_id`,`company_id`,`state`),
  KEY `idx_order_company_state` (`company_id`,`state`),
  KEY `idx_order_breakdown` (`breakdown_id`),
  KEY `idx_order_plan` (`plan_id`),
  KEY `idx_order_inspection` (`inspection_id`),
  KEY `idx_order_deleted` (`is_deleted`),
  KEY `idx_mnt_order_auto_open` (`company_id`,`equipment_id`,`project_id`,`is_auto`,`state`),
  CONSTRAINT `chk_mo_override` CHECK (`severity_override_by` is null or `severity_override_reason` <> ''),
  CONSTRAINT `chk_mo_lockout` CHECK (`lockout_state` = 'none' or `lockout_at` is not null)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: mnt_order_labor ──
CREATE TABLE `mnt_order_labor` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `order_id` int(11) NOT NULL COMMENT 'FK→mnt_order.id',
  `employee_id` int(11) DEFAULT NULL COMMENT 'FK→users.id (اختياري)',
  `role` varchar(100) DEFAULT NULL,
  `hours` decimal(8,2) NOT NULL DEFAULT 0.00,
  `hourly_rate` decimal(10,2) NOT NULL DEFAULT 0.00,
  `cost` decimal(12,2) NOT NULL DEFAULT 0.00,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `row_code` varchar(255) DEFAULT NULL COMMENT 'معرّف السطر',
  `labor_date` date DEFAULT NULL COMMENT 'التاريخ',
  `tech_note` varchar(500) DEFAULT NULL COMMENT 'ملاحظة فنية',
  `row_state` varchar(80) DEFAULT NULL COMMENT 'حالة السطر ▼',
  `data_state` varchar(255) DEFAULT NULL COMMENT 'حالة البيانات ▼',
  `src_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع المصدر',
  `created_by` int(11) DEFAULT NULL COMMENT 'المُنشئ',
  PRIMARY KEY (`id`),
  KEY `idx_labor_order` (`order_id`),
  CONSTRAINT `fk_labor_order` FOREIGN KEY (`order_id`) REFERENCES `mnt_order` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: mnt_order_part ──
CREATE TABLE `mnt_order_part` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `order_id` int(11) NOT NULL COMMENT 'FK→mnt_order.id',
  `part_name` varchar(200) NOT NULL,
  `category` varchar(100) DEFAULT NULL,
  `quantity` decimal(10,2) NOT NULL DEFAULT 1.00,
  `unit_cost` decimal(12,2) NOT NULL DEFAULT 0.00,
  `subtotal` decimal(12,2) NOT NULL DEFAULT 0.00,
  `is_major_component` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_part_order` (`order_id`),
  CONSTRAINT `fk_part_order` FOREIGN KEY (`order_id`) REFERENCES `mnt_order` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: mnt_part_request ──
CREATE TABLE `mnt_part_request` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `req_no` varchar(40) NOT NULL,
  `order_id` int(11) NOT NULL,
  `request_date` date DEFAULT NULL,
  `warehouse_ref` varchar(120) NOT NULL DEFAULT '' COMMENT 'مستورد للقراءة من المخازن',
  `lines_count` int(11) NOT NULL DEFAULT 0 COMMENT 'مشتق من mnt_order_part',
  `priority` enum('normal','urgent') NOT NULL DEFAULT 'normal',
  `custodian_id` int(11) DEFAULT NULL COMMENT 'مستلم العهدة',
  `issue_doc_ref` varchar(120) NOT NULL DEFAULT '' COMMENT 'رقم سند الصرف من المخازن',
  `receipt_match` enum('pending','matched','variance') NOT NULL DEFAULT 'pending',
  `state` enum('draft','submitted','approved','issued','partially_issued','rejected','cancelled') NOT NULL DEFAULT 'draft',
  `state_rule` varchar(60) NOT NULL DEFAULT '',
  `reject_reason` varchar(400) NOT NULL DEFAULT '',
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `src_ref` varchar(190) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_mpr` (`company_id`,`req_no`),
  KEY `ix_mpr_order` (`order_id`),
  CONSTRAINT `chk_mpr_rule` CHECK (`state_rule` <> ''),
  CONSTRAINT `chk_mpr_issue` CHECK (`state` not in ('issued','partially_issued') or `issue_doc_ref` <> ''),
  CONSTRAINT `chk_mpr_rej` CHECK (`state` <> 'rejected' or `reject_reason` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-W07 MNT-10 - طلب صرف القطع لامر العمل - لا صرف لامر مقفل';

-- ── Table: mnt_plan ──
CREATE TABLE `mnt_plan` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL COMMENT 'عزل الشركة (إجباري)',
  `code` varchar(50) DEFAULT NULL COMMENT 'مرجع الخطة، مثل PLN-2026-0001',
  `name` varchar(200) NOT NULL,
  `scope` varchar(50) DEFAULT NULL COMMENT 'معدة/فئة',
  `equipment_id` int(11) DEFAULT NULL COMMENT 'FK→equipments.id',
  `category_id` int(11) DEFAULT NULL COMMENT 'FK→equipments_types.id',
  `trigger_basis` varchar(20) NOT NULL DEFAULT 'ساعات' COMMENT 'ساعات/زمن',
  `interval_value` int(11) DEFAULT NULL COMMENT 'الفاصل (ساعات أو أيام)',
  `tolerance` int(11) DEFAULT NULL,
  `last_done_date` date DEFAULT NULL,
  `last_done_meter` decimal(12,2) DEFAULT NULL,
  `next_due_date` date DEFAULT NULL,
  `next_due_meter` decimal(12,2) DEFAULT NULL,
  `state` varchar(30) NOT NULL DEFAULT 'نشطة' COMMENT 'نشطة/متوقفة',
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_plan_eq_due` (`equipment_id`,`next_due_date`),
  KEY `idx_plan_company_state` (`company_id`,`state`),
  KEY `idx_plan_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: mnt_plan_task ──
CREATE TABLE `mnt_plan_task` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `plan_id` int(11) NOT NULL COMMENT 'FK→mnt_plan.id',
  `name` varchar(200) NOT NULL,
  `task_type` int(11) DEFAULT NULL COMMENT 'FK→mnt_lookup.id (نوع مهمة)',
  `component` varchar(150) DEFAULT NULL,
  `est_hours` decimal(8,2) NOT NULL DEFAULT 0.00,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_plantask_plan` (`plan_id`),
  CONSTRAINT `fk_plantask_plan` FOREIGN KEY (`plan_id`) REFERENCES `mnt_plan` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: mnt_repeat_repair ──
CREATE TABLE `mnt_repeat_repair` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `equipment_id` int(11) NOT NULL,
  `origin_order_id` int(11) NOT NULL COMMENT 'رقم الامر الاصلي',
  `origin_cert_id` int(10) unsigned DEFAULT NULL,
  `new_order_id` int(11) DEFAULT NULL COMMENT 'رقم الامر الجديد - مشتق',
  `tree_node` varchar(80) NOT NULL DEFAULT '' COMMENT 'عقدة شجرة الاسباب',
  `repeat_date` date NOT NULL,
  `days_since_cert` int(11) DEFAULT NULL COMMENT 'مشتق - لا يدخل',
  `within_validity` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'مشتق من valid_until',
  `rca_trigger` enum('repeat_within_validity','safety_critical','high_cost','manual') NOT NULL,
  `rca_state` enum('open','in_analysis','root_found','closed') NOT NULL DEFAULT 'open',
  `rca_ref` varchar(190) NOT NULL DEFAULT '',
  `root_cause` varchar(400) NOT NULL DEFAULT '',
  `decision_ar` varchar(400) NOT NULL DEFAULT '',
  `derivation_rule` varchar(60) NOT NULL DEFAULT '',
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `src_ref` varchar(190) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_mrr` (`company_id`,`origin_order_id`,`repeat_date`),
  KEY `ix_mrr_eq` (`equipment_id`),
  CONSTRAINT `chk_mrr_rule` CHECK (`derivation_rule` <> ''),
  CONSTRAINT `chk_mrr_close` CHECK (`rca_state` <> 'closed' or `root_cause` <> '' and `decision_ar` <> ''),
  CONSTRAINT `chk_mrr_win` CHECK (`within_validity` = 0 or `days_since_cert` is not null)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-W07 MNT-15 - سجل اعادة الاصلاح وتحليل السبب الجذري';

-- ── Table: mnt_return_cert ──
CREATE TABLE `mnt_return_cert` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `cert_no` varchar(40) NOT NULL,
  `order_id` int(11) NOT NULL,
  `equipment_id` int(11) NOT NULL,
  `safety_severity` enum('minor','major','safety_critical') NOT NULL DEFAULT 'major' COMMENT 'منقول من الامر لحظة الاصدار - هو الذي اوجب الشهادة',
  `cert_required` tinyint(1) NOT NULL DEFAULT 1,
  `cert_rule` varchar(60) NOT NULL DEFAULT '',
  `tech_complete_date` date DEFAULT NULL COMMENT 'تاريخ الانجاز الفني',
  `test_performed` varchar(300) NOT NULL DEFAULT '' COMMENT 'الاختبار المنفذ موثقا',
  `test_result` enum('pass','conditional','fail') DEFAULT NULL,
  `meter_at_close` decimal(14,2) DEFAULT NULL COMMENT 'قراءة العداد عند الاقفال',
  `downtime_hours` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT 'مستورد للقراءة من امر العمل',
  `actual_cost` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT 'مشتق من العمالة والقطع والخارجي',
  `cost_rule` varchar(60) NOT NULL DEFAULT '',
  `new_readiness_state` enum('operational','operational_restricted','stopped','prohibited','ready_after_approval') DEFAULT NULL,
  `operating_limits` varchar(400) NOT NULL DEFAULT '',
  `valid_days` int(11) NOT NULL DEFAULT 0 COMMENT 'من repair01_w7_thresholds لا من الشيفرة',
  `valid_until` date DEFAULT NULL,
  `signed_by` int(11) DEFAULT NULL COMMENT 'توقيع مدير الصيانة او المخول الفني',
  `signer_kind` varchar(40) NOT NULL DEFAULT '',
  `state` enum('draft','submitted','approved','rejected','expired','superseded') NOT NULL DEFAULT 'draft',
  `state_rule` varchar(60) NOT NULL DEFAULT '',
  `reject_reason` varchar(400) NOT NULL DEFAULT '',
  `reviewed_by` int(11) DEFAULT NULL,
  `approved_by` int(11) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `superseded_by` int(10) unsigned DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `src_ref` varchar(190) NOT NULL DEFAULT '',
  `cert_validity` varchar(80) DEFAULT NULL COMMENT 'صلاحية الشهادة',
  `data_state` varchar(255) DEFAULT NULL COMMENT 'حالة البيانات ▼',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_mrc_no` (`company_id`,`cert_no`),
  KEY `ix_mrc_order` (`order_id`),
  KEY `ix_mrc_eq` (`equipment_id`,`valid_until`),
  CONSTRAINT `chk_mrc_rule` CHECK (`state_rule` <> '' and `cert_rule` <> ''),
  CONSTRAINT `chk_mrc_appr` CHECK (`state` <> 'approved' or `approved_by` is not null and `approved_at` is not null and `test_result` is not null and `test_result` <> 'fail'),
  CONSTRAINT `chk_mrc_evid` CHECK (`state` not in ('submitted','approved') or `test_performed` <> '' and `tech_complete_date` is not null),
  CONSTRAINT `chk_mrc_rej` CHECK (`state` <> 'rejected' or `reject_reason` <> ''),
  CONSTRAINT `chk_mrc_limits` CHECK (`new_readiness_state` is null or `new_readiness_state` <> 'operational_restricted' or `operating_limits` <> ''),
  CONSTRAINT `chk_mrc_valid` CHECK (`state` <> 'approved' or `valid_until` is not null),
  CONSTRAINT `chk_mrc_signer` CHECK (`safety_severity` <> 'safety_critical' or `state` <> 'approved' or `signer_kind` = 'technical_authority')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-W07 MNT-14 - شهادة اعادة الخدمة: الشهادة وحدها تعيد المعدة';

-- ── Table: mnt_safety_rule ──
CREATE TABLE `mnt_safety_rule` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `equipment_type` varchar(80) NOT NULL DEFAULT '' COMMENT 'فارغ يعني كل الانواع - DEC-OPEN-12 لا قائمة صلبة واحدة',
  `system_key` varchar(60) NOT NULL COMMENT 'brakes steering control lifting estop fire structural',
  `system_ar` varchar(160) NOT NULL DEFAULT '',
  `default_severity` enum('minor','major','safety_critical') NOT NULL DEFAULT 'major',
  `requires_cert` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'شهادة عودة مستقلة - البسيط لا يحتاجها',
  `requires_lockout` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'ايقاف ومنع تشغيل قبل الاصلاح',
  `approver_kind` varchar(40) NOT NULL DEFAULT '' COMMENT 'technician او technical_authority - لا المشغل وحده',
  `rule_ref` varchar(60) NOT NULL DEFAULT '',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `src_ref` varchar(190) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_msr` (`company_id`,`equipment_type`,`system_key`),
  KEY `ix_msr_sev` (`default_severity`),
  CONSTRAINT `chk_msr_rule` CHECK (`rule_ref` <> ''),
  CONSTRAINT `chk_msr_cert` CHECK (`default_severity` <> 'safety_critical' or `requires_cert` = 1 and `requires_lockout` = 1 and `approver_kind` = 'technical_authority')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-W07 - تصنيف السلامة بحسب نوع المعدة والنظام - DEC-OPEN-12';

-- ── Table: modules ──
CREATE TABLE `modules` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `code` varchar(50) DEFAULT NULL,
  `owner_role_id` int(11) DEFAULT NULL,
  `group_id` int(11) DEFAULT NULL,
  `is_link` varchar(10) NOT NULL DEFAULT '0',
  `is_quick` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'تظهر في روابط الوصول السريع بلوحة التحكم',
  `icon` varchar(50) NOT NULL,
  `display_order` int(11) DEFAULT 0 COMMENT 'ترتيب العرض في القوائم',
  `owner_dept_note` varchar(120) DEFAULT NULL COMMENT 'الإدارةُ المالكةُ نصًّا (nav09_file_map.owner_dept) — للوحداتِ المشترَكةِ بين أدوارٍ كثيرة',
  PRIMARY KEY (`id`),
  KEY `owner_role_id` (`owner_role_id`),
  KEY `idx_display_order` (`display_order`),
  KEY `ix_modules_group` (`group_id`),
  CONSTRAINT `modules_group_fk` FOREIGN KEY (`group_id`) REFERENCES `link_groups` (`id`) ON DELETE SET NULL,
  CONSTRAINT `modules_ibfk_1` FOREIGN KEY (`owner_role_id`) REFERENCES `roles` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: monthly_performance ──
CREATE TABLE `monthly_performance` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `contract_id` int(10) unsigned NOT NULL,
  `container_id` int(10) unsigned NOT NULL COMMENT 'حاوية المقعد (op_containers · level=معدة · seat_no)',
  `period` char(7) NOT NULL COMMENT 'YYYY-MM',
  `contract_hours` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT 'التعاقدية (من contract_hours_monthly للمقعد)',
  `executed_hours` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT 'المنفَّذة — مجمَّعة من container_consumption',
  `executed_base_hours` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT 'الأساسية المنفَّذة (دون الإضافي)',
  `standby_hours` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT 'الاستعداد',
  `available_hours` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT 'المتاحة',
  `shortfall_hours` decimal(10,2) GENERATED ALWAYS AS (greatest(`contract_hours` - `executed_hours` - `standby_hours`,0)) STORED COMMENT 'العجز عن التعاقد — محسوب',
  `completion_pct` decimal(6,2) GENERATED ALWAYS AS (if(`contract_hours` > 0,round(`executed_hours` / `contract_hours` * 100,2),NULL)) STORED COMMENT 'نسبة الإنجاز — محسوبة',
  `trips` decimal(12,2) NOT NULL DEFAULT 0.00,
  `tons` decimal(14,2) NOT NULL DEFAULT 0.00,
  `meters` decimal(14,2) NOT NULL DEFAULT 0.00,
  `fuel_consumed` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT 'وقود مستهلك',
  `state` enum('open','closed') NOT NULL DEFAULT 'open',
  `closed_by` int(10) unsigned DEFAULT NULL,
  `closed_at` datetime DEFAULT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `row_code` varchar(80) DEFAULT NULL COMMENT 'رقم السطر',
  `container_key` varchar(80) DEFAULT NULL COMMENT 'مفتاح دورة الالتزام',
  `contract_ref` varchar(80) DEFAULT NULL COMMENT 'كود العقد',
  `client_no` varchar(60) DEFAULT NULL COMMENT 'رقم العميل',
  `client_name` varchar(80) DEFAULT NULL COMMENT 'اسم العميل (بحث)',
  `business_model` varchar(255) DEFAULT NULL COMMENT 'نموذج العمل',
  `renewal_no` varchar(80) DEFAULT NULL COMMENT 'رقم التجديد',
  `month_no` varchar(80) DEFAULT NULL COMMENT 'رقم الشهر',
  `month_from` date DEFAULT NULL COMMENT 'من',
  `month_to` date DEFAULT NULL COMMENT 'إلى',
  `line_ref` varchar(255) DEFAULT NULL COMMENT 'البند',
  `machines_count` decimal(12,3) DEFAULT NULL COMMENT 'عدد الآليات ◄',
  `monthly_target` decimal(18,3) DEFAULT NULL COMMENT 'المستهدف الشهري',
  `executed_qty` decimal(18,3) DEFAULT NULL COMMENT 'الكمية المنفَّذة ◄',
  `uom_ref` varchar(80) DEFAULT NULL COMMENT 'الوحدة',
  `operating_hours` decimal(14,2) DEFAULT NULL COMMENT 'ساعات التشغيل ◄',
  `trips_count` decimal(14,2) DEFAULT NULL COMMENT 'النقلات ◄',
  `deducted_standby` decimal(14,2) DEFAULT NULL COMMENT 'مخصومة/استعداد ◄',
  `deducted_work` decimal(14,2) DEFAULT NULL COMMENT 'مخصومة/عمل ◄',
  `added_work` decimal(14,2) DEFAULT NULL COMMENT 'مضافة/عمل ◄',
  `added_standby` decimal(14,2) DEFAULT NULL COMMENT 'مضافة/استعداد ◄',
  `measured_qty` decimal(18,3) DEFAULT NULL COMMENT 'الكمية المنجزة (المقاسة) ◄',
  `executed_achievement` varchar(255) DEFAULT NULL COMMENT 'تحقق المنفَّذ',
  `measured_achievement` varchar(255) DEFAULT NULL COMMENT 'تحقق المنجز',
  `computed_revenue_usd` decimal(18,2) DEFAULT NULL COMMENT 'الإيراد المحسوب ($) ◄',
  `computed_revenue_sdg` decimal(18,2) DEFAULT NULL COMMENT 'الإيراد المحسوب (ج.س) ◄',
  `statement_source` varchar(255) DEFAULT NULL COMMENT 'مصدر البيان',
  `perf_notes` varchar(500) DEFAULT NULL COMMENT 'ملاحظات',
  `billed_qty` decimal(18,3) DEFAULT NULL COMMENT 'الكمية المفوترة للعميل ◄',
  `billed_usd` decimal(18,2) DEFAULT NULL COMMENT 'المفوتر للعميل ($) ◄',
  `unbilled_executed` decimal(18,3) DEFAULT NULL COMMENT 'منفَّذ غير مفوتر',
  `unclaimed_revenue` decimal(18,2) DEFAULT NULL COMMENT 'إيراد غير مطالَب به ($)',
  `invoice_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع الفاتورة',
  `contract_currency` varchar(255) DEFAULT NULL COMMENT 'عملة العقد',
  `revenue_columns_state` varchar(255) DEFAULT NULL COMMENT 'حالة أعمدة الإيراد',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_mp_seat_period` (`company_id`,`container_id`,`period`),
  KEY `ix_mp_contract` (`company_id`,`contract_id`,`period`),
  KEY `fk_mp_container` (`container_id`),
  CONSTRAINT `fk_mp_container` FOREIGN KEY (`container_id`) REFERENCES `op_containers` (`id`),
  CONSTRAINT `ck_mp_hours` CHECK (`contract_hours` >= 0 and `executed_hours` >= 0 and `standby_hours` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: monthly_performance_downtime ──
CREATE TABLE `monthly_performance_downtime` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `perf_id` int(10) unsigned NOT NULL,
  `reason_code` varchar(40) NOT NULL COMMENT 'من stop_reason_codes حصرًا',
  `hours` decimal(10,2) NOT NULL,
  `obligation_id` int(11) NOT NULL COMMENT 'بند الالتزام المقابل — إلزامي (سبب بلا بند لا يُقبل)',
  `bearer_party` enum('client','company','supplier','operator','none') NOT NULL COMMENT 'الطرف المتحمل — مُشتق من البند وقت التسجيل، لا يُكتب حرًّا',
  `effect_on_billing` enum('billable_standby','non_billable','per_clause') NOT NULL DEFAULT 'per_clause' COMMENT 'لقطة أثر البند على الفوترة',
  `note` varchar(200) DEFAULT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_mpd_reason` (`perf_id`,`reason_code`),
  KEY `ix_mpd_company` (`company_id`,`perf_id`),
  KEY `fk_mpd_reason` (`reason_code`),
  KEY `fk_mpd_obligation` (`obligation_id`),
  CONSTRAINT `fk_mpd_obligation` FOREIGN KEY (`obligation_id`) REFERENCES `contract_obligations` (`id`),
  CONSTRAINT `fk_mpd_perf` FOREIGN KEY (`perf_id`) REFERENCES `monthly_performance` (`id`),
  CONSTRAINT `fk_mpd_reason` FOREIGN KEY (`reason_code`) REFERENCES `stop_reason_codes` (`code`),
  CONSTRAINT `ck_mpd_hours` CHECK (`hours` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: nav09_action_alias ──
CREATE TABLE `nav09_action_alias` (
  `old_code` varchar(60) NOT NULL,
  `new_code` varchar(60) NOT NULL,
  `canonical_file` varchar(80) DEFAULT NULL COMMENT 'محدِّد السياق حين يكون القديم غامضًا',
  `note` varchar(255) DEFAULT NULL,
  `status` enum('active','planned','retired') NOT NULL DEFAULT 'active',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`old_code`,`new_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: nav09_action_map ──
CREATE TABLE `nav09_action_map` (
  `canonical_code` varchar(60) NOT NULL,
  `label_ar` varchar(190) NOT NULL,
  `screen_title` varchar(190) NOT NULL,
  `canonical_file` varchar(80) DEFAULT NULL,
  `actor_ar` varchar(120) DEFAULT NULL,
  `writes_text` varchar(255) DEFAULT NULL,
  `event_name` varchar(80) DEFAULT NULL,
  `consumers_text` varchar(255) DEFAULT NULL,
  `effect_text` varchar(500) DEFAULT NULL,
  `reverse_text` varchar(255) DEFAULT NULL,
  `live_code` varchar(80) DEFAULT NULL,
  `state` enum('alias','pending','bound_page','declared_unbuilt') NOT NULL DEFAULT 'pending',
  `guard_verified` enum('pending','yes','no','n_a') NOT NULL DEFAULT 'pending' COMMENT '⑤ أيمنعه حارسٌ في الخادم؟ — شاهدُه محاولةٌ غيرُ مخوَّلةٍ تُرفض برمز',
  `guard_evidence` varchar(190) NOT NULL DEFAULT '' COMMENT 'دليلُ حكمِ الحارس — رمزُ الرفضِ أو مسارُ الفحص',
  `idempotency_verified` enum('pending','yes','no','n_a') NOT NULL DEFAULT 'pending' COMMENT '⑩ أتُرفض إعادةُ النداء؟ — الإعادةُ ترجع مرجعَ الأول',
  `idempotency_evidence` varchar(190) NOT NULL DEFAULT '',
  `uat_verified` enum('pending','yes','no','n_a') NOT NULL DEFAULT 'pending' COMMENT '⑫ أاجتاز رحلةً حيةً بمستخدمٍ حقيقي؟ — محضرُ UAT موقَّع',
  `uat_evidence` varchar(190) NOT NULL DEFAULT '',
  `write_class` enum('read_only','domain_write','governance_write','external_side_effect') DEFAULT NULL COMMENT 'U10 ورقة 21 — تصنيف الكتابة ولازم التدقيق',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`canonical_code`),
  KEY `ix_n9a_state` (`state`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: nav09_file_map ──
CREATE TABLE `nav09_file_map` (
  `canonical_file` varchar(80) NOT NULL,
  `title_ar` varchar(190) NOT NULL,
  `owner_dept` varchar(64) NOT NULL,
  `state` enum('live','mapped','soon') NOT NULL DEFAULT 'soon',
  `real_path` varchar(190) DEFAULT NULL,
  `note` varchar(255) DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`canonical_file`),
  KEY `ix_n9m_state` (`state`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: nav_canonical ──
CREATE TABLE `nav_canonical` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `route` varchar(160) NOT NULL COMMENT 'المعرِّف — Dir/file.php بلا استعلامٍ ولا مرساة',
  `canonical_ar` varchar(190) NOT NULL COMMENT 'الاسمُ العربيُّ الرسميُّ الواحد',
  `canonical_en` varchar(190) DEFAULT NULL,
  `level_no` tinyint(4) NOT NULL COMMENT 'المستوى 1..6 (ف٧-١)',
  `level_name` varchar(60) NOT NULL,
  `group_name` varchar(190) NOT NULL COMMENT 'المجموعةُ المعياريةُ الواحدة (بند ٣)',
  `sort_no` int(11) NOT NULL DEFAULT 999 COMMENT 'الترتيبُ داخل المجموعة — من الدورةِ المستندية',
  `nature` varchar(60) DEFAULT NULL,
  `owner_dept` varchar(120) DEFAULT NULL COMMENT 'الإدارةُ المالكةُ للمفهوم',
  `status` enum('APPROVED','PENDING_OWNER','PENDING_DEDUP','PENDING_OWNER_MERGE','TECHNICAL_ONLY','MERGED','RETIRED') NOT NULL,
  `decision_state` enum('PENDING_OWNER','OWNER_REVIEW_OVERDUE','APPROVED','REJECTED') DEFAULT NULL COMMENT 'محورُ القرار: هل حُسم ومن حسمه — والصمتُ لا يُرقّيه',
  `application_state` enum('CURRENT','PROVISIONALLY_APPLIED_NO_OBJECTION','DEPLOYED','ROLLED_BACK') NOT NULL DEFAULT 'CURRENT' COMMENT 'محورُ التطبيق: ما يراه المستخدمُ فعلًا — مستقلٌّ عن محورِ القرار',
  `decided_by` int(11) DEFAULT NULL COMMENT 'الفاعلُ الحقيقيُّ وحدَه — NULL ما لم يوجد',
  `decision_source` varchar(190) DEFAULT NULL COMMENT 'مرجعُ القرارِ الوثائقيُّ حين لا فاعلَ بشريّ — أحدُهما إلزاميٌّ للحسم',
  `decided_at` datetime DEFAULT NULL,
  `provisional_since` datetime DEFAULT NULL COMMENT 'متى بدأ التطبيقُ المؤقَّت',
  `provisional_reversible` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'حصرُ النطاق: 1 = تسميةٌ/موضعٌ يُعكسان · 0 يمنع التطبيقَ المؤقَّت',
  `policy_domain` enum('NAVIGATION_NAMING_POSITION','PERMISSIONS','APPROVAL_LADDERS','FINANCIAL_CAPS','SEGREGATION_OF_DUTIES','LEGAL_OBLIGATIONS','FINANCIAL_DECISIONS') NOT NULL DEFAULT 'NAVIGATION_NAMING_POSITION' COMMENT 'مجالُ الصفّ — والتطبيقُ المؤقَّتُ ممنوعٌ بنيويًّا في الستةِ المحظورة',
  `old_names` text DEFAULT NULL COMMENT 'المسمياتُ الملغاة — مرادفاتٌ تاريخية',
  `derivation` varchar(190) DEFAULT NULL COMMENT 'مصدرُ الاشتقاق (بند ٤ — إلزاميّ)',
  `view_of` varchar(255) DEFAULT NULL COMMENT 'علاقةُ المنظر/الارتباط بمسارٍ داخل الـ359',
  `merge_into` varchar(255) DEFAULT NULL,
  `retirement_status` varchar(40) DEFAULT NULL,
  `current_label` varchar(190) DEFAULT NULL COMMENT 'اسمُ الانتقالِ للمعلَّق — من الصفِّ لا من إرث',
  `current_parent` varchar(255) DEFAULT NULL,
  `matrix_row` smallint(6) DEFAULT NULL COMMENT 'رقمُ الصفِّ في الدفترِ المعتمَد',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `output_doc` varchar(190) DEFAULT NULL COMMENT 'المستندُ الناتجُ — من دفترِ التدقيقِ حصرًا، ولا يُكتب تخمينًا',
  `state_transition` varchar(190) DEFAULT NULL COMMENT 'وسمُ انتقالِ الحالةِ الصريحُ — مقروءٌ من الشيفرةِ لا مؤلَّف',
  `ops_source` varchar(190) DEFAULT NULL COMMENT 'من أين جاء أيٌّ منهما — فلا رقمَ بلا مصدر',
  `placement_kind` enum('SINGLE','CROSS_ROLE_ENTRY','UNJUSTIFIED_SPLIT') NOT NULL DEFAULT 'SINGLE' COMMENT 'مدخلٌ عابرٌ للأدوارِ مشروعٌ · أو اختلافٌ يُوحَّد بقرارِ المالك',
  `placement_basis` varchar(190) DEFAULT NULL COMMENT 'مصدرُ التصنيفِ — مقيسٌ أو مسمًّى بنصِّ المالك، لا اجتهادٌ صامت',
  `space_class` varchar(32) NOT NULL DEFAULT '' COMMENT 'صنفُ الظهورِ الغالبُ بعدَ شجرةِ القرار — ليقرأ قارئُ المصفوفةِ حكمَ الحارس',
  `anchor_key` varchar(24) DEFAULT NULL COMMENT 'مفتاحُ مِرساةِ القشرة — الغلافُ ينادي المفتاحَ والسجلُّ يعطي المسارَ والاسم',
  `screen_id` varchar(12) NOT NULL DEFAULT '' COMMENT 'REPAIR01 - المعرف المعياري للشاشة SCR-nnnn',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_route` (`route`),
  UNIQUE KEY `uq_anchor` (`anchor_key`),
  KEY `ix_status_level` (`status`,`level_no`,`sort_no`),
  KEY `ix_screen_id` (`screen_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='UXUI-01: سجلُّ التنقلِ المعياريُّ — صورةُ مصفوفةِ الـ359 المعتمَدة';

-- ── Table: nav_canonical_current ──
CREATE TABLE `nav_canonical_current` (
  `route` varchar(160) NOT NULL,
  `role_id` int(11) NOT NULL,
  `cur_label` varchar(190) NOT NULL,
  `cur_group` varchar(190) NOT NULL,
  `cur_order` int(11) NOT NULL COMMENT 'تسلسلُ الظهورِ الحيُّ في الدور — من uxui_live_positions.tsv',
  PRIMARY KEY (`route`,`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='UXUI-01 v3: موضعُ الانتقالِ الحاليُّ للمعلَّقِ لكلِّ دور — المصفوفةُ وحدَها مصدرًا';

-- ── Table: nav_canonical_variants ──
CREATE TABLE `nav_canonical_variants` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `canonical_route` varchar(160) NOT NULL,
  `variant_key` varchar(120) NOT NULL COMMENT '#مرساة أو ?view=منظر',
  `variant_type` enum('anchor','declared_view') NOT NULL,
  `variant_purpose` varchar(190) NOT NULL COMMENT 'الاسمُ الظاهرُ للمدخلِ الثاني',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_variant` (`canonical_route`,`variant_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='UXUI-01 v3: سجلُّ المداخلِ الثانية — المرساةُ والمنظرُ المعلَن';

-- ── Table: nav_dedup_verdicts ──
CREATE TABLE `nav_dedup_verdicts` (
  `pair_no` smallint(6) NOT NULL,
  `route_a` varchar(160) NOT NULL,
  `route_b` varchar(160) NOT NULL,
  `similarity` decimal(5,4) DEFAULT NULL,
  `auto_hint` varchar(190) DEFAULT NULL COMMENT 'الترجيحُ الآليُّ — اقتراحٌ لا حكم',
  `verdict_class` enum('independent','related_containment','same_function','view_of_same_data','sequential_stages','header_lines') NOT NULL,
  `verdict_text` varchar(600) NOT NULL COMMENT 'الحكمُ الفنيُّ المسبَّبُ من الكود',
  `evidence` varchar(400) DEFAULT NULL COMMENT 'الجداولُ/الحوارسُ التي بُني عليها الحكم',
  `decided_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`pair_no`),
  KEY `ix_class` (`verdict_class`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='UXUI-01: أحكامُ ازدواجِ المعنى الـ59 — مثبَّتةٌ حقولًا لا نصًّا في ملف';

-- ── Table: nav_group_taxonomy ──
CREATE TABLE `nav_group_taxonomy` (
  `code` varchar(24) NOT NULL COMMENT 'رمزٌ ثابتٌ — يعيش في data-group-key فتُحفظ حالةُ الطيّ',
  `name_ar` varchar(64) NOT NULL COMMENT 'اسمُ المجموعةِ كما يُقرأ في السايدبار',
  `icon` varchar(64) NOT NULL COMMENT 'أيقونةُ الرأسِ — مُتحقَّقٌ وجودُها في مكتبةِ الأيقوناتِ المحمَّلة',
  `sort_no` tinyint(4) NOT NULL COMMENT 'ترتيبُ الظهور: أنا ← ما ينتظرني ← عملي ← المجالات ← الرقابة ← البصيرة ← الضبط',
  `open_default` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'مفتوحةٌ عند أولِ زيارةٍ فقط — واختيارُ المستخدمِ يغلبها',
  PRIMARY KEY (`code`),
  UNIQUE KEY `uq_sort` (`sort_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='العشرُ مجموعاتٍ — سقفُ التبويبِ في السايدبار لكلِّ إدارة';

-- ── Table: nav_items ──
CREATE TABLE `nav_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `role_id` int(11) NOT NULL COMMENT 'الدور المالك لهذا العنصر في قائمته',
  `door` varchar(16) NOT NULL COMMENT 'HOME·DAILY·APPR·REC·REP·SET — الأبواب الستة',
  `group_id` int(11) DEFAULT NULL COMMENT 'link_groups — مجموعةٌ قابلةٌ للطيّ داخل الباب؛ NULL = مباشرةً تحته',
  `module_id` int(11) DEFAULT NULL COMMENT 'modules.id حين يكون العنصر شاشةً مسجَّلة — مرجعُ الصلاحية والاسم',
  `label_ar` varchar(64) NOT NULL COMMENT 'اسم العرض؛ يُفحص خلوّه من المحظور المعماري عند الحفظ',
  `route` varchar(128) NOT NULL COMMENT 'المسار كما في سجل الشاشات',
  `icon` varchar(50) DEFAULT NULL,
  `sort_order` int(11) NOT NULL DEFAULT 0 COMMENT 'الترتيب داخل الباب/المجموعة',
  `counter_source` varchar(64) DEFAULT NULL COMMENT 'مُعرِّف العدّاد من سجل العدّادات — عدّادٌ واحدٌ بقيمةٍ واحدة',
  `permission_code` varchar(128) DEFAULT NULL COMMENT 'كود الشاشة لفحص can_view؛ NULL = ظهورٌ بلا فحص (ثوابت)',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_nav_role_route` (`role_id`,`route`),
  KEY `ix_nav_role_door` (`role_id`,`door`,`sort_order`),
  KEY `ix_nav_group` (`group_id`),
  KEY `ix_nav_module` (`module_id`),
  CONSTRAINT `chk_nav_route_not_relative` CHECK (`route` is null or `route`  not like '../%'),
  CONSTRAINT `chk_nav_door` CHECK (`door` in ('HOME','DAILY','APPR','REC','REP','SET','GOV','FIN','RISK')),
  CONSTRAINT `chk_nav_items_module_or_code` CHECK (`permission_code` is null or `permission_code` = '' or `module_id` is not null and `module_id` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

