  `proof_doc` varchar(120) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='UXUI-01: حجرُ تعريفِ التنقلِ القديم (الدور 5) — ثلاثون يومًا ثم حذف';

