-- ── Table: nav_lifecycle_groups ──
CREATE TABLE `nav_lifecycle_groups` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `workspace_id` varchar(24) NOT NULL,
  `group_key` varchar(150) NOT NULL COMMENT 'الاسمُ المطبَّعُ (navr_gz) — مفتاحُ المطابقة',
  `label_ar` varchar(150) NOT NULL COMMENT 'اسمُ العرضِ كما في الورقة',
  `sort_no` tinyint(3) unsigned NOT NULL,
  `source_ref` varchar(190) NOT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ws_group` (`workspace_id`,`group_key`),
  UNIQUE KEY `uq_ws_sort` (`workspace_id`,`sort_no`),
  CONSTRAINT `fk_nlg_ws` FOREIGN KEY (`workspace_id`) REFERENCES `nav_workspaces` (`workspace_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='NAVR: مجموعاتُ الدورةِ خاصّةٌ بالمساحة';

-- ── Table: nav_pending_answers ──
CREATE TABLE `nav_pending_answers` (
  `closure_id` int(10) unsigned NOT NULL,
  `q_no` tinyint(4) NOT NULL COMMENT '1 الاسم · 2 المجموعة · 3 الترتيب · 4 المستندُ الداخل · 5 الناتج · 6 الحالةُ التالية',
  `answer` enum('yes','no','unanswered') NOT NULL DEFAULT 'unanswered',
  `note` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`closure_id`,`q_no`),
  CONSTRAINT `fk_ans_closure` FOREIGN KEY (`closure_id`) REFERENCES `nav_pending_closure` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='UXUI-01: أسئلةُ الإغلاقِ الستةُ بأجوبتِها';

-- ── Table: nav_pending_closure ──
CREATE TABLE `nav_pending_closure` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `route` varchar(160) NOT NULL,
  `owner_dept` varchar(120) NOT NULL,
  `proposed_label` varchar(190) NOT NULL COMMENT 'الاسمُ المعياريُّ المقترَح',
  `proposed_group` varchar(190) NOT NULL,
  `proposed_level` tinyint(4) NOT NULL,
  `proposed_order` int(11) NOT NULL,
  `sent_at` datetime NOT NULL COMMENT 'بدءُ مهلةِ الثلاثةِ أيام',
  `due_at` datetime NOT NULL,
  `decision` enum('pending','approved','modified','auto_approved_by_silence') NOT NULL DEFAULT 'pending',
  `decision_state` enum('PENDING_OWNER','OWNER_REVIEW_OVERDUE','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING_OWNER',
  `application_state` enum('CURRENT','PROVISIONALLY_APPLIED_NO_OBJECTION','DEPLOYED','ROLLED_BACK') NOT NULL DEFAULT 'CURRENT',
  `escalated_at` datetime DEFAULT NULL COMMENT 'وقتُ التصعيدِ للنائبِ المختص',
  `escalated_to_role` int(11) DEFAULT NULL COMMENT 'موضعُ السلطةِ لا اسمُ شخص',
  `escalation_due_at` datetime DEFAULT NULL COMMENT 'مهلةُ النائبِ: يومان',
  `provisional_since` datetime DEFAULT NULL,
  `rolled_back_at` datetime DEFAULT NULL,
  `decided_by` int(11) DEFAULT NULL COMMENT 'users.id — يُقرأ من الجلسةِ لا يُكتب نصًّا',
  `decided_at` datetime DEFAULT NULL,
  `modification_note` varchar(500) DEFAULT NULL,
  `reopened_at` datetime DEFAULT NULL COMMENT 'الصمتُ قابلٌ للنقضِ لاحقًا من الشاشة',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_route` (`route`),
  KEY `ix_dept_state` (`owner_dept`,`decision`,`due_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='UXUI-01: إغلاقُ المعلَّقِ بقاعدةِ ثلاثةِ أيامٍ — الصمتُ يعتمد المقترحَ ويبقى قابلًا للنقض';

-- ── Table: nav_placements ──
CREATE TABLE `nav_placements` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `workspace_id` varchar(24) NOT NULL,
  `screen_id` varchar(12) DEFAULT NULL COMMENT 'SCR-#### متى كانت مبنيّةً مجسورة',
  `route` varchar(160) DEFAULT NULL COMMENT 'مسارُ الشاشةِ المبنيّة — NULL لغيرِ المبنيّ',
  `target_ref` varchar(190) NOT NULL COMMENT 'هويّةُ هدفِ الدليل: code·idx·الاسم',
  `target_id` varchar(24) DEFAULT NULL,
  `group_id` int(11) NOT NULL,
  `sort_no` smallint(5) unsigned NOT NULL,
  `placement_type` enum('MENU_ITEM','TAB_CHILD','DIRECT_ONLY','PROJECTION','UTILITY','LANDING_PAGE','NOT_BUILT') NOT NULL COMMENT 'أصنافُ §8 السبعة — وLANDING_PAGE أُضيف بأمرِ GOV_UI_EXEC',
  `source_ref` varchar(190) NOT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ws_target` (`workspace_id`,`target_ref`),
  KEY `ix_ws_grp_sort` (`workspace_id`,`group_id`,`sort_no`),
  KEY `ix_route` (`route`),
  KEY `fk_np_grp` (`group_id`),
  KEY `ix_np_target` (`target_id`),
  CONSTRAINT `fk_np_grp` FOREIGN KEY (`group_id`) REFERENCES `nav_lifecycle_groups` (`id`),
  CONSTRAINT `fk_np_target` FOREIGN KEY (`target_id`) REFERENCES `nav_targets` (`target_id`),
  CONSTRAINT `fk_np_ws` FOREIGN KEY (`workspace_id`) REFERENCES `nav_workspaces` (`workspace_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='NAVR: موضعُ الشاشةِ في مساحتِها — والصلاحياتُ طبقةٌ مستقلّةٌ لا تُخزَّن هنا';

-- ── Table: nav_redirects ──
CREATE TABLE `nav_redirects` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `old_route` varchar(128) NOT NULL,
  `new_route` varchar(128) NOT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `hits` int(11) NOT NULL DEFAULT 0 COMMENT 'عدّادُ استعمالٍ يقيس أمان الحذف لاحقًا',
  `last_hit_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_navred_old` (`old_route`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='تحويلُ المسارات القديمة — UX-01 §10.2';

-- ── Table: nav_route_group ──
CREATE TABLE `nav_route_group` (
  `route` varchar(160) NOT NULL COMMENT 'المسارُ مطبَّعًا صغيرًا — بلا ../ ولا استعلامٍ ولا مرساة',
  `group_code` varchar(24) NOT NULL,
  `basis` varchar(190) NOT NULL COMMENT 'سندُ الحكم: PIN · GROUP:… · LEVEL:… · DIR:… · FALLBACK',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`route`),
  KEY `ix_nrg_group` (`group_code`),
  CONSTRAINT `fk_nrg_group` FOREIGN KEY (`group_code`) REFERENCES `nav_group_taxonomy` (`code`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='المسارُ ⇄ مجموعتُه الواحدة — والمشترَكُ بين الإداراتِ في مكانٍ واحدٍ دائمًا';

-- ── Table: nav_targets ──
CREATE TABLE `nav_targets` (
  `target_id` varchar(24) NOT NULL COMMENT 'NT-<code>-<nnn> ثابتٌ منذ التعريف',
  `source_doc` varchar(190) NOT NULL,
  `sheet_code` varchar(24) NOT NULL,
  `row_no` smallint(5) unsigned NOT NULL COMMENT 'صفُّ الورقةِ لحظةَ التعريف — نسبٌ لا مفتاحُ مطابقة',
  `canonical_title` varchar(190) NOT NULL,
  `workspace_id` varchar(24) NOT NULL,
  `group_key` varchar(150) NOT NULL,
  `target_order` smallint(5) unsigned NOT NULL,
  `visibility_class` varchar(16) NOT NULL COMMENT 'MENU_ITEM/TAB_CHILD/PROJECTION/DIRECT_ONLY/UTILITY/NOT_BUILT',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`target_id`),
  UNIQUE KEY `uq_ws_order` (`workspace_id`,`sheet_code`,`target_order`),
  CONSTRAINT `fk_nt_ws` FOREIGN KEY (`workspace_id`) REFERENCES `nav_workspaces` (`workspace_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='NAVR §١٩: هويّةُ هدفِ الملاحةِ الثابتة — واسمُ Excel نسبٌ لا مفتاح';

-- ── Table: nav_workspaces ──
CREATE TABLE `nav_workspaces` (
  `workspace_id` varchar(24) NOT NULL,
  `kind` enum('DEPARTMENT','EXECUTIVE','PERSONAL','PLATFORM_UTILITY') NOT NULL,
  `name_ar` varchar(150) NOT NULL,
  `dept_code` varchar(24) DEFAULT NULL,
  `ruling` varchar(400) NOT NULL COMMENT 'حكمُ التصنيفِ مكتوبًا في الصفِّ نفسِه — لا يُخلط مقامٌ بلا حكم',
  `source_ref` varchar(190) NOT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`workspace_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='NAVR: مساحاتُ العملِ — طبقةٌ كانت حقيقةً سياقيّةً بلا مخزن';

-- ── Table: nav_ws_roles ──
CREATE TABLE `nav_ws_roles` (
  `workspace_id` varchar(24) NOT NULL,
  `role_id` int(11) NOT NULL,
  `binding` enum('PRIMARY','SECONDARY') NOT NULL DEFAULT 'PRIMARY',
  `source_ref` varchar(190) NOT NULL,
  `primary_role` int(11) GENERATED ALWAYS AS (if(`binding` = 'PRIMARY',`role_id`,NULL)) STORED,
  PRIMARY KEY (`workspace_id`,`role_id`),
  UNIQUE KEY `uq_one_primary` (`primary_role`),
  CONSTRAINT `fk_wsr_ws` FOREIGN KEY (`workspace_id`) REFERENCES `nav_workspaces` (`workspace_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='NAVR: مساحةُ كلِّ دور — PRIMARY واحدة';

-- ── Table: non_delegable_actions ──
CREATE TABLE `non_delegable_actions` (
  `company_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'عمودُ العزل — 0: قائمةٌ معياريةٌ لكلِّ الكيانات',
  `action_code` varchar(80) NOT NULL,
  `title_ar` varchar(160) NOT NULL,
  `doc_ref` varchar(20) NOT NULL DEFAULT 'GOV-AUTH-01',
  PRIMARY KEY (`action_code`),
  KEY `ix_company` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='الخمسةُ التي لا تُفوَّض أبدًا — يرفضها القادحُ لا العُرف';

-- ── Table: op_containers ──
CREATE TABLE `op_containers` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `container_no` varchar(40) NOT NULL COMMENT 'CNT-سنة-تسلسل — ترقيمٌ خادمي',
  `level` enum('رئيسية','مورد','نوع','معدة','مشغّل') NOT NULL,
  `parent_id` int(10) unsigned DEFAULT NULL COMMENT 'NULL للرئيسية حصرًا — يحرسه ck_container_parent',
  `contract_id` int(10) unsigned NOT NULL,
  `contract_item_id` int(10) unsigned DEFAULT NULL COMMENT 'contractequipments.id — مصدرُ سقف الرئيسية',
  `obl_id` int(10) unsigned DEFAULT NULL COMMENT 'CAP-01 §16: التزامُ نوع المعدة (contract_commitments.id) — مضافٌ صراحةً ليصحَّ قيدُ التطابق (C21)',
  `resource_plan_id` int(10) unsigned DEFAULT NULL COMMENT 'صفُّ خطة الموارد الذي بُذرت منه الحاوية (P-04) — والقديمُ يبقى على contract_item_id',
  `unit_type` enum('hour','ton','meter','cbm','day','shift','trip') NOT NULL DEFAULT 'hour' COMMENT 'وحدةُ البند — والسقفُ والمستهلَكُ بها',
  `work_model` varchar(40) DEFAULT NULL COMMENT 'نموذجُ العمل كما في البند',
  `cap_qty` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'السقف — لا يُتجاوز',
  `allocated_qty` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'Σ ما وُزّع على الأبناء — قيدُ Σ البنيوي',
  `consumed_qty` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'Σ ما استُهلك فعلًا',
  `remaining_qty` decimal(16,2) GENERATED ALWAYS AS (`cap_qty` - `consumed_qty`) STORED COMMENT 'مولَّدٌ لا يُكتب — فلا مصدرانِ للرقم الواحد',
  `supplier_id` int(10) unsigned DEFAULT NULL,
  `equipment_id` int(10) unsigned DEFAULT NULL,
  `operator_employee_id` int(10) unsigned DEFAULT NULL,
  `project_id` int(10) unsigned DEFAULT NULL COMMENT 'الموقع — مفتاحُ الحجب المرحليّ (المرحلة ③)',
  `role_kind` enum('أساسية','احتياطية','أساسي','بديل أول','بديل ثانٍ','مشترك') DEFAULT NULL,
  `seat_no` smallint(5) unsigned DEFAULT NULL COMMENT 'N-11: رقم المقعد التعاقدي — فريد داخل العقد لمستوى معدة',
  `seat_kind` enum('contractual_seat','operational_resource_slot','supplier_allocation') DEFAULT NULL COMMENT 'N-11: نوع المقعد — يُشتق من فصل بند البيع عن خطة الموارد (PLAN-03 §4) لا يُصنَّف مستقلًّا',
  `seat_equipment_type_id` int(10) unsigned DEFAULT NULL COMMENT 'N-11: نوع المعدة المطلوب للمقعد (equipments_types.id)',
  `contract_hours_monthly` decimal(10,2) DEFAULT NULL COMMENT 'N-11: الساعات التعاقدية الشهرية للمقعد',
  `primary_units_contracted` smallint(5) unsigned DEFAULT NULL COMMENT 'CAP-01 §8.1: أساسياتُ درجة «نوع» — الشجرةُ تفرض Σ والسياسةُ في contract_commitments',
  `standby_units_required` smallint(5) unsigned DEFAULT NULL COMMENT 'CAP-01 §8.1: الاحتياطيُّ المطلوب لدرجة «نوع»',
  `standby_units_allowed` smallint(5) unsigned DEFAULT NULL COMMENT 'CAP-01 §8.1: سقفُ الاحتياطي لدرجة «نوع» — StandbyCapService يقيس عليه',
  `seat_unit_price` decimal(14,4) DEFAULT NULL COMMENT 'N-11: سعر وحدة المقعد',
  `seat_currency` varchar(8) DEFAULT NULL COMMENT 'N-11: عملة سعر المقعد',
  `shift_no` tinyint(3) unsigned DEFAULT NULL COMMENT 'نوبةُ المشغّل',
  `valid_from` date DEFAULT NULL,
  `valid_to` date DEFAULT NULL,
  `state` enum('نشطة','معلَّقة','مقفلة') NOT NULL DEFAULT 'نشطة',
  `origin` enum('عقد','مشتقّة') NOT NULL DEFAULT 'عقد' COMMENT 'H-01 ②: منشأُ الرقم — «مشتقّة» تنتظر إقرارَ الإدارة ولا تُقدَّم متفقًا عليها',
  `origin_note` varchar(255) DEFAULT NULL COMMENT 'مِن أين اشتُقّت بالضبط — فيُدقَّق الاستنتاجُ لا يُصدَّق',
  `origin_ack_by` int(10) unsigned DEFAULT NULL COMMENT 'مَن أقرّ الحصةَ المشتقّة — NULL = لم تُقرّ بعد',
  `origin_ack_at` datetime DEFAULT NULL,
  `close_reason` varchar(200) DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(10) unsigned DEFAULT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `seat_obl_uq_key` varchar(40) GENERATED ALWAYS AS (if(`seat_no` is not null and `obl_id` is not null and `is_deleted` = 0,concat(`obl_id`,_utf8mb4':',`seat_no`),NULL)) STORED COMMENT 'CAP-01 §16: UQ(obl_id, seat_no) — فهرسٌ فريدٌ مشروطٌ على عمودٍ مولَّد',
  `slot_role` enum('primary_two_shifts','primary_one_shift','reserve') DEFAULT NULL COMMENT 'دورُ الخانة — مصدرُ F-01',
  `daily_hours_basis` decimal(5,2) DEFAULT NULL COMMENT 'F-01: 20 للورديتين · 12 للواحدة — قادحٌ يحسبه ولا يُقبل من الشاشة',
  `monthly_basis` decimal(8,2) DEFAULT NULL COMMENT 'F-02: اليوميُّ × 30 — قادحٌ يحسبه',
  `unit_margin` decimal(12,4) DEFAULT NULL COMMENT 'هامشُ الخانة — مدخلُ F-12',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_container_no` (`company_id`,`container_no`),
  UNIQUE KEY `uq_main_per_item` (`company_id`,`contract_item_id`,`level`),
  UNIQUE KEY `uq_seat_no` (`company_id`,`contract_id`,`seat_no`),
  UNIQUE KEY `uq_oc_id_obl` (`id`,`obl_id`),
  UNIQUE KEY `uq_seat_per_obl` (`seat_obl_uq_key`),
  KEY `ix_parent` (`company_id`,`parent_id`),
  KEY `ix_contract` (`company_id`,`contract_id`,`level`),
  KEY `ix_site` (`company_id`,`project_id`,`state`),
  KEY `ix_container_origin` (`company_id`,`origin`,`origin_ack_by`),
  KEY `ix_oc_resource_plan` (`resource_plan_id`),
  KEY `fk_oc_parent_obl` (`parent_id`,`obl_id`),
  CONSTRAINT `fk_container_parent` FOREIGN KEY (`parent_id`) REFERENCES `op_containers` (`id`),
  CONSTRAINT `fk_oc_parent_obl` FOREIGN KEY (`parent_id`, `obl_id`) REFERENCES `op_containers` (`id`, `obl_id`),
  CONSTRAINT `ck_container_alloc` CHECK (`allocated_qty` >= 0 and `allocated_qty` <= `cap_qty`),
  CONSTRAINT `ck_container_consumed` CHECK (`consumed_qty` >= 0 and `consumed_qty` <= `cap_qty`),
  CONSTRAINT `ck_container_parent` CHECK (`level` = 'رئيسية' and `parent_id` is null or `level` <> 'رئيسية' and `parent_id` is not null),
  CONSTRAINT `ck_container_cap` CHECK (`cap_qty` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: operations ──
CREATE TABLE `operations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) DEFAULT NULL,
  `equipment` varchar(100) NOT NULL,
  `equipment_type` varchar(100) NOT NULL DEFAULT '0',
  `equipment_category` varchar(20) NOT NULL,
  `prev_equipment_category` varchar(20) DEFAULT NULL,
  `project_id` varchar(20) NOT NULL,
  `contract_id` varchar(10) NOT NULL,
  `supplier_id` varchar(10) NOT NULL,
  `start` varchar(50) NOT NULL,
  `end` varchar(50) NOT NULL,
  `reason` mediumtext NOT NULL,
  `days` varchar(20) NOT NULL,
  `total_equipment_hours` decimal(10,2) DEFAULT 0.00 COMMENT 'إجمالي ساعات العمل الكلية للآلية',
  `shift_hours` decimal(10,2) DEFAULT 0.00 COMMENT 'عدد ساعات الوردية للمعدة',
  `target_daily_hours` decimal(10,2) DEFAULT NULL COMMENT 'الساعات اليومية المستهدفة للآلية (مرجع للمقارنة منفّذ/مستهدف)',
  `shift_type` enum('D','N','B') NOT NULL DEFAULT 'B',
  `status` tinyint(1) DEFAULT 1,
  `op_state` enum('تعمل','جاهزة','معطلة') NOT NULL DEFAULT 'جاهزة' COMMENT 'حالة الآلية النشطة — تُدار من صفحة الحركة فقط',
  `equipment_health` enum('سليمة','معطلة') NOT NULL DEFAULT 'سليمة' COMMENT 'الصحة الفنية للمعدة (مستقلة عن status التشغيلي)',
  `health_reason` varchar(150) DEFAULT NULL COMMENT 'سبب العطل، مثل: صيانة',
  `health_updated_at` datetime DEFAULT NULL,
  `health_updated_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_total_equipment_hours` (`total_equipment_hours`),
  KEY `idx_shift_hours` (`shift_hours`),
  KEY `idx_operations_equipment_health` (`equipment_health`),
  KEY `idx_operations_project` (`project_id`),
  KEY `idx_operations_supplier` (`supplier_id`),
  KEY `idx_operations_equipment` (`equipment`),
  KEY `idx_operations_start` (`start`),
  KEY `idx_operations_company_id` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: operator_rotations ──
CREATE TABLE `operator_rotations` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `container_id` int(10) unsigned NOT NULL COMMENT 'حاويةُ المشغّل',
  `operator_employee_id` int(10) unsigned NOT NULL,
  `cycle_on_days` smallint(5) unsigned NOT NULL COMMENT 'أيامُ العمل في الدورة',
  `cycle_off_days` smallint(5) unsigned NOT NULL COMMENT 'أيامُ الراحة',
  `cycle_start` date NOT NULL COMMENT 'مبدأُ الدورة — منه يُحسب المناوب',
  `shift_no` tinyint(3) unsigned DEFAULT NULL,
  `valid_to` date DEFAULT NULL,
  `note` varchar(200) DEFAULT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `cycle_code` varchar(255) DEFAULT NULL COMMENT 'معرّف الدورة',
  `person_ref` varchar(80) DEFAULT NULL COMMENT 'كود الفرد ◄',
  `rotation_pattern` varchar(80) DEFAULT NULL COMMENT 'نمط التناوب ▼',
  `cycle_start_date` varchar(255) DEFAULT NULL COMMENT 'بداية الدورة',
  `leave_start` varchar(255) DEFAULT NULL COMMENT 'بداية الإجازة',
  `leave_end` varchar(255) DEFAULT NULL COMMENT 'نهاية الإجازة',
  `leave_type` varchar(80) DEFAULT NULL COMMENT 'نوع الإجازة ▼',
  `assigned_backup` varchar(255) DEFAULT NULL COMMENT 'البديل المكلَّف ◄',
  `backup_qual_check` varchar(255) DEFAULT NULL COMMENT 'فحص تأهيل البديل ◄',
  `swap_state` varchar(80) DEFAULT NULL COMMENT 'حالة التبادل ▼',
  `coverage_effect` varchar(255) DEFAULT NULL COMMENT 'أثر التغطية ◄',
  `cycle_state` varchar(80) DEFAULT NULL COMMENT 'حالة الدورة ▼',
  `data_state` varchar(255) DEFAULT NULL COMMENT 'حالة البيانات ▼',
  `src_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع المصدر',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_rotation` (`company_id`,`container_id`,`operator_employee_id`,`cycle_start`),
  KEY `ix_rotation_op` (`company_id`,`operator_employee_id`),
  KEY `fk_rotation_container` (`container_id`),
  CONSTRAINT `fk_rotation_container` FOREIGN KEY (`container_id`) REFERENCES `op_containers` (`id`),
  CONSTRAINT `ck_rotation_cycle` CHECK (`cycle_on_days` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: opportunities ──
CREATE TABLE `opportunities` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `opp_code` varchar(50) NOT NULL,
  `title` varchar(255) NOT NULL,
  `client_id` int(11) DEFAULT NULL,
  `source` varchar(100) DEFAULT NULL,
  `sector_category` varchar(100) DEFAULT NULL,
  `state_region` varchar(100) DEFAULT NULL,
  `revenue_model` enum('hourly','ton','meter','mixed') DEFAULT NULL,
  `expected_revenue` decimal(14,2) NOT NULL DEFAULT 0.00,
  `currency` enum('USD','SDG') NOT NULL DEFAULT 'USD',
  `probability` decimal(5,2) NOT NULL DEFAULT 0.00,
  `stage` enum('جديدة','قيد الدراسة','مؤهلة','عرض مقدم','تفاوض','فوز','خسارة','مستبعدة') NOT NULL DEFAULT 'جديدة',
  `attractiveness` enum('منخفضة','متوسطة','عالية') DEFAULT NULL,
  `strategy_fit` enum('منخفض','متوسط','عالي') DEFAULT NULL,
  `capacity_summary` text DEFAULT NULL,
  `requirements_json` text DEFAULT NULL COMMENT 'INJAZ-S05 — المتطلبات المبدئية المُهيكلة (معدات بالنوع + عددا مشغّلين/موردين) JSON؛ capacity_summary مشتقٌّ منه',
  `funding_needed` decimal(14,2) NOT NULL DEFAULT 0.00,
  `study_decision` enum('متابعة','تعليق','استبعاد') DEFAULT NULL,
  `expected_close_date` date DEFAULT NULL,
  `lost_reason` varchar(255) DEFAULT NULL,
  `win_reason` varchar(255) DEFAULT NULL,
  `review_notes` text DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_opportunities_company_code` (`company_id`,`opp_code`),
  KEY `idx_opp_company` (`company_id`),
  KEY `idx_opp_client` (`client_id`),
  KEY `idx_opp_stage` (`stage`),
  KEY `idx_opp_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ── Table: ops_deviation_report ──
CREATE TABLE `ops_deviation_report` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL DEFAULT 0,
  `row_code` varchar(255) DEFAULT NULL COMMENT 'معرّف السطر',
  `period_ref` varchar(255) DEFAULT NULL COMMENT 'الفترة ◄',
  `project_ref` varchar(255) DEFAULT NULL COMMENT 'المشروع ◄',
  `equipment_ref` varchar(255) DEFAULT NULL COMMENT 'المعدة ◄',
  `calibrated_plan` decimal(18,3) DEFAULT NULL COMMENT 'المخطط المعاير ◄',
  `approved_executed` decimal(18,3) DEFAULT NULL COMMENT 'المنفَّذ المعتمد ◄',
  `gap` decimal(18,3) DEFAULT NULL COMMENT 'الفجوة ◄',
  `deviation_pct` decimal(8,2) DEFAULT NULL COMMENT 'نسبة الانحراف ◄',
  `control_limit` varchar(120) DEFAULT NULL COMMENT 'الحد المضبوط ◄',
  `limit_exceeded` varchar(255) DEFAULT NULL COMMENT 'تجاوز الحد؟ ◄',
  `catchup_rate` decimal(18,3) DEFAULT NULL COMMENT 'الوتيرة المطلوبة للحاق ◄',
  `top_three_reasons` varchar(255) DEFAULT NULL COMMENT 'أكبر ثلاثة أسباب ◄',
  `deviation_owner` varchar(255) DEFAULT NULL COMMENT 'مسؤول الانحراف ◄',
  `escalation_state` varchar(255) DEFAULT NULL COMMENT 'حالة التصعيد ◄',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_84896734_co` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='DEP-11 — تقرير الانحراف والتصعيد · الحبة: سطرُ انحرافٍ واحدٌ لمشروعٍ ومعدّةٍ في فترة';

-- ── Table: ops_resource_move_order ──
CREATE TABLE `ops_resource_move_order` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL DEFAULT 0,
  `order_no` varchar(80) DEFAULT NULL COMMENT 'رقم الأمر',
  `order_date` date DEFAULT NULL COMMENT 'تاريخ الأمر',
  `resource_kind` varchar(80) DEFAULT NULL COMMENT 'نوع المورد المنقول ▼',
  `resource_ref` varchar(80) DEFAULT NULL COMMENT 'كود المورد المنقول ◄',
  `from_project` varchar(255) DEFAULT NULL COMMENT 'من مشروع ◄',
  `from_site` varchar(255) DEFAULT NULL COMMENT 'من موقع ◄',
  `to_project` varchar(255) DEFAULT NULL COMMENT 'إلى مشروع ◄',
  `to_site` varchar(255) DEFAULT NULL COMMENT 'إلى موقع ◄',
  `move_reason` varchar(80) DEFAULT NULL COMMENT 'سبب الحركة ▼',
  `requested_exec_date` date DEFAULT NULL COMMENT 'تاريخ التنفيذ المطلوب',
  `month_plan_effect` varchar(255) DEFAULT NULL COMMENT 'أثر الحركة على خطة الشهر',
  `needs_transfer_order` varchar(80) DEFAULT NULL COMMENT 'يتطلب أمر ترحيل؟ ▼',
  `transfer_order_ref` varchar(80) DEFAULT NULL COMMENT 'رقم أمر الترحيل المتفرع ◄',
  `order_state` varchar(80) DEFAULT NULL COMMENT 'حالة الأمر ▼',
  `reviewer` varchar(255) DEFAULT NULL COMMENT 'المراجع',
  `approved_by` int(11) DEFAULT NULL COMMENT 'المعتمِد',
  `approved_at` datetime DEFAULT NULL COMMENT 'تاريخ الاعتماد',
  `data_state` varchar(255) DEFAULT NULL COMMENT 'حالة البيانات ▼',
  `src_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع المصدر',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_382c739c_co` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='DEP-11 — طلب وقرار حركة الموارد · الحبة: أمرُ حركةِ موردٍ واحدٌ من موقعٍ إلى موقع';

-- ── Table: ops_room_kpi ──
CREATE TABLE `ops_room_kpi` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL DEFAULT 0,
  `kpi_id` varchar(60) DEFAULT NULL COMMENT 'معرّف المؤشر',
  `kpi_ref` varchar(255) DEFAULT NULL COMMENT 'المؤشر — KPI Catalog ◄',
  `value` decimal(18,3) DEFAULT NULL COMMENT 'القيمة ◄',
  `uom` varchar(80) DEFAULT NULL COMMENT 'الوحدة ◄',
  `period_ref` varchar(80) DEFAULT NULL COMMENT 'الفترة ▼',
  `source_ref` varchar(255) DEFAULT NULL COMMENT 'المصدر ◄',
  `control_limit` varchar(120) DEFAULT NULL COMMENT 'الحد المضبوط ◄',
  `state` varchar(255) DEFAULT NULL COMMENT 'الحالة ◄',
  `trend` varchar(255) DEFAULT NULL COMMENT 'اتجاه الوتيرة ◄',
  `deviation_owner` varchar(255) DEFAULT NULL COMMENT 'مسؤول الانحراف ◄',
  `updated_on` datetime DEFAULT NULL COMMENT 'آخر تحديث ◄',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_da5c18e3_co` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='DEP-11 — غرفة العمليات · الحبة: مؤشرُ غرفةِ عملياتٍ واحدٌ في فترة';

-- ── Table: ops_seasonal_factor ──
CREATE TABLE `ops_seasonal_factor` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL DEFAULT 0,
  `factor_code` varchar(255) DEFAULT NULL COMMENT 'معرّف المعامل',
  `season` varchar(255) DEFAULT NULL COMMENT 'الموسم',
  `from_date` date DEFAULT NULL COMMENT 'من تاريخ',
  `to_date` date DEFAULT NULL COMMENT 'إلى تاريخ',
  `business_model` varchar(80) DEFAULT NULL COMMENT 'نموذج العمل ▼',
  `calibration_factor` decimal(10,4) DEFAULT NULL COMMENT 'معامل المعايرة',
  `calc_basis` varchar(255) DEFAULT NULL COMMENT 'أساس الاحتساب',
  `apply_scope` varchar(80) DEFAULT NULL COMMENT 'نطاق التطبيق ▼',
  `factor_state` varchar(80) DEFAULT NULL COMMENT 'حالة المعامل ▼',
  `data_state` varchar(255) DEFAULT NULL COMMENT 'حالة البيانات ▼',
  `src_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع المصدر',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_d0e2a57f_co` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='DEP-11 — الخطة الموسمية ومعاملاتها · الحبة: معاملُ معايرةٍ موسميٌّ واحدٌ في مدّة';

-- ── Table: ops_stop_register ──
CREATE TABLE `ops_stop_register` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `occurrence_key` char(40) NOT NULL COMMENT 'sha1 لحبة الواقعة - مفتاح العطالة',
  `stop_date` date NOT NULL,
  `shift` enum('day','night') NOT NULL,
  `equipment_id` int(11) DEFAULT NULL,
  `site_id` int(11) DEFAULT NULL,
  `project_id` int(11) DEFAULT NULL,
  `ops_state` varchar(32) NOT NULL DEFAULT '' COMMENT 'من مفردات unit_time_log.ops_state',
  `hours` decimal(8,2) NOT NULL DEFAULT 0.00,
  `resp_party` varchar(24) NOT NULL DEFAULT '',
  `obligation_type` varchar(32) NOT NULL DEFAULT '',
  `billable` tinyint(1) NOT NULL DEFAULT 0,
  `authority` enum('unit_time_log','timesheet','manual') NOT NULL DEFAULT 'unit_time_log' COMMENT 'السجل الحاكم للواقعة - والباقي مرآة',
  `authority_rule` varchar(48) NOT NULL DEFAULT '',
  `authority_ref` varchar(64) NOT NULL DEFAULT '',
  `decision` enum('pending','classified','attributed','disputed','closed') NOT NULL DEFAULT 'pending',
  `decided_by` int(11) DEFAULT NULL,
  `decided_at` datetime DEFAULT NULL,
  `sla_due_at` datetime DEFAULT NULL COMMENT 'المهلة - كيان مستقل بمهلة',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `stop_code` varchar(60) DEFAULT NULL COMMENT 'رقم القرار',
  `reason_tree_ref` varchar(255) DEFAULT NULL COMMENT 'سبب التصنيف من الشجرة ◄',
  `billing_effect` varchar(255) DEFAULT NULL COMMENT 'أثر الفوترة ◄',
  `contract_unit_effect` varchar(80) DEFAULT NULL COMMENT 'أثر الوحدة التعاقدية ◄',
  `decision_doc` varchar(500) DEFAULT NULL COMMENT 'مستند القرار',
  `ops_endorsement` varchar(255) DEFAULT NULL COMMENT 'مصادقة التشغيل ◄',
  `reviewer` varchar(255) DEFAULT NULL COMMENT 'المراجع',
  `approved_by` int(11) DEFAULT NULL COMMENT 'المعتمِد',
  `approved_at` datetime DEFAULT NULL COMMENT 'تاريخ الاعتماد',
  `data_state` varchar(255) DEFAULT NULL COMMENT 'حالة البيانات ▼',
  `src_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع المصدر',
  `decision_no` varchar(500) DEFAULT NULL COMMENT 'رقم القرار',
  `event_date` date DEFAULT NULL COMMENT 'تاريخ الواقعة',
  `stop_period_ref` decimal(12,2) DEFAULT NULL COMMENT 'معرّف فترة التوقف ◄',
  `stop_reason_ref` decimal(12,2) DEFAULT NULL COMMENT 'سبب التوقف ◄',
  `accumulated_stop_hours` decimal(12,2) DEFAULT NULL COMMENT 'ساعات التوقف المتراكمة ◄',
  `mandatory_sla` varchar(80) DEFAULT NULL COMMENT 'المهلة الإلزامية ◄',
  `sla_elapsed` date DEFAULT NULL COMMENT 'انقضت المهلة؟ ◄',
  `decision_reason` varchar(500) DEFAULT NULL COMMENT 'مبرر القرار',
  `readiness_effect` varchar(500) DEFAULT NULL COMMENT 'أثر القرار على الجاهزية ▼',
  `decision_effective_date` date DEFAULT NULL COMMENT 'تاريخ نفاذ القرار',
  `decision_state` varchar(500) DEFAULT NULL COMMENT 'حالة القرار ▼',
  `created_by` int(11) DEFAULT NULL COMMENT 'المُنشئ',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_occurrence` (`occurrence_key`),
  KEY `ix_day` (`company_id`,`stop_date`,`shift`),
  KEY `ix_decision` (`decision`),
  CONSTRAINT `chk_stop_decided` CHECK (`decision` = 'pending' or `decided_by` is not null and `decided_at` is not null)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='REPAIR01 W04 - السجل الواحد لواقعة التوقف بمفتاح عطالة فريد';

-- ── Table: ops_stop_source ──
CREATE TABLE `ops_stop_source` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL COMMENT 'DEC-OPEN-03 - لا قراءة سجل بلا كيان قانوني',
  `occurrence_key` char(40) NOT NULL,
  `register_name` enum('unit_time_log','timesheet') NOT NULL,
  `source_ref` varchar(64) NOT NULL DEFAULT '' COMMENT 'مفتاح الصف في سجله',
  `role` enum('AUTHORITY','MIRROR') NOT NULL DEFAULT 'MIRROR',
  `hours_read` decimal(8,2) NOT NULL DEFAULT 0.00,
  `variance_hours` decimal(8,2) NOT NULL DEFAULT 0.00,
  `variance_rule` varchar(48) NOT NULL DEFAULT '',
  `variance_note` varchar(255) NOT NULL DEFAULT '',
  `measured_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_occ_register` (`occurrence_key`,`register_name`),
  KEY `ix_role` (`role`),
  KEY `ix_company` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='REPAIR01 W04 - قراءة كل سجل مصدر للواقعة نفسها بفارقها المسجل';

-- ── Table: org_assignment_types ──
CREATE TABLE `org_assignment_types` (
  `type_code` varchar(40) NOT NULL,
  `name_ar` varchar(190) NOT NULL,
  `level` enum('central','site') NOT NULL,
  `default_capabilities_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`default_capabilities_json`)),
  `requires_functional_line` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'الموقعيُّ كلُّه =1: خطّان تشغيليٌّ وفنيٌّ لا خطٌّ واحد (§2⑦)',
  `is_unit_head` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'نوعٌ يجعل صاحبَه رأسَ وحدته — يغذي اشتقاق v_org_unit_heads',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`type_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ORG-01 §7: أنواعُ التكليف — يُضاف نوعٌ جديدٌ بصفٍّ لا بتعديل برمجة';

-- ── Table: org_assignments ──
CREATE TABLE `org_assignments` (
  `asg_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `person_id` int(11) NOT NULL COMMENT 'users.id — كنمط signing_authorities.person_id',
  `assignment_type_code` varchar(40) NOT NULL,
  `org_unit_id` int(10) unsigned NOT NULL,
  `scope_type` enum('project','site','site_group') NOT NULL,
  `scope_id` int(11) NOT NULL COMMENT 'المشروعُ أو الموقعُ أو مجموعةُ المواقع — ولا تكليفَ مفتوحُ النطاق',
  `valid_from` date NOT NULL,
  `valid_to` date NOT NULL COMMENT 'إلزاميٌّ — لا تكليفَ مفتوحُ المدة، وتمديدُه قرارٌ جديد',
  `decided_by_person_id` int(11) NOT NULL COMMENT 'مصدرُ القرار: مديرُ التشغيل أو المديرُ التنفيذي',
  `decision_ref` varchar(120) DEFAULT NULL,
  `deputy_person_id` int(11) DEFAULT NULL COMMENT 'النائبُ المعتمَد — ولا نيابةَ شفويةٌ ولا مفتوحةُ المدة',
  `state` enum('active','suspended','ended') NOT NULL DEFAULT 'active',
  `active_site_mgr_key` varchar(80) GENERATED ALWAYS AS (if(`assignment_type_code` = _utf8mb4'site_movement_mgr' and `state` = _utf8mb4'active',concat(`company_id`,_utf8mb4':',`scope_type`,_utf8mb4':',`scope_id`),NULL)) STORED COMMENT 'حيلةُ الفريد المشروط: NULL لغير مدير الحركة النشط — فينتج «واحدٌ نشطٌ لكل موقع»',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`asg_id`),
  UNIQUE KEY `uq_asg_natural` (`company_id`,`assignment_type_code`,`scope_type`,`scope_id`,`valid_from`),
  UNIQUE KEY `uq_one_active_movement_mgr` (`active_site_mgr_key`),
  KEY `idx_asg_person` (`person_id`,`state`),
  KEY `idx_asg_scope` (`company_id`,`scope_type`,`scope_id`,`state`),
  KEY `idx_asg_validity` (`state`,`valid_to`),
  KEY `fk_asg_type` (`assignment_type_code`),
  KEY `fk_asg_unit` (`org_unit_id`),
  CONSTRAINT `fk_asg_type` FOREIGN KEY (`assignment_type_code`) REFERENCES `org_assignment_types` (`type_code`),
  CONSTRAINT `fk_asg_unit` FOREIGN KEY (`org_unit_id`) REFERENCES `org_units` (`unit_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ORG-01 §2/§7: التكليفُ سجلٌّ تنظيميٌّ بنطاقٍ ومدةٍ وسقفٍ ونائبٍ — ويسقط آليًّا بانتهائه';

-- ── Table: org_structure_versions ──
CREATE TABLE `org_structure_versions` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `version_code` varchar(16) NOT NULL COMMENT 'ORG-000001',
  `change_kind` enum('إنشاء وحدة','تعديل وحدة','تعطيل وحدة','نقل تبعية','تعديل مسمى','رجوع لنسخة') NOT NULL,
  `unit_id` int(11) DEFAULT NULL COMMENT 'org_units.unit_id المتأثرة',
  `decision_ref` varchar(64) NOT NULL COMMENT 'قرارُ الإنشاء أو التعديل — مرجعيٌّ إلزامي',
  `effective_date` date NOT NULL,
  `snapshot_json` mediumtext NOT NULL COMMENT 'لقطةُ الهيكل قبل التغيير — أساسُ الرجوع',
  `change_json` text DEFAULT NULL COMMENT 'ما تغيّر بالضبط — قبلَ وبعد',
  `assignments_review_note` varchar(255) NOT NULL DEFAULT '' COMMENT 'التكليفاتُ القائمةُ تُراجَع — نتيجةُ المراجعة',
  `state` enum('applied','reverted') NOT NULL DEFAULT 'applied',
  `reverted_by_ref` varchar(16) NOT NULL DEFAULT '' COMMENT 'العكس: نسخةُ الرجوع التي نقضتها',
  `changed_by` int(11) NOT NULL COMMENT '§9-1 المُنشئ',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `approved_by` int(11) DEFAULT NULL COMMENT '§9-1 المعتمِد',
  `approved_at` datetime DEFAULT NULL,
  `authority_ref` varchar(120) NOT NULL DEFAULT '',
  `parent_ref` varchar(32) NOT NULL DEFAULT '' COMMENT 'النسخةُ السابقة في السلسلة',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_orgv_code` (`company_id`,`version_code`),
  KEY `ix_orgv_unit` (`company_id`,`unit_id`,`effective_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='M-14 org.change: كلُّ تغييرِ هيكلٍ نسخةٌ بلقطتها وقرارها — والرجوعُ بقرارٍ لا محوًا';

-- ── Table: org_units ──
CREATE TABLE `org_units` (
  `unit_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `unit_code` varchar(40) NOT NULL COMMENT 'رمزٌ ثابتٌ للوحدة تُخاطَب به برمجيًّا',
  `name_ar` varchar(190) NOT NULL,
  `layer` enum('operational','parallel','oversight') NOT NULL COMMENT 'الطبقة: تشغيليةٌ تحت مدير التشغيل · موازيةٌ تحت التنفيذي · رقابية',
  `parent_unit_id` int(10) unsigned DEFAULT NULL,
  `owner_doc` varchar(120) DEFAULT NULL COMMENT 'الوثيقةُ الحاكمة للوحدة',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`unit_id`),
  UNIQUE KEY `uq_org_units_scope` (`company_id`,`unit_code`),
  KEY `idx_org_units_parent` (`parent_unit_id`),
  CONSTRAINT `fk_org_units_parent` FOREIGN KEY (`parent_unit_id`) REFERENCES `org_units` (`unit_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ORG-01 §7: الوحداتُ التنظيمية — head_person_id مشتقٌّ من org_assignments (v_org_unit_heads) ولا يُكتب';

-- ── Table: ownership_access_grants ──
CREATE TABLE `ownership_access_grants` (
  `grant_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `person_id` int(11) NOT NULL,
  `permission_code` enum('ownership.owner_view','ownership.finance_terms','ownership.purchase_value') NOT NULL,
  `reason` varchar(255) DEFAULT NULL,
  `valid_from` date DEFAULT NULL,
  `valid_to` date DEFAULT NULL,
  `granted_by` int(11) NOT NULL,
  `state` enum('active','revoked') NOT NULL DEFAULT 'active',
  `revoked_by` int(11) DEFAULT NULL,
  `revoked_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`grant_id`),
  KEY `ix_oag_person` (`company_id`,`person_id`,`permission_code`,`state`),
  CONSTRAINT `ck_oag_value_strict` CHECK (`permission_code` <> _utf8mb4'ownership.purchase_value' or `reason` is not null and `valid_from` is not null and `valid_to` is not null)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: party_contacts ──
CREATE TABLE `party_contacts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `party_type` enum('client','supplier') NOT NULL,
  `party_ref` int(10) unsigned NOT NULL,
  `contact_name` varchar(190) NOT NULL,
  `job_title` varchar(120) DEFAULT NULL,
  `phone` varchar(40) DEFAULT NULL,
  `phone_alt` varchar(40) DEFAULT NULL,
  `email` varchar(190) DEFAULT NULL,
  `is_primary` tinyint(1) NOT NULL DEFAULT 0,
  `is_signatory` tinyint(1) NOT NULL DEFAULT 0,
  `authority_kind` enum('تفويضٌ عام','تفويضٌ خاص','سلطةٌ أصلية','—') NOT NULL DEFAULT '—',
  `authority_scope` varchar(300) DEFAULT NULL,
  `authority_doc_ref` varchar(120) DEFAULT NULL,
  `authority_from` date DEFAULT NULL,
  `authority_to` date DEFAULT NULL,
  `state` enum('نشط','منتهٍ','ملغى') NOT NULL DEFAULT 'نشط',
  `note` varchar(300) DEFAULT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(10) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pc_party_name` (`company_id`,`party_type`,`party_ref`,`contact_name`),
  KEY `ix_pc_party` (`company_id`,`party_type`,`party_ref`,`is_deleted`),
  KEY `ix_pc_signatory` (`company_id`,`is_signatory`,`state`),
  CONSTRAINT `chk_pc_authority` CHECK (`is_signatory` = 0 or `authority_kind` <> '—' and `authority_scope` is not null and char_length(`authority_scope`) >= 3 and `authority_doc_ref` is not null and char_length(`authority_doc_ref`) >= 2),
  CONSTRAINT `chk_pc_window` CHECK (`authority_from` is null or `authority_to` is null or `authority_to` >= `authority_from`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: pay_components ──
CREATE TABLE `pay_components` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL COMMENT 'عزلٌ مباشر (سابقة claim_lines: يُقرأ مجمَّعًا بلا JOIN أبيه)',
  `contract_id` int(11) NOT NULL,
  `component_type` enum('basic','cost_of_living','housing','transport','food','site','hazard','work_nature','shift','night','responsibility','supervision','assignment','travel','mission','communication','medical','fixed_bonus','other_allowance','custom') NOT NULL COMMENT 'قائمةُ §3.2 العشرون نصًّا — لاتينيةً (گوتشا الترميز) والتعريبُ في الخدمة',
  `calc_method` enum('fixed_amount','pct_reference','pct_basic','pct_gross','per_day','per_shift','per_hour','per_unit','tiers','custom_formula') NOT NULL COMMENT 'طرقُ الاحتساب العشر — §3.2',
  `value` decimal(18,2) DEFAULT NULL,
  `rate` decimal(12,2) DEFAULT NULL,
  `in_insurance` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'يدخل التأمينات؟',
  `in_tax` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'يدخل الضريبة؟',
  `in_leave_pay` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'يدخل أجرَ الإجازة؟',
  `in_eos` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'يدخل نهايةَ الخدمة؟',
  `in_hour_base` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'يدخل حسابَ الساعة؟',
  `in_overtime` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'يدخل العملَ الإضافي؟',
  `in_incentive_base` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'يدخل وعاءَ الحافز؟',
  `is_variable` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'ثابتٌ أم متغير',
  `periodicity` enum('monthly','periodic','once') NOT NULL DEFAULT 'monthly',
  `cost_bearer_type` enum('project','client_contract','dept','company') DEFAULT NULL COMMENT 'إشارةُ المكوّن المفردة — شجرةُ Σ=100 (cost_bearers) بيتُها الشريحة ④',
  `cost_bearer_id` int(11) DEFAULT NULL,
  `cost_center_id` int(11) DEFAULT NULL,
  `valid_from` date DEFAULT NULL,
  `valid_to` date DEFAULT NULL,
  `state` enum('active','replaced','ended') NOT NULL DEFAULT 'active' COMMENT 'حالاتُ سياسة الأجر — التصريحُ الكامل مع E-24/H-10',
  `created_by` int(11) DEFAULT NULL,
  `is_deleted` tinyint(4) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_pc_contract` (`contract_id`),
  KEY `ix_pc_company` (`company_id`),
  KEY `fk_pc_cost_center` (`cost_center_id`),
  CONSTRAINT `fk_pc_contract` FOREIGN KEY (`contract_id`) REFERENCES `employee_contracts` (`id`),
  CONSTRAINT `fk_pc_cost_center` FOREIGN KEY (`cost_center_id`) REFERENCES `fin_cost_centers` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: pay_models ──
CREATE TABLE `pay_models` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(32) NOT NULL,
  `label_ar` varchar(64) NOT NULL,
  `calc_path` enum('time','production','mixed','other') NOT NULL DEFAULT 'other',
  `is_active` tinyint(4) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pay_model_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: payroll_absence_types ──
CREATE TABLE `payroll_absence_types` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `event_type` varchar(40) NOT NULL COMMENT 'يطابق worker_leave_absence.event_type حرفيًّا',
  `code` varchar(4) DEFAULT NULL COMMENT 'WRK-01 §3: رمز الحالة (1·0·10·11·ST·S·M·A1·A2·EM·UP)',
  `deducts` tinyint(4) NOT NULL DEFAULT 0 COMMENT '1 = غيابٌ يُخصم · 0 = إجازةٌ مدفوعة',
  `deduct_percent` decimal(5,2) NOT NULL DEFAULT 100.00 COMMENT 'نسبةُ الخصم من أجر اليوم',
  `label_ar` varchar(80) DEFAULT NULL,
  `active` tinyint(4) NOT NULL DEFAULT 1,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `pay_effect` enum('full','none','per_contract','per_policy','stops_accrual','per_hr','deduct_daily') DEFAULT NULL COMMENT 'أثر الراتب',
  `incentive_base` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'يدخل أساس الحافز؟',
  `presence` enum('site','off','transit','mission') DEFAULT NULL COMMENT 'التواجد',
  `billable` enum('yes','no','by_attribution') DEFAULT NULL COMMENT 'الفوترة — ST بالإسناد',
  `supplier_due` enum('yes','no','by_attribution','per_contract') DEFAULT NULL COMMENT 'استحقاق المورد',
  `conduct_violation` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'A2: مخالفة سلوكية تُسجَّل — أثر ثانٍ مستقل',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_absence_type` (`company_id`,`event_type`),
  UNIQUE KEY `uq_absence_code` (`company_id`,`code`),
  CONSTRAINT `ck_absence_pct` CHECK (`deduct_percent` >= 0 and `deduct_percent` <= 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: payroll_deductions ──
CREATE TABLE `payroll_deductions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `run_id` int(11) NOT NULL,
  `person_id` int(11) NOT NULL,
  `source_type` enum('advance','on_behalf','penalty','absence','other') NOT NULL,
  `source_id` int(11) NOT NULL COMMENT 'مرجعُ المصدر — 0 مرفوضٌ بالقيد',
  `amount` decimal(18,2) NOT NULL COMMENT 'المخصومُ فعلًا في هذه الدورة (موجبٌ)',
  `requested_amount` decimal(18,2) DEFAULT NULL COMMENT 'القسطُ المستحقُّ قبل حدِّ الحماية',
  `doc_ref` varchar(120) NOT NULL COMMENT '«ولا خصمَ بلا مستند» — إلزاميٌّ بنيويًّا',
  `rescheduled` tinyint(4) NOT NULL DEFAULT 0 COMMENT '1 = قُصّ بحدِّ الحماية ورُحّل باقيه',
  `note` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_payroll_deduction` (`run_id`,`person_id`,`source_type`,`source_id`),
  KEY `ix_deduction_run` (`run_id`),
  CONSTRAINT `fk_deduction_run` FOREIGN KEY (`run_id`) REFERENCES `payroll_runs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ck_deduction_amount` CHECK (`amount` >= 0),
  CONSTRAINT `ck_deduction_doc` CHECK (char_length(trim(`doc_ref`)) > 0),
  CONSTRAINT `ck_deduction_src` CHECK (`source_id` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: payroll_lines ──
CREATE TABLE `payroll_lines` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `run_id` int(11) NOT NULL,
  `person_id` int(11) NOT NULL COMMENT 'employees.id — «العقدُ يشير إلى سجل الأشخاص»',
  `contract_id` int(11) NOT NULL,
  `snapshot_id` int(11) NOT NULL COMMENT '**البوابة**: لا سطرَ احتسابٍ بلا لقطته (ENT-01 §2)',
  `path` enum('institutional','project') NOT NULL DEFAULT 'institutional' COMMENT 'مسارا §3',
  `component_ref` varchar(64) NOT NULL COMMENT 'component#N أو rule#N — مرجعُه داخل اللقطة',
  `line_kind` enum('component','overtime','absence_deduction','production','incentive') NOT NULL DEFAULT 'component' COMMENT 'نوعُ السطر — production/incentive مولَّدا المسار الإنتاجي (H-09-③)',
  `component_type` varchar(40) DEFAULT NULL,
  `calc_method` varchar(40) DEFAULT NULL,
  `qty` decimal(18,2) DEFAULT NULL,
  `entitled_days` decimal(6,2) DEFAULT NULL COMMENT 'أيامُ الاستحقاق في الفترة',
  `period_days` decimal(6,2) DEFAULT NULL COMMENT 'أيامُ الفترة كاملةً',
  `rate` decimal(18,4) DEFAULT NULL,
  `amount` decimal(18,2) DEFAULT NULL COMMENT 'NULL = لم يُحتسب بعد (بحالته وسببه) — لا صفرَ ملفَّق',
  `unit_record_id` int(11) DEFAULT NULL COMMENT 'للمسار التشغيلي — الشريحة ③',
  `bearer_type` varchar(20) DEFAULT NULL COMMENT 'جهةُ التحمّل من اللقطة',
  `bearer_id` int(11) DEFAULT NULL,
  `percent` decimal(6,2) DEFAULT NULL COMMENT 'نسبةُ الجهة — Σ لكل مكوّنٍ = 100',
  `calc_state` enum('computed','pending_slice','blocked') NOT NULL DEFAULT 'computed',
  `note` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_payroll_line_run_person` (`run_id`,`person_id`),
  KEY `ix_payroll_line_snapshot` (`snapshot_id`),
  CONSTRAINT `fk_payroll_line_run` FOREIGN KEY (`run_id`) REFERENCES `payroll_runs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_payroll_line_snapshot` FOREIGN KEY (`snapshot_id`) REFERENCES `contract_snapshots` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: payroll_run_blocks ──
CREATE TABLE `payroll_run_blocks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `run_id` int(11) NOT NULL,
  `contract_id` int(11) NOT NULL,
  `person_id` int(11) DEFAULT NULL,
  `kind` enum('excluded','blocked') NOT NULL DEFAULT 'blocked' COMMENT 'excluded = خارج النطاق بسببٍ مكتوب · blocked = عطبٌ يوقف الدورة',
  `block_code` varchar(40) NOT NULL COMMENT 'snapshot_missing · contract_not_readable · bearer_sum_invalid …',
  `block_http` smallint(6) NOT NULL DEFAULT 422,
  `reason` varchar(255) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_payroll_block` (`run_id`,`contract_id`,`block_code`),
  KEY `ix_payroll_block_run` (`run_id`),
  CONSTRAINT `fk_payroll_block_run` FOREIGN KEY (`run_id`) REFERENCES `payroll_runs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: payroll_runs ──
CREATE TABLE `payroll_runs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `period_from` date NOT NULL,
  `period_to` date NOT NULL,
  `category_filter` varchar(32) NOT NULL DEFAULT 'all' COMMENT 'فئةُ CON-01 §2 أو all — جزءٌ من المفتاح الفريد فلا تُخلط الدورات',
  `project_filter` int(11) DEFAULT NULL,
  `state` enum('Open','Calculated','Blocked','Review','Approved','Paid','Closed') NOT NULL DEFAULT 'Open' COMMENT 'دورةُ ENT-01 §8 السباعية نصًّا',
  `persons_count` int(11) NOT NULL DEFAULT 0,
  `lines_count` int(11) NOT NULL DEFAULT 0,
  `blocked_count` int(11) NOT NULL DEFAULT 0,
  `gross_total` decimal(18,2) DEFAULT NULL COMMENT 'NULL = لم يكتمل الاحتساب (الشريحتان ②③)',
  `currency` varchar(8) DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  `note` varchar(255) DEFAULT NULL,
  `is_deleted` tinyint(4) NOT NULL DEFAULT 0,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_payroll_run_key` (`company_id`,`period_from`,`period_to`,`category_filter`),
  KEY `ix_payroll_run_state` (`company_id`,`state`),
  CONSTRAINT `ck_payroll_run_period` CHECK (`period_to` >= `period_from`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: payroll_settings ──
CREATE TABLE `payroll_settings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `protection_percent` decimal(5,2) DEFAULT NULL COMMENT 'أدنى نسبةٍ من الإجمالي تبقى للعامل — NULL = لم يُقرَّر بعد',
  `note` varchar(255) DEFAULT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_payroll_settings_co` (`company_id`),
  CONSTRAINT `ck_protection_pct` CHECK (`protection_percent` is null or `protection_percent` >= 0 and `protection_percent` <= 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: payroll_time_inputs ──
CREATE TABLE `payroll_time_inputs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `run_id` int(11) NOT NULL,
  `person_id` int(11) NOT NULL,
  `kind` enum('overtime_hours','unpaid_days','night_shifts') NOT NULL,
  `qty` decimal(12,2) NOT NULL,
  `doc_ref` varchar(120) NOT NULL COMMENT 'مرجعُ المستند — إلزاميٌّ بنيويًّا',
  `note` varchar(255) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_time_input` (`run_id`,`person_id`,`kind`),
  KEY `ix_time_input_co` (`company_id`,`run_id`),
  CONSTRAINT `fk_time_input_run` FOREIGN KEY (`run_id`) REFERENCES `payroll_runs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ck_time_input_doc` CHECK (char_length(trim(`doc_ref`)) > 0),
  CONSTRAINT `ck_time_input_qty` CHECK (`qty` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: perm_shadow_diffs ──
CREATE TABLE `perm_shadow_diffs` (
  `diff_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `module_code` varchar(120) NOT NULL,
  `action` varchar(40) NOT NULL,
  `permission_code` varchar(120) NOT NULL,
  `scope_rule` varchar(120) NOT NULL,
  `legacy_decision` tinyint(1) NOT NULL,
  `derived_decision` tinyint(1) NOT NULL,
  `detail` varchar(255) DEFAULT NULL,
  `resolved` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'حُقق وأُصلح سببه (قالب أو تحويل)',
  `at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`diff_id`),
  KEY `idx_psd_at` (`at`),
  KEY `idx_psd_user` (`company_id`,`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SEC-01 §13 المرحلة ③: كل فرق سماح/منع/نطاق/سقف صف — والحد صفر لا نسبة';

-- ── Table: permission_approval_steps ──
CREATE TABLE `permission_approval_steps` (
  `st_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `req_id` int(10) unsigned NOT NULL,
  `seq_no` int(11) NOT NULL,
  `approver_rule` enum('hr','functional_owner','requester_department_manager','finance_owner_if_financial','security_manager','executive') NOT NULL COMMENT 'قاعدة ديناميكية لا دور ثابت — functional_owner يُحل من ORG-01 بحسب المجال والنطاق والتاريخ',
  `mandatory` tinyint(1) NOT NULL DEFAULT 1,
  `approver_person_id` int(11) DEFAULT NULL COMMENT 'يُحل لحظة الفتح',
  `auth_id` int(10) unsigned DEFAULT NULL,
  `decision` enum('approve','reject') DEFAULT NULL,
  `reason` varchar(255) DEFAULT NULL,
  `at` datetime DEFAULT NULL,
  PRIMARY KEY (`st_id`),
  UNIQUE KEY `uq_step` (`req_id`,`seq_no`),
  CONSTRAINT `fk_step_req` FOREIGN KEY (`req_id`) REFERENCES `permission_change_requests` (`req_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SEC-01 §12: لا تُفتح خطوة قبل سابقتها — يحرسه PermissionChangeWorkflow';

-- ── Table: permission_audit_events ──
CREATE TABLE `permission_audit_events` (
  `ev_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `event_type` enum('granted','elevated','reduced','revoked','expired','suspended','break_glass') NOT NULL,
  `person_id` int(11) NOT NULL,
  `permission_code` varchar(120) NOT NULL,
  `scope_rule` varchar(120) DEFAULT NULL,
  `before_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`before_json`)),
  `after_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`after_json`)),
  `requested_by` int(11) DEFAULT NULL,
  `approved_by` int(11) DEFAULT NULL,
  `executed_by` int(11) DEFAULT NULL,
  `request_ref` varchar(120) DEFAULT NULL,
  `reason` varchar(255) DEFAULT NULL,
  `source` enum('template','assignment','exception','grant','break_glass') NOT NULL,
  `founding_mode` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'وسم أفعال التأسيس §7-④',
  `at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`ev_id`),
  KEY `idx_pae_person` (`company_id`,`person_id`,`at`),
  KEY `idx_pae_type` (`event_type`,`at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SEC-01 §12: لا يُعدَّل ولا يُحذف — ولا يُخلط بمراجعة المدير الدورية';

-- ── Table: permission_change_requests ──
CREATE TABLE `permission_change_requests` (
  `req_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `person_id` int(11) NOT NULL,
  `change_kind` enum('within_role','supervisor','section_mgr','dept_mgr_or_high') NOT NULL,
  `from_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`from_json`)),
  `to_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`to_json`)),
  `reason` varchar(255) NOT NULL,
  `doc_ref` varchar(120) DEFAULT NULL,
  `risk_level` enum('low','medium','high') NOT NULL COMMENT 'محسوب من النوع',
  `state` enum('draft','pending','approved','rejected','applied') NOT NULL DEFAULT 'draft',
  `created_by` int(11) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`req_id`),
  KEY `idx_pcr_state` (`company_id`,`state`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SEC-01 §8: الموافقات بدرجة المخاطرة لا بمسار واحد';

-- ── Table: permission_exceptions ──
CREATE TABLE `permission_exceptions` (
  `ex_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `person_id` int(11) NOT NULL,
  `permission_code` varchar(120) NOT NULL,
  `scope_rule` varchar(120) NOT NULL,
  `effect` enum('grant','deny') NOT NULL DEFAULT 'grant',
  `reason` varchar(255) NOT NULL,
  `valid_from` datetime NOT NULL,
  `valid_to` datetime NOT NULL COMMENT 'إلزامي — ويسقط آليًّا',
  `is_break_glass` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'كسر الزجاج: مدة ≤ 24 ساعة بمراجعة لاحقة إلزامية',
  `approvals_ref` varchar(120) DEFAULT NULL,
  `state` enum('active','expired','revoked') NOT NULL DEFAULT 'active',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`ex_id`),
  KEY `idx_ex_person` (`company_id`,`person_id`,`state`),
  KEY `idx_ex_expiry` (`state`,`valid_to`),
  CONSTRAINT `chk_bg_24h` CHECK (`is_break_glass` = 0 or timestampdiff(HOUR,`valid_from`,`valid_to`) <= 24)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: permission_review_cycles ──
CREATE TABLE `permission_review_cycles` (
  `cycle_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `org_unit_id` int(10) unsigned NOT NULL,
  `period` varchar(10) NOT NULL COMMENT 'مثال 2026-H2',
  `manager_person_id` int(11) NOT NULL,
  `due_at` date NOT NULL,
  `state` enum('open','signed','escalated') NOT NULL DEFAULT 'open',
  `signed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`cycle_id`),
  UNIQUE KEY `uq_prc` (`org_unit_id`,`period`),
  KEY `idx_prc_due` (`state`,`due_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SEC-01 §10⑥: ما لم يُوقَّع خلال مهلته يُصعَّد للإدارة العامة';

-- ── Table: permission_review_lines ──
CREATE TABLE `permission_review_lines` (
  `line_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `cycle_id` int(10) unsigned NOT NULL,
  `person_id` int(11) NOT NULL,
  `permission_code` varchar(120) NOT NULL,
  `scope_rule` varchar(120) DEFAULT NULL,
  `decision` enum('confirm','reduce','revoke') DEFAULT NULL,
  `reason` varchar(255) DEFAULT NULL,
  `decided_at` datetime DEFAULT NULL,
  PRIMARY KEY (`line_id`),
  KEY `idx_prl_cycle` (`cycle_id`,`person_id`),
  CONSTRAINT `fk_prl_cycle` FOREIGN KEY (`cycle_id`) REFERENCES `permission_review_cycles` (`cycle_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SEC-01 §12: سطر لكل (موظف × صلاحية) — Insert-only';

-- ── Table: permission_template_versions ──
CREATE TABLE `permission_template_versions` (
  `ver_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `tpl_id` int(10) unsigned NOT NULL,
  `version` int(11) NOT NULL,
  `effective_from` date DEFAULT NULL,
  `effective_to` date DEFAULT NULL,
  `state` enum('draft','tested','published','superseded') NOT NULL DEFAULT 'draft',
  `approval_ref` varchar(120) DEFAULT NULL,
  `change_reason` varchar(255) DEFAULT NULL,
  `impact_preview_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'أثر التغيير قبل النشر: كم مستخدمًا وأي صلاحية' CHECK (json_valid(`impact_preview_json`)),
  `superseded_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`ver_id`),
  UNIQUE KEY `uq_ver` (`tpl_id`,`version`),
  CONSTRAINT `fk_ver_tpl` FOREIGN KEY (`tpl_id`) REFERENCES `permission_templates` (`tpl_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SEC-01 §4⑥: لا يُعدل إصدار نافذ بأثر رجعي — النشر إصدار جديد بسريان مستقبلي';

-- ── Table: permission_templates ──
CREATE TABLE `permission_templates` (
  `tpl_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `tpl_kind` enum('relation','family','level','title','assignment') NOT NULL,
  `key_code` varchar(60) NOT NULL,
  `is_ceiling` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'لقوالب العلاقة: سقف لا أرضية',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`tpl_id`),
  UNIQUE KEY `uq_tpl_kind_key` (`tpl_kind`,`key_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SEC-01 §4: القالب جدول يُعدل بقرار لا كود يُبرمج';

-- ── Table: permit_approval_actions ──
CREATE TABLE `permit_approval_actions` (
  `act_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `req_id` int(10) unsigned NOT NULL,
  `rq_id` int(10) unsigned NOT NULL,
  `approver_person_id` int(11) NOT NULL,
  `auth_id` int(10) unsigned DEFAULT NULL COMMENT 'مرجعُ التفويض signing_authorities — LEG-01 §4',
  `decision` enum('approve','reject') NOT NULL,
  `reason` varchar(255) DEFAULT NULL,
  `at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`act_id`),
  UNIQUE KEY `uq_act_step` (`req_id`,`rq_id`),
  KEY `fk_permit_act_rq` (`rq_id`),
  CONSTRAINT `fk_permit_act_req` FOREIGN KEY (`req_id`) REFERENCES `permit_requests` (`req_id`),
  CONSTRAINT `fk_permit_act_rq` FOREIGN KEY (`rq_id`) REFERENCES `permit_required_approvals` (`rq_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ORG-01 §7: قيدُ التسلسل «لا تُفتح خطوةٌ قبل اكتمال ما قبلها» يحرسه PermitGate بـ409';

-- ── Table: permit_requests ──
CREATE TABLE `permit_requests` (
  `req_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `permit_type_code` varchar(40) NOT NULL,
  `subject_ref` varchar(120) NOT NULL COMMENT 'مرجعُ الموضوع: معدةٌ أو مادةٌ أو شخصٌ أو فني',
  `site_id` int(11) NOT NULL,
  `requested_by` int(11) NOT NULL,
  `reason` varchar(255) DEFAULT NULL,
  `doc_ref` varchar(120) DEFAULT NULL,
  `state` enum('draft','pending','approved','rejected','expired','used') NOT NULL DEFAULT 'draft',
  `valid_until` datetime DEFAULT NULL COMMENT 'يُحسب من validity_hours عند اكتمال الموافقات — بساعة القاعدة',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`req_id`),
  KEY `idx_permit_state_site` (`state`,`site_id`),
  KEY `idx_permit_company` (`company_id`,`state`),
  KEY `fk_preq_type` (`permit_type_code`),
  CONSTRAINT `fk_preq_type` FOREIGN KEY (`permit_type_code`) REFERENCES `permit_types` (`permit_type_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ORG-01 §7: طلبُ الإذن — يمرّ بصندوق الاعتماد الجامع بندًا واحدًا لكل موافقٍ في دوره';

-- ── Table: permit_required_approvals ──
CREATE TABLE `permit_required_approvals` (
  `rq_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `permit_type_code` varchar(40) NOT NULL,
  `seq_no` int(11) NOT NULL,
  `approver_role` varchar(60) NOT NULL COMMENT 'المجالُ الوظيفيُّ الموافق — يحلُّه PermitGate من التكليفات النافذة',
  `mandatory` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`rq_id`),
  UNIQUE KEY `uq_rq_seq` (`permit_type_code`,`seq_no`),
  CONSTRAINT `fk_permit_rq_type` FOREIGN KEY (`permit_type_code`) REFERENCES `permit_types` (`permit_type_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ORG-01 §5/§7: مصفوفةُ الموافقات المشتركة — يُقرأ منها من يوافق وبأي ترتيب';

-- ── Table: permit_status_history ──
CREATE TABLE `permit_status_history` (
  `hist_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `req_id` int(10) unsigned NOT NULL,
  `from_state` varchar(20) NOT NULL,
  `to_state` varchar(20) NOT NULL,
  `by_person_id` int(11) NOT NULL,
  `at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`hist_id`),
  KEY `idx_hist_req` (`req_id`,`at`),
  CONSTRAINT `fk_permit_hist_req` FOREIGN KEY (`req_id`) REFERENCES `permit_requests` (`req_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ORG-01 §7: تاريخُ حالات الإذن — للإدراج فقط';

-- ── Table: permit_types ──
CREATE TABLE `permit_types` (
  `permit_type_code` varchar(40) NOT NULL,
  `name_ar` varchar(190) NOT NULL,
  `subject_kind` enum('equipment','material','person','technician') NOT NULL,
  `direction` enum('in','out','activate','deactivate') NOT NULL,
  `validity_hours` int(11) NOT NULL DEFAULT 24,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`permit_type_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ORG-01 §5/§7: الأنواعُ التسعةُ صفوفٌ هنا لا كودًا';

-- ── Table: person_positions ──
CREATE TABLE `person_positions` (
  `p_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `person_id` int(10) unsigned NOT NULL,
  `company_id` int(11) NOT NULL,
  `relation_code` varchar(40) NOT NULL,
  `family_code` varchar(40) NOT NULL COMMENT 'ولا موظف بلا عائلة (DEC-SEC-F)',
  `level_code` varchar(40) NOT NULL,
  `title_code` varchar(40) NOT NULL COMMENT 'job_titles.title_code',
  `org_unit_id` int(10) unsigned DEFAULT NULL,
  `manager_person_id` int(10) unsigned DEFAULT NULL,
  `scope_type` enum('company','department','section','unit','project','site','site_group','shift','own_records') NOT NULL,
  `scope_id` int(11) NOT NULL COMMENT 'قيد: لا صف بلا نطاق — الصلاحية بلا نطاق مرفوضة بنيويًّا',
  `is_primary` tinyint(1) NOT NULL DEFAULT 1,
  `valid_from` date NOT NULL,
  `valid_to` date DEFAULT NULL,
  `state` enum('active','suspended','ended') NOT NULL DEFAULT 'active',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`p_id`),
  UNIQUE KEY `uq_pp_natural` (`person_id`,`title_code`,`scope_type`,`scope_id`,`valid_from`),
  KEY `idx_pp_person` (`person_id`,`state`),
  KEY `idx_pp_company` (`company_id`,`state`),
  KEY `fk_pp_relation` (`relation_code`),
  KEY `fk_pp_family` (`family_code`),
  KEY `fk_pp_level` (`level_code`),
  CONSTRAINT `fk_pp_family` FOREIGN KEY (`family_code`) REFERENCES `hr_dictionaries` (`code`),
  CONSTRAINT `fk_pp_level` FOREIGN KEY (`level_code`) REFERENCES `hr_dictionaries` (`code`),
  CONSTRAINT `fk_pp_person` FOREIGN KEY (`person_id`) REFERENCES `persons` (`person_id`),
  CONSTRAINT `fk_pp_relation` FOREIGN KEY (`relation_code`) REFERENCES `hr_dictionaries` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SEC-01 §12: منع تداخل فترتين لنفس (المسمى×النطاق) يحرسه PositionService — ومركزان مشروعان يبدآن معًا مقبولان';

-- ── Table: person_relationships ──
CREATE TABLE `person_relationships` (
  `rel_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `person_id` int(10) unsigned NOT NULL,
  `company_id` int(11) NOT NULL COMMENT 'الكيان — والعزل يمنع تسرب كيان إلى آخر ولو كان الشخص واحدًا',
  `relation_code` varchar(40) NOT NULL COMMENT 'hr_dictionaries layer=relation',
  `employee_id` int(11) DEFAULT NULL COMMENT 'جسر صفوف employees — تبقى بياناتِ الموظف الإدارية لا الهوية',
  `valid_from` date NOT NULL,
  `valid_to` date DEFAULT NULL COMMENT 'NULL = علاقة قائمة (الدائم) — والمؤقتة بنهاية',
  `state` enum('active','suspended','ended') NOT NULL DEFAULT 'active',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`rel_id`),
  KEY `idx_prel_person` (`person_id`,`state`),
  KEY `idx_prel_company` (`company_id`,`relation_code`,`state`),
  CONSTRAINT `fk_prel_person` FOREIGN KEY (`person_id`) REFERENCES `persons` (`person_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SEC-01 §14②: موظف المورد لا يُنشأ له موظف داخلي وهمي';

-- ── Table: personal_notifications ──
CREATE TABLE `personal_notifications` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `user_id` int(10) unsigned NOT NULL,
  `kind` varchar(24) NOT NULL DEFAULT 'info',
  `title` varchar(300) NOT NULL,
  `body` varchar(600) DEFAULT NULL,
  `link` varchar(300) DEFAULT NULL COMMENT 'رابط الأصل بضغطة واحدة',
  `requires_action` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'WF-06',
  `task_item_id` bigint(20) unsigned DEFAULT NULL COMMENT 'المهمة المولَّدة إن تطلب فعلًا — AC-WFM-08',
  `read_at` datetime DEFAULT NULL,
  `expires_at` datetime DEFAULT NULL,
  `created_by` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_pn_user` (`company_id`,`user_id`,`read_at`),
  KEY `ix_pn_action` (`requires_action`,`task_item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='WFM: التنبيه إحاطة — ولا يصير مهمة إلا بفعل مطلوب';

-- ── Table: persons ──
CREATE TABLE `persons` (
  `person_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) DEFAULT NULL COMMENT 'DEC-OPEN-03 - لا صف في كيان أم بلا كيان قانوني',
  `employee_id` int(11) DEFAULT NULL COMMENT 'REPAIR01 W03 - Person_ID المالك employees.id',
  `person_class` enum('WORKFORCE','IDENTITY_ONLY','UNRESOLVED') NOT NULL DEFAULT 'UNRESOLVED' COMMENT 'WORKFORCE يلزمه employee_id - IDENTITY_ONLY صف هوية معلن',
  `full_name` varchar(190) NOT NULL,
  `national_ref` varchar(60) DEFAULT NULL COMMENT 'مرجع هوية — معرّف دائم لا يُعاد استعماله',
  `contact_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`contact_json`)),
  `docs_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`docs_json`)),
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `w3_link_rule` varchar(48) NOT NULL DEFAULT '' COMMENT 'قاعدة الوصل - لا قيمة بلا قاعدة',
  PRIMARY KEY (`person_id`),
  UNIQUE KEY `uq_persons_national` (`national_ref`),
  UNIQUE KEY `uq_employee` (`employee_id`),
  KEY `ix_company` (`company_id`),
  KEY `ix_class` (`person_class`),
  CONSTRAINT `chk_persons_w3_company` CHECK (`active` <> 1 or `company_id` is not null and `company_id` <> 0),
  CONSTRAINT `chk_persons_w3_master_key` CHECK (`active` <> 1 or `person_class` <> 'WORKFORCE' or `employee_id` is not null and `employee_id` <> 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SEC-01 §14: سجل الإنسان — حساب واحد عبر المنصة والصفات متعددة';

-- ── Table: policy_rules ──
CREATE TABLE `policy_rules` (
  `rule_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `policy_id` int(10) unsigned NOT NULL,
  `rule_kind` varchar(60) NOT NULL,
  `formula_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`formula_json`)),
  `threshold` decimal(18,4) DEFAULT NULL,
  `cap` decimal(18,4) DEFAULT NULL,
  `periodicity` enum('daily','weekly','monthly') DEFAULT NULL,
  `valid_from` date DEFAULT NULL,
  `valid_to` date DEFAULT NULL,
  PRIMARY KEY (`rule_id`),
  KEY `ix_pr_policy` (`policy_id`,`rule_kind`),
  CONSTRAINT `fk_pr_policy` FOREIGN KEY (`policy_id`) REFERENCES `dept_policies` (`policy_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='POL-01 §2-②: قواعد الإدارة بمعادلاتها وسقوفها';

-- ── Table: portal_activity_log ──
CREATE TABLE `portal_activity_log` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `account_id` int(11) NOT NULL,
  `capacity_id` int(10) unsigned DEFAULT NULL,
  `action_code` varchar(40) NOT NULL,
  `target_type` varchar(40) DEFAULT NULL,
  `target_id` varchar(64) DEFAULT NULL,
  `result` enum('ok','denied') NOT NULL DEFAULT 'ok',
  `ip` varchar(45) DEFAULT NULL,
  `device` varchar(190) DEFAULT NULL,
  `at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_pal_account` (`account_id`,`at`),
  KEY `ix_pal_company` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='USR-01 §5 — سجلُّ النشاط: يراه صاحبُه والمدقّقُ وHR ولا يُعدَّل ولا يُحذف';

-- ── Table: portal_elements ──
CREATE TABLE `portal_elements` (
  `element_code` varchar(64) NOT NULL,
  `title_ar` varchar(190) NOT NULL,
  `owner_doc` varchar(32) NOT NULL COMMENT 'الوثيقةُ المالكة (USR-01 · WSP-01 …)',
  `sensitivity` enum('normal','sensitive') NOT NULL DEFAULT 'normal',
  `default_mode` enum('open','closed') NOT NULL DEFAULT 'closed',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`element_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ADM-01 §2 — قاموسُ عناصر البوابة: ما ليس فيه لا يُصيَّر أصلًا';

-- ── Table: positions ──
CREATE TABLE `positions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `name` varchar(120) NOT NULL COMMENT 'اسم المنصب التنظيمي (مثال: مدير حركة موقع MB1)',
  `role_id` int(11) NOT NULL COMMENT 'دور النظام الذي يمنحه المنصب — جسرٌ إلى roles.id لا بديل عنه',
  `job_title_id` int(11) DEFAULT NULL COMMENT 'ربط اختياري بالمسمى الوظيفي HR (job_titles.id)',
  `description` varchar(255) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_positions_company` (`company_id`),
  KEY `idx_positions_role` (`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='K6/ADR-07: المناصب — طبقة الصلاحية على المنصب فوق الأدوار';

-- ── Table: pricelists ──
CREATE TABLE `pricelists` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `pricelist_code` varchar(50) NOT NULL,
  `name` varchar(255) NOT NULL,
  `currency` enum('USD','SDG') NOT NULL DEFAULT 'USD',
  `revenue_model` enum('hourly','ton','meter') DEFAULT NULL,
  `base_price` decimal(14,2) NOT NULL DEFAULT 0.00,
  `distance_factor` decimal(6,3) DEFAULT NULL,
  `shift_factor` decimal(6,3) DEFAULT NULL,
  `volume_factor` decimal(6,3) DEFAULT NULL,
  `duration_factor` decimal(6,3) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pricelists_company_code` (`company_id`,`pricelist_code`),
  KEY `idx_pl_scope` (`company_id`,`is_deleted`),
  KEY `idx_pl_model` (`revenue_model`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: proc_award ──
CREATE TABLE `proc_award` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `rfq_id` int(10) unsigned NOT NULL,
  `minute_no` varchar(40) NOT NULL DEFAULT '',
  `committee_ref` varchar(190) NOT NULL DEFAULT '',
  `criteria_ref` varchar(190) NOT NULL DEFAULT '' COMMENT 'معايير التقييم المعلنة قبل الفتح',
  `winner_id` int(10) unsigned NOT NULL DEFAULT 0,
  `winner_amount` decimal(16,2) NOT NULL DEFAULT 0.00,
  `lowest_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'مشتق - اقل العروض سعرا',
  `lowest_amount` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'مشتق',
  `is_lowest` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'مشتق - لا يكتب بيد',
  `award_why` varchar(900) NOT NULL DEFAULT '' COMMENT 'الزامي حين الفائز ليس الادنى',
  `approved_by` int(10) unsigned NOT NULL DEFAULT 0,
  `approved_at` datetime DEFAULT NULL,
  `state` varchar(32) NOT NULL DEFAULT 'draft',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_award_rfq` (`rfq_id`) COMMENT 'ترسية واحدة لكل طلب عروض',
  CONSTRAINT `fk_awd_rfq` FOREIGN KEY (`rfq_id`) REFERENCES `proc_rfq` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_awd_why` CHECK (`is_lowest` = 1 or `award_why` <> ''),
  CONSTRAINT `chk_awd_crit` CHECK (`criteria_ref` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PRC-10 محضر × طلب عروض - ترسية واحدة';

-- ── Table: proc_count_line ──
CREATE TABLE `proc_count_line` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `session_id` int(10) unsigned NOT NULL,
  `item_id` int(10) unsigned NOT NULL DEFAULT 0,
  `item_name` varchar(190) NOT NULL DEFAULT '',
  `qty_book` decimal(16,3) NOT NULL DEFAULT 0.000 COMMENT 'الدفتري - مشتق من proc_stock_move',
  `qty_counted` decimal(16,3) NOT NULL DEFAULT 0.000,
  `qty_diff` decimal(16,3) NOT NULL DEFAULT 0.000 COMMENT 'مشتق',
  `unit_cost` decimal(16,4) NOT NULL DEFAULT 0.0000,
  `diff_value` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'مشتق',
  `settle_action` varchar(24) NOT NULL DEFAULT '' COMMENT 'ADJUST او INVESTIGATE او WRITE_OFF',
  `settle_why` varchar(600) NOT NULL DEFAULT '',
  `settled_by` int(10) unsigned NOT NULL DEFAULT 0,
  `settled_at` datetime DEFAULT NULL,
  `move_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'حركة التسوية المنشاة',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cntl` (`session_id`,`item_id`),
  KEY `ix_cntl` (`company_id`,`session_id`),
  CONSTRAINT `fk_cntl_ses` FOREIGN KEY (`session_id`) REFERENCES `proc_count_session` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_cntl_settle` CHECK (`qty_diff` = 0 or `settle_action` = '' or `settle_why` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='WH-16 صنف × جلسة جرد - Lines Child بقرار التسوية';

-- ── Table: proc_count_session ──
CREATE TABLE `proc_count_session` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `code` varchar(40) NOT NULL DEFAULT '',
  `warehouse_id` int(10) unsigned NOT NULL DEFAULT 0,
  `count_kind` varchar(24) NOT NULL DEFAULT '' COMMENT 'FULL او CYCLE او SPOT',
  `count_date` date DEFAULT NULL,
  `counted_by` int(10) unsigned NOT NULL DEFAULT 0,
  `reviewed_by` int(10) unsigned NOT NULL DEFAULT 0,
  `approved_by` int(10) unsigned NOT NULL DEFAULT 0,
  `approved_at` datetime DEFAULT NULL,
  `line_count` int(11) NOT NULL DEFAULT 0 COMMENT 'مشتق',
  `diff_count` int(11) NOT NULL DEFAULT 0 COMMENT 'مشتق - بنود بفرق',
  `diff_value` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'مشتق',
  `state` varchar(32) NOT NULL DEFAULT 'draft',
  `notes` varchar(500) NOT NULL DEFAULT '',
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `created_by` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cnt_code` (`company_id`,`code`),
  CONSTRAINT `chk_cnt_kind` CHECK (`count_kind` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='WH-15 جلسة جرد × مخزن - Header وبنود الفروق Child';

-- ── Table: proc_custody ──
CREATE TABLE `proc_custody` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `issue_id` int(11) DEFAULT NULL COMMENT 'proc_issue.id',
  `issue_line_id` int(11) DEFAULT NULL COMMENT 'proc_issue_line.id',
  `item_id` int(11) DEFAULT NULL,
  `item_name` varchar(200) DEFAULT NULL,
  `holder_id` int(11) DEFAULT NULL,
  `holder_name` varchar(150) DEFAULT NULL,
  `transfer_date` date DEFAULT NULL,
  `equipment_id` int(11) DEFAULT NULL,
  `project_id` int(11) DEFAULT NULL,
  `maintenance_order_id` int(11) DEFAULT NULL,
  `qty_issued` decimal(12,2) NOT NULL DEFAULT 0.00,
  `qty_returned` decimal(12,2) NOT NULL DEFAULT 0.00,
  `qty_consumed` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT 'المصروفة - المرتجعة',
  `state` varchar(20) NOT NULL DEFAULT 'مصروفة' COMMENT 'مصروفة/إرجاع جزئي/مستهلكة/مُقفلة',
  `notes` mediumtext DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_proc_custody_company_state` (`company_id`,`state`),
  KEY `idx_proc_custody_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: proc_delivery_event ──
CREATE TABLE `proc_delivery_event` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `order_id` int(10) unsigned NOT NULL,
  `event_kind` varchar(32) NOT NULL DEFAULT '' COMMENT 'PROMISED او SHIPPED او ARRIVED او DELAYED او PARTIAL',
  `event_date` date DEFAULT NULL,
  `qty_expected` decimal(16,3) NOT NULL DEFAULT 0.000,
  `qty_actual` decimal(16,3) NOT NULL DEFAULT 0.000,
  `delay_days` int(11) NOT NULL DEFAULT 0 COMMENT 'مشتق من الوعد والواقع',
  `delay_why` varchar(400) NOT NULL DEFAULT '',
  `receipt_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'سند الادخال ان وقع',
  `logged_by` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_dlv` (`company_id`,`order_id`,`event_date`),
  CONSTRAINT `chk_dlv_kind` CHECK (`event_kind` <> ''),
  CONSTRAINT `chk_dlv_delay` CHECK (`event_kind` <> 'DELAYED' or `delay_why` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PRC-14 حدث توريد × امر - سطر متابعة';

-- ── Table: proc_expiry_override ──
CREATE TABLE `proc_expiry_override` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `item_id` int(10) unsigned NOT NULL,
  `lot_id` int(10) unsigned NOT NULL DEFAULT 0,
  `op_kind` varchar(24) NOT NULL DEFAULT '',
  `op_ref` varchar(60) NOT NULL DEFAULT '',
  `expiry_date` date DEFAULT NULL,
  `requested_by` int(10) unsigned NOT NULL DEFAULT 0,
  `approver_role` varchar(190) NOT NULL DEFAULT '' COMMENT 'الدور المخول في السياسة',
  `approved_by` int(10) unsigned NOT NULL DEFAULT 0,
  `approved_at` datetime DEFAULT NULL,
  `reason` varchar(600) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_ovr_item` (`company_id`,`item_id`),
  CONSTRAINT `chk_ovr_full` CHECK (`reason` <> '' and `approver_role` <> '' and `op_kind` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='DEC-OPEN-15 تجاوز صرف المنتهي باعتماد سلطة السياسة';

-- ── Table: proc_hazmat_control ──
CREATE TABLE `proc_hazmat_control` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `item_id` int(10) unsigned NOT NULL,
  `hazard_class` varchar(60) NOT NULL DEFAULT '',
  `store_rule` varchar(400) NOT NULL DEFAULT '' COMMENT 'ضوابط التخزين',
  `handling_rule` varchar(400) NOT NULL DEFAULT '',
  `permit_needed` tinyint(1) NOT NULL DEFAULT 0,
  `permit_ref` varchar(190) NOT NULL DEFAULT '',
  `issue_gate` varchar(190) NOT NULL DEFAULT '' COMMENT 'بوابة الصرف - من يجيز',
  `separation_rule` varchar(400) NOT NULL DEFAULT '' COMMENT 'ما لا يخزن بجواره',
  `decision_ref` varchar(48) NOT NULL DEFAULT '',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_haz` (`company_id`,`item_id`),
  CONSTRAINT `chk_haz_full` CHECK (`hazard_class` <> '' and `store_rule` <> '' and `handling_rule` <> '' and `issue_gate` <> ''),
  CONSTRAINT `chk_haz_permit` CHECK (`permit_needed` = 0 or `permit_ref` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='WH-07 صنف خطر × ضوابطه - سطر ضوابط';

-- ── Table: proc_invoice_match ──
CREATE TABLE `proc_invoice_match` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `order_id` int(10) unsigned NOT NULL,
  `invoice_no` varchar(60) NOT NULL DEFAULT '',
  `invoice_date` date DEFAULT NULL,
  `invoice_amount` decimal(16,2) NOT NULL DEFAULT 0.00,
  `po_amount` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'مشتق من بنود الامر',
  `grn_amount` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'مشتق من سندات الادخال',
  `var_invoice_po` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'مشتق',
  `var_grn_po` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'مشتق',
  `within_tol` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'مشتق من عتبة السجل لا من رقم صلب',
  `verdict` varchar(24) NOT NULL DEFAULT '' COMMENT 'MATCHED او VARIANCE او BLOCKED',
  `var_decision` varchar(24) NOT NULL DEFAULT '' COMMENT 'ACCEPT او REJECT - للفرق خارج العتبة',
  `var_reason` varchar(600) NOT NULL DEFAULT '',
  `decided_by` int(10) unsigned NOT NULL DEFAULT 0,
  `decided_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_match` (`company_id`,`order_id`,`invoice_no`),
  CONSTRAINT `chk_mt_inv` CHECK (`invoice_no` <> ''),
  CONSTRAINT `chk_mt_var` CHECK (`within_tol` = 1 or `verdict` <> 'MATCHED'),
  CONSTRAINT `chk_mt_dec` CHECK (`var_decision` = '' or `var_reason` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PRC-15 مطابقة × فاتورة × امر - مطابقة واحدة';

-- ── Table: proc_issue ──
CREATE TABLE `proc_issue` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `code` varchar(50) DEFAULT NULL,
  `warehouse_id` int(11) DEFAULT NULL,
  `holder_id` int(11) DEFAULT NULL COMMENT 'المستلِم',
  `holder_name` varchar(150) DEFAULT NULL,
  `issue_date` date DEFAULT NULL,
  `equipment_id` int(11) DEFAULT NULL COMMENT 'بُعد تكلفة',
  `project_id` int(11) DEFAULT NULL COMMENT 'بُعد تكلفة',
  `maintenance_order_id` int(11) DEFAULT NULL COMMENT 'mnt_order.id (بلا FK)',
  `maint_type` varchar(20) DEFAULT NULL COMMENT 'وقائية/تصحيحية/رأسمالية',
  `contract_id` int(11) DEFAULT NULL,
  `supplier_id` int(11) DEFAULT NULL,
  `charge_supplier_id` int(11) DEFAULT NULL COMMENT 'مورّدُ الآليات (suppliers.id) الذي يُحمَّل ثمنَ الصرف — فارغٌ أي على الشركة',
  `total_cost` decimal(14,2) NOT NULL DEFAULT 0.00,
  `state` varchar(20) NOT NULL DEFAULT 'مسودة' COMMENT 'مسودة/محجوز/مصروف/محمَّل التكلفة',
  `notes` mediumtext DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_proc_issue_company_state` (`company_id`,`state`),
  KEY `idx_proc_issue_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: proc_issue_line ──
CREATE TABLE `proc_issue_line` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `issue_id` int(11) NOT NULL,
  `item_id` int(11) DEFAULT NULL,
  `item_name` varchar(200) NOT NULL,
  `qty` decimal(12,2) NOT NULL DEFAULT 1.00,
  `unit_cost` decimal(14,2) NOT NULL DEFAULT 0.00,
  `subtotal` decimal(14,2) NOT NULL DEFAULT 0.00,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_proc_issline_issue` (`issue_id`),
  CONSTRAINT `fk_proc_issline_iss` FOREIGN KEY (`issue_id`) REFERENCES `proc_issue` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: proc_issue_request ──
CREATE TABLE `proc_issue_request` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `code` varchar(40) NOT NULL DEFAULT '',
  `warehouse_id` int(10) unsigned NOT NULL DEFAULT 0,
  `requesting_dept` varchar(120) NOT NULL DEFAULT '',
  `requester_id` int(10) unsigned NOT NULL DEFAULT 0,
  `purpose` varchar(400) NOT NULL DEFAULT '',
  `equipment_id` int(10) unsigned NOT NULL DEFAULT 0,
  `project_id` int(10) unsigned NOT NULL DEFAULT 0,
  `maintenance_order_id` int(10) unsigned NOT NULL DEFAULT 0,
  `need_date` date DEFAULT NULL,
  `priority` varchar(24) NOT NULL DEFAULT '',
  `issue_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'سند الصرف الذي نفذه ان وقع',
  `state` varchar(32) NOT NULL DEFAULT 'draft',
  `reject_reason` varchar(400) NOT NULL DEFAULT '',
  `notes` varchar(500) NOT NULL DEFAULT '',
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `created_by` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ireq_code` (`company_id`,`code`),
  KEY `ix_ireq` (`company_id`,`state`),
  CONSTRAINT `chk_ireq_purpose` CHECK (`purpose` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='WH-08 طلب صرف × جهة - طلب واحد';

-- ── Table: proc_issue_request_line ──
CREATE TABLE `proc_issue_request_line` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `request_id` int(10) unsigned NOT NULL,
  `item_id` int(10) unsigned NOT NULL DEFAULT 0,
  `item_name` varchar(190) NOT NULL DEFAULT '',
  `qty_requested` decimal(16,3) NOT NULL DEFAULT 0.000,
  `qty_approved` decimal(16,3) DEFAULT NULL COMMENT 'NULL لم يبت فيه - وصفر قرار يوجب سببا',
  `qty_issued` decimal(16,3) NOT NULL DEFAULT 0.000 COMMENT 'مشتق من بنود سند الصرف',
  `cut_reason` varchar(400) NOT NULL DEFAULT '' COMMENT 'سبب خفض المعتمد عن المطلوب',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_ireql` (`company_id`,`request_id`),
  KEY `fk_ireql_req` (`request_id`),
  CONSTRAINT `fk_ireql_req` FOREIGN KEY (`request_id`) REFERENCES `proc_issue_request` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_ireql_qty` CHECK (`qty_requested` > 0 and (`qty_approved` is null or `qty_approved` <= `qty_requested`)),
  CONSTRAINT `chk_ireql_cut` CHECK (`qty_approved` is null or `qty_approved` = `qty_requested` or `cut_reason` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='WH-09 بند × طلب صرف - Request Lines Child غير بنود السند';

-- ── Table: proc_item ──
CREATE TABLE `proc_item` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `code` varchar(50) DEFAULT NULL,
  `name` varchar(200) NOT NULL,
  `category` varchar(100) DEFAULT NULL COMMENT 'فلاتر/زيوت وشحوم/إسبيرات/بطاريات/أسنان جردل/سيور',
  `material_nature` varchar(30) NOT NULL DEFAULT 'قابل للتخزين' COMMENT 'قابل للتخزين / غير قابل للتخزين / خدمة ومصنعيات',
  `uom` varchar(20) NOT NULL DEFAULT 'قطعة' COMMENT 'قطعة/لتر/كجم',
  `is_critical` tinyint(1) NOT NULL DEFAULT 0,
  `min_qty` decimal(12,2) NOT NULL DEFAULT 0.00,
  `max_qty` decimal(12,2) NOT NULL DEFAULT 0.00,
  `lead_time_days` int(11) NOT NULL DEFAULT 0,
  `safety_stock` decimal(12,2) NOT NULL DEFAULT 0.00,
  `avg_cost` decimal(18,4) DEFAULT NULL COMMENT 'المتوسط المرجح بمعادل الدفاتر — يشتقه ProcCostingService من دفتر الحركات',
  `avg_cost_updated_at` datetime DEFAULT NULL COMMENT 'لحظة آخر إعادة احتساب',
  `served_equipment_id` int(11) DEFAULT NULL COMMENT 'equipments.id (بلا FK)',
  `served_category` varchar(100) DEFAULT NULL,
  `notes` mediumtext DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `track_lot` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'يشتق من proc_item_track_rule - لا يكتب بيد',
  `track_serial` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'يشتق من proc_item_track_rule - لا يكتب بيد',
  `track_expiry` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'يشتق من proc_item_track_rule - لا يكتب بيد',
  `track_rule_ref` varchar(60) NOT NULL DEFAULT '' COMMENT 'مفتاح القاعدة التي اشتقت الاعلام - علم بلا قاعدة مرفوض',
  `track_lot_level` enum('OFF','OPTIONAL','REQUIRED') NOT NULL DEFAULT 'OFF' COMMENT 'محلول من السياسة',
  `track_serial_level` enum('OFF','OPTIONAL','REQUIRED') NOT NULL DEFAULT 'OFF' COMMENT 'محلول من السياسة',
  `track_mfg_level` enum('OFF','OPTIONAL','REQUIRED') NOT NULL DEFAULT 'OFF' COMMENT 'محلول من السياسة',
  `track_expiry_level` enum('OFF','OPTIONAL','REQUIRED') NOT NULL DEFAULT 'OFF' COMMENT 'محلول من السياسة',
  `track_warranty_level` enum('OFF','OPTIONAL','REQUIRED') NOT NULL DEFAULT 'OFF' COMMENT 'محلول من السياسة',
  `expiry_enforce` enum('WARNING','APPROVAL_REQUIRED','HARD_BLOCK') NOT NULL DEFAULT 'WARNING' COMMENT 'محلول من السياسة',
  `issue_policy` enum('FIFO','FEFO','MANUAL') NOT NULL DEFAULT 'FIFO' COMMENT 'محلول من السياسة',
  `requalify` enum('ENABLED','DISABLED') NOT NULL DEFAULT 'DISABLED' COMMENT 'محلول من السياسة',
  `policy_scope` varchar(16) NOT NULL DEFAULT '' COMMENT 'ITEM ان خصص و CATEGORY ان ورث و NONE ان لا سياسة',
  `policy_version` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_proc_item_company` (`company_id`),
  KEY `idx_proc_item_critical` (`company_id`,`is_critical`),
  KEY `idx_proc_item_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: proc_item_track_rule ──
CREATE TABLE `proc_item_track_rule` (
  `rule_key` varchar(60) NOT NULL,
  `company_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'صفر يعني كل الكيانات',
  `category` varchar(120) NOT NULL DEFAULT '' COMMENT 'فئة الصنف كما في proc_item.category',
  `track_lot` tinyint(1) NOT NULL DEFAULT 0,
  `track_serial` tinyint(1) NOT NULL DEFAULT 0,
  `track_expiry` tinyint(1) NOT NULL DEFAULT 0,
  `expiry_policy` varchar(24) NOT NULL DEFAULT '' COMMENT 'BLOCK او WARN_OVERRIDE - فارغ لغير المنتهي',
  `issue_order` varchar(24) NOT NULL DEFAULT '' COMMENT 'FEFO او FIFO او FREE',
  `why` varchar(600) NOT NULL DEFAULT '',
  `decision_ref` varchar(48) NOT NULL DEFAULT '',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`rule_key`),
  UNIQUE KEY `uq_cat` (`company_id`,`category`),
  CONSTRAINT `chk_pitr_any` CHECK (`track_lot` = 1 or `track_serial` = 1 or `track_expiry` = 1),
  CONSTRAINT `chk_pitr_why` CHECK (`why` <> '' and `decision_ref` <> '' and `category` <> ''),
  CONSTRAINT `chk_pitr_exp` CHECK (`track_expiry` = 0 or `expiry_policy` <> '' and `issue_order` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='REPAIR01 W09 - فئة الصنف تحدد اعلام التتبع - ينشا خاويا بانتظار DEC-OPEN-15';

-- ── Table: proc_landed_cost ──
CREATE TABLE `proc_landed_cost` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL COMMENT 'الكيان المالك — عزل المستأجر',
  `order_id` int(11) NOT NULL COMMENT 'أمر الشراء المحمَّل (proc_order.id — بلا FK كسائر proc_*)',
  `doc_no` varchar(60) NOT NULL COMMENT 'رقم مستند المصروف (بوليصة/إيصال جمركي…)',
  `cost_type` varchar(30) NOT NULL DEFAULT 'شحن' COMMENT 'شحن · جمارك · تخليص · نقل داخلي · أخرى',
  `amount` decimal(18,2) NOT NULL COMMENT 'المبلغ بعملة المستند',
  `currency` varchar(8) NOT NULL DEFAULT 'SDG',
  `fx_rate` decimal(12,4) NOT NULL DEFAULT 1.0000 COMMENT 'إلى معادل الدفاتر — ضربًا (عرف base_amount)',
  `base_amount` decimal(18,2) NOT NULL COMMENT 'المعادل = amount × fx_rate',
  `supplier_id` int(11) DEFAULT NULL COMMENT 'مقدم الخدمة (proc_supplier) إن وُجد',
  `notes` varchar(255) DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_landed_order` (`company_id`,`order_id`,`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='التكلفة الوصولية لأوامر الشراء — ترسمل على تكلفة الاستلام توزيعا بالقيمة';

-- ── Table: proc_lookup ──
CREATE TABLE `proc_lookup` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `type` varchar(40) NOT NULL COMMENT 'فئة صنف / وحدة قياس / نوع مخزن / طبيعة مادة',
  `name` varchar(150) NOT NULL,
  `extra` varchar(255) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_proc_lookup_company_type` (`company_id`,`type`),
  KEY `idx_proc_lookup_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: proc_lot ──
CREATE TABLE `proc_lot` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `lot_no` varchar(60) NOT NULL,
  `item_id` int(10) unsigned NOT NULL,
  `supplier_id` int(10) unsigned NOT NULL DEFAULT 0,
  `order_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'امر الشراء',
  `receipt_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'سند الادخال',
  `qty_received` decimal(16,3) NOT NULL DEFAULT 0.000,
  `qty_available` decimal(16,3) NOT NULL DEFAULT 0.000 COMMENT 'مشتق من الحركات',
  `mfg_date` date DEFAULT NULL COMMENT 'مستقل عن الصلاحية - قد يوجد احدهما',
  `expiry_date` date DEFAULT NULL,
  `warehouse_id` int(10) unsigned NOT NULL DEFAULT 0,
  `bin` varchar(60) NOT NULL DEFAULT '',
  `quality_state` varchar(24) NOT NULL DEFAULT 'GOOD',
  `policy_version` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'نسخة السياسة السارية لحظة الانشاء',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_lot` (`company_id`,`item_id`,`lot_no`),
  KEY `ix_lot_exp` (`company_id`,`expiry_date`),
  CONSTRAINT `chk_lot_no` CHECK (`lot_no` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='DEC-OPEN-15 سجل الدفعة - الحقول الالزامية بحسب سياسة الصنف وحدها';

-- ── Table: proc_offer ──
CREATE TABLE `proc_offer` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `rfq_id` int(10) unsigned NOT NULL,
  `supplier_id` int(10) unsigned NOT NULL,
  `offer_ref` varchar(60) NOT NULL DEFAULT '',
  `submitted_at` datetime DEFAULT NULL,
  `received_by` int(10) unsigned NOT NULL DEFAULT 0,
  `valid_until` date DEFAULT NULL,
  `currency` varchar(8) NOT NULL DEFAULT '',
  `fx_rate` decimal(14,6) NOT NULL DEFAULT 1.000000,
  `total_amount` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'مشتق من proc_offer_line',
  `base_amount` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'total × fx_rate',
  `line_count` int(11) NOT NULL DEFAULT 0 COMMENT 'مشتق',
  `delivery_days` int(11) NOT NULL DEFAULT 0,
  `payment_terms` varchar(190) NOT NULL DEFAULT '',
  `late` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'مشتق من due_date - لا يكتب بيد',
  `state` varchar(32) NOT NULL DEFAULT 'received',
  `notes` varchar(500) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_offer` (`rfq_id`,`supplier_id`) COMMENT 'مورد واحد عرض واحد لكل طلب',
  KEY `ix_offer` (`company_id`,`rfq_id`),
  CONSTRAINT `fk_off_rfq` FOREIGN KEY (`rfq_id`) REFERENCES `proc_rfq` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_off_cur` CHECK (`currency` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PRC-08 عرض × مورد × طلب عروض - Child Register برأسه';

-- ── Table: proc_offer_line ──
CREATE TABLE `proc_offer_line` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `offer_id` int(10) unsigned NOT NULL,
  `request_line_id` int(10) unsigned NOT NULL COMMENT 'بند الطلب الذي يقابله - مقارنة بندا ببند',
  `item_id` int(10) unsigned NOT NULL DEFAULT 0,
  `item_name` varchar(190) NOT NULL DEFAULT '',
  `qty_offered` decimal(16,3) NOT NULL DEFAULT 0.000,
  `unit_price` decimal(16,4) NOT NULL DEFAULT 0.0000,
  `subtotal` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'qty × price - مشتق',
  `brand` varchar(120) NOT NULL DEFAULT '',
  `is_alternative` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'بديل عن المطلوب - يعلن ولا يقارن كمطابق',
  `alt_why` varchar(400) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_offl` (`offer_id`,`request_line_id`),
  KEY `ix_offl` (`company_id`,`offer_id`),
  CONSTRAINT `fk_offl_off` FOREIGN KEY (`offer_id`) REFERENCES `proc_offer` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_offl_alt` CHECK (`is_alternative` = 0 or `alt_why` <> ''),
  CONSTRAINT `chk_offl_qty` CHECK (`qty_offered` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PRC-09 بند عرض × عرض × بند طلب - Line-by-Line Child';

-- ── Table: proc_order ──
CREATE TABLE `proc_order` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `code` varchar(50) DEFAULT NULL,
  `supplier_id` int(11) DEFAULT NULL COMMENT 'proc_supplier.id',
  `project_id` int(11) DEFAULT NULL COMMENT 'البُعد المفقود — يُشتق من طلب الشراء (FES: المشروع إلزامي)',
  `request_id` int(11) DEFAULT NULL COMMENT 'proc_request.id',
  `fin_approval_ref` varchar(100) DEFAULT NULL COMMENT 'مرجع الاعتماد المالي (شرط الإصدار)',
  `op_classification` varchar(20) NOT NULL DEFAULT 'استهلاكية',
  `currency` varchar(10) NOT NULL DEFAULT 'SDG' COMMENT 'SDG/USD',
  `fx_rate` decimal(12,4) NOT NULL DEFAULT 1.0000,
  `payment_time` varchar(20) NOT NULL DEFAULT 'فوري' COMMENT 'فوري/مؤجل/آجل 30/60/90',
  `expected_receipt_type` varchar(20) NOT NULL DEFAULT 'مخزن' COMMENT 'مخزن/مباشر للمعدة/مشروع/ورشة',
  `expected_delivery_date` date DEFAULT NULL COMMENT 'موعد التوريد المتفق — الإلزامي الثالث (§5.1)',
  `sent_at` datetime DEFAULT NULL COMMENT 'لحظة الإرسال للمورد (Approved→Sent §8.2)',
  `sent_by` int(11) DEFAULT NULL COMMENT 'مُرسِل الأمر',
  `late_alerted_at` datetime DEFAULT NULL COMMENT 'آخر إنذار تأخّر توريد (Late بعدّاده §8.2)',
  `received_pct` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT 'نسبة المستلَم — 100 = اكتمال',
  `first_receipt_at` datetime DEFAULT NULL COMMENT 'أول استلام (PartialReceived)',
  `final_receipt_at` datetime DEFAULT NULL COMMENT 'الاستلام النهائي — زنادُ الأثر المالي',
  `closed_at` datetime DEFAULT NULL COMMENT 'إقفال الأمر',
  `closed_by` int(11) DEFAULT NULL COMMENT 'مُقفِل الأمر',
  `invoice_no` varchar(64) DEFAULT NULL COMMENT 'رقم فاتورة المورد',
  `invoice_date` date DEFAULT NULL COMMENT 'تاريخ الفاتورة',
  `invoice_amount` decimal(18,2) DEFAULT NULL COMMENT 'قيمة الفاتورة (لمضاهاة الفرق)',
  `match_state` varchar(16) NOT NULL DEFAULT 'unmatched' COMMENT 'unmatched·matched·var_pending·rejected (§8.2)',
  `var_decision` varchar(30) DEFAULT NULL COMMENT 'حسم الفرق: قبول الفرق · إشعار دائن · رفض الفاتورة',
  `var_decision_reason` varchar(255) DEFAULT NULL COMMENT 'تفسير الحسم — إلزامي مع القرار',
  `var_decided_by` int(11) DEFAULT NULL COMMENT 'مخوَّل الحسم users.id',
  `var_decided_at` datetime DEFAULT NULL COMMENT 'لحظة الحسم',
  `matched_at` datetime DEFAULT NULL COMMENT 'لحظة المطابقة',
  `matched_by` int(11) DEFAULT NULL COMMENT 'من طابق',
  `total_amount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `base_amount` decimal(18,2) DEFAULT NULL COMMENT 'المعادل الموحّد = total_amount × fx_rate (FES §3.3)',
  `tax_amount` decimal(18,2) NOT NULL DEFAULT 0.00 COMMENT 'الضريبة — متطلبٌ نظامي (الدستور §8)',
  `due_date` date DEFAULT NULL COMMENT 'تاريخ استحقاق السداد (FES §3.1 فهرس الاستحقاق)',
  `event_id` int(11) DEFAULT NULL COMMENT 'مرجع الحدث المالي المنشور — قراءةً بمرجعه (§5.1-③)',
  `state` varchar(30) NOT NULL DEFAULT 'مسودة' COMMENT 'مسودة/مؤكَّد/استلام أولي/استلام نهائي/مطابَق/مغلق',
  `notes` mediumtext DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `rfq_id` int(11) DEFAULT NULL COMMENT 'طلبُ العروضِ الذي رُسي عنه هذا الأمر (INJ-0091)',
  `award_id` int(11) DEFAULT NULL COMMENT 'صفُّ الترسيةِ الذي وُلد منه هذا الأمر (INJ-0091)',
  `package_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'الحزمة التي انتج الامر عنها',
  `award_minute_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'محضر الترسية - امر بلا سند تنافسي يعلن',
  `direct_reason` varchar(500) NOT NULL DEFAULT '' COMMENT 'سبب الشراء المباشر - الزامي بلا محضر',
  `amend_count` int(11) NOT NULL DEFAULT 0 COMMENT 'مشتق من proc_po_amendment',
  PRIMARY KEY (`id`),
  KEY `idx_proc_order_company_state` (`company_id`,`state`),
  KEY `idx_proc_order_deleted` (`is_deleted`),
  KEY `ix_po_receipt` (`state`,`final_receipt_at`),
  KEY `ix_po_project` (`project_id`),
  KEY `ix_po_due` (`due_date`),
  KEY `ix_po_match` (`match_state`),
  KEY `ix_po_event` (`event_id`),
  KEY `ix_po_expected` (`expected_delivery_date`),
  KEY `ix_po_rfq_id` (`rfq_id`),
  KEY `ix_po_award_id` (`award_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: proc_order_line ──
CREATE TABLE `proc_order_line` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `order_id` int(11) NOT NULL,
  `item_id` int(11) DEFAULT NULL,
  `item_name` varchar(200) NOT NULL,
  `qty` decimal(12,2) NOT NULL DEFAULT 1.00,
  `unit_price` decimal(14,2) NOT NULL DEFAULT 0.00,
  `op_classification` varchar(20) DEFAULT NULL,
  `subtotal` decimal(14,2) NOT NULL DEFAULT 0.00,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_proc_ordline_order` (`order_id`),
  CONSTRAINT `fk_proc_ordline_ord` FOREIGN KEY (`order_id`) REFERENCES `proc_order` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: proc_orderpoint ──
CREATE TABLE `proc_orderpoint` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `item_id` int(11) NOT NULL COMMENT 'proc_item.id',
  `warehouse_id` int(11) DEFAULT NULL COMMENT 'proc_warehouse.id',
  `min_qty` decimal(12,2) NOT NULL DEFAULT 0.00,
  `max_qty` decimal(12,2) NOT NULL DEFAULT 0.00,
  `trigger_qty` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT 'ROP - نقطة إعادة الطلب',
  `safety_stock` decimal(12,2) NOT NULL DEFAULT 0.00,
  `mode` varchar(20) NOT NULL DEFAULT 'يدوي' COMMENT 'تلقائي / يدوي',
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_proc_orderpoint_company` (`company_id`),
  KEY `idx_proc_orderpoint_item` (`item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: proc_package ──
CREATE TABLE `proc_package` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `code` varchar(40) NOT NULL DEFAULT '',
  `title` varchar(190) NOT NULL DEFAULT '',
  `period_from` date DEFAULT NULL,
  `period_to` date DEFAULT NULL,
  `strategy` varchar(32) NOT NULL DEFAULT '' COMMENT 'سبب التجميع - وفر كمية او مورد واحد او مسار واحد',
  `member_count` int(11) NOT NULL DEFAULT 0 COMMENT 'مشتق من proc_package_member',
  `line_count` int(11) NOT NULL DEFAULT 0 COMMENT 'مشتق',
  `est_value` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'مشتق من بنود الطلبات المضمومة',
  `state` varchar(32) NOT NULL DEFAULT 'draft',
  `closed_at` datetime DEFAULT NULL,
  `closed_by` int(10) unsigned NOT NULL DEFAULT 0,
  `notes` varchar(500) NOT NULL DEFAULT '',
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `created_by` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pkg_code` (`company_id`,`code`),
  KEY `ix_pkg_state` (`company_id`,`state`),
  CONSTRAINT `chk_pkg_strategy` CHECK (`strategy` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PRC-04 حزمة شراء × فترة - حزمة واحدة';

-- ── Table: proc_package_member ──
CREATE TABLE `proc_package_member` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `package_id` int(10) unsigned NOT NULL,
  `request_id` int(10) unsigned NOT NULL,
  `join_reason` varchar(300) NOT NULL DEFAULT '',
  `joined_by` int(10) unsigned NOT NULL DEFAULT 0,
  `joined_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pkg_req` (`request_id`) COMMENT 'طلب واحد في حزمة واحدة - لا ضم مزدوج',
  KEY `ix_pkgm` (`company_id`,`package_id`),
  KEY `fk_pkgm_pkg` (`package_id`),
  CONSTRAINT `fk_pkgm_pkg` FOREIGN KEY (`package_id`) REFERENCES `proc_package` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_pkgm_why` CHECK (`join_reason` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PRC-05 حزمة × طلب مضموم - Junction Child';

-- ── Table: proc_po_amendment ──
CREATE TABLE `proc_po_amendment` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `order_id` int(10) unsigned NOT NULL,
  `seq_no` int(11) NOT NULL DEFAULT 1,
  `kind` varchar(32) NOT NULL DEFAULT '' COMMENT 'QTY او PRICE او DATE او CANCEL او ITEM',
  `before_val` varchar(300) NOT NULL DEFAULT '',
  `after_val` varchar(300) NOT NULL DEFAULT '',
  `delta_amount` decimal(16,2) NOT NULL DEFAULT 0.00,
  `reason` varchar(600) NOT NULL DEFAULT '',
  `gov_path` varchar(190) NOT NULL DEFAULT '' COMMENT 'المسار الحوكمي الذي اعتمده',
  `requested_by` int(10) unsigned NOT NULL DEFAULT 0,
  `approved_by` int(10) unsigned NOT NULL DEFAULT 0,
  `approved_at` datetime DEFAULT NULL,
  `state` varchar(32) NOT NULL DEFAULT 'pending',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_amend` (`order_id`,`seq_no`),
  KEY `ix_amend` (`company_id`,`order_id`),
  CONSTRAINT `chk_amd_full` CHECK (`kind` <> '' and `reason` <> '' and `gov_path` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PRC-13 استثناء او تعديل × امر - سطر بمساره الحوكمي';

-- ── Table: proc_receipt_custody ──
CREATE TABLE `proc_receipt_custody` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `code` varchar(50) DEFAULT NULL,
  `holder_id` int(11) DEFAULT NULL COMMENT 'المستلِم (users/employees.id بلا FK)',
  `holder_name` varchar(150) DEFAULT NULL COMMENT 'لقطة نصية للمستلِم',
  `receipt_date` date DEFAULT NULL,
  `supplier_id` int(11) DEFAULT NULL COMMENT 'proc_supplier.id',
  `order_id` int(11) DEFAULT NULL COMMENT 'proc_order.id',
  `receipt_location` varchar(255) DEFAULT NULL COMMENT 'عطبرة/موقع المورد/…',
  `warehouse_id` int(11) DEFAULT NULL COMMENT 'مخزن الإدخال — إلزامي حين الوجهة مخزن؛ NULL لغير المخزنية',
  `expected_destination` varchar(30) NOT NULL DEFAULT 'مخزن' COMMENT 'مخزن/ورشة/مشروع/معدة',
  `state` varchar(30) NOT NULL DEFAULT 'مستلَمة' COMMENT 'مستلَمة/قيد الترحيل/مسلَّمة للوجهة',
  `notes` mediumtext DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_proc_rc_company_state` (`company_id`,`state`),
  KEY `idx_proc_rc_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: proc_receipt_line ──
CREATE TABLE `proc_receipt_line` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `custody_id` int(11) NOT NULL,
  `item_id` int(11) DEFAULT NULL,
  `item_name` varchar(200) NOT NULL,
  `qty` decimal(12,2) NOT NULL DEFAULT 1.00,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `qty_received` decimal(16,3) NOT NULL DEFAULT 0.000 COMMENT 'الوارد',
  `qty_accepted` decimal(16,3) NOT NULL DEFAULT 0.000 COMMENT 'المقبول بعد الفحص',
  `qty_rejected` decimal(16,3) NOT NULL DEFAULT 0.000 COMMENT 'المرفوض',
  `reject_reason` varchar(400) NOT NULL DEFAULT '',
  `lot_no` varchar(60) NOT NULL DEFAULT '' COMMENT 'يلزم حين track_lot=1 - خامد حتى DEC-OPEN-15',
  `serial_no` varchar(80) NOT NULL DEFAULT '' COMMENT 'يلزم حين track_serial=1',
  `expiry_date` date DEFAULT NULL COMMENT 'يلزم حين track_expiry=1',
  `unit_cost` decimal(16,4) NOT NULL DEFAULT 0.0000,
  `order_line_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'بند الامر المقابل - للمطابقة الثلاثية',
  `lot_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'مرجع سجل الدفعة',
  `mfg_date` date DEFAULT NULL COMMENT 'مستقل عن الصلاحية',
  `warranty_until` date DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_proc_rcline_custody` (`custody_id`),
  CONSTRAINT `fk_proc_rcline_custody` FOREIGN KEY (`custody_id`) REFERENCES `proc_receipt_custody` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: proc_requalification ──
CREATE TABLE `proc_requalification` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `item_id` int(10) unsigned NOT NULL,
  `lot_id` int(10) unsigned NOT NULL DEFAULT 0,
  `serial_id` int(10) unsigned NOT NULL DEFAULT 0,
  `old_expiry` date DEFAULT NULL,
  `quarantined` tinyint(1) NOT NULL DEFAULT 0,
  `inspected_at` date DEFAULT NULL,
  `inspected_by` int(10) unsigned NOT NULL DEFAULT 0,
  `tech_doc_ref` varchar(190) NOT NULL DEFAULT '' COMMENT 'المستند الفني - لا تاريخ جديد بلا مستند',
  `new_expiry` date DEFAULT NULL,
  `approved_by` int(10) unsigned NOT NULL DEFAULT 0,
  `approved_at` datetime DEFAULT NULL,
  `state` varchar(24) NOT NULL DEFAULT 'opened',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_req_item` (`company_id`,`item_id`),
  CONSTRAINT `chk_req_doc` CHECK (`new_expiry` is null or `tech_doc_ref` <> '' and `approved_by` > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='DEC-OPEN-15 اعادة الفحص والتاهيل - تفعل بالسياسة';

-- ── Table: proc_request ──
CREATE TABLE `proc_request` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `code` varchar(50) DEFAULT NULL,
  `need_source` varchar(30) NOT NULL DEFAULT 'نقص مخزون' COMMENT 'خطة وقائية/أمر صيانة/نقص مخزون/إعادة طلب',
  `source_ref` varchar(100) DEFAULT NULL COMMENT 'مرجع المصدر (خطة/أمر/نقطة طلب)',
  `op_classification` varchar(20) NOT NULL DEFAULT 'استهلاكية' COMMENT 'وقائية/تصحيحية/رأسمالية/استهلاكية',
  `requesting_dept` varchar(40) DEFAULT NULL,
  `equipment_id` int(11) DEFAULT NULL,
  `project_id` int(11) DEFAULT NULL,
  `priority` varchar(20) NOT NULL DEFAULT 'عادي' COMMENT 'عادي/عاجل/حرج',
  `fin_approval_state` varchar(20) NOT NULL DEFAULT 'بانتظار' COMMENT 'بانتظار/معتمد مالياً/مرفوض',
  `state` varchar(30) NOT NULL DEFAULT 'مسودة' COMMENT 'مسودة/مقدَّم/اعتماد المشتريات/مراجعة مالية/معتمد مالياً/محوَّل لأمر شراء/مغلق/مرفوض',
  `notes` mediumtext DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_proc_request_company_state` (`company_id`,`state`),
  KEY `idx_proc_request_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: proc_request_line ──
CREATE TABLE `proc_request_line` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `request_id` int(11) NOT NULL,
  `item_id` int(11) DEFAULT NULL COMMENT 'proc_item.id (اختياري)',
  `item_name` varchar(200) NOT NULL COMMENT 'لقطة نصية للصنف',
  `qty` decimal(12,2) NOT NULL DEFAULT 1.00,
  `op_classification` varchar(20) DEFAULT NULL COMMENT 'تصنيف على مستوى البند',
  `note` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_proc_reqline_request` (`request_id`),
  CONSTRAINT `fk_proc_reqline_req` FOREIGN KEY (`request_id`) REFERENCES `proc_request` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: proc_rfq ──
CREATE TABLE `proc_rfq` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `code` varchar(40) NOT NULL DEFAULT '',
  `package_id` int(10) unsigned NOT NULL COMMENT 'حبة الكيان - طلب عروض × حزمة',
  `title` varchar(190) NOT NULL DEFAULT '',
  `issued_at` datetime DEFAULT NULL,
  `due_date` date DEFAULT NULL,
  `open_at` datetime DEFAULT NULL COMMENT 'موعد فتح المظاريف - لا عرض يقرا قبله',
  `opened_at` datetime DEFAULT NULL,
  `opened_by` int(10) unsigned NOT NULL DEFAULT 0,
  `invite_count` int(11) NOT NULL DEFAULT 0 COMMENT 'مشتق',
  `offer_count` int(11) NOT NULL DEFAULT 0 COMMENT 'مشتق',
  `state` varchar(32) NOT NULL DEFAULT 'draft',
  `cancel_reason` varchar(400) NOT NULL DEFAULT '',
  `notes` varchar(500) NOT NULL DEFAULT '',
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `created_by` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_rfq_code` (`company_id`,`code`),
  UNIQUE KEY `uq_rfq_pkg` (`package_id`) COMMENT 'حزمة واحدة = طلب عروض واحد',
  CONSTRAINT `fk_prfq_pkg` FOREIGN KEY (`package_id`) REFERENCES `proc_package` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PRC-06 طلب عروض × حزمة - مستقل عن supplier_rfqs بحبته (W9-D-02)';

-- ── Table: proc_rfq_invite ──
CREATE TABLE `proc_rfq_invite` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `rfq_id` int(10) unsigned NOT NULL,
  `supplier_id` int(10) unsigned NOT NULL,
  `invited_at` datetime NOT NULL DEFAULT current_timestamp(),
  `invited_by` int(10) unsigned NOT NULL DEFAULT 0,
  `channel` varchar(32) NOT NULL DEFAULT '',
  `responded_at` datetime DEFAULT NULL,
  `response` varchar(24) NOT NULL DEFAULT '' COMMENT 'offered او declined او silent',
  `decline_why` varchar(400) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_inv` (`rfq_id`,`supplier_id`) COMMENT 'مورد واحد دعوة واحدة',
  KEY `ix_inv` (`company_id`,`rfq_id`),
  CONSTRAINT `fk_inv_rfq` FOREIGN KEY (`rfq_id`) REFERENCES `proc_rfq` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_inv_decl` CHECK (`response` <> 'declined' or `decline_why` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PRC-07 RFQ × مورد مدعو - Invitations Child';

-- ── Table: proc_serial ──
CREATE TABLE `proc_serial` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `serial_no` varchar(80) NOT NULL,
  `item_id` int(10) unsigned NOT NULL,
  `lot_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'صنف ثم دفعة ثم ارقام - مدعوم لا مفروض',
  `supplier_id` int(10) unsigned NOT NULL DEFAULT 0,
  `order_id` int(10) unsigned NOT NULL DEFAULT 0,
  `receipt_id` int(10) unsigned NOT NULL DEFAULT 0,
  `warranty_until` date DEFAULT NULL,
  `warranty_ref` varchar(190) NOT NULL DEFAULT '',
  `warehouse_id` int(10) unsigned NOT NULL DEFAULT 0,
  `custodian_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'حائز العهدة',
  `asset_id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'الاصل المركب عليه',
  `installed_at` date DEFAULT NULL,
  `removed_at` date DEFAULT NULL,
  `repair_count` int(11) NOT NULL DEFAULT 0 COMMENT 'مشتق من سجل الاصلاح',
  `state` varchar(24) NOT NULL DEFAULT 'IN_STOCK',
  `disposed_at` date DEFAULT NULL,
  `policy_version` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_serial` (`company_id`,`item_id`,`serial_no`),
  KEY `ix_ser_asset` (`company_id`,`asset_id`),
  CONSTRAINT `chk_ser_no` CHECK (`serial_no` <> ''),
  CONSTRAINT `chk_ser_dates` CHECK (`removed_at` is null or `installed_at` is null or `removed_at` >= `installed_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='DEC-OPEN-15 سجل الرقم التسلسلي بدورة حياته';

-- ── Table: proc_stock_move ──
CREATE TABLE `proc_stock_move` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `item_id` int(11) NOT NULL,
  `warehouse_id` int(11) DEFAULT NULL,
  `move_type` varchar(20) NOT NULL COMMENT 'استلام/صرف/إرجاع/تحويل',
  `qty` decimal(12,2) NOT NULL DEFAULT 0.00,
  `unit_cost` decimal(18,4) DEFAULT NULL COMMENT 'تكلفة الوحدة بمعادل الدفاتر: الاستلام بفعليته + نصيبه الوصولي · الصرف بالمتوسط لحظته · NULL=حركة تاريخية غير مسعرة',
  `ref_type` varchar(30) DEFAULT NULL COMMENT 'proc_order/proc_issue/proc_receipt/يدوي',
  `ref_id` int(11) DEFAULT NULL,
  `note` varchar(255) DEFAULT NULL,
  `moved_at` datetime NOT NULL DEFAULT current_timestamp(),
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_proc_move_company` (`company_id`),
  KEY `idx_proc_move_item_wh` (`item_id`,`warehouse_id`),
  CONSTRAINT `chk_psm_return_needs_ref` CHECK (`move_type` <> 'مرتجع' or `ref_type` = 'issue' and `ref_id` is not null and `ref_id` > 0 or `note` like '%legacy_no_ref%')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: proc_stock_state ──
CREATE TABLE `proc_stock_state` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `item_id` int(10) unsigned NOT NULL,
  `warehouse_id` int(10) unsigned NOT NULL,
  `state_key` varchar(24) NOT NULL DEFAULT '' COMMENT 'GOOD او RESERVED او QUARANTINE او DAMAGED او EXPIRED',
  `qty` decimal(16,3) NOT NULL DEFAULT 0.000 COMMENT 'مشتق من proc_stock_move - لا يكتب بيد',
  `derive_rule` varchar(190) NOT NULL DEFAULT '',
  `computed_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sstate` (`company_id`,`item_id`,`warehouse_id`,`state_key`),
  CONSTRAINT `chk_ss_rule` CHECK (`derive_rule` <> '' and `state_key` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='WH-06 صنف × مخزن × حالة - سطر رصيد مشتق';

-- ── Table: proc_supplier ──
CREATE TABLE `proc_supplier` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `code` varchar(50) DEFAULT NULL,
  `name` varchar(200) NOT NULL,
  `supply_role` varchar(30) NOT NULL DEFAULT 'تشغيلي' COMMENT 'تشغيلي دائماً في هذه الوحدة',
  `dealing_nature` varchar(255) DEFAULT NULL COMMENT 'قطع/زيوت/فلاتر/خدمات إصلاح',
  `contact_person` varchar(150) DEFAULT NULL,
  `phone` varchar(50) DEFAULT NULL,
  `email` varchar(150) DEFAULT NULL,
  `address` mediumtext DEFAULT NULL,
  `payment_terms` varchar(100) DEFAULT NULL,
  `notes` mediumtext DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_proc_supplier_company` (`company_id`),
  KEY `idx_proc_supplier_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: proc_supplier_eval ──
CREATE TABLE `proc_supplier_eval` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `supplier_id` int(10) unsigned NOT NULL,
  `period_ym` char(7) NOT NULL DEFAULT '',
  `orders_count` int(11) NOT NULL DEFAULT 0 COMMENT 'مشتق',
  `on_time_pct` decimal(6,2) NOT NULL DEFAULT 0.00 COMMENT 'مشتق من proc_delivery_event',
  `reject_pct` decimal(6,2) NOT NULL DEFAULT 0.00 COMMENT 'مشتق من سندات الادخال',
  `variance_pct` decimal(6,2) NOT NULL DEFAULT 0.00 COMMENT 'مشتق من proc_invoice_match',
  `score` decimal(6,2) NOT NULL DEFAULT 0.00 COMMENT 'مشتق بقاعدة الوزن',
  `score_rule` varchar(190) NOT NULL DEFAULT '' COMMENT 'قاعدة الاشتقاق - لا رقم بلا قاعدة',
  `grade` varchar(24) NOT NULL DEFAULT '',
  `computed_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_seval` (`company_id`,`supplier_id`,`period_ym`),
  CONSTRAINT `chk_sev_rule` CHECK (`score_rule` <> '' and `period_ym` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PRC-16 مورد × فترة - سطر تقييم مشتق';

-- ── Table: proc_track_gap ──
CREATE TABLE `proc_track_gap` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `item_id` int(10) unsigned NOT NULL,
  `op_kind` varchar(24) NOT NULL DEFAULT '' COMMENT 'RECEIPT او ISSUE او TRANSFER او COUNT',
  `op_ref` varchar(60) NOT NULL DEFAULT '',
  `missing` varchar(190) NOT NULL DEFAULT '' COMMENT 'الحقول الناقصة مفصولة بواو',
  `policy_level` varchar(24) NOT NULL DEFAULT 'OPTIONAL',
  `resolved` tinyint(1) NOT NULL DEFAULT 0,
  `logged_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_gap_item` (`company_id`,`item_id`,`resolved`),
  CONSTRAINT `chk_gap_what` CHECK (`missing` <> '' and `op_kind` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='DEC-OPEN-15 نقص بيانات التتبع - قيد جودة لا حاجب عمل';

-- ── Table: proc_track_policy ──
CREATE TABLE `proc_track_policy` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned DEFAULT NULL COMMENT 'العدم يعني كل الكيانات — دلالة الكتالوج',
  `scope_kind` enum('CATEGORY','ITEM') NOT NULL COMMENT 'الفئة تعطي افتراضا والصنف يخصص',
  `scope_key` varchar(160) NOT NULL COMMENT 'اسم الفئة او معرف الصنف نصا',
  `version` int(10) unsigned NOT NULL DEFAULT 1,
  `effective_from` date NOT NULL,
  `effective_to` date DEFAULT NULL COMMENT 'العدم يعني سارية الى الان',
  `lot` enum('OFF','OPTIONAL','REQUIRED') NOT NULL DEFAULT 'OFF',
  `serial` enum('OFF','OPTIONAL','REQUIRED') NOT NULL DEFAULT 'OFF',
  `mfg_date` enum('OFF','OPTIONAL','REQUIRED') NOT NULL DEFAULT 'OFF',
  `expiry` enum('OFF','OPTIONAL','REQUIRED') NOT NULL DEFAULT 'OFF',
  `warranty` enum('OFF','OPTIONAL','REQUIRED') NOT NULL DEFAULT 'OFF',
  `expiry_enforce` enum('WARNING','APPROVAL_REQUIRED','HARD_BLOCK') NOT NULL DEFAULT 'WARNING',
  `issue_policy` enum('FIFO','FEFO','MANUAL') NOT NULL DEFAULT 'FIFO',
  `requalify` enum('ENABLED','DISABLED') NOT NULL DEFAULT 'DISABLED',
  `override_authority` varchar(190) NOT NULL DEFAULT '' COMMENT 'سلطة تجاوز الصلاحية - دور لا اسم',
  `why` varchar(600) NOT NULL DEFAULT '',
  `strict_why` varchar(600) NOT NULL DEFAULT '' COMMENT 'سبب رفع خاصية الى الزامي',
  `decision_ref` varchar(48) NOT NULL DEFAULT '',
  `changed_by` int(10) unsigned NOT NULL DEFAULT 0,
  `approved_by` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_scope_ver` (`company_id`,`scope_kind`,`scope_key`,`version`),
  KEY `ix_live` (`scope_kind`,`scope_key`,`effective_from`),
  CONSTRAINT `chk_tp_strict` CHECK (`lot` <> 'REQUIRED' and `serial` <> 'REQUIRED' and `mfg_date` <> 'REQUIRED' and `expiry` <> 'REQUIRED' and `warranty` <> 'REQUIRED' or `strict_why` <> ''),
  CONSTRAINT `chk_tp_auth` CHECK (`expiry_enforce` <> 'APPROVAL_REQUIRED' or `override_authority` <> ''),
  CONSTRAINT `chk_tp_fefo` CHECK (`issue_policy` <> 'FEFO' or `expiry` <> 'OFF'),
  CONSTRAINT `chk_tp_why` CHECK (`why` <> '' and `decision_ref` <> '' and `scope_key` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='DEC-OPEN-15 سياسة تتبع بمستويين وثماني خصائص ونسخ مؤرخة';

-- ── Table: proc_transfer ──
CREATE TABLE `proc_transfer` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `code` varchar(40) NOT NULL DEFAULT '',
  `from_wh_id` int(10) unsigned NOT NULL DEFAULT 0,
  `to_wh_id` int(10) unsigned NOT NULL DEFAULT 0,
  `reason` varchar(400) NOT NULL DEFAULT '',
  `sent_at` datetime DEFAULT NULL,
  `sent_by` int(10) unsigned NOT NULL DEFAULT 0,
  `received_at` datetime DEFAULT NULL,
  `received_by` int(10) unsigned NOT NULL DEFAULT 0,
  `in_transit_qty` decimal(16,3) NOT NULL DEFAULT 0.000 COMMENT 'مشتق - المرسل ناقص المستلم',
  `state` varchar(32) NOT NULL DEFAULT 'draft',
  `notes` varchar(500) NOT NULL DEFAULT '',
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `created_by` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_trf_code` (`company_id`,`code`),
  CONSTRAINT `chk_trf_diff` CHECK (`from_wh_id` <> `to_wh_id`),
  CONSTRAINT `chk_trf_why` CHECK (`reason` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='WH-13 امر تحويل × مخزنين - امر واحد';

-- ── Table: proc_transfer_line ──
CREATE TABLE `proc_transfer_line` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `transfer_id` int(10) unsigned NOT NULL,
  `item_id` int(10) unsigned NOT NULL DEFAULT 0,
  `item_name` varchar(190) NOT NULL DEFAULT '',
  `qty_sent` decimal(16,3) NOT NULL DEFAULT 0.000,
  `qty_received` decimal(16,3) NOT NULL DEFAULT 0.000,
  `qty_variance` decimal(16,3) NOT NULL DEFAULT 0.000 COMMENT 'مشتق',
  `variance_why` varchar(400) NOT NULL DEFAULT '',
  `lot_no` varchar(60) NOT NULL DEFAULT '',
  `serial_no` varchar(80) NOT NULL DEFAULT '',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_trfl` (`company_id`,`transfer_id`),
  KEY `fk_trfl_trf` (`transfer_id`),
  CONSTRAINT `fk_trfl_trf` FOREIGN KEY (`transfer_id`) REFERENCES `proc_transfer` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_trfl_qty` CHECK (`qty_sent` > 0),
  CONSTRAINT `chk_trfl_var` CHECK (`qty_variance` = 0 or `variance_why` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='WH-14 بند × امر تحويل - Lines Child';

-- ── Table: proc_warehouse ──
CREATE TABLE `proc_warehouse` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `code` varchar(50) DEFAULT NULL,
  `name` varchar(150) NOT NULL,
  `type` varchar(30) NOT NULL DEFAULT 'مخزن' COMMENT 'مخزن / ورشة / مباشر للآلية',
  `location` varchar(255) DEFAULT NULL,
  `notes` mediumtext DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_proc_wh_company` (`company_id`),
  KEY `idx_proc_wh_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: proc_wh_close ──
CREATE TABLE `proc_wh_close` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `warehouse_id` int(10) unsigned NOT NULL,
  `period_ym` char(7) NOT NULL DEFAULT '',
  `open_value` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'مشتق',
  `in_value` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'مشتق',
  `out_value` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'مشتق',
  `adj_value` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'مشتق من تسويات الجرد',
  `close_value` decimal(16,2) NOT NULL DEFAULT 0.00 COMMENT 'مشتق - فتح زائد وارد ناقص منصرف زائد تسوية',
  `balanced` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'مشتق - المعادلة تنطبق',
  `count_ref` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'جلسة الجرد المسندة',
  `closed_by` int(10) unsigned NOT NULL DEFAULT 0,
  `closed_at` datetime DEFAULT NULL,
  `state` varchar(32) NOT NULL DEFAULT 'open',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_whclose` (`company_id`,`warehouse_id`,`period_ym`),
  CONSTRAINT `chk_whc_period` CHECK (`period_ym` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='WH-18 شهر × مخزن - اقفال واحد';

-- ── Table: proc_wh_custodian ──
CREATE TABLE `proc_wh_custodian` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'معرف الاسناد — يولده النظام',
  `company_id` int(11) NOT NULL,
  `warehouse_id` int(11) NOT NULL COMMENT 'كود المخزن — موروث من الاب ويقفل',
  `employee_id` int(11) NOT NULL COMMENT 'مرجع الشخص بالموارد — من سجل الموظفين',
  `assign_type` enum('أساسي','بديل','مؤقت بالإنابة','مناوب بوردية') NOT NULL,
  `shift_name` enum('لا تنطبق','صباحية','مسائية','ليلية') NOT NULL DEFAULT 'لا تنطبق',
  `date_from` date NOT NULL,
  `date_to` date DEFAULT NULL,
  `perm_scope` enum('استلام وصرف وجرد وتحويل','استلام وصرف فقط','جرد فقط','قراءة') NOT NULL,
  `handover_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع محضر التسليم — يشتق عند الاقفال بتسليم',
  `assign_state` enum('نافذ','منتهٍ بتسليم','منتهٍ بلا تسليم') NOT NULL DEFAULT 'نافذ',
  `close_note` varchar(300) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `data_state` enum('حي','ملغي بمرجع') NOT NULL DEFAULT 'حي',
  `src_ref` varchar(120) NOT NULL DEFAULT '' COMMENT 'مرجع المصدر — من اي بوابة او استيراد جاء الصف',
  PRIMARY KEY (`id`),
  KEY `ix_pwc_wh` (`warehouse_id`,`assign_state`,`date_from`),
  KEY `ix_pwc_emp` (`employee_id`),
  KEY `ix_pwc_co` (`company_id`),
  CONSTRAINT `fk_pwc_emp` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`),
  CONSTRAINT `fk_pwc_wh` FOREIGN KEY (`warehouse_id`) REFERENCES `proc_warehouse` (`id`),
  CONSTRAINT `chk_pwc_period` CHECK (`date_to` is null or `date_to` >= `date_from`),
  CONSTRAINT `chk_pwc_closed_has_note` CHECK (`assign_state` = 'نافذ' or `close_note` is not null)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='WH-03 (حزمة -3): اسناد امناء المخازن — مخزن × شخص × فترة، والنافذ اليوم يشتق ولا يكتب';

-- ── Table: processed_operations ──
CREATE TABLE `processed_operations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `consumer` varchar(64) NOT NULL COMMENT 'اسم المستهلك (يوافق ems_event_consumers.consumer)',
  `doc_type` varchar(64) NOT NULL COMMENT 'نوع المستند المصدر (fin_unit_record · claim · …)',
  `doc_id` bigint(20) unsigned NOT NULL COMMENT 'معرّف المستند المصدر',
  `effect_kind` varchar(64) NOT NULL COMMENT 'نوع الأثر المعالَج (revenue · supplier_due · …)',
  `event_id` bigint(20) unsigned DEFAULT NULL COMMENT 'الحدث الذي حمل المعالجة (تتبع لا مفتاح)',
  `processed_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_processed_op` (`consumer`,`doc_type`,`doc_id`,`effect_kind`),
  KEY `ix_po_doc` (`doc_type`,`doc_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='N-06 ركن ③: عطالة المستهلك على مستوى (المستند × الأثر) — Insert-only';

-- ── Table: products ──
CREATE TABLE `products` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `product_code` varchar(50) NOT NULL,
  `name` varchar(200) NOT NULL,
  `product_type` enum('خدمة','معدة','مادة') NOT NULL DEFAULT 'خدمة',
  `revenue_model` enum('hourly','ton','meter') DEFAULT NULL,
  `default_uom` varchar(30) DEFAULT NULL,
  `standard_price` decimal(14,2) NOT NULL DEFAULT 0.00,
  `currency` enum('USD','SDG') NOT NULL DEFAULT 'USD',
  `description` text DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_products_company_code` (`company_id`,`product_code`),
  KEY `idx_prod_scope` (`company_id`,`is_deleted`),
  KEY `idx_prod_model` (`revenue_model`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: project ──
CREATE TABLE `project` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) DEFAULT NULL,
  `client_id` int(11) DEFAULT NULL COMMENT '┘àÏ╣Ï▒┘ü Ïº┘äÏ╣┘à┘è┘ä ┘à┘å Ï¼Ï»┘ê┘ä clients',
  `name` varchar(150) NOT NULL,
  `client` varchar(150) NOT NULL,
  `location` varchar(200) NOT NULL,
  `project_code` varchar(50) DEFAULT NULL COMMENT 'كود المشروع',
  `mine_code` varchar(100) DEFAULT NULL COMMENT 'كود المنجم',
  `category` varchar(100) DEFAULT NULL COMMENT 'الفئة',
  `sub_sector` varchar(100) DEFAULT NULL COMMENT 'القطاع الفرعي',
  `state` varchar(100) DEFAULT NULL COMMENT 'الولاية',
  `region` varchar(100) DEFAULT NULL COMMENT 'المنطقة',
  `nearest_market` varchar(100) DEFAULT NULL COMMENT 'أقرب سوق',
  `latitude` varchar(50) DEFAULT NULL COMMENT 'خط العرض',
  `longitude` varchar(50) DEFAULT NULL COMMENT 'خط الطول',
  `total` varchar(50) NOT NULL,
  `status` tinyint(1) DEFAULT 1,
  `created_by` int(11) DEFAULT NULL COMMENT 'معرف المستخدم المنشئ',
  `create_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp() COMMENT 'تاريخ آخر تحديث',
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_project_created_by` (`created_by`),
  KEY `idx_client_id` (`client_id`),
  KEY `idx_mine_code` (`mine_code`),
  KEY `idx_project_status_deleted` (`status`,`is_deleted`),
  CONSTRAINT `fk_project_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_project_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: quotations ──
CREATE TABLE `quotations` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `quotation_code` varchar(50) NOT NULL,
  `client_id` int(11) DEFAULT NULL,
  `opportunity_id` int(10) unsigned DEFAULT NULL,
  `currency` enum('USD','SDG') NOT NULL DEFAULT 'USD',
  `amount_total` decimal(14,2) NOT NULL DEFAULT 0.00,
  `validity_date` date DEFAULT NULL,
  `payment_terms` varchar(255) DEFAULT NULL,
  `state` enum('مسودة','مقدم','مقبول','مرفوض') NOT NULL DEFAULT 'مسودة',
  `notes` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_quotations_company_code` (`company_id`,`quotation_code`),
  KEY `idx_quo_scope` (`company_id`,`is_deleted`),
  KEY `idx_quo_opp` (`opportunity_id`),
  KEY `idx_quo_state` (`state`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: rate_book_lines ──
CREATE TABLE `rate_book_lines` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `book_id` int(11) NOT NULL,
  `equipment_type_id` int(11) NOT NULL COMMENT 'فئةُ المعدة — equipments_types.id',
  `work_model` enum('hour','day','shift','month','ton','meter','trip','cbm') NOT NULL DEFAULT 'hour',
  `tier_from_days` int(11) NOT NULL DEFAULT 1 COMMENT 'بدايةُ شريحة المدة بالأيام',
  `tier_to_days` int(11) DEFAULT NULL COMMENT 'نهايتُها — NULL = ما فوق',
  `unit_price` decimal(14,2) NOT NULL COMMENT 'سعرُ الوحدة في هذه الشريحة',
  `min_hire_days` int(11) NOT NULL DEFAULT 1 COMMENT 'الحدُّ الأدنى لمدة الإيجار',
  `min_hours_per_day` decimal(6,2) DEFAULT NULL COMMENT 'الحدُّ الأدنى للساعات اليومية المفوترة',
  `mobilization_fee` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT 'رسمُ التعبئة/الترحيل',
  `operator_included` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'أالمشغّلُ ضمن السعر؟',
  `fuel_included` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'أالوقودُ ضمن السعر؟',
  `note` varchar(255) DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_rate_tier` (`company_id`,`book_id`,`equipment_type_id`,`work_model`,`tier_from_days`),
  KEY `ix_line_book` (`company_id`,`book_id`),
  KEY `ix_line_lookup` (`company_id`,`equipment_type_id`,`work_model`,`tier_from_days`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='بنودُ دفتر الأسعار — سعرٌ لكل (فئة × نموذج عمل × شريحة مدة) (RENTAL-CORE ②)';

-- ── Table: rate_books ──
CREATE TABLE `rate_books` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `book_code` varchar(40) NOT NULL COMMENT 'كودُ الدفتر — فريد داخل الشركة',
  `name` varchar(160) NOT NULL,
  `currency` enum('USD','SDG') NOT NULL DEFAULT 'USD',
  `client_id` int(11) DEFAULT NULL COMMENT 'دفترٌ خاصٌّ بعميل — NULL يعني الدفترَ العام',
  `valid_from` date NOT NULL,
  `valid_to` date DEFAULT NULL COMMENT 'NULL = مفتوح',
  `state` enum('مسودة','معتمد','منتهٍ') NOT NULL DEFAULT 'مسودة',
  `approved_by` int(11) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `note` varchar(255) DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_book_code` (`company_id`,`book_code`),
  KEY `ix_book_live` (`company_id`,`state`,`valid_from`,`valid_to`),
  KEY `ix_book_client` (`company_id`,`client_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='دفاترُ الأسعار — رأسُ الدفتر بسريانه وعملته (RENTAL-CORE ②)';

-- ── Table: readiness_lines ──
CREATE TABLE `readiness_lines` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `readiness_code` varchar(50) NOT NULL,
  `contract_ref` int(11) NOT NULL,
  `name` enum('جاهزية الأسطول','جاهزية الموردين','جاهزية القوى','جاهزية التمويل','جاهزية الصيانة','جاهزية الموقع') NOT NULL DEFAULT 'جاهزية الأسطول',
  `source_ref` varchar(60) DEFAULT NULL,
  `required` varchar(255) DEFAULT NULL,
  `available` varchar(255) DEFAULT NULL,
  `state` enum('مجتاز','فجوة','قيد المعالجة') NOT NULL DEFAULT 'قيد المعالجة',
  `gap_note` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_rdl_company_code` (`company_id`,`readiness_code`),
  KEY `idx_rdl_scope` (`company_id`,`is_deleted`),
  KEY `idx_rdl_contract` (`contract_ref`),
  KEY `idx_rdl_state` (`state`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='INJAZ-S05 §6.12 — بنود فحص الجاهزية الستة بحالاتها لكل عقد';

-- ── Table: rec_applications ──
CREATE TABLE `rec_applications` (
  `app_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `vac_id` int(10) unsigned NOT NULL,
  `applicant_name` varchar(120) NOT NULL,
  `applicant_phone` varchar(40) DEFAULT NULL,
  `cv_ref` varchar(190) DEFAULT NULL COMMENT '③ السيرةُ الذاتية — مرجعُ الملف',
  `stage` enum('received','screening','interview','practical_test','offer','offer_accepted','contracting','onboarded','probation','confirmed','rejected','withdrawn') NOT NULL DEFAULT 'received' COMMENT 'الخطواتُ ③→⑩ — والرفضُ والانسحابُ خروجان معلَنان',
  `stage_note` varchar(255) DEFAULT NULL,
  `interview_at` datetime DEFAULT NULL,
  `test_score` decimal(5,2) DEFAULT NULL COMMENT '⑥ الاختبارُ العمليُّ للمشغّل',
  `offer_ref` varchar(120) DEFAULT NULL,
  `employee_id` int(11) DEFAULT NULL COMMENT '⑨ المباشرة — يربط بموظفٍ حقيقيٍّ في employees',
  `probation_end` date DEFAULT NULL COMMENT '⑩ نهايةُ فترة التجربة',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`app_id`),
  KEY `ix_app_vac` (`vac_id`,`stage`),
  CONSTRAINT `fk_app_vac` FOREIGN KEY (`vac_id`) REFERENCES `rec_vacancies` (`vac_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: rec_stage_log ──
CREATE TABLE `rec_stage_log` (
  `log_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `app_id` int(10) unsigned NOT NULL,
  `from_stage` varchar(30) DEFAULT NULL,
  `to_stage` varchar(30) NOT NULL,
  `note` varchar(255) DEFAULT NULL,
  `by_person` int(11) DEFAULT NULL,
  `at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`log_id`),
  KEY `ix_rsl_app` (`app_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='سجلُّ التقدم — Insert-only: من فعل ماذا ومتى';

-- ── Table: rec_vacancies ──
CREATE TABLE `rec_vacancies` (
  `vac_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `vacancy_no` varchar(30) NOT NULL,
  `job_title_id` int(11) DEFAULT NULL COMMENT 'job_titles — قاموسُ المسميات (SEC-01)',
  `title_text` varchar(120) NOT NULL,
  `org_unit_id` int(11) DEFAULT NULL COMMENT 'org_units — الإدارةُ الطالبة',
  `site_scope` varchar(80) DEFAULT NULL,
  `headcount` int(11) NOT NULL DEFAULT 1,
  `reason` varchar(255) DEFAULT NULL,
  `state` enum('draft','open','filled','cancelled') NOT NULL DEFAULT 'open',
  `posted_at` date DEFAULT NULL COMMENT '② نشرُ الوظيفة',
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`vac_id`),
  UNIQUE KEY `uq_vac` (`company_id`,`vacancy_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='① طلبُ الشاغر — أولُ الدورة العشرية';

-- ── Table: recurring_tasks ──
CREATE TABLE `recurring_tasks` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `template_id` int(10) unsigned NOT NULL,
  `freq` varchar(12) NOT NULL DEFAULT 'monthly' COMMENT 'daily|weekly|monthly|quarterly',
  `day_key` tinyint(3) unsigned NOT NULL DEFAULT 1 COMMENT 'يوم الأسبوع/الشهر بحسب النمط',
  `next_run_at` datetime DEFAULT NULL,
  `last_run_at` datetime DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `ix_rt_next` (`active`,`next_run_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: repair01_backlog_disposition ──
CREATE TABLE `repair01_backlog_disposition` (
  `consumer_key` varchar(64) NOT NULL,
  `event_key` varchar(120) NOT NULL,
  `backlog_count` int(11) NOT NULL DEFAULT 0,
  `disposition` enum('REPLAY_REQUIRED','EFFECT_ALREADY_REALIZED','AUDIT_ONLY','SUPERSEDED','MANUAL_RECONCILIATION','CLOSE_WITH_REASON') NOT NULL,
  `rule_applied` varchar(64) NOT NULL COMMENT 'اي قاعدة انتجت الحكم',
  `witness` varchar(500) NOT NULL,
  `watermark_id` bigint(20) DEFAULT NULL COMMENT 'اخر حدث مشمول بالحكم — نقطة الماء للدفعات',
  `replayed` int(11) NOT NULL DEFAULT 0 COMMENT 'ما صرف فعلا — صفر طوال جولة الضبط',
  `snapshot_id` varchar(48) NOT NULL,
  `ruled_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`consumer_key`,`event_key`),
  KEY `ix_bd_disp` (`disposition`),
  CONSTRAINT `chk_bd_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_bd_rule` CHECK (`rule_applied` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='امر الضبط 8 · تصريف المتراكم التاريخي — تصنيف قبل تشغيل وصفر Replay في جولة الضبط';

-- ── Table: repair01_build_ready ──
CREATE TABLE `repair01_build_ready` (
  `target_uid` varchar(16) NOT NULL,
  `requirement_id` varchar(40) NOT NULL DEFAULT '' COMMENT 'او تصريف موثق في الكون',
  `owner_domain` varchar(12) NOT NULL DEFAULT '',
  `canonical_entity` varchar(80) NOT NULL DEFAULT '' COMMENT 'فارغ = غير مسمى بعد — حاجب للمعاملات',
  `grain` varchar(190) NOT NULL DEFAULT '' COMMENT 'حبة التصميم من الدفتر — لا تؤلف',
  `realization_type` varchar(32) NOT NULL DEFAULT 'UNDECIDED' COMMENT 'MENU_SCREEN_DESIGNED/CHILD_OR_TAB/PROJECTION_REPORT/UNDECIDED',
  `source_of_truth` varchar(190) NOT NULL DEFAULT '',
  `sm_applicable` enum('YES','NO','UNDETERMINED') NOT NULL DEFAULT 'UNDETERMINED' COMMENT 'STATE_MACHINE_APPLICABLE — بالانطباق لا بالعدد',
  `wf_applicable` enum('YES','NO','UNDETERMINED') NOT NULL DEFAULT 'UNDETERMINED' COMMENT 'WORKFLOW_APPLICABLE',
  `decision_impact` varchar(24) NOT NULL DEFAULT '' COMMENT 'NOT_AFFECTED/AFFECTED_PENDING — على مستوى الهدف لا البرنامج',
  `build_blocker` varchar(400) NOT NULL DEFAULT '' COMMENT 'الحاجب المسمى — وفارغه يعني لا حاجب',
  `build_ready` enum('YES','NO') NOT NULL DEFAULT 'NO',
  `witness` varchar(600) NOT NULL COMMENT 'كيف اشتق كل حقل — ولا صف بلا شاهد',
  `snapshot_id` varchar(48) NOT NULL,
  `gated_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`target_uid`),
  KEY `ix_br_ready` (`build_ready`),
  KEY `ix_br_owner` (`owner_domain`),
  CONSTRAINT `chk_br_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_br_yes` CHECK (`build_ready` = 'NO' or `build_blocker` = '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='امر الضبط 3 · بوابة جاهزية البناء — صف لكل هدف غير مبني بحاجبه المسمى';

-- ── Table: repair01_build_ready_history ──
CREATE TABLE `repair01_build_ready_history` (
  `hid` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `gated_run` datetime NOT NULL,
  `snapshot_id` varchar(48) NOT NULL,
  `target_uid` varchar(16) NOT NULL,
  `requirement_id` varchar(40) NOT NULL DEFAULT '',
  `build_ready` varchar(8) NOT NULL,
  `build_blocker` varchar(400) NOT NULL DEFAULT '',
  PRIMARY KEY (`hid`),
  KEY `ix_brh_run` (`gated_run`),
  KEY `ix_brh_tgt` (`target_uid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='تاريخ تمريرات بوابة الجاهزية — نسخة كل تمريرة بلقطتها، قراءة اثر لا حكم';

-- ── Table: repair01_canon_screen_bind ──
CREATE TABLE `repair01_canon_screen_bind` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `route` varchar(190) NOT NULL COMMENT 'مسار الصف المعتمد — ومفتاح الرد',
  `before_screen_id` varchar(12) NOT NULL DEFAULT '' COMMENT 'المعرف قبل — والفراغ هو الحال الغالب',
  `after_screen_id` varchar(12) NOT NULL COMMENT 'المعرف من سجل الاسطح المبني',
  `registry_route` varchar(200) NOT NULL COMMENT 'مسار السجل الذي جسر — ولا جسر باسم',
  `live_positions` int(11) NOT NULL DEFAULT 0 COMMENT 'مواضع حية يفكها هذا الربط',
  `witness` varchar(600) NOT NULL COMMENT 'شاهد الربط — ولا صف بلا شاهد',
  `snapshot_id` varchar(48) NOT NULL,
  `applied_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_csb_route` (`route`),
  CONSTRAINT `chk_csb_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_csb_snapshot` CHECK (`snapshot_id` <> ''),
  CONSTRAINT `chk_csb_after` CHECK (`after_screen_id` <> ''),
  CONSTRAINT `chk_csb_changed` CHECK (`before_screen_id` <> `after_screen_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-02 6 س7 · ربط السجل المعتمد بمعرف الشاشة — قبل وبعد وهو مصدر التراجع';

-- ── Table: repair01_canonical_source ──
CREATE TABLE `repair01_canonical_source` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `entity` varchar(64) NOT NULL COMMENT 'الكيان المكتوب — حقيقة الاعمال',
  `writers` smallint(5) unsigned NOT NULL DEFAULT 0 COMMENT 'عدد الاسطح الحية التي تكتبه',
  `owners` smallint(5) unsigned NOT NULL DEFAULT 0 COMMENT 'عدد الادارات المالكة لتلك الاسطح',
  `rule_code` enum('N1_ARTIFACT_NAME_IDENTITY','N2_DECLARED_OVER_INFERRED','N3_CROSS_OWNER_NEEDS_CONTRACT','N4_TIE_DECLARED') NOT NULL COMMENT 'القاعدة التي حكمت — والمقياس يعلن ايتها',
  `canonical_screen` varchar(12) NOT NULL DEFAULT '' COMMENT 'المصدر القانوني حين يحسم بقياس — وفارغ حين لا يحسم',
  `canonical_owner` varchar(12) NOT NULL DEFAULT '' COMMENT 'الادارة المالكة للمصدر القانوني',
  `writer_screens` varchar(500) NOT NULL DEFAULT '' COMMENT 'كل الكتاب بمعرفاتهم وملاكهم',
  `resolved` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'هل حسم بقياس ام اعلن مفتوحا',
  `witness` varchar(600) NOT NULL COMMENT 'شاهد الحكم او شاهد تعذره — ولا صف بلا شاهد',
  `snapshot_id` varchar(48) NOT NULL COMMENT 'اللقطة التي قيس عليها',
  `measured_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_entity` (`entity`),
  KEY `ix_rule` (`rule_code`),
  KEY `ix_resolved` (`resolved`),
  CONSTRAINT `chk_cs_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_cs_snapshot` CHECK (`snapshot_id` <> ''),
  CONSTRAINT `chk_cs_resolved` CHECK (`resolved` = 0 or `canonical_screen` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-02 5-9 · المصدر القانوني للحقيقة المكررة — بقاعدة وشاهد لكل كيان';

-- ── Table: repair01_cross_contract ──
CREATE TABLE `repair01_cross_contract` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `entity` varchar(64) NOT NULL COMMENT 'الكيان المكتوب',
  `entity_verdict` enum('NOT_A_DUPLICATE','CONTRACTED','DIRECT_WRITE_BREACH') NOT NULL COMMENT 'حكم الكيان جملة بعد اسقاط من ليس كاتبا',
  `screen_id` varchar(12) NOT NULL COMMENT 'الكاتب',
  `owner_code` varchar(12) NOT NULL DEFAULT '' COMMENT 'ادارة الكاتب',
  `grain_rule` varchar(32) NOT NULL DEFAULT '' COMMENT 'قاعدة نسبة الكيان اليه',
  `raw_writes` smallint(5) unsigned NOT NULL DEFAULT 0 COMMENT 'جمل الكتابة الخامة على الكيان في مداه الخاص',
  `gates` varchar(200) NOT NULL DEFAULT '' COMMENT 'الابواب المسماة: ناشر او خدمة مجال',
  `writer_verdict` enum('X0_NO_MEASURED_WRITE','X1_SERVICE_MEDIATED','X2_RAW_DIRECT') NOT NULL COMMENT 'حكم الكاتب — ثلاثة لا اثنان',
  `witness` varchar(600) NOT NULL COMMENT 'شاهد الحكم — ولا صف بلا شاهد',
  `snapshot_id` varchar(48) NOT NULL COMMENT 'اللقطة التي قيس عليها',
  `measured_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ent_scr` (`entity`,`screen_id`),
  KEY `ix_ent_verdict` (`entity_verdict`),
  KEY `ix_wr_verdict` (`writer_verdict`),
  CONSTRAINT `chk_cx_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_cx_snapshot` CHECK (`snapshot_id` <> ''),
  CONSTRAINT `chk_cx_raw` CHECK (`writer_verdict` = 'X2_RAW_DIRECT' and `raw_writes` > 0 or `writer_verdict` <> 'X2_RAW_DIRECT' and `raw_writes` = 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-02 5-9 · عقد الكتابة العابرة مقيسا من الاثر — بشاهد لكل كاتب';

-- ── Table: repair01_debt_register ──
CREATE TABLE `repair01_debt_register` (
  `class_code` varchar(24) NOT NULL,
  `class_name_ar` varchar(160) NOT NULL,
  `measure_sql` text NOT NULL COMMENT 'العدد يقاس من المخزن ولا يكتب يدويا',
  `measure_tool` varchar(200) NOT NULL DEFAULT '' COMMENT 'امر مسح كود يطبع عددا واحدا - لصنف مقياسه ليس استعلاما',
  `measured_count` int(11) NOT NULL DEFAULT -1 COMMENT '-1 = لم يقس بعد',
  `measured_at` datetime DEFAULT NULL,
  `blocking_level` enum('BLOCKING','MAJOR','MINOR','INFORMATIONAL') NOT NULL,
  `assigned_wave` varchar(16) NOT NULL,
  `debt_owner` varchar(24) NOT NULL DEFAULT '',
  `exit_criteria` varchar(255) NOT NULL,
  `owner_ruling` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`class_code`),
  CONSTRAINT `chk_edc_exit` CHECK (`exit_criteria` <> ''),
  CONSTRAINT `chk_edc_owner` CHECK (`blocking_level` <> 'BLOCKING' or `debt_owner` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: repair01_decision_audit ──
CREATE TABLE `repair01_decision_audit` (
  `decision_id` varchar(40) NOT NULL,
  `verdict` varchar(40) NOT NULL COMMENT 'الاحكام الخمسة بنص البند 12',
  `why` varchar(400) NOT NULL,
  `audited_at` datetime NOT NULL,
  PRIMARY KEY (`decision_id`),
  KEY `ix_dcaud_v` (`verdict`),
  CONSTRAINT `chk_w135_aud_v` CHECK (`verdict` in ('VALID_APPROVAL','MISSING_APPROVAL_REFERENCE','SYSTEM_ASSUMED_APPROVAL','CONFLICTING_APPROVAL','LEGACY_UNVERIFIED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='مراجعة عكسية لقرارات المالك - امر 2026-08-26 البند 12';

-- ── Table: repair01_decision_impact ──
CREATE TABLE `repair01_decision_impact` (
  `decision_id` varchar(32) NOT NULL,
  `axis` enum('DOCUMENTS','DEPARTMENTS','SCREENS','FIELDS','GRAIN','SOURCE_OF_TRUTH','DATA','PERMISSIONS','STATE_MACHINES','APPROVALS','EVENTS','INTEGRATIONS','TESTS','MIGRATION') NOT NULL COMMENT 'محاور MASTER_EXEC §4-5 الاربعة عشر',
  `impact` text DEFAULT NULL COMMENT 'الاثر — منقولا حرفا من مصدره',
  `impact_source` varchar(120) NOT NULL DEFAULT '' COMMENT 'من اين نقل — ولا اثر بلا مصدر يسميه',
  `status` enum('PROJECTED','NEEDS_ADJUDICATION','NOT_APPLICABLE') NOT NULL DEFAULT 'NEEDS_ADJUDICATION' COMMENT 'PROJECTED اسقط بدليل · NEEDS_ADJUDICATION لا يشتق مكانيكيا',
  `blocked_why` varchar(400) NOT NULL DEFAULT '' COMMENT 'سبب عدم الاسقاط — مقيسا لا مظنونا',
  `snapshot_id` varchar(48) NOT NULL DEFAULT '',
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`decision_id`,`axis`),
  KEY `ix_di_status` (`status`),
  CONSTRAINT `chk_di_projected` CHECK (`status` <> 'PROJECTED' or `impact` is not null and `impact_source` <> ''),
  CONSTRAINT `chk_di_blocked` CHECK (`status` <> 'NEEDS_ADJUDICATION' or `blocked_why` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AMD-01 المرحلة 4 — سجل اثر القرار باربعة عشر محورا';

-- ── Table: repair01_decision_screen_bridge ──
CREATE TABLE `repair01_decision_screen_bridge` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `decision_id` varchar(32) NOT NULL COMMENT 'القرار الحاكم',
  `token_raw` varchar(190) NOT NULL COMMENT 'المفردة كما وردت في المصدر الحاكم — لا تُصحح',
  `resolution` enum('SCREEN','UNIT','SCOPE_CLASS','UNRESOLVED') NOT NULL COMMENT 'صنف الحل: سطح بعينه · نطاق · طبقة معلنة · متعذر',
  `unit_code` varchar(12) NOT NULL DEFAULT '' COMMENT 'رمز النطاق حين يُحل إلى نطاق',
  `screen_id` varchar(12) NOT NULL DEFAULT '' COMMENT 'معرف السطح حين يُحل إلى سطح',
  `scope_class` varchar(40) NOT NULL DEFAULT '' COMMENT 'الطبقة المعلنة حين يكون المدى صنفا لا فردا',
  `bridge_rule` varchar(48) NOT NULL COMMENT 'القاعدة التي حلت المفردة — T1..T4',
  `bridge_witness` varchar(400) NOT NULL COMMENT 'شاهد الحل — ولا حل بلا شاهد',
  `snapshot_id` varchar(48) NOT NULL DEFAULT '' COMMENT 'اللقطة التي قيس عليها',
  `resolved_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_dec_token` (`decision_id`,`token_raw`),
  KEY `ix_res` (`resolution`),
  KEY `ix_scr` (`screen_id`),
  KEY `ix_unit` (`unit_code`),
  CONSTRAINT `chk_bridge_witness` CHECK (`bridge_witness` <> ''),
  CONSTRAINT `chk_bridge_payload` CHECK (`resolution` = 'SCREEN' and `screen_id` <> '' or `resolution` = 'UNIT' and `unit_code` <> '' or `resolution` = 'SCOPE_CLASS' and `scope_class` <> '' or `resolution` = 'UNRESOLVED')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AMD-01 م4 · جسر مفردات الأثر الحرة إلى المعرفات — بشاهد لكل حل';

-- ── Table: repair01_decisions ──
CREATE TABLE `repair01_decisions` (
  `decision_id` varchar(32) NOT NULL,
  `domain` varchar(120) NOT NULL DEFAULT '',
  `question` text DEFAULT NULL,
  `current_state` text DEFAULT NULL,
  `options` text DEFAULT NULL,
  `recommended` text DEFAULT NULL,
  `owner_decision` text DEFAULT NULL,
  `status` enum('APPROVED','NEEDS_OWNER_DECISION') NOT NULL DEFAULT 'NEEDS_OWNER_DECISION',
  `blocking_level` enum('STRUCTURAL_TARGET_BLOCKER','READY_TO_BUILD_BLOCKER','UAT_BLOCKER','GO_LIVE_BLOCKER','CONFIG_PENDING','NONE','STRUCTURAL_BLOCKER','BUILD_BLOCKER','ENFORCEMENT_BLOCKER') DEFAULT NULL COMMENT 'درجات MASTER_EXEC §3 الست — والقديمة تبقى حتى يحكم على كل صف من جديد',
  `config_pending_stage` varchar(190) NOT NULL DEFAULT '' COMMENT 'المرحلة التي تصير عندها القيمة المؤجلة حاجزا — MASTER_EXEC §3',
  `blocker_type` enum('STRUCTURAL','THRESHOLD','حاجز إنفاذ','قيمة تضبط','محسوم آلية ومفتوح قيمة') DEFAULT NULL COMMENT 'محوران: بنيوي/عتبة (RPR-PATCH-01) ومفردات AMD-01 الثلاث للاحد عشر',
  `blocking_reason` varchar(255) NOT NULL DEFAULT '',
  `affected_documents` text DEFAULT NULL,
  `affected_screens` text DEFAULT NULL,
  `affected_rules` text DEFAULT NULL,
  `migration_impact` text DEFAULT NULL,
  `code_impact` text DEFAULT NULL,
  `evidence` text DEFAULT NULL,
  `approved_by` varchar(120) NOT NULL DEFAULT '',
  `approved_at` varchar(40) NOT NULL DEFAULT '',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `decision_source` varchar(190) NOT NULL DEFAULT '' COMMENT 'مصدر القرار - وثيقة او محادثة او امر',
  `owner_decision_reference` varchar(300) NOT NULL DEFAULT '' COMMENT 'مرجع جواب المالك بدليله',
  `recorded_by` varchar(120) NOT NULL DEFAULT '' COMMENT 'من قيد القرار في المخزن',
  `evidence_ref` varchar(300) NOT NULL DEFAULT '' COMMENT 'تجزئة او مسار الدليل',
  `effective_from` date DEFAULT NULL COMMENT 'سريان القرار',
  `amd01_verdict` enum('OPEN_VALID','ALREADY_DECIDED','SUPERSEDED','CONFIG_PENDING','WRONG_BLOCKER_CLASS','CONFLICT') DEFAULT NULL COMMENT 'حكم المراجعة العكسية السداسي — AMD-01 المرحلة 2',
  `amd01_verdict_ref` varchar(300) NOT NULL DEFAULT '' COMMENT 'مرجع الحكم — ولا حكم بلا مرجع',
  PRIMARY KEY (`decision_id`),
  KEY `k_status` (`status`),
  KEY `k_block` (`blocking_level`),
  KEY `k_btype` (`blocker_type`),
  CONSTRAINT `chk_w135_appr_ref` CHECK (`recorded_by` = '' or `status` <> 'APPROVED' or `owner_decision_reference` <> ''),
  CONSTRAINT `chk_dec_cfg_stage` CHECK (`blocking_level` <> 'CONFIG_PENDING' or `config_pending_stage` <> ''),
  CONSTRAINT `chk_dec_verdict_ref` CHECK (`amd01_verdict` is null or `amd01_verdict_ref` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: repair01_departments ──
CREATE TABLE `repair01_departments` (
  `canonical_code` varchar(12) NOT NULL,
  `display_order` smallint(5) unsigned DEFAULT NULL,
  `name_ar` varchar(160) NOT NULL,
  `sector` enum('CORPORATE','OPERATIONAL','OUTSIDE') NOT NULL,
  `parent_code` varchar(12) DEFAULT NULL,
  `note` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`canonical_code`),
  KEY `k_order` (`display_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: repair01_dept_crosswalk ──
CREATE TABLE `repair01_dept_crosswalk` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `legacy_name` varchar(160) NOT NULL,
  `canonical_code` varchar(12) NOT NULL,
  `verdict` enum('MAP','SPLIT','RECLASSIFY','NEW') NOT NULL,
  `split_rule` varchar(255) NOT NULL DEFAULT '',
  `note` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `k_legacy` (`legacy_name`),
  KEY `k_canon` (`canonical_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: repair01_event_effect_crosswalk ──
CREATE TABLE `repair01_event_effect_crosswalk` (
  `event_key` varchar(120) NOT NULL,
  `classification` varchar(24) NOT NULL DEFAULT '' COMMENT 'BUSINESS/AUDIT/RETIRED/NEEDS_ADJUDICATION',
  `occurrences` int(11) NOT NULL DEFAULT 0,
  `needs_effect` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'حدث اعمال يستلزم اثرا',
  `subscriptions` int(11) NOT NULL DEFAULT 0 COMMENT 'اشتراكات فعالة',
  `effect_consumers` int(11) NOT NULL DEFAULT 0 COMMENT 'مستهلكو اثر write غير حارس',
  `watch_consumers` int(11) NOT NULL DEFAULT 0 COMMENT 'حراس notify',
  `contracts_full` int(11) NOT NULL DEFAULT 0 COMMENT 'اشتراكات بعقد اثر كامل الخمسة',
  `last_progress` datetime DEFAULT NULL COMMENT 'اخر تسليم ناجح لهذا النوع',
  `backlog` int(11) NOT NULL DEFAULT 0 COMMENT 'وقائع خلف ابعد مؤشر مستهلك',
  `final_status` varchar(32) NOT NULL DEFAULT '' COMMENT 'EFFECT_COVERED/GUARD_ONLY/AUDIT_ONLY/RETIRED/NEEDS_ADJUDICATION',
  `witness` varchar(500) NOT NULL,
  `snapshot_id` varchar(48) NOT NULL,
  `built_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`event_key`),
  KEY `ix_eec_status` (`final_status`),
  CONSTRAINT `chk_eec_witness` CHECK (`witness` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='امر الضبط 7 · السجل الموحد: نوع الحدث ومنتجه واشتراكه وعقده ومتراكمه — مقامات مفصولة';

-- ── Table: repair01_events ──
CREATE TABLE `repair01_events` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `event_code` varchar(80) NOT NULL,
  `name` varchar(255) NOT NULL DEFAULT '',
  `wave` varchar(8) NOT NULL DEFAULT '',
  `source_unit` varchar(160) NOT NULL DEFAULT '',
  `source_screen` varchar(255) NOT NULL DEFAULT '',
  `idempotency_key` varchar(255) NOT NULL DEFAULT '',
  `consumers` text DEFAULT NULL,
  `effect_type` varchar(160) NOT NULL DEFAULT '',
  `retry_policy` varchar(80) NOT NULL DEFAULT '',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `trigger_rule` varchar(400) NOT NULL DEFAULT '' COMMENT 'المحفز - ما الذي يطلقه',
  `min_payload` varchar(600) NOT NULL DEFAULT '' COMMENT 'الحمولة الدنيا',
  `consumer_list` text DEFAULT NULL COMMENT 'كل مستهلك فعلي بالاسم',
  `consumer_effect` text DEFAULT NULL COMMENT 'أثر كل مستهلك على حدة',
  `preconditions` varchar(600) NOT NULL DEFAULT '' COMMENT 'الشروط المسبقة',
  `failure_policy` varchar(400) NOT NULL DEFAULT '' COMMENT 'سلوك الفشل',
  `compensation` varchar(400) NOT NULL DEFAULT '' COMMENT 'التعويض',
  `contract_status` enum('NONE','RECORDED') NOT NULL DEFAULT 'NONE' COMMENT 'حدث بلا عقد أثر مسجل لا ينفذ',
  `contract_rule` varchar(48) NOT NULL DEFAULT '',
  `contract_stage` varchar(8) NOT NULL DEFAULT '' COMMENT 'المرحلة التي كتبت العقد',
  PRIMARY KEY (`id`),
  KEY `k_code` (`event_code`),
  KEY `k_wave` (`wave`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: repair01_evidence_closure ──
CREATE TABLE `repair01_evidence_closure` (
  `requirement_id` varchar(40) NOT NULL,
  `screen_id` varchar(12) NOT NULL DEFAULT '',
  `req_type` varchar(24) NOT NULL DEFAULT '',
  `before_state` varchar(40) NOT NULL COMMENT 'حالة amd01_state قبل الاغلاق — ومفتاح الرد',
  `checks_passed` varchar(200) NOT NULL COMMENT 'E1..E4 التي اجتيزت باسمها',
  `render_proof` varchar(80) NOT NULL DEFAULT '' COMMENT 'len+sha من مجس التصيير الفعلي',
  `witness` varchar(600) NOT NULL,
  `snapshot_id` varchar(48) NOT NULL,
  `closed_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`requirement_id`),
  CONSTRAINT `chk_ec_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_ec_checks` CHECK (`checks_passed` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='امر الضبط 5 · مسار الاغلاق بالدليل — سجل كل اغلاق بفحوصه وهو مصدر التراجع';

-- ── Table: repair01_fc_states ──
CREATE TABLE `repair01_fc_states` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `entity` varchar(64) NOT NULL,
  `from_state` varchar(40) NOT NULL,
  `to_state` varchar(40) NOT NULL,
  `allowed` tinyint(1) NOT NULL DEFAULT 1,
  `owner_role` varchar(96) NOT NULL DEFAULT '',
  `precondition` varchar(400) NOT NULL DEFAULT '',
  `official_doc` varchar(160) NOT NULL DEFAULT '',
  `approval_gate` varchar(160) NOT NULL DEFAULT '',
  `reopen_rule` varchar(300) NOT NULL DEFAULT '',
  `correct_rule` varchar(300) NOT NULL DEFAULT '',
  `forbid_why` varchar(400) NOT NULL DEFAULT '',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_w15_state` (`entity`,`from_state`,`to_state`),
  CONSTRAINT `chk_w15_state_forbid` CHECK (`allowed` = 1 or `forbid_why` <> ''),
  CONSTRAINT `chk_w15_state_owner` CHECK (`allowed` = 0 or `owner_role` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='REPAIR01 W15 - الة حالة لكل كيان في النطاق';

-- ── Table: repair01_field_measure ──
CREATE TABLE `repair01_field_measure` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `screen_id` varchar(12) NOT NULL COMMENT 'معرف السطح المبني — الطرف المبني',
  `target_uid` varchar(12) NOT NULL COMMENT 'الهدف المطابق في كون الأهداف',
  `requirement_id` varchar(48) NOT NULL COMMENT 'مفتاح الطرف التصميمي في repair01_fields',
  `unit` varchar(12) NOT NULL DEFAULT '' COMMENT 'نطاق الهدف',
  `artifact_path` varchar(255) NOT NULL DEFAULT '' COMMENT 'الأثر الذي قيس منه — لا اسم الشاشة',
  `vocab_terms` int(11) NOT NULL DEFAULT 0 COMMENT 'مفردات الأثر المنتزعة — صفرها يفرق عجز القياس عن صفر المطابقة',
  `design_total` int(11) NOT NULL DEFAULT 0 COMMENT 'حقول التصميم كلها',
  `design_audit` int(11) NOT NULL DEFAULT 0 COMMENT 'منها AUDIT — الحاقية بنص 7-11 وخارج المقام',
  `design_applicable` int(11) NOT NULL DEFAULT 0 COMMENT 'المقام المنطبق = الكل ناقص AUDIT',
  `matched` int(11) NOT NULL DEFAULT 0 COMMENT 'ما وجد حاضرا في الأثر',
  `missing_sample` varchar(500) NOT NULL DEFAULT '' COMMENT 'عينة الناقص بأسمائه — لا عدد مجرد',
  `witness` varchar(500) NOT NULL COMMENT 'شاهد القياس أو شاهد العجز — ولا صف بلا شاهد',
  `snapshot_id` varchar(48) NOT NULL COMMENT 'اللقطة التي قيس عليها',
  `measured_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_screen_req` (`screen_id`,`requirement_id`),
  KEY `ix_snap` (`snapshot_id`),
  KEY `ix_unit` (`unit`),
  CONSTRAINT `chk_fm_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_fm_snapshot` CHECK (`snapshot_id` <> ''),
  CONSTRAINT `chk_fm_bounds` CHECK (`matched` <= `design_applicable` and `design_applicable` <= `design_total`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-02 7-5 · دفتر حقول المبني مقيسة من الأثر — بشاهد لكل سطح';

-- ── Table: repair01_field_measure_type ──
CREATE TABLE `repair01_field_measure_type` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `field_type` varchar(40) NOT NULL COMMENT 'نوع الحقل التصميمي',
  `step_ref` varchar(40) NOT NULL DEFAULT '' COMMENT 'خطوة 7 التي تسأل عن هذا النوع',
  `applicable` int(11) NOT NULL DEFAULT 0 COMMENT 'المقام لهذا النوع',
  `matched` int(11) NOT NULL DEFAULT 0 COMMENT 'ما وجد حاضرا في الاثر',
  `design_rule` varchar(190) NOT NULL DEFAULT '' COMMENT 'ما يقوله الملف عن هذا النوع بنفسه',
  `witness` varchar(400) NOT NULL COMMENT 'شاهد — ولا صف بلا شاهد',
  `snapshot_id` varchar(48) NOT NULL,
  `measured_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_type` (`field_type`),
  CONSTRAINT `chk_fmt_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_fmt_snapshot` CHECK (`snapshot_id` <> ''),
  CONSTRAINT `chk_fmt_bounds` CHECK (`matched` <= `applicable`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-02 3 · دفتر الحقول مفككا بنوع الحقل — ستة اسئلة لا سؤال';

-- ── Table: repair01_fields ──
CREATE TABLE `repair01_fields` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `requirement_id` varchar(48) NOT NULL DEFAULT '',
  `wave` varchar(8) NOT NULL DEFAULT '',
  `unit` varchar(160) NOT NULL DEFAULT '',
  `surface` varchar(255) NOT NULL DEFAULT '',
  `seq` varchar(12) NOT NULL DEFAULT '',
  `field_name` varchar(255) NOT NULL DEFAULT '',
  `field_type` varchar(80) NOT NULL DEFAULT '',
  `visibility_rule` varchar(255) NOT NULL DEFAULT '',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `k_req` (`requirement_id`),
  KEY `k_wave` (`wave`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: repair01_freeze_snapshot ──
CREATE TABLE `repair01_freeze_snapshot` (
  `snapshot_id` varchar(48) NOT NULL,
  `commit_hash` varchar(40) NOT NULL,
  `branch` varchar(80) NOT NULL DEFAULT '',
  `schema_version` varchar(40) NOT NULL COMMENT 'جداول/أعمدة مقيسة من information_schema',
  `registry_rows` int(11) NOT NULL,
  `config_baseline` varchar(64) NOT NULL COMMENT 'بصمة اعدادات البيئة الحاكمة',
  `measurement_tool_version` varchar(64) NOT NULL DEFAULT '' COMMENT 'بصمة عدة القياس: MT-<sha1 12>/<عدد الملفات> — السادسة من بصمة MASTER_EXEC 2-2',
  `frozen_at` datetime NOT NULL,
  `frozen_by` varchar(64) NOT NULL DEFAULT '',
  `purpose` varchar(160) NOT NULL,
  `window_kind` enum('BASELINE','DIAGNOSTIC') NOT NULL DEFAULT 'BASELINE' COMMENT 'BASELINE يشترط انحدارا اخضر · DIAGNOSTIC يختم الاحصاء ولا يشترط الخضرة',
  `regression_census` varchar(512) NOT NULL DEFAULT '' COMMENT 'نجح/المجموع · واسماء الحواجز الساقطة وقت الختم',
  `released_at` datetime DEFAULT NULL COMMENT 'فارغ = النافذة مفتوحة والتعديل ممنوع',
  `release_why` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`snapshot_id`),
  KEY `ix_frz_open` (`released_at`),
  CONSTRAINT `chk_frz_fields` CHECK (`commit_hash` <> '' and `schema_version` <> '' and `registry_rows` >= 0 and `config_baseline` <> '' and `purpose` <> ''),
  CONSTRAINT `chk_frz_release` CHECK (`released_at` is null or `release_why` <> ''),
  CONSTRAINT `chk_frz_tool` CHECK (`measurement_tool_version` <> ''),
  CONSTRAINT `chk_frz_census` CHECK (`regression_census` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: repair01_key_alias ──
CREATE TABLE `repair01_key_alias` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `key_code` varchar(40) NOT NULL,
  `alias_table` varchar(64) NOT NULL,
  `alias_column` varchar(64) NOT NULL DEFAULT '',
  `alias_kind` enum('PARALLEL_REGISTER','LABEL_ONLY','DENORM_LABEL') NOT NULL,
  `verdict` enum('LINKED','ALTERNATE_ID','SEED_NO_REFERENT','DIFFERENT_GRAIN','DENORM_LABEL') NOT NULL,
  `verdict_rule` varchar(48) NOT NULL DEFAULT '',
  `verdict_why` varchar(400) NOT NULL DEFAULT '',
  `rows_total` int(11) NOT NULL DEFAULT 0,
  `rows_seed` int(11) NOT NULL DEFAULT 0,
  `rows_resolvable` int(11) NOT NULL DEFAULT 0,
  `link_column` varchar(64) NOT NULL DEFAULT '' COMMENT 'العمود الحامل للمفتاح بعد الوصل',
  `rows_linked` int(11) NOT NULL DEFAULT 0,
  `resolved_at` datetime DEFAULT NULL,
  `wave_stage` varchar(8) NOT NULL DEFAULT '' COMMENT 'الموجة التي تحسمه إن لم يحسم هنا',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_alias` (`key_code`,`alias_table`,`alias_column`),
  KEY `ix_verdict` (`verdict`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='REPAIR01 W03 - المعرفات البديلة للحقيقة نفسها بحكم مقيس';

-- ── Table: repair01_key_registry ──
CREATE TABLE `repair01_key_registry` (
  `key_code` varchar(40) NOT NULL COMMENT 'المفتاح المشترك — Company_ID …',
  `key_ar` varchar(120) NOT NULL DEFAULT '',
  `seq_no` tinyint(3) unsigned NOT NULL DEFAULT 0 COMMENT 'ترتيب المفتاح في الوثيقة — لا ترتيب أبجدي',
  `owner_table` varchar(64) NOT NULL DEFAULT '' COMMENT 'الجدول المالك — واحد لا أكثر',
  `owner_column` varchar(64) NOT NULL DEFAULT '' COMMENT 'العمود الحامل للمفتاح',
  `owner_dept` varchar(12) NOT NULL DEFAULT '' COMMENT 'الرمز المعياري للادارة المالكة',
  `owner_screen_id` varchar(12) NOT NULL DEFAULT '' COMMENT 'SCR-nnnn الشاشة التي تنشئ المفتاح',
  `owner_rule` varchar(48) NOT NULL DEFAULT '',
  `create_rule` varchar(400) NOT NULL DEFAULT '' COMMENT 'قاعدة الإنشاء',
  `create_rule_src` varchar(255) NOT NULL DEFAULT '',
  `read_rule` varchar(400) NOT NULL DEFAULT '' COMMENT 'قاعدة القراءة',
  `read_rule_src` varchar(255) NOT NULL DEFAULT '',
  `company_scope` enum('SCOPED','ROOT') NOT NULL DEFAULT 'SCOPED',
  `company_column` varchar(64) NOT NULL DEFAULT '',
  `is_master` tinyint(1) NOT NULL DEFAULT 1,
  `measured_rows` int(11) NOT NULL DEFAULT 0,
  `measured_at` datetime DEFAULT NULL,
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`key_code`),
  UNIQUE KEY `uq_owner` (`owner_table`,`owner_column`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='REPAIR01 W03 - سجل المفاتيح الثلاثة عشر بمالك واحد';

-- ── Table: repair01_ledger_checksum_fix ──
CREATE TABLE `repair01_ledger_checksum_fix` (
  `filename` varchar(255) NOT NULL,
  `old_checksum` char(40) NOT NULL,
  `new_checksum` char(40) NOT NULL,
  `witness` varchar(600) NOT NULL,
  `fixed_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`filename`),
  CONSTRAINT `chk_lcf_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_lcf_diff` CHECK (`old_checksum` <> `new_checksum`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CTL 12 · مصالحة بصمة هجرة صقلت بعد تطبيقها — وهو مصدر التراجع';

-- ── Table: repair01_manual_entry_class ──
CREATE TABLE `repair01_manual_entry_class` (
  `entry_id` int(11) NOT NULL COMMENT 'fin_journal_entries.id',
  `category` varchar(32) NOT NULL COMMENT 'فئة القسمة الاولية — التقاطع صفر والاتحاد 1644',
  `era` enum('PRE_LEDGER','CURRENT') NOT NULL COMMENT 'قبل 2026 لا فترة له — بعده له فترة',
  `doc_hint` varchar(60) NOT NULL DEFAULT '' COMMENT 'مرجع مستند منتزع من memo ان وجد (CLM-…)',
  `rule_applied` varchar(32) NOT NULL,
  `witness` varchar(300) NOT NULL,
  `snapshot_id` varchar(48) NOT NULL,
  `classed_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`entry_id`),
  KEY `ix_mec_cat` (`category`,`era`),
  CONSTRAINT `chk_mec_witness` CHECK (`witness` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='امر الضبط 9 · مصالحة القيود اليدوية — مجموع الفئات = 1644 بفارق صفر';

-- ── Table: repair01_master_entities ──
CREATE TABLE `repair01_master_entities` (
  `entity_code` varchar(40) NOT NULL,
  `entity_ar` varchar(160) NOT NULL DEFAULT '',
  `key_code` varchar(40) NOT NULL DEFAULT '',
  `table_name` varchar(64) NOT NULL DEFAULT '',
  `company_column` varchar(64) NOT NULL DEFAULT '',
  `rows_total` int(11) NOT NULL DEFAULT 0,
  `rows_in_use` int(11) NOT NULL DEFAULT 0 COMMENT 'المقام الحاكم لـDEC-OPEN-03',
  `rows_no_company` int(11) NOT NULL DEFAULT 0,
  `rows_quarantined` int(11) NOT NULL DEFAULT 0,
  `quarantine_rule` varchar(48) NOT NULL DEFAULT '',
  `guard_kind` enum('TRIGGER','NOT_NULL','APP_ONLY','NONE') NOT NULL DEFAULT 'NONE',
  `guard_evidence` varchar(255) NOT NULL DEFAULT '',
  `verdict` varchar(48) NOT NULL DEFAULT '',
  `measured_at` datetime DEFAULT NULL,
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`entity_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='REPAIR01 W03 - الكيانات الأم وحكم DEC-OPEN-03';

-- ── Table: repair01_nav_group_bind ──
CREATE TABLE `repair01_nav_group_bind` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nav_item_id` int(11) NOT NULL COMMENT 'صف nav_items — ومفتاح الرد',
  `role_id` int(11) NOT NULL,
  `route` varchar(190) NOT NULL DEFAULT '',
  `canon_route` varchar(190) NOT NULL DEFAULT '' COMMENT 'المسار الذي جسر الى السجل المعتمد',
  `before_group_id` int(11) DEFAULT NULL COMMENT 'المجموعة قبل — NULL يعني بلا مجموعة',
  `before_group_name` varchar(190) NOT NULL DEFAULT '',
  `after_group_id` int(11) NOT NULL,
  `after_group_name` varchar(190) NOT NULL,
  `group_created` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1 = المجموعة انشئت لهذا الربط',
  `witness` varchar(600) NOT NULL COMMENT 'شاهد الربط — ولا صف بلا شاهد',
  `snapshot_id` varchar(48) NOT NULL COMMENT 'اللقطة التي قيس عليها',
  `applied_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ngb_item` (`nav_item_id`),
  KEY `ix_ngb_role` (`role_id`),
  KEY `ix_ngb_after` (`after_group_id`),
  CONSTRAINT `chk_ngb_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_ngb_snapshot` CHECK (`snapshot_id` <> ''),
  CONSTRAINT `chk_ngb_changed` CHECK (`before_group_id` is null or `before_group_id` <> `after_group_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-02 6 س3 · ربط بند الملاحة بمجموعته المعتمدة — قبل وبعد لكل بند وهو مصدر التراجع';

-- ── Table: repair01_nav_label_align ──
CREATE TABLE `repair01_nav_label_align` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nav_item_id` int(11) NOT NULL COMMENT 'صف nav_items — ومفتاح الرد',
  `role_id` int(11) NOT NULL,
  `route` varchar(190) NOT NULL DEFAULT '',
  `before_label` varchar(190) NOT NULL COMMENT 'الاسم المخزن قبل',
  `after_label` varchar(190) NOT NULL COMMENT 'الاسم المعتمد بعد',
  `canon_status` varchar(32) NOT NULL DEFAULT '' COMMENT 'حالة الصف المعتمد — والمحاذاة لا تقع الا على APPROVED',
  `witness` varchar(600) NOT NULL COMMENT 'شاهد المحاذاة — ولا صف بلا شاهد',
  `snapshot_id` varchar(48) NOT NULL,
  `applied_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_nla_item` (`nav_item_id`),
  KEY `ix_nla_role` (`role_id`),
  CONSTRAINT `chk_nla_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_nla_snapshot` CHECK (`snapshot_id` <> ''),
  CONSTRAINT `chk_nla_appr` CHECK (`canon_status` = 'APPROVED'),
  CONSTRAINT `chk_nla_changed` CHECK (`before_label` <> `after_label`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-02 6 س2 · محاذاة الاسم المخزن بالمعتمد — قبل وبعد وهو مصدر التراجع';

-- ── Table: repair01_nav_perm_bind ──
CREATE TABLE `repair01_nav_perm_bind` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nav_item_id` int(11) NOT NULL,
  `role_id` int(11) NOT NULL,
  `route` varchar(190) NOT NULL,
  `module_id` int(11) DEFAULT NULL,
  `after_code` varchar(128) NOT NULL COMMENT 'رمز الصلاحية المكتوب — من اخوته على المسار نفسه',
  `peer_roles` int(11) NOT NULL DEFAULT 0 COMMENT 'ادوار على المسار نفسه مفحوصة سلفا — وهي السند',
  `had_grant` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1 = للدور can_view سلفا فلا يختفي شيء',
  `witness` varchar(600) NOT NULL,
  `snapshot_id` varchar(48) NOT NULL,
  `applied_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_npb_item` (`nav_item_id`),
  CONSTRAINT `chk_npb_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_npb_snapshot` CHECK (`snapshot_id` <> ''),
  CONSTRAINT `chk_npb_code` CHECK (`after_code` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-02 6 س6 · سد ثقب الظهور بلا فحص صلاحية — وهو مصدر التراجع';

-- ── Table: repair01_nav_sort_align ──
CREATE TABLE `repair01_nav_sort_align` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nav_item_id` int(11) NOT NULL COMMENT 'صف nav_items — ومفتاح الرد',
  `role_id` int(11) NOT NULL,
  `group_id` int(11) DEFAULT NULL COMMENT 'السلة التي رتب داخلها',
  `route` varchar(190) NOT NULL DEFAULT '',
  `before_sort` int(11) NOT NULL COMMENT 'الترتيب قبل — وهو تاريخ الاضافة',
  `after_sort` int(11) NOT NULL COMMENT 'الترتيب بعد — وهو موضع الدورة',
  `canon_sort` int(11) NOT NULL DEFAULT 0 COMMENT 'sort_no المعتمد الذي رتب عليه',
  `bucket_size` int(11) NOT NULL DEFAULT 0 COMMENT 'عدد بنود السلة — فالترتيب نسبي',
  `witness` varchar(600) NOT NULL COMMENT 'شاهد المحاذاة — ولا صف بلا شاهد',
  `snapshot_id` varchar(48) NOT NULL,
  `applied_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_nsa_item` (`nav_item_id`),
  KEY `ix_nsa_role` (`role_id`),
  CONSTRAINT `chk_nsa_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_nsa_snapshot` CHECK (`snapshot_id` <> ''),
  CONSTRAINT `chk_nsa_changed` CHECK (`before_sort` <> `after_sort`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-02 6 س4 · محاذاة ترتيب المخزن بدورة العمل — قبل وبعد وهو مصدر التراجع';

-- ── Table: repair01_owner_actions ──
CREATE TABLE `repair01_owner_actions` (
  `action_key` varchar(40) NOT NULL,
  `class` enum('BUSINESS_DECISION','POLICY_DECISION','CONFIG_VALUE','TECHNICAL_DECISION','UAT_INPUT') NOT NULL,
  `decision` varchar(300) NOT NULL COMMENT 'القرار المحدد المطلوب',
  `blocks` varchar(300) NOT NULL COMMENT 'ما الذي يحجبه — بعدده',
  `required_by` varchar(120) NOT NULL COMMENT 'Required-by-Gate',
  `options` varchar(400) NOT NULL,
  `impact` varchar(300) NOT NULL,
  `recommendation` varchar(300) NOT NULL COMMENT 'توصية المنفذ',
  `status` enum('PENDING','DECIDED','WITHDRAWN') NOT NULL DEFAULT 'PENDING',
  `decided_ref` varchar(190) NOT NULL DEFAULT '' COMMENT 'مرجع القرار حين يصدر',
  `decided_at` datetime DEFAULT NULL COMMENT 'يكتب فقط اذا حدده المالك او فرضته سياسة',
  `snapshot_id` varchar(48) NOT NULL DEFAULT '',
  `raised_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`action_key`),
  KEY `ix_oa_status` (`status`,`class`),
  CONSTRAINT `chk_oa_decision` CHECK (`decision` <> '' and `blocks` <> '' and `options` <> '' and `recommendation` <> ''),
  CONSTRAINT `chk_oa_decided` CHECK (`status` <> 'DECIDED' or `decided_ref` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='امر الضبط 10 · OWNER_ACTION_REGISTER — قرار حقيقي مصنف لا طابور تنظيف';

-- ── Table: repair01_owner_close ──
CREATE TABLE `repair01_owner_close` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `screen_id` varchar(12) NOT NULL COMMENT 'السطح في repair01_screen_registry',
  `route` varchar(200) NOT NULL,
  `before_owner` varchar(12) NOT NULL DEFAULT '' COMMENT 'المالك قبل الاسناد (فارغ بقرار W2-D-01)',
  `before_rule` varchar(48) NOT NULL DEFAULT '',
  `after_owner` varchar(12) NOT NULL COMMENT 'المالك المسند او PLTF للقدرات المنصية',
  `assign_rule` varchar(48) NOT NULL COMMENT 'قاعدة الاسناد FC3_*',
  `witness` varchar(600) NOT NULL COMMENT 'الشاهد المقيس — ولا صف بلا شاهد',
  `capability` varchar(32) NOT NULL DEFAULT '' COMMENT 'رمز القدرة المنصية لصفوف PLTF',
  `snapshot_id` varchar(48) NOT NULL,
  `applied_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_oc_screen` (`screen_id`),
  CONSTRAINT `chk_oc_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_oc_after` CHECK (`after_owner` <> ''),
  CONSTRAINT `chk_oc_rule` CHECK (`assign_rule` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='FINAL_CLOSE 1-2 · اغلاق ملكية W2-D-01 المؤجلة بشاهد لكل سطح — وهو مصدر التراجع';

-- ── Table: repair01_ownership ──
CREATE TABLE `repair01_ownership` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `space_role` varchar(160) NOT NULL DEFAULT '',
  `screen` varchar(255) NOT NULL DEFAULT '',
  `route` varchar(255) NOT NULL DEFAULT '',
  `owner_dept` varchar(160) NOT NULL DEFAULT '',
  `classification` varchar(60) NOT NULL DEFAULT '',
  `ownership_kind` varchar(80) NOT NULL DEFAULT '',
  `space_count` smallint(5) unsigned NOT NULL DEFAULT 0,
  `gov_meaning` varchar(255) NOT NULL DEFAULT '',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `w1_verdict` enum('REVOKED_TO_OWNER','CONTEXTUAL_READ_ONLY','RECLASSIFY_OWNED','RECLASSIFY_PERSONAL','ESCALATED_DECISION') DEFAULT NULL,
  `w1_rule` varchar(48) NOT NULL DEFAULT '',
  `w1_reason` varchar(400) NOT NULL DEFAULT '',
  `w1_evidence` varchar(255) NOT NULL DEFAULT '',
  `w1_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `k_cls` (`classification`),
  KEY `k_screen` (`screen`),
  KEY `k_w1` (`w1_verdict`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: repair01_platform_capabilities ──
CREATE TABLE `repair01_platform_capabilities` (
  `capability_code` varchar(32) NOT NULL COMMENT 'رمز القدرة المنصية المشتركة',
  `name_ar` varchar(160) NOT NULL,
  `tech_owner` varchar(120) NOT NULL DEFAULT '' COMMENT 'مالك تقني مسمى شخصا — RPR-02 §4-4 المعيار الثالث',
  `policy_owner` varchar(120) NOT NULL DEFAULT '' COMMENT 'مالك السياسة',
  `last_closed` varchar(190) NOT NULL DEFAULT '' COMMENT 'اخر متطلب مغلق بالدليل',
  `first_open` varchar(190) NOT NULL DEFAULT '' COMMENT 'اول متطلب مفتوح',
  `blocker` varchar(190) NOT NULL DEFAULT '',
  `blocker_level` varchar(40) NOT NULL DEFAULT '' COMMENT 'درجة من الست',
  `blocker_valid` varchar(190) NOT NULL DEFAULT '' COMMENT 'هل الحاجز صحيح ولماذا',
  `resume_point` varchar(255) NOT NULL DEFAULT '',
  `next_action` varchar(255) NOT NULL DEFAULT '' COMMENT 'فعل واحد محدد لا خطة',
  `moved_from` varchar(120) NOT NULL DEFAULT '' COMMENT 'من اين نقل — ولا نقل بلا اثر',
  `moved_why` varchar(400) NOT NULL DEFAULT '',
  `snapshot_id` varchar(48) NOT NULL DEFAULT '',
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`capability_code`),
  CONSTRAINT `chk_pc_moved` CHECK (`moved_from` = '' or `moved_why` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-02 §5-2 و AMD-01 المرحلة 6 — سجل القدرات المنصية المستقل · ولا تعد PLATFORM ادارة 22';

-- ── Table: repair01_platform_justification ──
CREATE TABLE `repair01_platform_justification` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `screen_id` varchar(12) NOT NULL COMMENT 'السطح — والمعرف هو الربط',
  `label_ar` varchar(190) NOT NULL DEFAULT '',
  `verdict` enum('PLATFORM_JUSTIFIED','RETURN_TO_SCOPE','NO_SCOPE_TO_RETURN') NOT NULL COMMENT 'حكم 5-4 — والمقياس يعلن ايه',
  `criteria_met` varchar(4) NOT NULL COMMENT 'اربعة مواضع: رقم المعيار المستوفى او نقطة',
  `roles_rendered` smallint(5) unsigned NOT NULL DEFAULT 0 COMMENT 'ادوار يصير لها المسار — شاهد المعيار الاول',
  `scope_code` varchar(12) NOT NULL DEFAULT '' COMMENT 'النطاق الذي يعود اليه',
  `decision_ref` varchar(190) NOT NULL DEFAULT '' COMMENT 'مرجع القاعدة الحاكمة — سابق للقياس',
  `witness` varchar(600) NOT NULL COMMENT 'شاهد الحكم — ولا صف بلا شاهد',
  `snapshot_id` varchar(48) NOT NULL COMMENT 'اللقطة التي قيس عليها',
  `measured_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pj_screen` (`screen_id`),
  KEY `ix_pj_verdict` (`verdict`),
  CONSTRAINT `chk_pj_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_pj_snapshot` CHECK (`snapshot_id` <> ''),
  CONSTRAINT `chk_pj_ref` CHECK (`verdict` <> 'PLATFORM_JUSTIFIED' or `decision_ref` <> ''),
  CONSTRAINT `chk_pj_scope` CHECK (`verdict` <> 'RETURN_TO_SCOPE' or `scope_code` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-02 13 · تبرير PLATFORM باربعة 5-4 — وما لم يستوف يعود الى ادارته';

-- ── Table: repair01_platform_ownership ──
CREATE TABLE `repair01_platform_ownership` (
  `screen_id` varchar(12) NOT NULL,
  `label_ar` varchar(190) NOT NULL DEFAULT '',
  `justify_state` varchar(32) NOT NULL DEFAULT '' COMMENT 'من rpr02_platform_justify — J1/J2/J3',
  `criteria_met` varchar(12) NOT NULL DEFAULT '' COMMENT 'اي الاربعة استوفى — مثل 12-4',
  `tech_owner` varchar(120) NOT NULL DEFAULT '' COMMENT 'شخص مسمى — فارغه هو الحاجز',
  `status` enum('AWAITING_OWNER_NAME','JUSTIFIED','RETURNED_TO_SCOPE') NOT NULL DEFAULT 'AWAITING_OWNER_NAME',
  `witness` varchar(400) NOT NULL,
  `snapshot_id` varchar(48) NOT NULL DEFAULT '',
  PRIMARY KEY (`screen_id`),
  CONSTRAINT `chk_po_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_po_justified` CHECK (`status` <> 'JUSTIFIED' or `tech_owner` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='امر الضبط 11 · PLATFORM_SHARED_OWNERSHIP_REGISTER — لا اغلاق بلا مالك تقني مسمى';

-- ── Table: repair01_platform_surface ──
CREATE TABLE `repair01_platform_surface` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `screen_id` varchar(12) NOT NULL COMMENT 'السطح — والمعرف هو الربط',
  `label_ar` varchar(190) NOT NULL DEFAULT '',
  `route` varchar(190) NOT NULL DEFAULT '',
  `bind_rule` enum('P1_DECLARED_SCOPE_OWNER','P2_CAPABILITY_BOUND','P3_UNBOUND_DECLARED') NOT NULL COMMENT 'قاعدة الربط — والمقياس يعلن ايتها',
  `scope_code` varchar(12) NOT NULL DEFAULT '' COMMENT 'النطاق المعلن حين يكون المالك نطاقا',
  `capability_code` varchar(40) NOT NULL DEFAULT '' COMMENT 'قدرة AMD-01 4-7 حين يربط بقدرة',
  `visibility_class` varchar(40) NOT NULL DEFAULT '' COMMENT 'صنف الظهور مقيسا',
  `visibility_rule` varchar(60) NOT NULL DEFAULT '' COMMENT 'قاعدة الظهور مقيسة',
  `permission_policy` varchar(80) NOT NULL DEFAULT '' COMMENT 'سياسة الصلاحية مقيسة',
  `guard_kind` varchar(40) NOT NULL DEFAULT '' COMMENT 'صنف الحارس مقيسا',
  `owner_role` varchar(80) NOT NULL DEFAULT '' COMMENT 'دور المالك مقيسا',
  `approval_state` enum('AWAITING_OWNER','APPROVED') NOT NULL DEFAULT 'AWAITING_OWNER' COMMENT 'التسجيل ليس اعتمادا — و13 يشترط معتمدا',
  `owner_decision_ref` varchar(190) NOT NULL DEFAULT '' COMMENT 'مرجع قرار المالك — لازم للاعتماد',
  `witness` varchar(600) NOT NULL COMMENT 'شاهد الربط — ولا صف بلا شاهد',
  `snapshot_id` varchar(48) NOT NULL COMMENT 'اللقطة التي قيس عليها',
  `measured_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_screen` (`screen_id`),
  KEY `ix_rule` (`bind_rule`),
  KEY `ix_state` (`approval_state`),
  CONSTRAINT `chk_ps_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_ps_snapshot` CHECK (`snapshot_id` <> ''),
  CONSTRAINT `chk_ps_approved` CHECK (`approval_state` = 'AWAITING_OWNER' or `owner_decision_ref` <> ''),
  CONSTRAINT `chk_ps_payload` CHECK (`bind_rule` = 'P1_DECLARED_SCOPE_OWNER' and `scope_code` <> '' or `bind_rule` = 'P2_CAPABILITY_BOUND' and `capability_code` <> '' or `bind_rule` = 'P3_UNBOUND_DECLARED')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-02 12-13 · ربط سطح المنصة بقدرته او نطاقه — بقاعدة وشاهد لكل سطح';

-- ── Table: repair01_render_align ──
CREATE TABLE `repair01_render_align` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `role_id` int(11) NOT NULL COMMENT 'الدور — الحاكم بمفتاح الدور',
  `route` varchar(160) NOT NULL COMMENT 'المسار',
  `requirement_id` varchar(40) NOT NULL DEFAULT '' COMMENT 'متطلب الملف المطابق بالجسر',
  `had_row` tinyint(1) NOT NULL COMMENT '1=كان له اعلان قائم قبل المحاذاة',
  `gt_id` int(11) DEFAULT NULL COMMENT 'صف الاعلان في gov_target_nav (القائم او المدرج)',
  `before_group_ar` varchar(120) NOT NULL DEFAULT '' COMMENT 'مجموعة الاعلان قبل (للقائم)',
  `before_group_no` int(11) NOT NULL DEFAULT 0,
  `before_item_no` int(11) NOT NULL DEFAULT 0,
  `after_group_ar` varchar(120) NOT NULL COMMENT 'مجموعة الملف التصميمي',
  `after_group_no` int(11) NOT NULL,
  `after_item_no` int(11) NOT NULL,
  `rendered_before` varchar(220) NOT NULL COMMENT 'الراس والفرعي المصيران قبل — شاهد الشجرة لا الجدول',
  `witness` varchar(600) NOT NULL COMMENT 'شاهد المحاذاة — ولا صف بلا شاهد',
  `snapshot_id` varchar(48) NOT NULL COMMENT 'اللقطة',
  `applied_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ra_role_route` (`role_id`,`route`),
  CONSTRAINT `chk_ra_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_ra_snapshot` CHECK (`snapshot_id` <> ''),
  CONSTRAINT `chk_ra_rendered` CHECK (`rendered_before` <> ''),
  CONSTRAINT `chk_ra_after` CHECK (`after_group_ar` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='SIDEBAR_RENDER_FIX 4-3 · محاذاة المصير في الحاكم المثبت بحركة العداد — وهو مصدر التراجع';

-- ── Table: repair01_requirements ──
CREATE TABLE `repair01_requirements` (
  `requirement_id` varchar(48) NOT NULL,
  `wave` varchar(8) NOT NULL DEFAULT '',
  `stage_no` tinyint(3) unsigned DEFAULT NULL,
  `unit` varchar(160) NOT NULL DEFAULT '',
  `dependency` varchar(160) NOT NULL DEFAULT '',
  `seq` varchar(12) NOT NULL DEFAULT '',
  `group_name` varchar(160) NOT NULL DEFAULT '',
  `surface` varchar(255) NOT NULL DEFAULT '',
  `grain` varchar(255) NOT NULL DEFAULT '',
  `source_of_truth` varchar(255) NOT NULL DEFAULT '',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `amd01_state` enum('EVIDENCE_CLOSED','IMPLEMENTED_NOT_VERIFIED','PARTIALLY_IMPLEMENTED','INCORRECTLY_IMPLEMENTED','NOT_IMPLEMENTED','NOT_APPLICABLE') DEFAULT NULL COMMENT 'الحالة الفعلية من الست — AMD-01 المرحلة 3 · ووجود الكود ليس اغلاقا',
  `requirement_type` enum('STRUCTURAL','TRANSACTION','EVENT_INTEGRATION','PROJECTION_REPORT','CROSS_JOURNEY') DEFAULT NULL COMMENT 'يشتق من نوع السطح في الدليل المعماري — ولا يختار بالاجتهاد',
  `proof_contract` varchar(400) NOT NULL DEFAULT '' COMMENT 'عقد الاثبات اللازم لنوعه — AMD-01 §3-1 · ولا يطالب نوع بعقد غيره',
  `state_evidence` varchar(400) NOT NULL DEFAULT '' COMMENT 'القياس الذي انتج الحالة — ولا حالة بلا دليل يسميها',
  `identity_status` enum('MATCHED_BY_NAME','MATCHED_BY_ID','UNMATCHED_PENDING_RECONCILIATION') NOT NULL DEFAULT 'UNMATCHED_PENDING_RECONCILIATION' COMMENT 'RPR-02 §4-1: لا تقاس تغطية على كونين — وغياب الاسم ليس غياب السطح',
  `state_at` datetime DEFAULT NULL COMMENT 'زمن الحكم',
  `state_snapshot` varchar(48) NOT NULL DEFAULT '' COMMENT 'معرف اللقطة التي قيس عليها — ولا رقم بلا لقطته',
  `type_witness` varchar(500) DEFAULT NULL COMMENT 'مفردة حسم النوع من الدفتر الحاكم بلقطتها',
  `grain_entity` varchar(120) DEFAULT NULL COMMENT 'كيان الحبة المسمى من عمود grain المحكوم',
  `entity_witness` varchar(400) DEFAULT NULL COMMENT 'اقتباس موضع التسمية من grain بلقطته',
  `sm_model_ref` varchar(200) DEFAULT NULL COMMENT 'مرجع آلة حالة المعاملة من الدليل المعماري',
  `sm_witness` varchar(400) DEFAULT NULL COMMENT 'اقتباس موضع النموذج من الدليل بلقطته',
  PRIMARY KEY (`requirement_id`),
  KEY `k_wave` (`wave`),
  KEY `k_unit` (`unit`),
  KEY `k_stage` (`stage_no`),
  CONSTRAINT `chk_req_state_evidence` CHECK (`amd01_state` is null or `state_evidence` <> ''),
  CONSTRAINT `chk_req_state_snapshot` CHECK (`amd01_state` is null or `state_snapshot` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: repair01_screen_registry ──
CREATE TABLE `repair01_screen_registry` (
  `screen_id` varchar(12) NOT NULL COMMENT 'المعرف المعياري SCR-nnnn — ثابت لا يعاد ترقيمه',
  `screen_file` varchar(160) NOT NULL DEFAULT '' COMMENT 'اسم الملف — مفتاح سجل الدورة الحي',
  `route` varchar(200) DEFAULT NULL COMMENT 'المسار المعياري Dir/file.php — NULL لما لم يُبنَ (والفراغ لا يصلح: uq_route يمنع تكراره)',
  `route_rule` varchar(48) NOT NULL DEFAULT '',
  `owner_code` varchar(12) NOT NULL DEFAULT '' COMMENT 'الرمز المعياري للادارة المالكة',
  `owner_role` varchar(160) NOT NULL DEFAULT '' COMMENT 'الدور المسؤول عن الشاشة',
  `owner_rule` varchar(48) NOT NULL DEFAULT '',
  `lifecycle` enum('LIVE_REGISTERED','LIVE_UNREGISTERED','GHOST_TARGET','GHOST_RETIRED') NOT NULL DEFAULT 'LIVE_UNREGISTERED',
  `lifecycle_rule` varchar(48) NOT NULL DEFAULT '',
  `parent_screen_id` varchar(12) NOT NULL DEFAULT '' COMMENT 'الاب حين تكون تبويبا فيه',
  `parent_rule` varchar(48) NOT NULL DEFAULT '',
  `visibility_class` enum('MENU_ITEM','TAB_CHILD','DIRECT_ONLY','ANCHOR','NOT_BUILT') NOT NULL DEFAULT 'DIRECT_ONLY',
  `visibility_rule` varchar(48) NOT NULL DEFAULT '',
  `on_disk` tinyint(1) NOT NULL DEFAULT 0,
  `origin` varchar(24) NOT NULL DEFAULT '' COMMENT 'SURFACES / DISK / NAV',
  `ghost_verdict` varchar(32) NOT NULL DEFAULT '',
  `ghost_why` varchar(400) NOT NULL DEFAULT '',
  `guard_kind` varchar(32) NOT NULL DEFAULT '' COMMENT 'SELF_EARLY / SHARED_SHELL / SHELL / NONE',
  `guard_evidence` varchar(255) NOT NULL DEFAULT '',
  `w2_why` varchar(400) NOT NULL DEFAULT '',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `canonical_label_ar` varchar(190) NOT NULL DEFAULT '' COMMENT 'المسمى المعياري المعروض - البند 9',
  `surface_kind` varchar(24) NOT NULL DEFAULT '' COMMENT 'SOURCE او PROJECTION - البنود 4-8',
  `ownership_verdict` varchar(24) NOT NULL DEFAULT '' COMMENT 'حكم الملكية التساعي - البند 3',
  `action_guard` varchar(40) NOT NULL DEFAULT '' COMMENT 'حارس الفعل الخادمي عند وجود كتابة',
  `permission_policy` varchar(60) NOT NULL DEFAULT '' COMMENT 'سياسة الصلاحية المرجعية',
  `grain_ar` varchar(190) NOT NULL DEFAULT '' COMMENT 'حبة السطح - ما الصف الواحد فيه',
  `grain_entity` varchar(80) NOT NULL DEFAULT '' COMMENT 'كيان الحبة المقيس — الجدول الأساسي للسطح (RPR-02 §7-1)',
  `grain_cardinality` enum('ROW','LINE','LIVE_READ','LIST','NONE') NOT NULL DEFAULT 'NONE' COMMENT 'صنف الحبة المقيس — سطر/بند/قراءة حية/قائمة',
  `grain_measured` varchar(190) NOT NULL DEFAULT '' COMMENT 'الحبة المقيسة منطوقة بالعربية للمقارنة بحبة التصميم',
  `grain_rule` varchar(48) NOT NULL DEFAULT '' COMMENT 'القاعدة التي قررت الحبة — G1..G6',
  `grain_witness` varchar(400) NOT NULL DEFAULT '' COMMENT 'شاهد القياس: المسار المحلول والجداول بأدوارها — ولا حبة بلا شاهد',
  `grain_multi` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'سطح يجمع حبتين — خرق RPR-02 §7 الخطوة 1',
  `source_of_truth` varchar(120) NOT NULL DEFAULT '' COMMENT 'الجدول او السجل الحاكم',
  `state_model_ref` varchar(90) NOT NULL DEFAULT '' COMMENT 'مرجع الة الحالة عند انطباقها',
  `finance_debt_class` varchar(24) NOT NULL DEFAULT '' COMMENT 'تصنيف دين المالية - البند 15',
  `debt_owner` varchar(24) NOT NULL DEFAULT '' COMMENT 'مالك اغلاق الدين',
  `debt_wave` varchar(12) NOT NULL DEFAULT '' COMMENT 'موجة اغلاق الدين',
  `verdict_rule` varchar(240) NOT NULL DEFAULT '' COMMENT 'قاعدة الاشتقاق - لا حكم بلا قاعدة',
  `verdict_at` datetime DEFAULT NULL,
  `sot_rule` varchar(48) NOT NULL DEFAULT '' COMMENT 'قاعدة تعيين مصدر الحقيقة — SOLE_WRITER او DUPLICATE_SOURCE او قرار مسجل',
  `sot_witness` varchar(500) NOT NULL DEFAULT '' COMMENT 'شاهد التعيين — ولا مصدر حقيقة مكتوب بلا شاهد',
  `sot_snapshot` varchar(48) NOT NULL DEFAULT '' COMMENT 'اللقطة التي قيس عليها التعيين',
  `grain_tier` enum('OWN','SHARED_KIT','NONE') NOT NULL DEFAULT 'NONE' COMMENT 'الطبقة الخام: هل قيست جداول السطح من مصدره الخاص ام من كيت مشترك',
  `grain_fact_scope` enum('OWN_FACT','SHARED_KIT','INFRA_ONLY','NONE') NOT NULL DEFAULT 'NONE' COMMENT 'خلاصة الحكم: هل الكيان حقيقة اعمال يملكها هذا السطح — وعليها وحدها تقاس 9 و10 و11',
  PRIMARY KEY (`screen_id`),
  UNIQUE KEY `uq_route` (`route`),
  KEY `k_file` (`screen_file`),
  KEY `k_life` (`lifecycle`),
  KEY `k_vis` (`visibility_class`),
  KEY `k_guard` (`guard_kind`),
  KEY `ix_fact_scope` (`grain_fact_scope`),
  CONSTRAINT `chk_w135_ownv` CHECK (`ownership_verdict` in ('','DOMAIN_SOURCE','DOMAIN_PROJECTION','PLATFORM_SHARED','EXECUTIVE_PROJECTION','AUDIT_ASSURANCE','TAB_CHILD','LEGACY','RETIRE','UNKNOWN')),
  CONSTRAINT `chk_w135_kind` CHECK (`surface_kind` in ('','SOURCE','PROJECTION')),
  CONSTRAINT `chk_w135_fin` CHECK (`finance_debt_class` in ('','TARGET','SOURCE','PROJECTION','DUPLICATE','MERGE','RETIRE','LEGACY_READ_ONLY')),
  CONSTRAINT `chk_w135_why` CHECK (`ownership_verdict` = '' or `verdict_rule` <> ''),
  CONSTRAINT `chk_grain_witness` CHECK (`grain_entity` = '' or `grain_witness` <> ''),
  CONSTRAINT `chk_sot_witness` CHECK (`source_of_truth` = '' or `sot_witness` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='REPAIR01 W02 — canonical screen registry: one screen per row';

-- ── Table: repair01_sidebar_align ──
CREATE TABLE `repair01_sidebar_align` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `route` varchar(190) NOT NULL COMMENT 'المسار — ومفتاح الرد',
  `requirement_id` varchar(40) NOT NULL DEFAULT '' COMMENT 'متطلب الملف المطابق',
  `unit_name` varchar(160) NOT NULL DEFAULT '' COMMENT 'ادارة الملف',
  `before_group` varchar(160) NOT NULL DEFAULT '' COMMENT 'المجموعة المصيرة قبل',
  `after_group` varchar(160) NOT NULL DEFAULT '' COMMENT 'مجموعة الملف بعد',
  `before_order` int(11) NOT NULL DEFAULT 0 COMMENT 'الترتيب قبل',
  `after_order` int(11) NOT NULL DEFAULT 0 COMMENT 'تسلسل الملف بعد',
  `change_kind` enum('GROUP','ORDER','GROUP_AND_ORDER') NOT NULL,
  `witness` varchar(600) NOT NULL COMMENT 'شاهد المحاذاة — ولا صف بلا شاهد',
  `snapshot_id` varchar(48) NOT NULL COMMENT 'اللقطة التي قيس عليها',
  `applied_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sa_route` (`route`),
  KEY `ix_sa_kind` (`change_kind`),
  CONSTRAINT `chk_sa_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_sa_snapshot` CHECK (`snapshot_id` <> ''),
  CONSTRAINT `chk_sa_changed` CHECK (`before_group` <> `after_group` or `before_order` <> `after_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-02 8 · محاذاة السايدبار بالملف التصميمي — قبل وبعد لكل مسار وهو مصدر التراجع';

-- ── Table: repair01_sod_test_registry ──
CREATE TABLE `repair01_sod_test_registry` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `wave` varchar(8) NOT NULL COMMENT 'الموجة التي يقع فيها فصل الواجب',
  `process_key` varchar(120) NOT NULL COMMENT 'المفتاح القانوني لفصل الواجب — الطرف الاول',
  `forbidden_combo` varchar(400) NOT NULL DEFAULT '' COMMENT 'التركيبة الممنوعة كما وردت',
  `enforced_raw` varchar(600) NOT NULL DEFAULT '' COMMENT 'enforced_by كما ورد — لا يصحح ولا يوحد',
  `enforced_kind` enum('CODE_LIST','PROSE','ABSENT') NOT NULL COMMENT 'صنف ما ورد: رموز · نثر يصف · لا عمود اصلا',
  `test_file` varchar(190) NOT NULL DEFAULT '' COMMENT 'ملف الفاحص السالب — الطرف الثاني',
  `test_claim` varchar(400) NOT NULL DEFAULT '' COMMENT 'الدعوى التي يذكرها الفاحص',
  `bound` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'هل ارتبط الطرفان بمعرف',
  `witness` varchar(600) NOT NULL COMMENT 'شاهد الربط او شاهد انعدامه — ولا صف بلا شاهد',
  `snapshot_id` varchar(48) NOT NULL COMMENT 'اللقطة التي قيس عليها',
  `measured_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_wave_key` (`wave`,`process_key`),
  KEY `ix_bound` (`bound`),
  KEY `ix_kind` (`enforced_kind`),
  KEY `ix_snap` (`snapshot_id`),
  CONSTRAINT `chk_sodt_witness` CHECK (`witness` <> ''),
  CONSTRAINT `chk_sodt_snapshot` CHECK (`snapshot_id` <> ''),
  CONSTRAINT `chk_sodt_bound` CHECK (`bound` = 0 or `test_file` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-02 12-5 · سجل ربط الفاحص السالب بفصل واجب بعينه — بشاهد لكل صف';

-- ── Table: repair01_source_files ──
CREATE TABLE `repair01_source_files` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `file_no` varchar(8) NOT NULL,
  `file_name` varchar(255) NOT NULL,
  `sha256` char(64) NOT NULL,
  `bytes` int(10) unsigned NOT NULL,
  `sheet_count` smallint(5) unsigned NOT NULL,
  `data_rows` int(10) unsigned NOT NULL,
  `frozen_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_file` (`file_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: repair01_surfaces ──
CREATE TABLE `repair01_surfaces` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `screen_file` varchar(160) NOT NULL,
  `dept_legacy` varchar(160) NOT NULL DEFAULT '',
  `canonical_code` varchar(12) DEFAULT NULL,
  `screen_title` varchar(255) NOT NULL DEFAULT '',
  `layer_name` varchar(60) NOT NULL DEFAULT '',
  `stage_order` varchar(10) NOT NULL DEFAULT '',
  `stage_name` varchar(160) NOT NULL DEFAULT '',
  `group_name` varchar(160) NOT NULL DEFAULT '',
  `output_doc` varchar(255) NOT NULL DEFAULT '',
  `resp_role` varchar(160) NOT NULL DEFAULT '',
  `next_state` varchar(255) NOT NULL DEFAULT '',
  `stage_kind` varchar(20) NOT NULL DEFAULT '',
  `on_disk` tinyint(1) NOT NULL DEFAULT 0,
  `disk_path` varchar(255) NOT NULL DEFAULT '',
  `recon_verdict` varchar(60) NOT NULL DEFAULT '',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `canon_rule` varchar(48) NOT NULL DEFAULT '',
  `canon_why` varchar(400) NOT NULL DEFAULT '',
  `role_source` varchar(64) NOT NULL DEFAULT '',
  `role_why` varchar(400) NOT NULL DEFAULT '',
  `screen_id` varchar(12) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `k_file` (`screen_file`),
  KEY `k_disk` (`on_disk`),
  KEY `k_dept` (`dept_legacy`),
  KEY `k_scr` (`screen_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: repair01_target_gaps ──
CREATE TABLE `repair01_target_gaps` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `unit` varchar(160) NOT NULL DEFAULT '',
  `surface_name` varchar(255) NOT NULL,
  `built_counterpart` varchar(255) NOT NULL DEFAULT '',
  `verdict` varchar(120) NOT NULL DEFAULT '',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `origin_stage` varchar(8) NOT NULL DEFAULT '',
  `origin_note` varchar(255) NOT NULL DEFAULT '',
  `wave_stage` varchar(8) NOT NULL DEFAULT '',
  `split_code` varchar(12) NOT NULL DEFAULT '' COMMENT 'W10 شق الوحدة المشقوقة',
  `split_rule` varchar(48) NOT NULL DEFAULT '',
  `split_why` varchar(400) NOT NULL DEFAULT '',
  `ghost_disposition` varchar(20) NOT NULL DEFAULT '' COMMENT 'BUILD MERGE TAB PROJECTION RETIRE NOT_APPLICABLE - البند 17',
  `disposition_why` varchar(300) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `k_unit` (`unit`),
  CONSTRAINT `chk_w135_ghost` CHECK (`ghost_disposition` = '' and `disposition_why` = '' or `ghost_disposition` in ('BUILD','MERGE','TAB','PROJECTION','RETIRE','NOT_APPLICABLE') and `disposition_why` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: repair01_target_universe ──
CREATE TABLE `repair01_target_universe` (
  `target_uid` varchar(12) NOT NULL COMMENT 'المعرف القانوني الواحد لكل هدف — TGT-nnnn',
  `source` enum('OURS','THEIRS','BOTH') NOT NULL COMMENT 'OURS دفتر المتطلبات · THEIRS سجل الشاشات · BOTH هدف واحد لا اثنان',
  `unit` varchar(12) NOT NULL DEFAULT '' COMMENT 'رمز النطاق — 21 لا 22',
  `name_ar` varchar(255) NOT NULL DEFAULT '' COMMENT 'الاسم كما ورد في مصدره',
  `name_norm` varchar(255) NOT NULL DEFAULT '' COMMENT 'الاسم مطبعا — مفتاح المطابقة',
  `screen_file` varchar(190) NOT NULL DEFAULT '' COMMENT 'مسار الملف حيث عرف',
  `requirement_id` varchar(32) NOT NULL DEFAULT '' COMMENT 'من دفترنا',
  `screen_id` varchar(12) NOT NULL DEFAULT '' COMMENT 'من سجلهم',
  `gap_id` int(11) DEFAULT NULL COMMENT 'صف دفتر الاهداف غير المبنية',
  `match_method` enum('EXACT_UNIT','EXACT_ANY','COMPOUND_SPLIT','CONTAINMENT_CANDIDATE','WAVE_ANCHOR','RULED_BRIDGE','NONE') NOT NULL DEFAULT 'NONE' COMMENT 'طريق المطابقة — RULED_BRIDGE: جسر وظيفة محكوم بدليله (شاشة حية تخدم الهدف باسم اخر)',
  `match_witness` varchar(400) NOT NULL DEFAULT '' COMMENT 'الشاهد المقيس على المطابقة',
  `verdict` enum('MATCHED','MERGED_INTO','TAB_CHILD','PROJECTION','NOT_BUILT','NOT_APPLICABLE','RETIRED_TARGET') DEFAULT NULL COMMENT 'احكام RPR-02 §4-2 السبعة — وفارغ يعني لم يحكم بعد',
  `verdict_witness` varchar(400) NOT NULL DEFAULT '' COMMENT 'مرجع الدليل ومصدر القرار — وحكم بلا شاهد لا يقبل',
  `verdict_snapshot` varchar(48) NOT NULL DEFAULT '' COMMENT 'معرف اللقطة التي قيس عليها',
  `verdict_at` datetime DEFAULT NULL,
  PRIMARY KEY (`target_uid`),
  KEY `ix_tu_unit` (`unit`),
  KEY `ix_tu_norm` (`name_norm`),
  KEY `ix_tu_verdict` (`verdict`),
  KEY `ix_tu_req` (`requirement_id`),
  CONSTRAINT `chk_tu_witness` CHECK (`verdict` is null or `verdict_witness` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='RPR-02 §4-1 كون الاهداف الموحد — معرف واحد لكل هدف';

-- ── Table: repair01_ui_labels ──
CREATE TABLE `repair01_ui_labels` (
  `technical_key` varchar(160) NOT NULL COMMENT 'المفتاح التقني - screen او group او action او code او state',
  `arabic_ui_label` varchar(190) NOT NULL DEFAULT '' COMMENT 'المسمى العربي المعتمد - منقى',
  `short_label` varchar(60) NOT NULL DEFAULT '' COMMENT 'الصيغة القصيرة للزر والتبويب',
  `allowed_context` varchar(120) NOT NULL DEFAULT '' COMMENT 'SIDEBAR TAB BUTTON COLUMN STATE WORK_ITEM CYCLE',
  `sensitive` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'مسمى حساس لا يظهر لكل دور',
  `deprecated_label` varchar(190) NOT NULL DEFAULT '' COMMENT 'الصيغة المتقاعدة - لا تحذف فهي دليل',
  `replacement_label` varchar(190) NOT NULL DEFAULT '' COMMENT 'ما حل محل المتقاعد',
  `visibility_class` varchar(20) NOT NULL DEFAULT '' COMMENT 'USER_VISIBLE AUDITOR_VISIBLE ADMIN_VISIBLE DEVELOPER_ONLY',
  `label_state` varchar(16) NOT NULL DEFAULT 'ACTIVE' COMMENT 'DRAFT ACTIVE DEPRECATED REPLACED',
  `source_table` varchar(64) NOT NULL DEFAULT '',
  `source_column` varchar(64) NOT NULL DEFAULT '',
  `source_key` varchar(200) NOT NULL DEFAULT '' COMMENT 'مفتاح الصف في مصدره - لا اسم بلا صف يعود اليه',
  `owner_code` varchar(12) NOT NULL DEFAULT '' COMMENT 'الادارة المالكة بالرمز المعياري',
  `rule_id` varchar(48) NOT NULL DEFAULT '' COMMENT 'قاعدة الاشتقاق - لا قيمة بلا قاعدة',
  `src_ref` varchar(255) NOT NULL DEFAULT '',
  `origin` varchar(8) NOT NULL DEFAULT 'W06' COMMENT 'ختم الموجة التي سجلت الصف',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`technical_key`),
  KEY `ix_label` (`arabic_ui_label`),
  KEY `ix_dep` (`deprecated_label`),
  KEY `ix_state` (`label_state`),
  KEY `ix_vis` (`visibility_class`),
  KEY `ix_source` (`source_table`,`source_column`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='REPAIR01 W06 - سجل المسميات المركزي: مفتاح تقني واحد لكل مسمى';

-- ── Table: repair01_w00_anchor ──
CREATE TABLE `repair01_w00_anchor` (
  `metric` varchar(64) NOT NULL COMMENT 'مفتاح المقام - تقرؤه الحواجب',
  `label_ar` varchar(160) NOT NULL,
  `measure_sql` text NOT NULL COMMENT 'استعلام يعيد عددا واحدا - به تعاد القياس',
  `anchor_value` int(11) NOT NULL,
  `package_ref` varchar(190) NOT NULL COMMENT 'الحزمة او الامر الذي اثبت هذه القيمة',
  `src_ref` varchar(300) NOT NULL,
  `why` varchar(500) NOT NULL COMMENT 'لماذا هذه القيمة - لا ترسية بلا سبب',
  `anchored_at` datetime NOT NULL,
  `anchored_by` varchar(120) NOT NULL,
  PRIMARY KEY (`metric`),
  CONSTRAINT `chk_w00_anchor_traced` CHECK (`measure_sql` <> '' and `package_ref` <> '' and `src_ref` <> '' and `why` <> ''),
  CONSTRAINT `chk_w00_anchor_value` CHECK (`anchor_value` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='مرساة الطور صفر - حقيقة مسجلة تقرؤها الحواجب بدل ثابت حرفي';

-- ── Table: repair01_w00_anchor_log ──
CREATE TABLE `repair01_w00_anchor_log` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `metric` varchar(64) NOT NULL,
  `value_before` int(11) DEFAULT NULL COMMENT 'خالٍ عند الترسية الاولى',
  `value_after` int(11) NOT NULL,
  `measured_now` int(11) DEFAULT NULL COMMENT 'ما قيس حيا لحظة الترسية',
  `package_ref` varchar(190) NOT NULL,
  `why` varchar(500) NOT NULL,
  `moved_at` datetime NOT NULL,
  `moved_by` varchar(120) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_w00_anchor_log_metric` (`metric`),
  CONSTRAINT `chk_w00_log_reason` CHECK (`why` <> '' and `package_ref` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='سجل حركة مرساة الطور صفر - كل انتقال بسببه ومرجعه';

-- ── Table: repair01_w10_bridge ──
CREATE TABLE `repair01_w10_bridge` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `host_table` varchar(64) NOT NULL,
  `pointer_col` varchar(64) NOT NULL,
  `pointer_key` varchar(200) NOT NULL COMMENT 'مفتاح الصف الحي كما هو',
  `legacy_name` varchar(160) NOT NULL,
  `resolved_code` varchar(12) NOT NULL,
  `bridge_rule` varchar(48) NOT NULL,
  `bridge_why` varchar(400) NOT NULL,
  `probe_sql` varchar(600) NOT NULL COMMENT 'استعلام يثبت ان الرابط القديم ما زال يقرا',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_w10br` (`host_table`,`pointer_key`),
  KEY `ix_w10br_code` (`resolved_code`),
  CONSTRAINT `chk_w10br_full` CHECK (`resolved_code` <> '' and `bridge_rule` <> '' and `bridge_why` <> '' and `probe_sql` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W10 الجسر يترجم ولا يدهس الرابط القديم';

-- ── Table: repair01_w10_decisions ──
CREATE TABLE `repair01_w10_decisions` (
  `decision_id` varchar(24) NOT NULL,
  `question` varchar(400) NOT NULL,
  `ruling` varchar(400) NOT NULL,
  `rationale` varchar(1200) NOT NULL DEFAULT '',
  `scope_rows` int(11) NOT NULL DEFAULT 0,
  `src_ref` varchar(190) NOT NULL DEFAULT '',
  PRIMARY KEY (`decision_id`),
  CONSTRAINT `chk_w10dec_full` CHECK (`question` <> '' and `ruling` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W10 قرارات المرحلة';

-- ── Table: repair01_w10_journey ──
CREATE TABLE `repair01_w10_journey` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `run_id` varchar(40) NOT NULL,
  `seq` smallint(5) unsigned NOT NULL,
  `leg` varchar(48) NOT NULL DEFAULT '',
  `station` varchar(190) NOT NULL,
  `actor` varchar(120) NOT NULL DEFAULT '',
  `consumer` varchar(120) NOT NULL DEFAULT '',
  `business_effect` varchar(400) NOT NULL DEFAULT '',
  `passed` tinyint(1) NOT NULL DEFAULT 0,
  `detail` varchar(600) NOT NULL DEFAULT '',
  `at` datetime(6) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_w10jr` (`run_id`,`seq`),
  KEY `ix_w10jr_run` (`run_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W10 رحلة الشق محطة محطة باثر كل مستهلك';

-- ── Table: repair01_w10_sidebar ──
CREATE TABLE `repair01_w10_sidebar` (
  `screen_id` varchar(16) NOT NULL,
  `route` varchar(200) NOT NULL DEFAULT '',
  `owner_code` varchar(12) NOT NULL DEFAULT '',
  `s1_verdict` varchar(40) NOT NULL DEFAULT '',
  `s1_rule` varchar(48) NOT NULL DEFAULT '',
  `s2_verdict` varchar(40) NOT NULL DEFAULT '',
  `s2_rule` varchar(48) NOT NULL DEFAULT '',
  `s3_verdict` varchar(40) NOT NULL DEFAULT '',
  `s3_rule` varchar(48) NOT NULL DEFAULT '',
  `s4_verdict` varchar(40) NOT NULL DEFAULT '',
  `s4_rule` varchar(48) NOT NULL DEFAULT '',
  `s4_order_no` int(11) NOT NULL DEFAULT 0,
  `s5_verdict` varchar(40) NOT NULL DEFAULT '',
  `s5_rule` varchar(48) NOT NULL DEFAULT '',
  `s6_verdict` varchar(40) NOT NULL DEFAULT '',
  `s6_rule` varchar(48) NOT NULL DEFAULT '',
  `s6_perm_rows` int(11) NOT NULL DEFAULT 0,
  `s7_verdict` varchar(40) NOT NULL DEFAULT '',
  `s7_rule` varchar(48) NOT NULL DEFAULT '',
  `s7_linked` tinyint(1) NOT NULL DEFAULT 0,
  `group_name` varchar(190) NOT NULL DEFAULT '',
  PRIMARY KEY (`screen_id`),
  KEY `ix_w10sb_owner` (`owner_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W10 السايدبار قبل الشاشات سبع خطوات مرتبة';

-- ── Table: repair01_w10_sod ──
CREATE TABLE `repair01_w10_sod` (
  `process_key` varchar(64) NOT NULL,
  `process_name` varchar(190) NOT NULL DEFAULT '',
  `initiator_role` varchar(120) NOT NULL DEFAULT '',
  `reviewer_role` varchar(120) NOT NULL DEFAULT '',
  `approver_role` varchar(120) NOT NULL DEFAULT '',
  `executor_role` varchar(120) NOT NULL DEFAULT '',
  `closer_role` varchar(120) NOT NULL DEFAULT '',
  `forbidden_combo` varchar(300) NOT NULL DEFAULT '',
  `enforced_by` varchar(80) NOT NULL DEFAULT '',
  `authority_rule_id` varchar(48) NOT NULL DEFAULT '',
  `deputy_role` varchar(120) NOT NULL DEFAULT '',
  `scope_note` varchar(190) NOT NULL DEFAULT '',
  `delegation_rule` varchar(190) NOT NULL DEFAULT '',
  `effective_date` date DEFAULT NULL,
  PRIMARY KEY (`process_key`),
  CONSTRAINT `chk_w10sod_full` CHECK (`initiator_role` <> '' and `approver_role` <> '' and `executor_role` <> '' and `closer_role` <> '' and `forbidden_combo` <> '' and `enforced_by` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W10 فصل الواجبات بادوار ستة وتركيبة ممنوعة';

-- ── Table: repair01_w10_split ──
CREATE TABLE `repair01_w10_split` (
  `scope_key` varchar(16) NOT NULL COMMENT 'Screen_ID المعياري',
  `route` varchar(200) NOT NULL DEFAULT '',
  `screen_file` varchar(160) NOT NULL DEFAULT '',
  `title` varchar(255) NOT NULL DEFAULT '',
  `legacy_unit` varchar(160) NOT NULL,
  `in_surfaces` tinyint(1) NOT NULL DEFAULT 0,
  `in_registry` tinyint(1) NOT NULL DEFAULT 0,
  `surf_code_before` varchar(12) NOT NULL DEFAULT '',
  `reg_code_before` varchar(12) NOT NULL DEFAULT '',
  `resolved_code` varchar(12) NOT NULL,
  `split_rule` varchar(48) NOT NULL,
  `split_why` varchar(400) NOT NULL,
  `anchor_ref` varchar(190) NOT NULL DEFAULT '',
  `matched_token` varchar(190) NOT NULL DEFAULT '',
  `serves_both` tinyint(1) NOT NULL DEFAULT 0,
  `moved_surface` tinyint(1) NOT NULL DEFAULT 0,
  `moved_registry` tinyint(1) NOT NULL DEFAULT 0,
  `arbitrary_before` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'كان محسوما بترتيب الصفوف لا بمعناه',
  `updated_at` datetime NOT NULL DEFAULT current_timestamp(),
  `verified_at` datetime DEFAULT NULL COMMENT 'اثر مستهلك الحدث',
  `verify_ref` varchar(64) NOT NULL DEFAULT '',
  PRIMARY KEY (`scope_key`),
  KEY `ix_w10sp_code` (`resolved_code`),
  KEY `ix_w10sp_unit` (`legacy_unit`),
  CONSTRAINT `chk_w10sp_full` CHECK (`resolved_code` <> '' and `split_rule` <> '' and `split_why` <> ''),
  CONSTRAINT `chk_w10sp_reg` CHECK (`in_surfaces` = 1 or `in_registry` = 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W10 قرار الشق سطحا سطحا بقاعدته ومرساته';

-- ── Table: repair01_w10_states ──
CREATE TABLE `repair01_w10_states` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `entity` varchar(64) NOT NULL,
  `from_state` varchar(48) NOT NULL,
  `to_state` varchar(48) NOT NULL,
  `allowed` tinyint(1) NOT NULL DEFAULT 1,
  `owner_role` varchar(120) NOT NULL DEFAULT '',
  `precondition` varchar(400) NOT NULL DEFAULT '',
  `official_doc` varchar(190) NOT NULL DEFAULT '',
  `approval_gate` varchar(190) NOT NULL DEFAULT '',
  `reopen_rule` varchar(300) NOT NULL DEFAULT '',
  `correct_rule` varchar(300) NOT NULL DEFAULT '',
  `forbid_reason` varchar(400) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_w10st` (`entity`,`from_state`,`to_state`),
  CONSTRAINT `chk_w10st_forbid` CHECK (`allowed` = 1 or `forbid_reason` <> ''),
  CONSTRAINT `chk_w10st_allow` CHECK (`allowed` = 0 or `owner_role` <> '' and `precondition` <> '' and `official_doc` <> '' and `approval_gate` <> '' and `reopen_rule` <> '' and `correct_rule` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W10 الة حالة لكل كيان بممنوع صريح مسبب';

-- ── Table: repair01_w10_thresholds ──
CREATE TABLE `repair01_w10_thresholds` (
  `threshold_key` varchar(64) NOT NULL,
  `value_num` int(11) NOT NULL,
  `why` varchar(400) NOT NULL,
  `ref` varchar(190) NOT NULL,
  PRIMARY KEY (`threshold_key`),
  CONSTRAINT `chk_w10th_full` CHECK (`why` <> '' and `ref` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W10 كل رقم يقارن به يقرا من هنا';

-- ── Table: repair01_w10_vocab ──
CREATE TABLE `repair01_w10_vocab` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `token` varchar(190) NOT NULL COMMENT 'المفردة كما وردت في المخزن',
  `token_norm` varchar(190) NOT NULL COMMENT 'المفردة بعد التطبيع',
  `word_count` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `side` varchar(12) NOT NULL COMMENT 'الشق الذي تدل عليه المفردة',
  `weight` int(11) NOT NULL DEFAULT 0 COMMENT 'وزن المصدر زائد طول المفردة',
  `src_kind` varchar(40) NOT NULL COMMENT 'REQUIREMENT_SURFACE او CROSSWALK_CLAUSE او DEPARTMENT_NAME',
  `src_ref` varchar(190) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_w10voc` (`token_norm`,`side`),
  KEY `ix_w10voc_side` (`side`),
  CONSTRAINT `chk_w10voc_full` CHECK (`token_norm` <> '' and `side` <> '' and `src_kind` <> '' and `src_ref` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='W10 مفردات الشق مشتقة من المخزن لا مكتوبة في شيفرة';

-- ── Table: repair01_w11_consolidated ──
CREATE TABLE `repair01_w11_consolidated` (
  `figure_key` varchar(80) NOT NULL,
  `surface` varchar(200) NOT NULL DEFAULT '',
  `figure_name` varchar(190) NOT NULL DEFAULT '',
  `entity_count` int(11) NOT NULL DEFAULT 1 COMMENT 'عدد الكيانات الداخلة في الرقم',
  `tag` varchar(48) NOT NULL DEFAULT '' COMMENT 'SINGLE_ENTITY او GROUP_PROJECTION',
  `tag_label_ar` varchar(120) NOT NULL DEFAULT '' COMMENT 'الوسم المعروض للمستخدم',
  `read_owner` varchar(120) NOT NULL DEFAULT '' COMMENT 'من يملك قراءة الرقم المجمع',
  `why` varchar(600) NOT NULL DEFAULT '',
  `src_ref` varchar(190) NOT NULL DEFAULT '',
  PRIMARY KEY (`figure_key`),
  CONSTRAINT `chk_w11cons_tag` CHECK (`entity_count` <= 1 or `tag` = 'GROUP_PROJECTION' and `tag_label_ar` <> '' and `read_owner` <> '' and `why` <> '')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='REPAIR01 W11 - الرقم العابر للكيانات يوسم او يرفض';

