  `unit_entitlement` varchar(160) NOT NULL DEFAULT '' COMMENT 'الوحدات التعاقدية المكافئة (الاستحقاق) ◄',
  `unit` varchar(160) NOT NULL DEFAULT '' COMMENT 'الوحدات التعاقدية الممنوحة (أعدادا صحيحة)',
  `supplier` varchar(160) NOT NULL DEFAULT '' COMMENT 'تصنيف المورد ▼',
  `target` varchar(160) NOT NULL DEFAULT '' COMMENT 'آلات تعاقدية = المستهدف ÷ أساس الوحدة التعاقدية ◄',
  `target_supplier` varchar(160) NOT NULL DEFAULT '' COMMENT 'آلات واقعية = المستهدف ÷ إنتاجية آلة المورد ◄',
  `date` date DEFAULT NULL COMMENT 'ساري من تاريخ',
  `ref_allocation` varchar(160) NOT NULL DEFAULT '' COMMENT 'مرجع قرار التوزيع',
  `allocation` varchar(60) NOT NULL DEFAULT '' COMMENT 'حالة التوزيع ▼',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `created_by` int(11) NOT NULL DEFAULT 0,
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `dist_row_code` varchar(255) DEFAULT NULL COMMENT 'معرّف سطر التوزيع',
  `obligation_cycle_key` varchar(80) DEFAULT NULL COMMENT 'مفتاح دورة الالتزام السنوية ◄',
  `supplier_no_ref` varchar(80) DEFAULT NULL COMMENT 'رقم المورد ◄',
  `supplier_name_ref` varchar(255) DEFAULT NULL COMMENT 'اسم المورد ◄',
  `line_type_ref` varchar(255) DEFAULT NULL COMMENT 'نوع الآلية/البند ◄',
  `monthly_unit_base` decimal(18,3) DEFAULT NULL COMMENT 'أساس الوحدة التعاقدية الشهري ◄',
  `avg_monthly_executed` decimal(18,3) DEFAULT NULL COMMENT 'متوسط المنفَّذ الشهري ◄',
  `equivalent_units` decimal(18,3) DEFAULT NULL COMMENT 'الوحدات التعاقدية المكافئة (الاستحقاق) ◄',
  `granted_units` int(11) DEFAULT NULL COMMENT 'الوحدات التعاقدية الممنوحة (أعدادًا صحيحة)',
  `largest_remainder_gap` decimal(18,4) DEFAULT NULL COMMENT 'فارق أكبر البواقي ◄',
  `excess_machines` decimal(18,3) DEFAULT NULL COMMENT 'آليات زائدة عن الوحدات التعاقدية ◄',
  `supplier_class` varchar(80) DEFAULT NULL COMMENT 'تصنيف المورد ▼',
  `shared_slot_member` varchar(80) DEFAULT NULL COMMENT 'عضو خانة مشتركة؟ ▼',
  `shared_contribution_pct` varchar(80) DEFAULT NULL COMMENT 'نسبة المساهمة في الوحدة التعاقدية المشتركة',
  `contractual_machines` decimal(18,3) DEFAULT NULL COMMENT 'آلات تعاقدية = المستهدف ÷ أساس الوحدة التعاقدية ◄',
  `actual_machines` decimal(18,3) DEFAULT NULL COMMENT 'آلات واقعية = المستهدف ÷ إنتاجية آلة المورد ◄',
  `contractual_vs_actual_gap` decimal(18,3) DEFAULT NULL COMMENT 'الفرق بين التعاقدي والواقعي ◄',
  `valid_from` date DEFAULT NULL COMMENT 'ساري من تاريخ',
  `dist_decision_ref` varchar(80) DEFAULT NULL COMMENT 'مرجع قرار التوزيع',
  `dist_state` varchar(80) DEFAULT NULL COMMENT 'حالة التوزيع ▼',
  PRIMARY KEY (`id`),
  KEY `ix_sup_slot_allocation_quot_co` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── Table: sup_target_supplier ──
