  `vessel_id` int(10) unsigned NOT NULL DEFAULT 0,
  `direction` varchar(8) NOT NULL DEFAULT '' COMMENT 'in او out',
  `amount` decimal(18,2) NOT NULL DEFAULT 0.00,
