-- ── View: unified_fault_taxonomy ──
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `unified_fault_taxonomy` AS select distinct `fc`.`main_category_code` AS `code`,`fc`.`main_category_name` AS `name`,`fc`.`equipment_type` AS `equipment_type`,'failure_codes' AS `source` from `failure_codes` `fc` where `fc`.`main_category_code` is not null and `fc`.`main_category_code` <> '';

-- ── View: v_active_impersonations ──
SET collation_connection = 'utf8mb4_unicode_ci';
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_active_impersonations` AS select `i`.`imp_id` AS `imp_id`,`a`.`username` AS `actor`,`t`.`username` AS `target`,`i`.`reason` AS `reason`,`i`.`opened_at` AS `opened_at`,`i`.`valid_to` AS `valid_to`,`i`.`notified_at` AS `notified_at` from ((`impersonation_sessions` `i` join `users` `a` on(`a`.`id` = `i`.`actor_user`)) join `users` `t` on(`t`.`id` = `i`.`target_user`)) where `i`.`closed_at` is null;

-- ── View: v_approval_rules_effective ──
SET collation_connection = 'utf8mb4_unicode_ci';
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_approval_rules_effective` AS select `l`.`ladder_code` AS `ladder_code`,`l`.`slug` AS `entity_type`,`s`.`step_no` AS `step_order`,coalesce(`a`.`role_id`,-99) AS `role_required`,`s`.`actor_code` AS `actor_code`,`s`.`actor_name_ar` AS `actor_name_ar`,`s`.`step_kind` AS `step_kind`,`s`.`may_approve` AS `may_approve`,`l`.`name_ar` AS `ladder_name`,`l`.`cap_kind` AS `cap_kind`,`l`.`cap_amount` AS `cap_amount`,`l`.`cap_currency` AS `cap_currency`,`l`.`cap_state` AS `cap_state`,`l`.`escalate_after_hours` AS `escalate_after_hours`,`l`.`is_active` AS `is_active` from ((`gov_ladders` `l` join `gov_ladder_steps` `s` on(`s`.`ladder_code` = `l`.`ladder_code`)) left join `gov_ladder_actor_roles` `a` on(`a`.`actor_code` = `s`.`actor_code`)) where `l`.`is_active` = 1 union select `l`.`ladder_code` AS `ladder_code`,`l`.`entity_type` AS `entity_type`,`s`.`step_no` AS `step_order`,coalesce(`a`.`role_id`,-99) AS `role_required`,`s`.`actor_code` AS `actor_code`,`s`.`actor_name_ar` AS `actor_name_ar`,`s`.`step_kind` AS `step_kind`,`s`.`may_approve` AS `may_approve`,`l`.`name_ar` AS `ladder_name`,`l`.`cap_kind` AS `cap_kind`,`l`.`cap_amount` AS `cap_amount`,`l`.`cap_currency` AS `cap_currency`,`l`.`cap_state` AS `cap_state`,`l`.`escalate_after_hours` AS `escalate_after_hours`,`l`.`is_active` AS `is_active` from ((`gov_ladders` `l` join `gov_ladder_steps` `s` on(`s`.`ladder_code` = `l`.`ladder_code`)) left join `gov_ladder_actor_roles` `a` on(`a`.`actor_code` = `s`.`actor_code`)) where `l`.`is_active` = 1 and `l`.`entity_type` is not null and `l`.`entity_type` <> '';

-- ── View: v_authority_expiring ──
SET collation_connection = 'utf8mb4_general_ci';
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_authority_expiring` AS select 'grant' AS `kind`,`g`.`grant_id` AS `ref_id`,`g`.`user_id` AS `user_id`,`g`.`valid_to` AS `valid_to` from `gov_authority_grants` `g` where `g`.`revoked_at` is null and `g`.`valid_to` between current_timestamp() and current_timestamp() + interval 48 hour union all select 'delegation' AS `delegation`,`d`.`delegation_id` AS `delegation_id`,`d`.`to_user` AS `to_user`,`d`.`valid_to` AS `valid_to` from `gov_delegations` `d` where `d`.`revoked_at` is null and `d`.`valid_to` between current_timestamp() and current_timestamp() + interval 48 hour union all select 'elevation' AS `elevation`,`e`.`elevation_id` AS `elevation_id`,`e`.`user_id` AS `user_id`,`e`.`valid_to` AS `valid_to` from `gov_elevations` `e` where `e`.`state` = 'active' and `e`.`valid_to` between current_timestamp() and current_timestamp() + interval 48 hour union all select 'impersonation' AS `impersonation`,`i`.`imp_id` AS `imp_id`,`i`.`actor_user` AS `actor_user`,`i`.`valid_to` AS `valid_to` from `impersonation_sessions` `i` where `i`.`closed_at` is null and `i`.`valid_to` between current_timestamp() and current_timestamp() + interval 48 hour;

-- ── View: v_caps_unresolved ──
CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_caps_unresolved` AS select 'fin_authority_caps' AS `src`,`fin_authority_caps`.`id` AS `id`,`fin_authority_caps`.`company_id` AS `company_id`,`fin_authority_caps`.`scope_kind` AS `scope_kind`,`fin_authority_caps`.`scope_ref` AS `scope_ref`,`fin_authority_caps`.`apr_code` AS `apr_code`,`fin_authority_caps`.`max_amount` AS `max_amount`,`fin_authority_caps`.`currency` AS `currency`,`fin_authority_caps`.`cap_state` AS `cap_state` from `fin_authority_caps` where `fin_authority_caps`.`cap_state` <> 'resolved' union all select 'gov_ladders' AS `gov_ladders`,NULL AS `NULL`,`gov_ladders`.`company_id` AS `company_id`,'ladder' AS `ladder`,`gov_ladders`.`ladder_code` AS `ladder_code`,`gov_ladders`.`slug` AS `slug`,`gov_ladders`.`cap_amount` AS `cap_amount`,`gov_ladders`.`cap_currency` AS `cap_currency`,`gov_ladders`.`cap_state` AS `cap_state` from `gov_ladders` where `gov_ladders`.`cap_kind` = 'amount' and `gov_ladders`.`cap_state` <> 'resolved';

-- ── View: v_container_elapsed_target ──
SET collation_connection = 'utf8mb4_unicode_ci';
CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_container_elapsed_target` AS select `c`.`company_id` AS `company_id`,`c`.`id` AS `container_id`,`c`.`container_no` AS `container_no`,`c`.`cap_qty` AS `cap_qty`,`k`.`actual_start` AS `actual_start`,`k`.`actual_end` AS `actual_end`,least(`c`.`cap_qty`,greatest(0,round(`c`.`cap_qty` * (to_days(least(curdate(),`k`.`actual_end`)) - to_days(`k`.`actual_start`)) / nullif(to_days(`k`.`actual_end`) - to_days(`k`.`actual_start`),0),2))) AS `elapsed_target` from (`op_containers` `c` join `contracts` `k` on(`k`.`id` = `c`.`contract_id`)) where `c`.`level` = 'رئيسية' and `c`.`is_deleted` = 0 and `k`.`actual_start` is not null and `k`.`actual_end` is not null;

-- ── View: v_effective_authority ──
SET collation_connection = 'utf8mb4_unicode_ci';
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_effective_authority` AS select `g`.`user_id` AS `user_id`,`u`.`username` AS `username`,`g`.`profile_id` AS `profile_id`,`p`.`profile_code` AS `profile_code`,`p`.`grade` AS `grade`,`p`.`dept_code` AS `dept_code`,`g`.`source` AS `source`,1 AS `priority`,`g`.`valid_from` AS `valid_from`,`g`.`valid_to` AS `valid_to` from ((`gov_authority_grants` `g` join `users` `u` on(`u`.`id` = `g`.`user_id`)) join `gov_role_profiles` `p` on(`p`.`profile_id` = `g`.`profile_id`)) where `g`.`revoked_at` is null and (`g`.`valid_to` is null or `g`.`valid_to` > current_timestamp()) and `g`.`source` = 'profile' union all select `boss_u`.`id` AS `id`,`boss_u`.`username` AS `username`,`g`.`profile_id` AS `profile_id`,`p`.`profile_code` AS `profile_code`,`p`.`grade` AS `grade`,`p`.`dept_code` AS `dept_code`,'escalation' AS `escalation`,2 AS `2`,`g`.`valid_from` AS `valid_from`,`g`.`valid_to` AS `valid_to` from (((((`gov_authority_grants` `g` join `users` `sub_u` on(`sub_u`.`id` = `g`.`user_id`)) join `roles` `sub_r` on(`sub_r`.`id` = `sub_u`.`role`)) join `roles` `boss_r` on(`boss_r`.`id` = `sub_r`.`parent_role_id`)) join `users` `boss_u` on(`boss_u`.`role` = `boss_r`.`id` and `boss_u`.`status` = 1)) join `gov_role_profiles` `p` on(`p`.`profile_id` = `g`.`profile_id`)) where `g`.`revoked_at` is null and (`g`.`valid_to` is null or `g`.`valid_to` > current_timestamp()) and `g`.`source` = 'profile' union all select `g`.`user_id` AS `user_id`,`u`.`username` AS `username`,`g`.`profile_id` AS `profile_id`,`p`.`profile_code` AS `profile_code`,`p`.`grade` AS `grade`,`p`.`dept_code` AS `dept_code`,`g`.`source` AS `source`,3 AS `3`,`g`.`valid_from` AS `valid_from`,`g`.`valid_to` AS `valid_to` from ((`gov_authority_grants` `g` join `users` `u` on(`u`.`id` = `g`.`user_id`)) join `gov_role_profiles` `p` on(`p`.`profile_id` = `g`.`profile_id`)) where `g`.`revoked_at` is null and `g`.`valid_to` > current_timestamp() and `g`.`source` in ('delegation','elevation');

-- ── View: v_group_load ──
CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_group_load` AS select `g`.`owner_role_id` AS `role_id`,`g`.`id` AS `group_id`,`g`.`group_code` AS `group_code`,`g`.`name` AS `group_name`,`g`.`stage_no` AS `stage_no`,`g`.`stage_title` AS `stage_title`,count(`n`.`id`) AS `screens`,case when count(`n`.`id`) >= 8 then 'overloaded' when count(`n`.`id`) = 0 then 'empty' else 'ok' end AS `load_state` from (`link_groups` `g` left join `nav_items` `n` on(`n`.`group_id` = `g`.`id` and `n`.`active` = 1)) where `g`.`is_active` = 1 group by `g`.`id`;

-- ── View: v_hand_conflicts ──
SET collation_connection = 'utf8mb4_general_ci';
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_hand_conflicts` AS select 'grant_self_issued' AS `conflict_kind`,`g`.`grant_id` AS `ref_id`,`g`.`user_id` AS `actor`,`g`.`issued_by` AS `second_party`,`g`.`created_at` AS `created_at` from `gov_authority_grants` `g` where `g`.`issued_by` = `g`.`user_id` and `g`.`source` <> 'profile' union all select 'elevation_self_approved' AS `elevation_self_approved`,`e`.`elevation_id` AS `elevation_id`,`e`.`user_id` AS `user_id`,`e`.`ceo_approver` AS `ceo_approver`,`e`.`created_at` AS `created_at` from `gov_elevations` `e` where `e`.`ceo_approver` = `e`.`user_id`;

-- ── View: v_ladder_step_limit ──
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_ladder_step_limit` AS select `l`.`ladder_code` AS `ladder_code`,`l`.`name_ar` AS `name_ar`,count(`s`.`id`) AS `steps`,sum(`s`.`may_approve`) AS `approvers`,case when count(`s`.`id`) > 3 then 'exceeds_three' else 'within_limit' end AS `verdict` from (`gov_ladders` `l` left join `gov_ladder_steps` `s` on(`s`.`ladder_code` = `l`.`ladder_code`)) where `l`.`is_active` = 1 group by `l`.`ladder_code`,`l`.`name_ar`;

-- ── View: v_machine_daily_hours ──
CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_machine_daily_hours` AS select `ue`.`company_id` AS `company_id`,`ue`.`equipment_id` AS `equipment_id`,`ue`.`entry_date` AS `work_date`,round(coalesce(sum(case when `l`.`ops_state` = 'actual_work' then `l`.`hours` end),0),2) AS `daily_hours` from (`unit_entries` `ue` left join `unit_time_log` `l` on(`l`.`entry_id` = `ue`.`id`)) where `ue`.`seed_tag` is null and `ue`.`state` not in ('rejected','cancelled','superseded','reversed') group by `ue`.`company_id`,`ue`.`equipment_id`,`ue`.`entry_date`;

-- ── View: v_machine_daily_median ──
CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_machine_daily_median` AS select `x`.`company_id` AS `company_id`,`x`.`equipment_id` AS `equipment_id`,round(avg(`x`.`daily_hours`),2) AS `median_daily_hours`,max(`x`.`cnt`) AS `days_counted` from (select `v_machine_daily_hours`.`company_id` AS `company_id`,`v_machine_daily_hours`.`equipment_id` AS `equipment_id`,`v_machine_daily_hours`.`daily_hours` AS `daily_hours`,row_number() over ( partition by `v_machine_daily_hours`.`company_id`,`v_machine_daily_hours`.`equipment_id` order by `v_machine_daily_hours`.`daily_hours`) AS `rn`,count(0) over ( partition by `v_machine_daily_hours`.`company_id`,`v_machine_daily_hours`.`equipment_id`) AS `cnt` from `v_machine_daily_hours` where `v_machine_daily_hours`.`daily_hours` > 0) `x` where `x`.`rn` in (floor((`x`.`cnt` + 1) / 2),ceiling((`x`.`cnt` + 1) / 2)) group by `x`.`company_id`,`x`.`equipment_id`;

-- ── View: v_monthly_performance ──
SET collation_connection = 'utf8mb4_unicode_ci';
CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_monthly_performance` AS select `ue`.`company_id` AS `company_id`,date_format(`ue`.`entry_date`,'%Y-%m') AS `period`,`ue`.`supplier_entity_id` AS `supplier_entity_id`,`ue`.`contract_id` AS `contract_id`,`ue`.`project_id` AS `project_id`,`ue`.`equipment_id` AS `equipment_id`,count(distinct `ue`.`id`) AS `entries_count`,count(distinct `ue`.`entry_date`) AS `days_worked`,round(coalesce(sum(case when `l`.`ops_state` = 'actual_work' then `l`.`hours` end),0),2) AS `run_hours`,round(coalesce(sum(case when `l`.`ops_state` = 'standby' then `l`.`hours` end),0),2) AS `standby_hours`,round(coalesce(sum(case when `l`.`ops_state` in ('tech_breakdown','supplier_stop','operator_stop','client_stop','fuel_logistics_stop','planned_stop','force_majeure') then `l`.`hours` end),0),2) AS `breakdown_hours`,round(coalesce(sum(`l`.`hours`),0),2) AS `total_hours`,round(coalesce(sum(case when `l`.`resp_party` = 'client' then `l`.`hours` end),0),2) AS `client_liable_hours`,round(coalesce(sum(case when `l`.`resp_party` = 'supplier' then `l`.`hours` end),0),2) AS `supplier_liable_hours`,round(coalesce(sum(case when `l`.`resp_party` = 'company' then `l`.`hours` end),0),2) AS `company_liable_hours`,round(coalesce(sum(case when `l`.`ops_state` = 'standby' or `l`.`resp_party` = 'client' and `l`.`ops_state` in ('tech_breakdown','supplier_stop','operator_stop','client_stop','fuel_logistics_stop','planned_stop','force_majeure') then `l`.`hours` end),0),2) AS `billable_standby_hours`,case when coalesce(sum(`l`.`hours`),0) > 0 then round(100 * coalesce(sum(case when `l`.`ops_state` = 'actual_work' then `l`.`hours` end),0) / sum(`l`.`hours`),2) else NULL end AS `availability_pct`,round(coalesce(sum(`ue`.`fuel_issued_qty`),0),2) AS `fuel_issued_qty`,round(coalesce(sum(`ue`.`fuel_received_qty`),0),2) AS `fuel_received_qty`,round(coalesce(sum(case when `ue`.`meter_after` is not null and `ue`.`meter_before` is not null then `ue`.`meter_after` - `ue`.`meter_before` end),0),2) AS `meter_delta`,round(coalesce(sum(case when `ue`.`unit_type` = 'ton' then `ue`.`qty` end),0),2) AS `tons`,round(coalesce(sum(case when `ue`.`unit_type` = 'meter' then `ue`.`qty` end),0),2) AS `meters`,round(coalesce(sum(case when `ue`.`unit_type` = 'trip' then `ue`.`qty` end),0),2) AS `trips`,max(`ue`.`updated_at`) AS `last_entry_at` from (`unit_entries` `ue` left join `unit_time_log` `l` on(`l`.`entry_id` = `ue`.`id`)) where `ue`.`seed_tag` is null and `ue`.`state` not in ('rejected','cancelled','superseded','reversed') group by `ue`.`company_id`,date_format(`ue`.`entry_date`,'%Y-%m'),`ue`.`supplier_entity_id`,`ue`.`contract_id`,`ue`.`project_id`,`ue`.`equipment_id`;

-- ── View: v_open_elevations ──
SET collation_connection = 'utf8mb4_unicode_ci';
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_open_elevations` AS select `e`.`elevation_id` AS `elevation_id`,`e`.`user_id` AS `user_id`,`u`.`username` AS `username`,`e`.`target_grade` AS `target_grade`,`e`.`target_dept` AS `target_dept`,`e`.`state` AS `state`,`e`.`hr_witness` AS `hr_witness`,`e`.`fin_witness` AS `fin_witness`,`e`.`ceo_approver` AS `ceo_approver`,`e`.`valid_to` AS `valid_to`,`e`.`reason` AS `reason` from (`gov_elevations` `e` join `users` `u` on(`u`.`id` = `e`.`user_id`)) where `e`.`state` not in ('expired','rejected');

-- ── View: v_org_unit_heads ──
SET collation_connection = 'utf8mb4_unicode_ci';
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_org_unit_heads` AS select `u`.`unit_id` AS `unit_id`,`u`.`company_id` AS `company_id`,`u`.`unit_code` AS `unit_code`,`u`.`name_ar` AS `name_ar`,`a`.`person_id` AS `head_person_id`,`a`.`asg_id` AS `head_assignment_id`,`a`.`scope_type` AS `head_scope_type`,`a`.`scope_id` AS `head_scope_id` from (`org_units` `u` left join `org_assignments` `a` on(`a`.`org_unit_id` = `u`.`unit_id` and `a`.`state` = 'active' and curdate() between `a`.`valid_from` and `a`.`valid_to` and `a`.`assignment_type_code` in (select `t`.`type_code` from `org_assignment_types` `t` where `t`.`is_unit_head` = 1)));

-- ── View: v_oversight_lines ──
SET collation_connection = 'utf8mb4_unicode_ci';
CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_oversight_lines` AS select `r`.`id` AS `role_id`,`r`.`name` AS `role_name`,`r`.`parent_role_id` AS `admin_parent_id`,`pa`.`name` AS `admin_parent_name`,`r`.`oversight_role_id` AS `oversight_role_id`,`ov`.`name` AS `oversight_role_name`,`r`.`oversight_note` AS `oversight_note` from ((`roles` `r` left join `roles` `pa` on(`pa`.`id` = `r`.`parent_role_id`)) left join `roles` `ov` on(`ov`.`id` = `r`.`oversight_role_id`)) where `r`.`oversight_role_id` is not null or `r`.`id` = 9;

-- ── View: v_slot_total_margin ──
CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_slot_total_margin` AS select `seat`.`company_id` AS `company_id`,`seat`.`id` AS `slot_id`,`seat`.`container_no` AS `container_no`,`sup`.`supplier_id` AS `supplier_id`,`seat`.`unit_margin` AS `unit_margin`,round(coalesce(`st`.`settled`,0) * coalesce(`seat`.`monthly_basis`,0) / nullif(`basis`.`total_basis`,0),2) AS `slot_settled_hours`,round(coalesce(`seat`.`unit_margin`,0) * coalesce(`st`.`settled`,0) * coalesce(`seat`.`monthly_basis`,0) / nullif(`basis`.`total_basis`,0),2) AS `slot_total_margin`,case when coalesce(`seat`.`unit_margin`,0) < 0 then 'سالبٌ — يُرفع لمالكِ العقد' else '' end AS `margin_flag` from (((`op_containers` `seat` join `op_containers` `sup` on(`sup`.`id` = `seat`.`parent_id` and `sup`.`level` = 'مورد' and `sup`.`is_deleted` = 0)) left join (select `op_containers`.`parent_id` AS `parent_id`,sum(`op_containers`.`monthly_basis`) AS `total_basis` from `op_containers` where `op_containers`.`is_deleted` = 0 and `op_containers`.`level` = 'معدة' group by `op_containers`.`parent_id`) `basis` on(`basis`.`parent_id` = `sup`.`id`)) left join (select `settlements`.`company_id` AS `company_id`,`settlements`.`party_ref` AS `party_ref`,sum(`settlements`.`client_settled_hours`) AS `settled` from `settlements` where `settlements`.`is_deleted` = 0 and `settlements`.`party_type` = 'supplier' group by `settlements`.`company_id`,`settlements`.`party_ref`) `st` on(`st`.`company_id` = `seat`.`company_id` and `st`.`party_ref` = cast(`sup`.`supplier_id` as char charset utf8mb4))) where `seat`.`level` = 'معدة' and `seat`.`is_deleted` = 0;

-- ── View: v_supplier_balance_aging ──
SET collation_connection = 'utf8mb4_unicode_ci';
CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_supplier_balance_aging` AS select `s`.`company_id` AS `company_id`,`s`.`party_ref` AS `supplier_id`,max(`su`.`name`) AS `supplier_name`,max(`su`.`supplier_code`) AS `supplier_code`,`s`.`currency` AS `currency`,count(0) AS `open_settlements`,sum(`s`.`net_amount`) AS `outstanding_amount`,min(`s`.`period_to`) AS `oldest_period_to`,max(`s`.`period_to`) AS `newest_period_to`,max(to_days(curdate()) - to_days(`s`.`period_to`)) AS `oldest_age_days`,sum(case when to_days(curdate()) - to_days(`s`.`period_to`) <= 30 then `s`.`net_amount` else 0 end) AS `bucket_0_30`,sum(case when to_days(curdate()) - to_days(`s`.`period_to`) between 31 and 60 then `s`.`net_amount` else 0 end) AS `bucket_31_60`,sum(case when to_days(curdate()) - to_days(`s`.`period_to`) between 61 and 90 then `s`.`net_amount` else 0 end) AS `bucket_61_90`,sum(case when to_days(curdate()) - to_days(`s`.`period_to`) between 91 and 180 then `s`.`net_amount` else 0 end) AS `bucket_91_180`,sum(case when to_days(curdate()) - to_days(`s`.`period_to`) > 180 then `s`.`net_amount` else 0 end) AS `bucket_over_180`,sum(case when `s`.`state` = 'payment_requested' then `s`.`net_amount` else 0 end) AS `requested_amount`,sum(case when `s`.`state` = 'approved' then `s`.`net_amount` else 0 end) AS `approved_amount`,sum(case when `s`.`open_objections` > 0 then 1 else 0 end) AS `with_objections`,case when max(to_days(curdate()) - to_days(`s`.`period_to`)) > 180 then 'أكثر من ١٨٠ يومًا' when max(to_days(curdate()) - to_days(`s`.`period_to`)) > 90 then '٩١–١٨٠ يومًا' when max(to_days(curdate()) - to_days(`s`.`period_to`)) > 60 then '٦١–٩٠ يومًا' when max(to_days(curdate()) - to_days(`s`.`period_to`)) > 30 then '٣١–٦٠ يومًا' else 'حتى ٣٠ يومًا' end collate utf8mb4_unicode_ci AS `age_bucket`,case when sum(case when `s`.`open_objections` > 0 then 1 else 0 end) > 0 then 'حسمُ الاعتراضاتِ المفتوحةِ قبلَ الصرف' when sum(case when `s`.`state` = 'payment_requested' then 1 else 0 end) > 0 then 'متابعةُ طلبِ الدفعِ لدى المالية' when max(to_days(curdate()) - to_days(`s`.`period_to`)) > 180 then 'تصعيدٌ — رصيدٌ تجاوز ١٨٠ يومًا' when max(to_days(curdate()) - to_days(`s`.`period_to`)) > 90 then 'إصدارُ طلبِ دفعٍ عاجل' else 'ضمنَ المهلةِ — لا إجراءَ عاجل' end collate utf8mb4_unicode_ci AS `suggested_action`,min(`s`.`prepared_at`) AS `first_prepared_at`,max(`s`.`approved_at`) AS `last_approved_at` from (`settlements` `s` left join `suppliers` `su` on(`su`.`id` = `s`.`party_ref` and `su`.`is_deleted` = 0)) where `s`.`is_deleted` = 0 and `s`.`party_type` = 'supplier' and `s`.`state` in ('approved','payment_requested') and `s`.`paid_at` is null group by `s`.`company_id`,`s`.`party_ref`,`s`.`currency`;

-- ── View: v_supplier_qualification ──
SET collation_connection = 'utf8mb4_unicode_ci';
CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_supplier_qualification` AS select `s`.`company_id` AS `company_id`,`s`.`id` AS `supplier_id`,`s`.`name` AS `supplier_name`,`s`.`supplier_code` AS `supplier_code`,`s`.`commercial_registration` is not null and `s`.`commercial_registration` <> '' AS `has_cr`,`s`.`tax_number` is not null and `s`.`tax_number` <> '' AS `has_tax`,`s`.`identity_number` is not null and `s`.`identity_number` <> '' AS `has_identity`,`s`.`identity_expiry_date` AS `identity_expiry_date`,`s`.`identity_expiry_date` is not null and `s`.`identity_expiry_date` < curdate() AS `identity_expired`,`s`.`bank_account_no` is not null and `s`.`bank_account_no` <> '' AS `has_bank_account`,`s`.`bank_iban` is not null and `s`.`bank_iban` <> '' AS `has_iban`,`s`.`bank_verified_at` is not null AS `bank_verified`,(`s`.`commercial_registration` is null or `s`.`commercial_registration` = '') + (`s`.`tax_number` is null or `s`.`tax_number` = '') + (`s`.`identity_number` is null or `s`.`identity_number` = '') + (`s`.`bank_account_no` is null or `s`.`bank_account_no` = '') + (`s`.`bank_verified_at` is null) AS `missing_count`,concat_ws('، ',case when `s`.`commercial_registration` is null or `s`.`commercial_registration` = '' then cast('سجلٌّ تجاريّ' as char charset utf8mb4) collate utf8mb4_unicode_ci end,case when `s`.`tax_number` is null or `s`.`tax_number` = '' then cast('رقمٌ ضريبيّ' as char charset utf8mb4) collate utf8mb4_unicode_ci end,case when `s`.`identity_number` is null or `s`.`identity_number` = '' then cast('هويّة' as char charset utf8mb4) collate utf8mb4_unicode_ci end,case when `s`.`bank_account_no` is null or `s`.`bank_account_no` = '' then cast('حسابٌ بنكيّ' as char charset utf8mb4) collate utf8mb4_unicode_ci end,case when `s`.`bank_verified_at` is null then cast('توثيقُ الحساب' as char charset utf8mb4) collate utf8mb4_unicode_ci end) AS `missing_list`,case when `s`.`commercial_registration` is null or `s`.`commercial_registration` = '' or `s`.`tax_number` is null or `s`.`tax_number` = '' or `s`.`identity_number` is null or `s`.`identity_number` = '' or `s`.`bank_account_no` is null or `s`.`bank_account_no` = '' or `s`.`bank_verified_at` is null then cast('ناقصُ التأهيل' as char charset utf8mb4) collate utf8mb4_unicode_ci when `s`.`identity_expiry_date` is not null and `s`.`identity_expiry_date` < curdate() then cast('هويّةٌ منتهية' as char charset utf8mb4) collate utf8mb4_unicode_ci else cast('مؤهَّل' as char charset utf8mb4) collate utf8mb4_unicode_ci end AS `qualification_state`,coalesce(`k`.`live_contracts`,0) AS `live_contracts` from (`suppliers` `s` left join (select `supplier_contracts`.`supplier_id` AS `supplier_id`,count(0) AS `live_contracts` from `supplier_contracts` where `supplier_contracts`.`is_deleted` = 0 group by `supplier_contracts`.`supplier_id`) `k` on(`k`.`supplier_id` = `s`.`id`)) where `s`.`is_deleted` = 0;

-- ── View: v_supplier_share_units ──
SET collation_connection = 'utf8mb4_unicode_ci';
CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_supplier_share_units` AS select `s`.`company_id` AS `company_id`,`s`.`id` AS `supplier_container_id`,`s`.`container_no` AS `container_no`,`s`.`supplier_id` AS `supplier_id`,round(coalesce(sum(`seat`.`monthly_basis`),0) * ((to_days(coalesce(`s`.`valid_to`,`p`.`valid_to`)) - to_days(coalesce(`s`.`valid_from`,`p`.`valid_from`))) / 30.0),2) AS `share_units`,coalesce(`s`.`valid_from`,`p`.`valid_from`) AS `effective_from`,coalesce(`s`.`valid_to`,`p`.`valid_to`) AS `effective_to` from ((`op_containers` `s` left join `op_containers` `p` on(`p`.`id` = `s`.`parent_id`)) left join `op_containers` `seat` on(`seat`.`parent_id` = `s`.`id` and `seat`.`is_deleted` = 0 and `seat`.`level` = 'معدة')) where `s`.`level` = 'مورد' and `s`.`is_deleted` = 0 group by `s`.`company_id`,`s`.`id`,`s`.`container_no`,`s`.`supplier_id`,coalesce(`s`.`valid_from`,`p`.`valid_from`),coalesce(`s`.`valid_to`,`p`.`valid_to`);

-- ── View: v_supplier_targets_monthly ──
SET collation_connection = 'utf8mb4_unicode_ci';
CREATE ALGORITHM=UNDEFINED SQL SECURITY INVOKER VIEW `v_supplier_targets_monthly` AS with recursive span as (select `v_supplier_share_units`.`company_id` AS `company_id`,`v_supplier_share_units`.`supplier_id` AS `supplier_id`,date_format(min(`v_supplier_share_units`.`effective_from`),'%Y-%m-01') AS `m_first`,date_format(max(`v_supplier_share_units`.`effective_to`),'%Y-%m-01') AS `m_last` from `v_supplier_share_units` where `v_supplier_share_units`.`supplier_id` is not null and `v_supplier_share_units`.`effective_from` is not null and `v_supplier_share_units`.`effective_to` is not null group by `v_supplier_share_units`.`company_id`,`v_supplier_share_units`.`supplier_id`), months as (select `span`.`company_id` AS `company_id`,`span`.`supplier_id` AS `supplier_id`,cast(`span`.`m_first` as date) AS `mon`,cast(`span`.`m_last` as date) AS `m_last` from `span` union all select `months`.`company_id` AS `company_id`,`months`.`supplier_id` AS `supplier_id`,`months`.`mon` + interval 1 month AS `DATE_ADD(mon, INTERVAL 1 MONTH)`,`months`.`m_last` AS `m_last` from `months` where `months`.`mon` < `months`.`m_last`)select `m`.`company_id` AS `company_id`,`m`.`supplier_id` AS `supplier_id`,`s`.`name` AS `supplier_name`,cast(date_format(`m`.`mon`,'%Y-%m') as char charset utf8mb4) collate utf8mb4_unicode_ci AS `target_month`,`m`.`mon` AS `month_start`,count(`u`.`supplier_container_id`) AS `shares_active`,round(coalesce(sum(`u`.`share_units` * 30.0 / nullif(to_days(`u`.`effective_to`) - to_days(`u`.`effective_from`),0)),0),2) AS `monthly_target`,case when count(`u`.`supplier_container_id`) = 0 then cast('شهرُ صفرٍ — لا حصةَ سارية' as char charset utf8mb4) collate utf8mb4_unicode_ci else cast('مستهدَفٌ من حصصٍ سارية' as char charset utf8mb4) collate utf8mb4_unicode_ci end AS `basis` from ((`months` `m` left join `suppliers` `s` on(`s`.`id` = `m`.`supplier_id`)) left join `v_supplier_share_units` `u` on(`u`.`supplier_id` = `m`.`supplier_id` and `u`.`company_id` = `m`.`company_id` and `u`.`effective_from` is not null and `u`.`effective_to` is not null and `u`.`effective_from` <= last_day(`m`.`mon`) and `u`.`effective_to` >= `m`.`mon`)) group by `m`.`company_id`,`m`.`supplier_id`,`s`.`name`,`m`.`mon`;

-- ── View: v_worker_billable_hours ──
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_worker_billable_hours` AS select `wp`.`id` AS `employee_id`,`t`.`date` AS `work_date`,cast(`t`.`operator` as unsigned) AS `operation_id`,coalesce(sum(`t`.`executed_hours`),0) AS `productive_hours`,coalesce(sum(`t`.`standby_hours`),0) AS `standby_hours`,coalesce(sum(`t`.`hr_fault`),0) AS `worker_downtime`,coalesce(sum(`t`.`maintenance_fault`),0) AS `maintenance_downtime`,greatest(coalesce(sum(`t`.`executed_hours`),0) + coalesce(sum(`t`.`standby_hours`),0) - coalesce(sum(`t`.`hr_fault`),0),0) AS `billable_baseline` from (`employees` `wp` join `timesheet` `t` on(cast(`t`.`employee_id` as unsigned) = `wp`.`id`)) group by `wp`.`id`,`t`.`date`,cast(`t`.`operator` as unsigned);

-- ── View: v_worker_presence ──
SET collation_connection = 'utf8mb4_unicode_ci';
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_worker_presence` AS select `wp`.`id` AS `employee_id`,case when `wp`.`workforce_state` = 'منتهٍ' then 'منتهٍ' when exists(select 1 from `worker_leave_absence` `la` where `la`.`employee_id` = `wp`.`id` and `la`.`state` in ('معتمد','مفتوح','مُغطًّى') and (`la`.`date_from` is null or `la`.`date_from` <= curdate()) and (`la`.`date_to` is null or `la`.`date_to` >= curdate()) limit 1) then 'خارج الموقع/إجازة' when exists(select 1 from `worker_movement` `m` where `m`.`employee_id` = `wp`.`id` and `m`.`state` in ('أمرٌ صادر','في الطريق') limit 1) then 'في الطريق' when exists(select 1 from `equipment_drivers` `ed` where `ed`.`employee_id` = `wp`.`id` and `ed`.`status` = 1 limit 1) then 'داخل الموقع' else 'بانتظار التخصيص' end AS `presence_state` from `employees` `wp`;

-- ── View: v_worker_worklog ──
SET collation_connection = 'utf8mb4_unicode_ci';
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_worker_worklog` AS select `wp`.`id` AS `employee_id`,`wp`.`name` AS `worker_name`,coalesce(`wp`.`worker_category`,'موظف') AS `worker_category`,coalesce(`wp`.`workforce_state`,'-') AS `worker_state`,(select count(distinct `o`.`id`) from (`equipment_drivers` `ed` join `operations` `o` on(`o`.`equipment` = `ed`.`equipment_id`)) where `ed`.`employee_id` = `wp`.`id` and `ed`.`status` = 1) AS `operations_count`,(select coalesce(sum(`b`.`billable_baseline`),0) from `v_worker_billable_hours` `b` where `b`.`employee_id` = `wp`.`id`) AS `total_billable_hours`,(select count(0) from `worker_leave_absence` `la` where `la`.`employee_id` = `wp`.`id`) AS `leave_absence_count`,(select count(0) from `worker_movement` `m` where `m`.`employee_id` = `wp`.`id`) AS `movement_count`,(select count(0) from `worker_evaluation` `ev` where `ev`.`employee_id` = `wp`.`id`) AS `evaluation_count`,(select coalesce(sum(`ev`.`amount`),0) from `worker_evaluation` `ev` where `ev`.`employee_id` = `wp`.`id` and `ev`.`incentive_penalty_type` = 'حافز') AS `incentive_total`,(select coalesce(sum(`ev`.`amount`),0) from `worker_evaluation` `ev` where `ev`.`employee_id` = `wp`.`id` and `ev`.`incentive_penalty_type` = 'جزاء') AS `penalty_total` from `employees` `wp`;

-- ── Trigger: trg_share_no_overlap_ins ──
DROP TRIGGER IF EXISTS `trg_share_no_overlap_ins`;
CREATE TRIGGER trg_share_no_overlap_ins BEFORE INSERT ON asset_ownership_shares
FOR EACH ROW BEGIN 
    DECLARE clash INT;
    SELECT COUNT(*) INTO clash
      FROM asset_ownership_shares x
     WHERE x.company_id = NEW.company_id
       AND x.asset_kind = NEW.asset_kind
       AND x.asset_id = NEW.asset_id
       AND x.financier_entity_id = NEW.financier_entity_id
       AND x.share_id <> COALESCE(NEW.share_id, 0)
       AND NEW.valid_from <= COALESCE(x.valid_to, '9999-12-31')
       AND x.valid_from  <= COALESCE(NEW.valid_to, '9999-12-31');
    IF clash > 0 THEN
        SIGNAL SQLSTATE '45000'
          SET MESSAGE_TEXT = 'SHR-409: فترتان متراكبتان لنفس (الاصل × الممول) — valid_to شامل فاغلق اليوم السابق';
    END IF;
 END;

-- ── Trigger: trg_share_no_overlap_upd ──
DROP TRIGGER IF EXISTS `trg_share_no_overlap_upd`;
CREATE TRIGGER trg_share_no_overlap_upd BEFORE UPDATE ON asset_ownership_shares
FOR EACH ROW BEGIN 
    DECLARE clash INT;
    SELECT COUNT(*) INTO clash
      FROM asset_ownership_shares x
     WHERE x.company_id = NEW.company_id
       AND x.asset_kind = NEW.asset_kind
       AND x.asset_id = NEW.asset_id
       AND x.financier_entity_id = NEW.financier_entity_id
       AND x.share_id <> COALESCE(NEW.share_id, 0)
       AND NEW.valid_from <= COALESCE(x.valid_to, '9999-12-31')
       AND x.valid_from  <= COALESCE(NEW.valid_to, '9999-12-31');
    IF clash > 0 THEN
        SIGNAL SQLSTATE '45000'
          SET MESSAGE_TEXT = 'SHR-409: فترتان متراكبتان لنفس (الاصل × الممول) — valid_to شامل فاغلق اليوم السابق';
    END IF;
 END;

-- ── Trigger: trg_cc_balance_ins ──
DROP TRIGGER IF EXISTS `trg_cc_balance_ins`;
CREATE TRIGGER trg_cc_balance_ins BEFORE INSERT ON container_consumption FOR EACH ROW
BEGIN
    DECLARE v_cap DECIMAL(14,2); DECLARE v_used DECIMAL(14,2); DECLARE v_key VARCHAR(64);
    SELECT cap_qty, consumed_qty, container_no INTO v_cap, v_used, v_key
      FROM op_containers WHERE id = NEW.container_id;
    SET NEW.share_key      = COALESCE(NEW.share_key, v_key);
    SET NEW.balance_before = v_cap - COALESCE(v_used, 0);
    SET NEW.balance_after  = NEW.balance_before - COALESCE(NEW.qty, 0);
    SET NEW.gap_units      = GREATEST(0, -NEW.balance_after);
END;

-- ── Trigger: trg_swap_ho_ins ──
DROP TRIGGER IF EXISTS `trg_swap_ho_ins`;
CREATE TRIGGER trg_swap_ho_ins BEFORE INSERT ON container_swaps FOR EACH ROW
BEGIN
    IF NEW.effective_from IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'HO-01: لا حدثَ تسليمٍ بلا تاريخِ سريان';
    END IF;
    IF NEW.doc_ref IS NULL OR NEW.doc_ref = '' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'لا تسليمَ بلا مستندٍ — اذكرْ مرجعَ المحضرِ أو الخطاب';
    END IF;
    IF NEW.container_id IS NULL OR NEW.to_container_id IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'HO-02: التسليمُ بطرفين — الحاويةُ المسلِّمةُ والمستلِمة';
    END IF;
    IF EXISTS (SELECT 1 FROM fin_financial_periods p
               WHERE p.company_id = NEW.company_id AND p.period_type='month'
                 AND NEW.effective_from BETWEEN p.start_date AND p.end_date
                 AND p.posting_allowed = 0) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'HO-05: الشهرُ مغلقٌ — لا حدثَ يعيد احتسابَ شهرٍ مقفل';
    END IF;
END;

-- ── Trigger: trg_contract_needs_quote_ins ──
DROP TRIGGER IF EXISTS `trg_contract_needs_quote_ins`;
CREATE TRIGGER trg_contract_needs_quote_ins BEFORE INSERT ON contracts FOR EACH ROW BEGIN IF COALESCE(NEW.is_deleted,0)=0 AND COALESCE(NEW.quotation_id,0)=0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'لا عقدَ بلا مرجعِ عرضٍ — أنشئِ العرضَ واقبله أولًا (سلسلة عميل⇐فرصة⇐عرض⇐عقد)';
      END IF; END;

-- ── Trigger: trg_contract_needs_quote_upd ──
DROP TRIGGER IF EXISTS `trg_contract_needs_quote_upd`;
CREATE TRIGGER trg_contract_needs_quote_upd BEFORE UPDATE ON contracts FOR EACH ROW BEGIN IF COALESCE(NEW.is_deleted,0)=0 AND COALESCE(NEW.quotation_id,0)=0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'لا عقدَ بلا مرجعِ عرضٍ — أنشئِ العرضَ واقبله أولًا (سلسلة عميل⇐فرصة⇐عرض⇐عقد)';
      END IF; END;

-- ── Trigger: trg_cmt_f03_ins ──
DROP TRIGGER IF EXISTS `trg_cmt_f03_ins`;
CREATE TRIGGER trg_cmt_f03_ins BEFORE INSERT ON contract_commitments FOR EACH ROW BEGIN IF NEW.slot_monthly_basis IS NOT NULL AND NEW.renewal_months IS NOT NULL THEN
        SET NEW.type_capacity = COALESCE(NEW.primary_units_contracted, 0) * NEW.slot_monthly_basis * NEW.renewal_months;
      END IF; END;

-- ── Trigger: trg_cmt_f03_upd ──
DROP TRIGGER IF EXISTS `trg_cmt_f03_upd`;
CREATE TRIGGER trg_cmt_f03_upd BEFORE UPDATE ON contract_commitments FOR EACH ROW BEGIN IF NEW.slot_monthly_basis IS NOT NULL AND NEW.renewal_months IS NOT NULL THEN
        SET NEW.type_capacity = COALESCE(NEW.primary_units_contracted, 0) * NEW.slot_monthly_basis * NEW.renewal_months;
      END IF; END;

-- ── Trigger: trg_cnote_close_needs_doc ──
DROP TRIGGER IF EXISTS `trg_cnote_close_needs_doc`;
CREATE TRIGGER trg_cnote_close_needs_doc BEFORE UPDATE ON contract_notes
        FOR EACH ROW BEGIN
          IF NEW.note_state = 'closed' AND OLD.note_state <> 'closed'
             AND NEW.severity = 'critical'
             AND (NEW.closure_doc_ref IS NULL OR NEW.closure_doc_ref = ''
                  OR NEW.closed_by IS NULL OR NEW.closed_by = 0) THEN
            SIGNAL SQLSTATE '45000'
              SET MESSAGE_TEXT = 'CNOTE-422: إغلاقُ ملاحظةٍ حرجةٍ يلزمه مستندٌ ومعتمِد';
          END IF;
        END;

-- ── Trigger: trg_delivery_backoff ──
DROP TRIGGER IF EXISTS `trg_delivery_backoff`;
CREATE TRIGGER `trg_delivery_backoff` BEFORE UPDATE ON `ems_event_deliveries`
      FOR EACH ROW
      BEGIN
        IF NEW.`state` = 'failed' AND NEW.`attempt_no` > OLD.`attempt_no` THEN
          SET NEW.`next_attempt_at` = NOW(3) + INTERVAL POW(4, LEAST(OLD.`attempt_no`, 4)) SECOND;
        END IF;
        IF NEW.`state` = 'processed' AND NEW.`processed_at` IS NULL THEN
          SET NEW.`processed_at` = NOW(3);
        END IF;
        IF NEW.`state` = 'dlq' AND NEW.`processed_at` IS NULL THEN
          SET NEW.`processed_at` = NOW(3);
        END IF;
      END;

-- ── Trigger: trg_n21_equipments_owner_ins ──
DROP TRIGGER IF EXISTS `trg_n21_equipments_owner_ins`;
CREATE TRIGGER `trg_n21_equipments_owner_ins` BEFORE INSERT ON `equipments` FOR EACH ROW BEGIN
  IF NEW.`actual_owner_name` IS NOT NULL OR NEW.`owner_type` IS NOT NULL
     OR NEW.`owner_phone` IS NOT NULL OR NEW.`owner_supplier_relation` IS NOT NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT =
      'N-21: أعمدة المالك في equipments مهجورة — بيانات الملكية في المجال المقيَّد حصرًا';
  END IF;
END;

-- ── Trigger: trg_n21_equipments_owner_upd ──
DROP TRIGGER IF EXISTS `trg_n21_equipments_owner_upd`;
CREATE TRIGGER `trg_n21_equipments_owner_upd` BEFORE UPDATE ON `equipments` FOR EACH ROW BEGIN
  IF (NEW.`actual_owner_name` IS NOT NULL AND (OLD.`actual_owner_name` IS NULL OR NEW.`actual_owner_name` <> OLD.`actual_owner_name`))
     OR (NEW.`owner_type` IS NOT NULL AND (OLD.`owner_type` IS NULL OR NEW.`owner_type` <> OLD.`owner_type`))
     OR (NEW.`owner_phone` IS NOT NULL AND (OLD.`owner_phone` IS NULL OR NEW.`owner_phone` <> OLD.`owner_phone`))
     OR (NEW.`owner_supplier_relation` IS NOT NULL AND (OLD.`owner_supplier_relation` IS NULL OR NEW.`owner_supplier_relation` <> OLD.`owner_supplier_relation`)) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT =
      'N-21: أعمدة المالك في equipments مهجورة — الكتابة في المجال المقيَّد حصرًا';
  END IF;
END;

-- ── Trigger: trg_exap_immutable ──
DROP TRIGGER IF EXISTS `trg_exap_immutable`;
CREATE TRIGGER `trg_exap_immutable` BEFORE UPDATE ON `exec_approvals`
FOR EACH ROW
BEGIN
  IF OLD.decision IS NOT NULL AND OLD.decision <> '' AND (
       NOT (NEW.decision <=> OLD.decision)
    OR NOT (NEW.decision_reason <=> OLD.decision_reason)
    OR NOT (NEW.decision_date <=> OLD.decision_date)
    OR NOT (NEW.amount <=> OLD.amount)
    OR NOT (NEW.request_no <=> OLD.request_no)
    OR NOT (NEW.authority_ref <=> OLD.authority_ref)
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BR-CEO-08: القرار الموقع لا يعدل — التغيير قرار جديد يشير للأصل';
  END IF;
END;

-- ── Trigger: trg_excs_immutable ──
DROP TRIGGER IF EXISTS `trg_excs_immutable`;
CREATE TRIGGER `trg_excs_immutable` BEFORE UPDATE ON `exec_contract_signings`
FOR EACH ROW
BEGIN
  IF OLD.signing_date IS NOT NULL AND (
       NOT (NEW.signing_date <=> OLD.signing_date)
    OR NOT (NEW.amount <=> OLD.amount)
    OR NOT (NEW.contract_no <=> OLD.contract_no)
    OR NOT (NEW.signed_by_us <=> OLD.signed_by_us)
    OR NOT (NEW.authority_ref <=> OLD.authority_ref)
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BR-CEO-08: العقد الموقع لا يعدل — الإنهاء أو التعليق قرار موثق جديد';
  END IF;
END;

-- ── Trigger: trg_exdc_immutable ──
DROP TRIGGER IF EXISTS `trg_exdc_immutable`;
CREATE TRIGGER `trg_exdc_immutable` BEFORE UPDATE ON `exec_decisions`
FOR EACH ROW
BEGIN
  IF OLD.decision_date IS NOT NULL AND (
       NOT (NEW.chosen_option <=> OLD.chosen_option)
    OR NOT (NEW.choice_reason <=> OLD.choice_reason)
    OR NOT (NEW.decision_date <=> OLD.decision_date)
    OR NOT (NEW.assigned_dept <=> OLD.assigned_dept)
    OR NOT (NEW.exec_deadline <=> OLD.exec_deadline)
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BR-CEO-08: القرار المحسوم لا يعدل — قرار لاحق يعدله بمرجع الأصل';
  END IF;
END;

-- ── Trigger: trg_expc_immutable ──
DROP TRIGGER IF EXISTS `trg_expc_immutable`;
CREATE TRIGGER `trg_expc_immutable` BEFORE UPDATE ON `exec_project_charters`
FOR EACH ROW
BEGIN
  IF OLD.approval_date IS NOT NULL AND OLD.approval_date <> ''
     AND OLD.status IN ('مفتوح', 'مغلق') AND (
       NOT (NEW.decision_no <=> OLD.decision_no)
    OR NOT (NEW.approval_date <=> OLD.approval_date)
    OR NOT (NEW.site_manager <=> OLD.site_manager)
    OR NOT (NEW.contract_ref <=> OLD.contract_ref)
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BR-CEO-08: قرار الفتح المعتمد لا يعدل — الإغلاق قرار مشابه بمحضر تصفية';
  END IF;
END;

-- ── Trigger: trg_grant_issuer ──
DROP TRIGGER IF EXISTS `trg_grant_issuer`;
CREATE TRIGGER `trg_grant_issuer` BEFORE INSERT ON `gov_authority_grants` FOR EACH ROW
      BEGIN
        DECLARE issuer_role INT DEFAULT NULL;
        SELECT `role` INTO issuer_role FROM `users` WHERE `id` = NEW.`issued_by` LIMIT 1;
        IF NEW.`source` <> 'profile' AND (issuer_role IS NULL OR issuer_role NOT IN (15)) THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'chk_grant_issuer: المنحُ بيدِ الحوكمةِ حصرًا (A1)';
        END IF;
      END;

-- ── Trigger: trg_cap_owner_only ──
DROP TRIGGER IF EXISTS `trg_cap_owner_only`;
CREATE TRIGGER `trg_cap_owner_only` BEFORE INSERT ON `gov_cap_history` FOR EACH ROW
      BEGIN
        DECLARE r INT DEFAULT NULL;
        SELECT `role` INTO r FROM `users` WHERE `id` = NEW.`changed_by` LIMIT 1;
        IF r IS NULL OR r <> 9 THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'تعديلُ السقفِ باعتمادِ المالكِ وحدَه (الدور 9)';
        END IF;
      END;

-- ── Trigger: trg_deleg_no_relay ──
DROP TRIGGER IF EXISTS `trg_deleg_no_relay`;
CREATE TRIGGER `trg_deleg_no_relay` BEFORE INSERT ON `gov_delegations` FOR EACH ROW
      BEGIN
        IF EXISTS (SELECT 1 FROM `gov_delegations` d
                    WHERE d.`to_user` = NEW.`from_user` AND d.`revoked_at` IS NULL
                      AND d.`valid_to` > NOW()) THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'chk_deleg_no_relay: لا سلسلةَ تفويضٍ ثانية';
        END IF;
      END;

-- ── Trigger: trg_deleg_non_delegable ──
DROP TRIGGER IF EXISTS `trg_deleg_non_delegable`;
CREATE TRIGGER `trg_deleg_non_delegable` BEFORE INSERT ON `gov_delegations` FOR EACH ROW
      BEGIN
        IF EXISTS (SELECT 1 FROM `non_delegable_actions` n
                    WHERE NEW.`scope_json` LIKE CONCAT('%', n.`action_code`, '%')) THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'chk_non_delegable: فعلٌ محصورٌ لا يُفوَّض';
        END IF;
      END;

-- ── Trigger: trg_imp_not_oversight ──
DROP TRIGGER IF EXISTS `trg_imp_not_oversight`;
CREATE TRIGGER `trg_imp_not_oversight` BEFORE INSERT ON `impersonation_sessions` FOR EACH ROW
      BEGIN
        DECLARE tgt_role INT DEFAULT NULL;
        SELECT `role` INTO tgt_role FROM `users` WHERE `id` = NEW.`target_user` LIMIT 1;
        IF tgt_role IN (15,20,28,29,30,33) THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'chk_imp_not_oversight: لا نيابةَ على الرقابيّين';
        END IF;
      END;

-- ── Trigger: trg_nav_provisional_scope ──
DROP TRIGGER IF EXISTS `trg_nav_provisional_scope`;
CREATE TRIGGER `trg_nav_provisional_scope`
    BEFORE UPDATE ON `nav_canonical` FOR EACH ROW
    BEGIN
        IF NEW.application_state = 'PROVISIONALLY_APPLIED_NO_OBJECTION'
           AND NEW.policy_domain <> 'NAVIGATION_NAMING_POSITION' THEN
            SIGNAL SQLSTATE '45000'
              SET MESSAGE_TEXT = 'التطبيقُ المؤقَّتُ ممنوعٌ في هذا المجال: الصلاحياتُ · سلاليمُ الاعتمادِ · السقوفُ الماليةُ · فصلُ الواجباتِ · الالتزاماتُ القانونيةُ · القراراتُ المالية';
        END IF;
        IF NEW.application_state = 'PROVISIONALLY_APPLIED_NO_OBJECTION'
           AND NEW.provisional_reversible <> 1 THEN
            SIGNAL SQLSTATE '45000'
              SET MESSAGE_TEXT = 'التطبيقُ المؤقَّتُ محصورٌ فيما يُعكس — وهذا الصفُّ غيرُ معلَنٍ قابلًا للعكس';
        END IF;
        IF NEW.decision_state IN ('APPROVED','REJECTED')
           AND COALESCE(OLD.decision_state,'') <> NEW.decision_state
           AND NEW.decided_by IS NULL
           AND (NEW.decision_source IS NULL OR NEW.decision_source = '') THEN
            SIGNAL SQLSTATE '45000'
              SET MESSAGE_TEXT = 'حسمٌ بلا فاعلٍ ولا مصدرٍ حاكمٍ مرفوض — الصمتُ لا يُرقِّي قرارًا';
        END IF;
    END;

-- ── Trigger: trg_opc_cap_ins ──
DROP TRIGGER IF EXISTS `trg_opc_cap_ins`;
CREATE TRIGGER trg_opc_cap_ins BEFORE INSERT ON op_containers FOR EACH ROW BEGIN 
    IF NEW.parent_id IS NOT NULL AND COALESCE(NEW.is_deleted,0) = 0 THEN
        SET @cap_parent = (SELECT p.cap_qty FROM op_containers p WHERE p.id = NEW.parent_id);
        SET @cap_sibs = (SELECT COALESCE(SUM(s.cap_qty),0) FROM op_containers s
                          WHERE s.parent_id = NEW.parent_id AND s.is_deleted = 0 AND s.id <> COALESCE(NEW.id,0));
        IF @cap_parent IS NOT NULL AND (@cap_sibs + NEW.cap_qty) > @cap_parent + 0.005 THEN
            SIGNAL SQLSTATE '45000'
              SET MESSAGE_TEXT = 'سعةُ الحاوية: مجموعُ الأبناءِ يتجاوز سعةَ الأب — الأعلى مشتقٌّ من الأدنى ولا يُتجاوز';
        END IF;
    END IF; END;

-- ── Trigger: trg_opc_cap_upd ──
DROP TRIGGER IF EXISTS `trg_opc_cap_upd`;
CREATE TRIGGER trg_opc_cap_upd BEFORE UPDATE ON op_containers FOR EACH ROW BEGIN 
    IF NEW.parent_id IS NOT NULL AND COALESCE(NEW.is_deleted,0) = 0 THEN
        SET @cap_parent = (SELECT p.cap_qty FROM op_containers p WHERE p.id = NEW.parent_id);
        SET @cap_sibs = (SELECT COALESCE(SUM(s.cap_qty),0) FROM op_containers s
                          WHERE s.parent_id = NEW.parent_id AND s.is_deleted = 0 AND s.id <> COALESCE(NEW.id,0));
        IF @cap_parent IS NOT NULL AND (@cap_sibs + NEW.cap_qty) > @cap_parent + 0.005 THEN
            SIGNAL SQLSTATE '45000'
              SET MESSAGE_TEXT = 'سعةُ الحاوية: مجموعُ الأبناءِ يتجاوز سعةَ الأب — الأعلى مشتقٌّ من الأدنى ولا يُتجاوز';
        END IF;
    END IF; END;

-- ── Trigger: trg_opc_f0102_ins ──
DROP TRIGGER IF EXISTS `trg_opc_f0102_ins`;
CREATE TRIGGER trg_opc_f0102_ins BEFORE INSERT ON op_containers FOR EACH ROW BEGIN IF NEW.slot_role IS NOT NULL THEN
        SET NEW.daily_hours_basis = CASE NEW.slot_role
            WHEN 'primary_two_shifts' THEN 20
            WHEN 'primary_one_shift'  THEN 12
            ELSE COALESCE(NEW.daily_hours_basis, 0) END;
        SET NEW.monthly_basis = NEW.daily_hours_basis * 30;
      END IF; END;

-- ── Trigger: trg_opc_f0102_upd ──
DROP TRIGGER IF EXISTS `trg_opc_f0102_upd`;
CREATE TRIGGER trg_opc_f0102_upd BEFORE UPDATE ON op_containers FOR EACH ROW BEGIN IF NEW.slot_role IS NOT NULL THEN
        SET NEW.daily_hours_basis = CASE NEW.slot_role
            WHEN 'primary_two_shifts' THEN 20
            WHEN 'primary_one_shift'  THEN 12
            ELSE COALESCE(NEW.daily_hours_basis, 0) END;
        SET NEW.monthly_basis = NEW.daily_hours_basis * 30;
      END IF; END;

-- ── Trigger: trg_po_request_required ──
DROP TRIGGER IF EXISTS `trg_po_request_required`;
CREATE TRIGGER trg_po_request_required BEFORE INSERT ON proc_order
         FOR EACH ROW BEGIN
           IF NEW.request_id IS NULL OR NEW.request_id = 0 THEN
             SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PO-REQ-422: لا أمرَ شراءٍ بلا طلبٍ مرتبط';
           END IF;
         END;

-- ── Trigger: trg_psm_return_not_exceed_issued ──
DROP TRIGGER IF EXISTS `trg_psm_return_not_exceed_issued`;
CREATE TRIGGER trg_psm_return_not_exceed_issued
BEFORE INSERT ON proc_stock_move
FOR EACH ROW
BEGIN
  DECLARE v_issued   DECIMAL(18,4) DEFAULT 0;
  DECLARE v_returned DECIMAL(18,4) DEFAULT 0;
  DECLARE v_msg      VARCHAR(255);
  IF NEW.move_type = 'مرتجع' AND NEW.ref_type = 'issue' AND NEW.ref_id > 0 THEN
    SELECT COALESCE(SUM(il.qty),0) INTO v_issued
      FROM proc_issue_line il
      JOIN proc_issue i ON i.id = il.issue_id
     WHERE il.issue_id = NEW.ref_id AND il.item_id = NEW.item_id
       AND i.company_id = NEW.company_id;
    SELECT COALESCE(SUM(m.qty),0) INTO v_returned
      FROM proc_stock_move m
     WHERE m.company_id = NEW.company_id AND m.move_type = 'مرتجع'
       AND m.ref_type = 'issue' AND m.ref_id = NEW.ref_id AND m.item_id = NEW.item_id;
    IF (v_returned + NEW.qty) > (v_issued + 0.0001) THEN
      SET v_msg = CONCAT('FN-07: المرتجع يتجاوز المصروف — مصروف ', v_issued,
                         ' · أُرجع ', v_returned, ' · المطلوب ', NEW.qty);
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
    END IF;
  END IF;
END;

-- ── Trigger: trg_stock_no_negative ──
DROP TRIGGER IF EXISTS `trg_stock_no_negative`;
CREATE TRIGGER trg_stock_no_negative BEFORE INSERT ON proc_stock_move
FOR EACH ROW
BEGIN
    DECLARE bal DECIMAL(18,4);
    IF NEW.move_type NOT IN ('استلام','تحويل وارد','مرتجع','تسوية زيادة') THEN
        SELECT COALESCE(SUM(CASE WHEN move_type IN ('استلام','تحويل وارد','مرتجع','تسوية زيادة') THEN qty ELSE -qty END), 0)
          INTO bal
          FROM proc_stock_move
         WHERE company_id = NEW.company_id
           AND item_id = NEW.item_id
           AND warehouse_id = NEW.warehouse_id;
        IF bal < NEW.qty THEN
            SIGNAL SQLSTATE '45000'
              SET MESSAGE_TEXT = 'STK-409: لا يخرج من المخزن ما ليس فيه — الرصيد اقل من المطلوب';
        END IF;
    END IF;
END;

-- ── Trigger: trg_settle_f0708_ins ──
DROP TRIGGER IF EXISTS `trg_settle_f0708_ins`;
CREATE TRIGGER trg_settle_f0708_ins BEFORE INSERT ON settlements FOR EACH ROW BEGIN SET NEW.supplier_executed_hours = NEW.client_executed_hours + NEW.adj_work_added
        + NEW.adj_breakdown_added + NEW.adj_standby_added - NEW.adj_deducted;
      SET NEW.borne_by_treasury = GREATEST(NEW.supplier_executed_hours - NEW.client_settled_hours, 0); END;

-- ── Trigger: trg_settle_f0708_upd ──
DROP TRIGGER IF EXISTS `trg_settle_f0708_upd`;
CREATE TRIGGER trg_settle_f0708_upd BEFORE UPDATE ON settlements FOR EACH ROW BEGIN SET NEW.supplier_executed_hours = NEW.client_executed_hours + NEW.adj_work_added
        + NEW.adj_breakdown_added + NEW.adj_standby_added - NEW.adj_deducted;
      SET NEW.borne_by_treasury = GREATEST(NEW.supplier_executed_hours - NEW.client_settled_hours, 0); END;

-- ── Trigger: trg_taxinv_needs_lines ──
DROP TRIGGER IF EXISTS `trg_taxinv_needs_lines`;
CREATE TRIGGER trg_taxinv_needs_lines BEFORE INSERT ON tax_invoices FOR EACH ROW
BEGIN
    IF NEW.claim_id IS NOT NULL
       AND (SELECT COUNT(*) FROM claim_lines l WHERE l.claim_id = NEW.claim_id) = 0 THEN
        SIGNAL SQLSTATE '45000'
          SET MESSAGE_TEXT = 'لا فاتورةَ لمستخلصٍ بلا بنود — أكمِلْ بنودَ المستخلصِ أولًا';
    END IF;
END;

-- ── Trigger: trg_ue_dup_shield_ins ──
DROP TRIGGER IF EXISTS `trg_ue_dup_shield_ins`;
CREATE TRIGGER `trg_ue_dup_shield_ins` BEFORE INSERT ON `unit_entries`
FOR EACH ROW
BEGIN
  IF NEW.entry_date >= '2026-08-05'
     AND NEW.state NOT IN ('rejected','cancelled','superseded','reversed')
     AND EXISTS (
       SELECT 1 FROM unit_entries ue
        WHERE ue.equipment_id = NEW.equipment_id
          AND ue.entry_date = NEW.entry_date
          AND ue.shift <=> NEW.shift
          AND ue.state NOT IN ('rejected','cancelled','superseded','reversed')
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'ق-18: تكرار (معدة×تاريخ×وردية) مرفوض بنيويًّا على السكة الجديدة';
  END IF;
END;

-- ── Trigger: trg_ue_dup_shield_upd ──
DROP TRIGGER IF EXISTS `trg_ue_dup_shield_upd`;
CREATE TRIGGER `trg_ue_dup_shield_upd` BEFORE UPDATE ON `unit_entries`
FOR EACH ROW
BEGIN
  IF NEW.entry_date >= '2026-08-05'
     AND NEW.state NOT IN ('rejected','cancelled','superseded','reversed')
     AND (NOT (NEW.equipment_id <=> OLD.equipment_id)
       OR NOT (NEW.entry_date <=> OLD.entry_date)
       OR NOT (NEW.shift <=> OLD.shift))
     AND EXISTS (
       SELECT 1 FROM unit_entries ue
        WHERE ue.equipment_id = NEW.equipment_id
          AND ue.entry_date = NEW.entry_date
          AND ue.shift <=> NEW.shift
          AND ue.id <> OLD.id
          AND ue.state NOT IN ('rejected','cancelled','superseded','reversed')
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'ق-18: نقل الصف إلى (معدة×تاريخ×وردية) مشغولة مرفوض بنيويًّا';
  END IF;
END;

SET FOREIGN_KEY_CHECKS = 1;
